INSERT INTO public.courses (id, module_id, code, title, short_title, professor, source_files, bm_count, bm_shared_note, bm_recent_count, unique_concepts, priority, priority_score, vigilance_2026, summary, status, version, lessons, attachments, ai_extraction, ppt_import, created_at, updated_at, published_at) VALUES ('C1', 'M1', 'C1', 'Introduction à la santé publique', 'Intro Santé Publique', 'Pr BOUMARAF Khawla (SEMEP CHU Batna)', $medjson$["Introduction à la santé publique- Pr Boumaraf.pdf (62 slides)"]$medjson$::jsonb, 13, '+ 3 recoupements directs 2025 avec C3 (MNT)', 4, 6, 'very_high', 92, FALSE, 'Concepts fondateurs de la santé, les 3 approches (conventionnelle, globaliste, prospective), niveaux de prévention (I à IV), déterminants, historique en Algérie (1974), priorités de santé publique, SSP et outils.', 'published', 1, $medjson$[{"id":"L1.1","courseId":"C1","order":1,"title":"Concepts, 3 approches de la santé \u0026 déterminants","durationMin":12,"sourceRef":"Chapitre 2, slides 5–10","bmCount":5,"bmRefs":["Ch. 2 Q1 (2024)","Ch. 14 Q2 (2025)","Ch. 14 Q3 (2025)","Ch. 17 Q9 (2022)","Ch. 19 Q11 (2022)"],"priority":"very_high","priorityScore":80,"bmWarning":"⚠️ 2 erreurs majeures dans le corrigé BM : Ch. 2 Q1 (approche prospective = B, PAS C) et Ch. 14 Q2 (approche conventionnelle = C seul, PAS ABC).","understand":{"intro":"La notion de « santé » a profondément évolué : d’une vision purement biologique (absence de maladie) vers une approche globale (OMS) puis dynamique et adaptative (prospective). Ce chapitre est tombé en 2024 et en 2025.","sections":[{"heading":"Les 3 définitions historiques de référence","paragraphs":["Le cours du Pr Boumaraf retient trois jalons chronologiques pour cerner la santé :"],"bullets":["\u003cstrong\u003eLeriche (1937) :\u003c/strong\u003e « La santé est la vie dans le silence des organes » (vision physiologique/clinique).","\u003cstrong\u003eOMS (1946) :\u003c/strong\u003e « Un état de complet bien-être physique, mental et social, et ne consiste pas seulement en une absence de maladie ou d’infirmité ».","\u003cstrong\u003eUNICEF (1989) :\u003c/strong\u003e la santé dépend aussi du travail, du revenu, de l’éducation, de la culture, des droits et des libertés."]},{"heading":"Les déterminants de la santé (objectifs/subjectifs, intrinsèques/extrinsèques)","paragraphs":["Les déterminants sont l’ensemble des facteurs qui influencent l’état de santé d’une population — ils peuvent être \u003cstrong\u003epositifs\u003c/strong\u003e (protecteurs) ou \u003cstrong\u003enégatifs\u003c/strong\u003e (facteurs de risque)."],"bullets":["\u003cstrong\u003eDéterminants intrinsèques :\u003c/strong\u003e patrimoine génétique, caractéristiques biologiques individuelles.","\u003cstrong\u003eDéterminants extrinsèques :\u003c/strong\u003e infrastructures sanitaires, environnement microbiologique, culture et comportements, conditions socio-économiques."]}],"tables":[{"title":"Comparaison des 3 approches de la santé (Ultra-testé 2024–2025)","headers":["Critère","Approche Conventionnelle","Approche Globaliste","Approche Prospective"],"rows":[["Idée centrale","Santé = absence de maladie (norme vs dysfonctionnement biologique)","Maladie = fait biologique ET social","Santé = processus dynamique, capacité d’adaptation et de réaction à l’environnement"],["Référence / Clé","Pratique médicale quotidienne","Définition OMS (1946) : bien-être physique, mental et social","Équilibre facteurs endogènes/exogènes + moyens de contrôle disponibles"],["Limite / Piège QCM","Définie EN DEHORS de tout critère socio-économique et culturel","Idéal philosophique difficile à quantifier","Ne se limite PAS uniquement à l’environnement"]]}],"darija":"باش ما تغلطش أبدا في الـ QCM : \u003cstrong\u003eConventionnelle\u003c/strong\u003e = غير « ما راكش مريض » بلا أي معيار اجتماعي أو ثقافي. \u003cstrong\u003eGlobaliste\u003c/strong\u003e = تعريف l’OMS (بدني + نفسي + اجتماعي). \u003cstrong\u003eProspective\u003c/strong\u003e = القدرة على التكيف + \u003cstrong\u003eles moyens de contrôle\u003c/strong\u003e تاع العوامل الداخلية والخارجية (endogènes/exogènes). وحذاري من غلطتين في الـ BM (Ch.2 Q1 و Ch.14 Q2) !","triad":{"toUnderstand":["Pourquoi l’approche conventionnelle est jugée réductrice en santé publique.","Comment l’approche prospective introduit la notion dynamique de capacité d’adaptation et de moyens de contrôle."],"toMemorize":["Les mots-clés exacts de chaque approche (absence de maladie / OMS 1946 / moyens de contrôle endogènes-exogènes).","Déterminants intrinsèques (patrimoine génétique) vs extrinsèques (infrastructures, microbiologie, culture/comportements)."],"toRecognizeInQcm":["« en dehors de tout critère socio-économique et culturel » → Conventionnelle.","« dimensions physique, mentale et sociale » → Globaliste (NE PAS cocher pour Prospective !).","« facteurs endogènes et exogènes » ou « capacité d’adaptation / interaction » → Prospective."]}},"memorize":[{"id":"M_L1.1_1","category":"Définition","title":"Approche conventionnelle","content":"Santé = \u003cstrong\u003eabsence de maladie\u003c/strong\u003e (dysfonctionnement biologique), définie \u003cstrong\u003een dehors de tout critère socio-économique et culturel\u003c/strong\u003e.","highlight":true},{"id":"M_L1.1_2","category":"Définition","title":"Approche globaliste (OMS 1946)","content":"Maladie = fait biologique ET social. Santé = \u003cstrong\u003eétat de complet bien-être physique, mental et social\u003c/strong\u003e (ne consiste pas seulement en une absence de maladie).","highlight":true},{"id":"M_L1.1_3","category":"Définition","title":"Approche prospective","content":"Processus dynamique : \u003cstrong\u003ecapacité d’adaptation et d’interaction\u003c/strong\u003e avec l’environnement, tenant compte des \u003cstrong\u003emoyens de contrôle des facteurs endogènes et exogènes\u003c/strong\u003e.","highlight":true},{"id":"M_L1.1_4","category":"Distinction","title":"Déterminants intrinsèques vs extrinsèques","content":"\u003cstrong\u003eIntrinsèques :\u003c/strong\u003e patrimoine génétique, biologie. \u003cstrong\u003eExtrinsèques :\u003c/strong\u003e infrastructures sanitaires, environnement microbiologique, culture et comportements. Ils sont \u003cstrong\u003epositifs et/ou négatifs\u003c/strong\u003e.","highlight":false},{"id":"M_L1.1_5","category":"Définition","title":"Leriche (1937) \u0026 UNICEF (1989)","content":"\u003cstrong\u003eLeriche (1937) :\u003c/strong\u003e « La vie dans le silence des organes ». \u003cstrong\u003eUNICEF (1989) :\u003c/strong\u003e intègre travail, revenu, éducation, culture, droits et libertés.","highlight":false}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L1.2","courseId":"C1","order":2,"title":"Les 4 niveaux de prévention, éducation \u0026 promotion de la santé","durationMin":12,"sourceRef":"Chapitre 7.5.1 \u0026 7.5.2, slides 46–53","bmCount":5,"bmRefs":["Ch. 2 Q2 (2024)","Ch. 32 Q3–Q4 (2022)","Ch. 32 Q11–Q12 (ND)","+ 5 QCM partagés C3 (MNT)"],"priority":"very_high","priorityScore":100,"understand":{"intro":"Les niveaux de prévention constituent l’un des 2 sujets les plus testés de toute la BM (10 occurrences cumulées C1 + C3 de 2021 à 2025). La clé est d’associer sans erreur chaque niveau à son indicateur (incidence vs prévalence) et à ses exemples concrets.","sections":[{"heading":"Prévention vs Prophylaxie","paragraphs":["La prévention regroupe l’ensemble des mesures visant à éviter ou réduire le nombre et la gravité des maladies ou accidents."],"bullets":["\u003cstrong\u003eProphylaxie :\u003c/strong\u003e prévention spécifiquement dirigée contre une \u003cstrong\u003emaladie transmissible\u003c/strong\u003e.","\u003cstrong\u003eChimioprophylaxie :\u003c/strong\u003e prévention d’une maladie transmissible par administration d’un médicament (ex. méningite à méningocoque, paludisme)."]},{"heading":"Éducation pour la santé vs Promotion de la santé","paragraphs":["Ces deux notions sont complémentaires mais ne sont pas synonymes :"],"bullets":["\u003cstrong\u003eÉducation pour la santé :\u003c/strong\u003e outil ciblant les connaissances, attitudes et comportements individuels.","\u003cstrong\u003ePromotion de la santé (Charte d’Ottawa) :\u003c/strong\u003e approche globale agissant sur les comportements ET sur les environnements favorables, les politiques publiques et l’autonomisation des communautés."]}],"tables":[{"title":"Tableau d’or des 4 niveaux de prévention (Score 100/100)","headers":["Niveau","Cible","Objectif / Indicateur","Exemples classiques en QCM"],"rows":[["Primaire","Sujets sains / exposés avant la maladie","Diminuer l’INCIDENCE (nouveaux cas)","Vaccination, ioduration du sel (goitre/crétinisme), arrêt du tabac, hygiène"],["Secondaire","Sujets asymptomatiques / stade précoce","Diminuer la PRÉVALENCE (nouveaux + anciens cas) et la durée","Dépistage précoce (mammographie cancer du sein, FCV, glycémie, coloscopie)"],["Tertiaire","Malades avérés","Diminuer complications, rechutes, récidives et incapacités","Suivi diabétique, traitement rétinopathie, réadaptation cardiaque"],["Quaternaire","Patients exposés au système de soins","Protéger contre la surmédicalisation, les soins/actes invasifs inutiles et les IAS","Éviter examens ou prescriptions inutiles, pertinence des soins"]]}],"darija":"احفظ هاد المعادلة الذهبية : \u003cstrong\u003ePrimaire = تنقص Incidence\u003c/strong\u003e (حالات جدد : تلقيح، ملح باليود، توقيف الدخان). \u003cstrong\u003eSecondaire = Dépistage وتنقص Prévalence\u003c/strong\u003e (حالات جدد + قدم). \u003cstrong\u003eTertiaire = المضاعفات والانتكاس (récidives)\u003c/strong\u003e. \u003cstrong\u003eQuaternaire = حماية من كثرة الفحوصات والدواء الزايد (surmédicalisation)\u003c/strong\u003e.","triad":{"toUnderstand":["Pourquoi le dépistage réduit la prévalence (durée d’évolution écourtée) et non l’incidence.","Pourquoi la prévention quaternaire protège à la fois le patient et le soignant de la surmédicalisation."],"toMemorize":["Primaire → Incidence ; Secondaire → Prévalence ; Tertiaire → Complications/récidives ; Quaternaire → Surmédicalisation / IAS.","L’ioduration du sel contre le goitre/crétinisme = prévention PRIMAIRE (piège Ch. 2 Q2 B)."],"toRecognizeInQcm":["« diminuer les nouveaux cas » → Primaire ; « diminuer nouveaux et anciens cas » → Secondaire.","« déceler précocement » / « dépistage » → Secondaire.","« réduire la prescription d’interventions inutiles » → Quaternaire."]}},"memorize":[{"id":"M_L1.2_1","category":"Classification","title":"Prévention Primaire","content":"Actes destinés à \u003cstrong\u003ediminuer l’incidence\u003c/strong\u003e (nouveaux cas). Exemples : vaccination, \u003cstrong\u003eioduration du sel\u003c/strong\u003e, lutte antitabac.","highlight":true},{"id":"M_L1.2_2","category":"Classification","title":"Prévention Secondaire","content":"Actes visant à \u003cstrong\u003edéceler précocement\u003c/strong\u003e la maladie et \u003cstrong\u003ediminuer sa prévalence\u003c/strong\u003e (nouveaux + anciens cas) et sa durée. Axe principal : \u003cstrong\u003ele dépistage\u003c/strong\u003e (ex. cancer du sein).","highlight":true},{"id":"M_L1.2_3","category":"Classification","title":"Prévention Tertiaire","content":"Actes destinés à prévenir les \u003cstrong\u003ecomplications, rechutes, récidives et séquelles\u003c/strong\u003e chez un malade avéré.","highlight":true},{"id":"M_L1.2_4","category":"Classification","title":"Prévention Quaternaire","content":"Protection du patient et du soignant contre la \u003cstrong\u003esurmédicalisation\u003c/strong\u003e, les \u003cstrong\u003einterventions inutiles/invasives\u003c/strong\u003e et les \u003cstrong\u003eIAS\u003c/strong\u003e.","highlight":true},{"id":"M_L1.2_5","category":"Définition","title":"Prophylaxie vs Chimioprophylaxie","content":"\u003cstrong\u003eProphylaxie :\u003c/strong\u003e prévention contre une maladie transmissible. \u003cstrong\u003eChimioprophylaxie :\u003c/strong\u003e prévention par médicament.","highlight":false}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L1.3","courseId":"C1","order":3,"title":"Historique (Algérie 1974), priorités de SP, SSP \u0026 outils","durationMin":12,"sourceRef":"Chapitres 3 à 8, slides 13–60","bmCount":3,"bmRefs":["Ch. 29 Q14 (2023)","Ch. 41 Q6 (2023)","Ch. 38 Q8 (2022)"],"priority":"medium","priorityScore":52,"understand":{"intro":"Cette leçon rassemble les repères historiques mondiaux et algériens (dont la date-clé de 1974 tombée 2 fois), les critères d’une priorité de santé publique, la hiérarchie Politique/Plan/Programme/Action et les Soins de Santé Primaires (SSP).","sections":[{"heading":"Historique clé de la santé publique (Monde \u0026 Algérie)","paragraphs":["L’histoire de la santé publique relie l’observation environnementale à l’épidémiologie moderne et aux systèmes de santé :"],"bullets":["\u003cstrong\u003eHippocrate :\u003c/strong\u003e « Primum non nocere », traité \u003cem\u003eDes airs, des eaux et des lieux\u003c/em\u003e.","\u003cstrong\u003eSemmelweis (1847) :\u003c/strong\u003e lien entre lavage des mains des médecins et fièvre puerpérale.","\u003cstrong\u003eJohn Snow (1854–1855) :\u003c/strong\u003e démonstration du lien choléra ↔ eau contaminée (pompe de Broad Street à Londres), réfutant la théorie des miasmes.","\u003cstrong\u003eTransition épidémiologique (Abdel Omran, 1971) :\u003c/strong\u003e 3 âges (pestilence/famine EV \u003c 30 ans → recul des infections → maladies dégénératives et chroniques).","\u003cstrong\u003eAlgérie — Phase de transition :\u003c/strong\u003e \u003cstrong\u003eGratuité des soins en janvier 1974\u003c/strong\u003e, réforme des études médicales et création du secteur sanitaire."]},{"heading":"Priorités de santé publique \u0026 hiérarchie des interventions","paragraphs":["Face à des ressources limitées, un problème est retenu comme priorité de santé publique sur 4 critères principaux (plus la vulnérabilité/curabilité) :"],"bullets":["\u003cstrong\u003e4 critères du cours :\u003c/strong\u003e 1) \u003cstrong\u003eGrave\u003c/strong\u003e (létalité, séquelles, incapacités), 2) \u003cstrong\u003eFréquente\u003c/strong\u003e (prévalence/ampleur élevée), 3) \u003cstrong\u003eImpact socio-économique\u003c/strong\u003e, 4) \u003cstrong\u003ePerception sociale\u003c/strong\u003e (+ maladie curable ou évitable par la prévention).","\u003cstrong\u003eHiérarchie :\u003c/strong\u003e Politique de SP ⊃ \u003cstrong\u003ePlan de SP\u003c/strong\u003e (série de programmes coordonnés) ⊃ \u003cstrong\u003eProgramme de SP\u003c/strong\u003e (actions coordonnées dans le temps/espace pour objectifs précis) ⊃ \u003cstrong\u003eAction de SP\u003c/strong\u003e (composante opérationnelle).","\u003cstrong\u003e3 objectifs SP (OMS 1985) :\u003c/strong\u003e réduire morbidité/incapacité, réduire mortalité prématurée/évitable, assurer l’égalité dans la santé."]}],"tables":[{"title":"Repères institutionnels \u0026 outils de la santé publique","headers":["Concept","Contenu clé à retenir"],"rows":[["Algérie — Janvier 1974","Instauration de la gratuité des soins (tombé 2× dans la BM : Ch. 29 Q14 \u0026 Ch. 41 Q6)"],["Soins de Santé Primaires (SSP)","Chronologie : Famille → Communauté → Services de santé (8 composantes essentielles)"],["Outils de la SP","Épidémiologie, biostatistique, démographie, économie de la santé, planification/évaluation, éducation sanitaire"]]}],"darija":"التاريخ لي تكرر زوج مرات في الـ BM : \u003cstrong\u003eمجانية العلاج في الجزائر (Gratuité des soins) = جانفي 1974\u003c/strong\u003e ! وشفا بلي باش مرض يولي \u003cstrong\u003epriorité de santé publique\u003c/strong\u003e لازم يكون : منتشر (prévalence élevée) + خطير + قابل للعلاج أو الوقاية (curable ou évitable).","triad":{"toUnderstand":["La logique descendante Politique → Plan → Programme → Action.","Pourquoi la vulnérabilité (curable ou évitable) conditionne le classement en priorité sanitaire."],"toMemorize":["Gratuité des soins en Algérie : janvier 1974.","Les 4 critères de priorité : Grave, Fréquente, Impact socio-économique, Perception sociale (+ curable/évitable).","John Snow (1854–1855, Broad Street, choléra) ; Semmelweis (1847, lavage des mains) ; Abdel Omran (1971, transition)."],"toRecognizeInQcm":["Date de la gratuité des soins en Algérie → 1974 (pièges : 1949, 1976).","Critères priorité SP : prévalence élevée + curable/évitable (exclure « pas de traitement » et « coût élevé du traitement »)."]}},"memorize":[{"id":"M_L1.3_1","category":"Seuil / Chiffre","title":"Gratuité des soins en Algérie","content":"Instaurée en \u003cstrong\u003ejanvier 1974\u003c/strong\u003e (avec réforme des études médicales et création du secteur sanitaire).","highlight":true},{"id":"M_L1.3_2","category":"Liste","title":"Critères d’une priorité de santé publique","content":"\u003cstrong\u003e1) Grave\u003c/strong\u003e (létalité, séquelles), \u003cstrong\u003e2) Fréquente\u003c/strong\u003e (prévalence élevée), \u003cstrong\u003e3) Impact socio-économique\u003c/strong\u003e, \u003cstrong\u003e4) Perception sociale\u003c/strong\u003e, et \u003cstrong\u003ecurable ou évitable\u003c/strong\u003e par la prévention.","highlight":true},{"id":"M_L1.3_3","category":"Classification","title":"Hiérarchie des interventions","content":"\u003cstrong\u003ePolitique de SP\u003c/strong\u003e ⊃ \u003cstrong\u003ePlan de SP\u003c/strong\u003e ⊃ \u003cstrong\u003eProgramme de SP\u003c/strong\u003e ⊃ \u003cstrong\u003eAction de SP\u003c/strong\u003e.","highlight":false},{"id":"M_L1.3_4","category":"Liste","title":"Transition épidémiologique (Abdel Omran, 1971)","content":"3 âges : (1) Pestilence et famine (EV \u003c 30 ans), (2) Recul des maladies infectieuses, (3) Maladies dégénératives et chroniques.","highlight":false}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]}]$medjson$::jsonb, $medjson$[]$medjson$::jsonb, $medjson${"analyzedAt":null,"engine":"curated","totalPages":0,"lowConfidencePages":[],"warnings":[],"status":"none"}$medjson$::jsonb, NULL, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, module_id, code, title, short_title, professor, source_files, bm_count, bm_shared_note, bm_recent_count, unique_concepts, priority, priority_score, vigilance_2026, summary, status, version, lessons, attachments, ai_extraction, ppt_import, created_at, updated_at, published_at) VALUES ('C2', 'M2', 'C2', 'Épidémiologie des maladies transmissibles & surveillance', 'MT & Surveillance', 'Dr F. BEICHI (Université Batna 2)', $medjson$["Epidémiologie des MT .pdf (10 p., avec Annexe Décret MDO 22-250)"]$medjson$::jsonb, 30, 'Cours n°1 en volume dans la BM (Ch. 12 + Ch. 13 + Ch. 38 + Ch. 19 Q10)', 8, 10, 'very_high', 95, FALSE, 'Importance des MT (Monde vs Algérie), chaîne épidémiologique, pouvoir pathogène/virulence/contagiosité (R0), surveillance épidémiologique (processus, types, qualités Ch. 38), MDO Décret 22-250 (44 Cat.1 / 14 Cat.2) et prophylaxie.', 'published', 1, $medjson$[{"id":"L2.1","courseId":"C2","order":1,"title":"Situation des MT (Monde/Algérie), chaîne \u0026 agent pathogène","durationMin":14,"sourceRef":"§ I à II, pages 2–5","bmCount":8,"bmRefs":["Ch. 12 Q1, Q3, Q5, Q6, Q10 (2021–2024)","Ch. 13 Q1–Q2 (2025)","Ch. 19 Q10 (2022)"],"priority":"very_high","priorityScore":85,"bmWarning":"⚠️ Nuance BM Ch. 12 Q1 vs Q6 : les MT sont principales causes de morbi-mortalité dans les PED (dans le monde, MNT = 74 %). En Algérie : ÉRADICATION de la poliomyélite et du paludisme autochtone, mais simple DIMINUTION de la tuberculose !","understand":{"intro":"Les maladies transmissibles restent un enjeu majeur de santé publique (notamment dans les PED et par les maladies émergentes/réémergentes). En 2024 et 2025, 5 QCM ont directement testé les résultats en Algérie et les propriétés de l’agent pathogène.","sections":[{"heading":"Transmissible vs Contagieuse \u0026 Résultats obtenus en Algérie","paragraphs":["\u003cstrong\u003eRègle fondamentale (p. 2) :\u003c/strong\u003e « Toutes les maladies contagieuses sont transmissibles, mais l’inverse n’est pas vrai » (ex. tétanos, paludisme, toxoplasmose, TIAC sont transmissibles mais NON contagieuses d’homme à homme)."],"bullets":["\u003cstrong\u003ePoliomyélite en Algérie :\u003c/strong\u003e \u003cstrong\u003eéradication\u003c/strong\u003e obtenue (attention : le QCM 2024 Ch. 12 Q3 retient « éradication », pas seulement « élimination »).","\u003cstrong\u003ePaludisme autochtone :\u003c/strong\u003e maîtrise puis \u003cstrong\u003eéradication/élimination\u003c/strong\u003e (certifié par l’OMS).","\u003cstrong\u003eTuberculose pulmonaire :\u003c/strong\u003e \u003cstrong\u003ediminution\u003c/strong\u003e de l’incidence (NON éliminée !).","\u003cstrong\u003eMTH \u0026 endémo-épidémiques :\u003c/strong\u003e manifestations sporadiques ou épidémiques (TIAC, typhoïde, leishmanioses, brucellose, méningites)."]},{"heading":"Les 4 maillons de la chaîne épidémiologique","paragraphs":["Toute transmission infectieuse suppose la succession de 4 maillons indissociables :"],"bullets":["\u003cstrong\u003e1) Agent pathogène :\u003c/strong\u003e caractérisé par pouvoir pathogène, virulence, contagiosité (R₀) et immunogénicité.","\u003cstrong\u003e2) Réservoir :\u003c/strong\u003e humain (malade ou porteur sain), animal (zoonoses) ou inanimé (tellurique, inerte, hydrique).","\u003cstrong\u003e3) Mode de transmission :\u003c/strong\u003e horizontale (directe ou indirecte via véhicule/vecteur) ou verticale (transplacentaire, génitale).","\u003cstrong\u003e4) Hôte réceptif :\u003c/strong\u003e état immunitaire, âge, nutrition, facteurs génétiques et environnementaux."]}],"tables":[{"title":"Distinction capitale : Pouvoir pathogène vs Virulence vs Contagiosité","headers":["Propriété","Définition exacte du cours","Mesure / Piège QCM"],"rows":[["Pouvoir pathogène","Capacité (aptitude) de provoquer des manifestations morbides chez l’hôte réceptif","Taux d’attaque, sévérité, létalité (PAS « exclusivement » la létalité !)"],["Virulence","Expression et intensité du pouvoir pathogène ; aptitude à se multiplier / reproduire la maladie","Dépend du germe (toxines, multiplication) et de l’hôte (BM Ch. 12 Q10 = B)"],["Contagiosité","Aptitude à se propager dans une collectivité donnée","Mesurée par R₀ : rougeole (très élevé) \u003e SARS-CoV-2 ; nulle dans brucellose/tétanos"]]}],"darija":"شفا على هاد 3 فروق في الكور تاع Dr Beichi : \u003cstrong\u003ePouvoir pathogène\u003c/strong\u003e = القدرة يديرلك مرض. \u003cstrong\u003eVirulence\u003c/strong\u003e = شدة المرض والقدرة على التكاثر (reproduire la maladie). \u003cstrong\u003eContagiosité\u003c/strong\u003e = سرعة الانتشار في المجتمع (\u003cstrong\u003eR₀\u003c/strong\u003e : بوحمرون \u003cem\u003erougeole\u003c/em\u003e أكثر انتشارا من \u003cem\u003eSARS-CoV-2\u003c/em\u003e !). وفي الجزائر : \u003cstrong\u003ePolio = Éradication\u003c/strong\u003e، \u003cstrong\u003ePaludisme autochtone = Éradiqué\u003c/strong\u003e، أما \u003cstrong\u003eTuberculose = نقصت برك (ماشي éliminée)\u003c/strong\u003e.","triad":{"toUnderstand":["Pourquoi une maladie transmissible (ex. tétanos, paludisme) n’est pas forcément contagieuse.","La différence entre capacité à causer un trouble (pouvoir pathogène), intensité/multiplication (virulence) et diffusion communautaire (contagiosité)."],"toMemorize":["Acquis Algérie : éradication poliomyélite, éradication paludisme autochtone, diminution tuberculose.","Définition de R₀ et fait que R₀(rougeole) \u003e R₀(SARS-CoV-2)."],"toRecognizeInQcm":["« capacité de provoquer des manifestations morbides » → Pouvoir pathogène (Ch. 12 Q5 B).","« aptitude à reproduire la maladie » → Virulence (Ch. 12 Q10 B).","« élimination de la tuberculose pulmonaire en Algérie » → TOUJOURS FAUX !"]}},"memorize":[{"id":"M_L2.1_1","category":"Distinction","title":"Transmissible vs Contagieuse","content":"Toutes les maladies contagieuses sont transmissibles, mais \u003cstrong\u003el’inverse est faux\u003c/strong\u003e (ex. paludisme, tétanos, TIAC = transmissibles non contagieuses).","highlight":true},{"id":"M_L2.1_2","category":"Liste","title":"Résultats sanitaires en Algérie","content":"\u003cstrong\u003eÉradication\u003c/strong\u003e de la poliomyélite ; \u003cstrong\u003eéradication/disparition\u003c/strong\u003e du paludisme autochtone ; \u003cstrong\u003ediminution\u003c/strong\u003e (non élimination) de la tuberculose pulmonaire.","highlight":true},{"id":"M_L2.1_3","category":"Définition","title":"Pouvoir pathogène vs Virulence vs Contagiosité","content":"\u003cstrong\u003ePouvoir pathogène :\u003c/strong\u003e capacité à provoquer des manifestations morbides. \u003cstrong\u003eVirulence :\u003c/strong\u003e intensité / aptitude à reproduire la maladie. \u003cstrong\u003eContagiosité :\u003c/strong\u003e aptitude à se propager dans une collectivité (\u003cstrong\u003eR₀\u003c/strong\u003e).","highlight":true},{"id":"M_L2.1_4","category":"Formule","title":"Taux de reproduction de base (R₀)","content":"Nombre moyen de sujets infectés par un cas contagieux dans une population \u003cstrong\u003eentièrement susceptible\u003c/strong\u003e. \u003cstrong\u003eR₀(rougeole) \u003e R₀(SARS-CoV-2)\u003c/strong\u003e.","highlight":true}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L2.2","courseId":"C2","order":2,"title":"Surveillance épidémiologique : processus, types \u0026 attributs qualité","durationMin":15,"sourceRef":"§ V, pages 6–8 + Complément BM Ch. 38 (7 QCM)","bmCount":16,"bmRefs":["Ch. 12 Q4, Q9 (2021, 2024)","Ch. 38 Q1–Q7, Q9–Q15 (2019–2022, ND)"],"priority":"very_high","priorityScore":90,"bmWarning":"⚠️ Complément indispensable : 7 QCM de Ch. 38 testent les attributs de qualité d’un système de surveillance (Représentativité, Souplesse, Se, Sp, Simplicité, Acceptabilité) non détaillés dans le polycopié de 10 p. De plus, Ch. 12 Q9 / Ch. 38 Q1 / Q11 ont des clés divergentes sur la surveillance MDO (retenir : passive + obligatoire + professionnels).","understand":{"intro":"Avec 16 QCM dans la BM (Ch. 12 + Ch. 38), la surveillance épidémiologique est le cœur absolu du Cours 2. Elle repose sur un processus CONTINU en 4 étapes dont la finalité ultime est l’ACTION.","sections":[{"heading":"Définition, 4 étapes, finalité \u0026 circuit algérien","paragraphs":["La surveillance épidémiologique est un \u003cstrong\u003eprocessus continu et systématique\u003c/strong\u003e (JAMAIS ponctuel — contrairement à une enquête !)."],"bullets":["\u003cstrong\u003e4 étapes :\u003c/strong\u003e 1) Collecte des données → 2) Compilation / regroupement / tabulation → 3) Analyse et interprétation → 4) Diffusion (rétro-information).","\u003cstrong\u003eFinalité ultime :\u003c/strong\u003e produire de l’information \u003cstrong\u003epour mettre en place des actions de contrôle\u003c/strong\u003e / aide à la décision (Ch. 38 Q12 C).","\u003cstrong\u003eCondition de fonctionnement :\u003c/strong\u003e la \u003cstrong\u003erapidité du traitement de l’information et sa diffusion\u003c/strong\u003e (Ch. 38 Q14 D).","\u003cstrong\u003eCircuit en Algérie :\u003c/strong\u003e \u003cstrong\u003eSEMEP\u003c/strong\u003e (niveau local) → \u003cstrong\u003eDSP\u003c/strong\u003e (wilaya) → \u003cstrong\u003eINSP + DGPPS / MS\u003c/strong\u003e (national)."]},{"heading":"Les 3 modes de surveillance (Passive, Active, Sentinelle)","paragraphs":["Le mode de collecte distingue la manière dont l’information remonte vers l’autorité sanitaire :"],"bullets":["\u003cstrong\u003eSurveillance passive :\u003c/strong\u003e le système attend la remontée routinière des données recueillies au cours de l’activité médicale, sans sollicitation active (ex. \u003cstrong\u003eMDO\u003c/strong\u003e, \u003cstrong\u003eTIAC\u003c/strong\u003e).","\u003cstrong\u003eSurveillance active :\u003c/strong\u003e les autorités sanitaires recherchent activement et périodiquement les cas auprès des services (ex. \u003cstrong\u003ePFA\u003c/strong\u003e pour la poliomyélite).","\u003cstrong\u003eSurveillance sentinelle :\u003c/strong\u003e échantillon de praticiens/services/labos \u003cstrong\u003evolontaires\u003c/strong\u003e (non exhaustif) déclarant régulièrement (ex. réseau \u003cstrong\u003eGROG\u003c/strong\u003e pour la grippe dans 6 wilayas ; note : considérée comme active dans Ch. 12 Q4 A)."]}],"tables":[{"title":"Les 6 attributs de qualité d’un système de surveillance (7 QCM BM Ch. 38 !)","headers":["Attribut","Signification exacte à connaître pour les QCM","Formule / Indicateur"],"rows":[["Sensibilité (Se)","Capacité à identifier correctement la maladie / les vrais positifs","VP / (VP + FN)"],["Spécificité (Sp)","Capacité à identifier l’absence de maladie / les vrais négatifs","VN / (VN + FP)"],["Représentativité","La maladie est bien décrite selon les caractères temps, lieu et personne (portrait fidèle)","Distribution T / L / P"],["Souplesse","Capacité à s’adapter aux changements de définition de cas ou à de nouvelles sources d’information","Adaptabilité"],["Simplicité","Structure légère, procédures de recueil rapides, définition de cas facile à utiliser","Légèreté \u0026 rapidité"],["Acceptabilité","Volonté de participation des acteurs : taux de participation + qualité des rapports transmis","Taux de participation"]]}],"darija":"الـ \u003cstrong\u003eSurveillance\u003c/strong\u003e عملية \u003cstrong\u003eمستمرة (continue)\u003c/strong\u003e ماشي ponctuelle ! الهدف تاعها هو \u003cstrong\u003el’action\u003c/strong\u003e (اتخاذ القرار). \u003cstrong\u003ePassive\u003c/strong\u003e = الدولة تستنى الطبيب يصرح (MDO، TIAC). \u003cstrong\u003eActive\u003c/strong\u003e = الدولة تروح تحوس على الحالات (PFA). \u003cstrong\u003eSentinelle\u003c/strong\u003e = عينة أطباء متطوعين (GROG في 6 ولايات). واحفظ جدول الصفات الستة (Ch. 38) راهو طاح 7 مرات !","triad":{"toUnderstand":["Pourquoi la diffusion rapide (rétro-information) conditionne l’efficacité de la surveillance.","La différence entre une surveillance exhaustive/obligatoire (MDO) et un réseau sentinelle volontaire (GROG)."],"toMemorize":["Les 4 étapes : collecte → compilation → analyse → diffusion.","Les formules exactes de Sensibilité = VP/(VP+FN) et Spécificité = VN/(VN+FP).","Les mots-clés exacts des 6 attributs (Représentativité = T/L/P ; Souplesse = adaptation définition/sources ; Acceptabilité = participation)."],"toRecognizeInQcm":["« processus ponctuel » → TOUJOURS FAUX pour la surveillance !","« s’adapter à des changements de définition de cas ou nouvelles sources » → Souplesse (Ch. 38 Q3 BC).","« léger de par sa structure, recueil rapide » → Simplicité (Ch. 38 Q15 A)."]}},"memorize":[{"id":"M_L2.2_1","category":"Définition","title":"Surveillance épidémiologique (4 étapes \u0026 finalité)","content":"Processus \u003cstrong\u003econtinu\u003c/strong\u003e (collecte, compilation, analyse, diffusion) dont la finalité est l’\u003cstrong\u003eaction de contrôle\u003c/strong\u003e, conditionné par la \u003cstrong\u003erapidité du traitement et de la diffusion\u003c/strong\u003e.","highlight":true},{"id":"M_L2.2_2","category":"Distinction","title":"Passive vs Active vs Sentinelle","content":"\u003cstrong\u003ePassive :\u003c/strong\u003e attend la remontée (MDO, TIAC). \u003cstrong\u003eActive :\u003c/strong\u003e recherche périodique (PFA). \u003cstrong\u003eSentinelle :\u003c/strong\u003e échantillon volontaire (GROG grippe, 6 wilayas ; classée active en Ch. 12 Q4).","highlight":true},{"id":"M_L2.2_3","category":"Formule","title":"Sensibilité \u0026 Spécificité (Ch. 38)","content":"\u003cstrong\u003eSensibilité\u003c/strong\u003e = \u003cspan class=\"math-frac\"\u003e\u003cspan\u003eVP\u003c/span\u003e\u003cspan\u003eVP + FN\u003c/span\u003e\u003c/span\u003e (vrais positifs). \u003cstrong\u003eSpécificité\u003c/strong\u003e = \u003cspan class=\"math-frac\"\u003e\u003cspan\u003eVN\u003c/span\u003e\u003cspan\u003eVN + FP\u003c/span\u003e\u003c/span\u003e (vrais négatifs / absence de maladie).","highlight":true},{"id":"M_L2.2_4","category":"Liste","title":"Représentativité, Souplesse, Simplicité, Acceptabilité","content":"\u003cstrong\u003eReprésentativité :\u003c/strong\u003e temps/lieu/personne. \u003cstrong\u003eSouplesse :\u003c/strong\u003e adaptation changement définition/sources. \u003cstrong\u003eSimplicité :\u003c/strong\u003e structure légère/recueil rapide. \u003cstrong\u003eAcceptabilité :\u003c/strong\u003e taux de participation + qualité rapports.","highlight":true}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L2.3","courseId":"C2","order":3,"title":"MDO algériennes (Décret 22-250) \u0026 prophylaxie en 3 axes","durationMin":13,"sourceRef":"§ III, IV, VI \u0026 Annexe Décret 22-250, pages 5–10","bmCount":6,"bmRefs":["Ch. 12 Q2 (2024)","Ch. 12 Q7–Q8 (2022)","Ch. 12 Q11–Q12 (2021)","Ch. 12 Q13 (ND)"],"priority":"very_high","priorityScore":85,"understand":{"intro":"Le Décret exécutif n° 22-250 du 30 juin 2022 actualise la liste officielle algérienne des Maladies à Déclaration Obligatoire (MDO) en deux catégories bien distinctes — source directe de 5 QCM BM très répétitifs.","sections":[{"heading":"Décret exécutif n° 22-250 du 30 juin 2022 : Catégorie 1 vs Catégorie 2","paragraphs":["La déclaration est \u003cstrong\u003eobligatoire\u003c/strong\u003e pour tous les \u003cstrong\u003emédecins\u003c/strong\u003e (publics et libéraux) et \u003cstrong\u003ebiologistes\u003c/strong\u003e (publics et privés)."],"bullets":["\u003cstrong\u003eCatégorie 1 (44 maladies — surveillance nationale) :\u003c/strong\u003e Rubéole, Peste, Méningite à méningocoque, TIAC, Botulisme, Rage, Tuberculose, VIH/SIDA, Hépatites A/B/C, PFA, Paludisme, Tétanos, Brucellose, Leishmanioses, ISO, PAVM, BMR…","\u003cstrong\u003eCatégorie 2 (14 maladies — surveillance internationale / notifiables OMS) :\u003c/strong\u003e \u003cstrong\u003eSRAS (SARS)\u003c/strong\u003e, \u003cstrong\u003eEbola\u003c/strong\u003e, Choléra, Fièvre jaune, Variole, Poliomyélite (virus sauvage), SARS-CoV-2, MERS, \u003cstrong\u003eGrippe humaine causée par un nouveau sous-type\u003c/strong\u003e, Dengue, Chikungunya, Fièvre de la Vallée du Rift, West Nile, Autres fièvres hémorragiques.","\u003cstrong\u003ePièges hors-liste MDO (tombés en QCM) :\u003c/strong\u003e Grippe saisonnière banale (NON !), Ankylostomiase (NON !), Maladie de Lyme (NON !)."]},{"heading":"Prophylaxie des MT : rupture de la chaîne en 3 axes","paragraphs":["Toute lutte contre une MT vise à rompre au moins un maillon de la chaîne épidémiologique :"],"bullets":["\u003cstrong\u003e1) Action sur le réservoir :\u003c/strong\u003e isolement, traitement curatif, dépistage/surveillance des suspects et contacts, déclaration obligatoire, lutte contre réservoir animal.","\u003cstrong\u003e2) Action sur la transmission :\u003c/strong\u003e IEC (éducation sanitaire), hygiène du milieu (MTH : eau potable, assainissement), désinfection, désinsectisation/dératisation.","\u003cstrong\u003e3) Protection du sujet réceptif :\u003c/strong\u003e immunisation active (vaccination), immunisation passive / \u003cstrong\u003eséroprophylaxie\u003c/strong\u003e (SAS, SAT), \u003cstrong\u003echimioprophylaxie\u003c/strong\u003e (paludisme, méningite à méningocoque)."]}],"tables":[{"title":"MDO Algérie : Tableau anti-piège QCM (Décret 22-250)","headers":["Maladie testée dans la BM","Statut MDO en Algérie","Catégorie / Notification OMS"],"rows":[["SRAS (SARS) \u0026 Ebola","OUI — MDO","Catégorie 2 — Obligatoirement notifiable à l’OMS (Ch. 12 Q7, Q11, Q13)"],["Rubéole, Peste, Méningite à méningocoque","OUI — MDO","Catégorie 1 — Surveillance nationale (Ch. 12 Q8, Q12)"],["Grippe saisonnière / Ankylostomiase / Lyme","NON (piège !)","Seule la grippe par NOUVEAU sous-type est MDO Cat. 2 !"]]}],"darija":"احفظ الأرقام تاع المرسوم \u003cstrong\u003eDécret 22-250 (30 juin 2022)\u003c/strong\u003e : \u003cstrong\u003e44 أمراض في Catégorie 1\u003c/strong\u003e (وطني) و \u003cstrong\u003e14 في Catégorie 2\u003c/strong\u003e (دولي للـ OMS، كيما \u003cstrong\u003eSRAS و Ebola\u003c/strong\u003e). رد بالك من فخ الـ BM : « Grippe » وحدها ماشي MDO، و« 42 MDO de l’arrêté de 1990/2013 » فخ قديم ما تكوشيهش !","triad":{"toUnderstand":["Pourquoi la Catégorie 2 correspond aux urgences de portée internationale (RSI / OMS).","Comment chaque mesure prophylactique cible un maillon précis (réservoir, transmission ou sujet réceptif)."],"toMemorize":["Décret 22-250 du 30 juin 2022 : 44 Cat. 1 + 14 Cat. 2 ; déclarants = médecins + biologistes.","Les 14 maladies de Catégorie 2 (SRAS, Ebola, Choléra, Fièvre jaune, Variole, Polio, COVID-19, MERS, Grippe nouveau sous-type…).","Modélisation (Ch. 12 Q2) = étude prévisionnelle et tendancielle des MT."],"toRecognizeInQcm":["SRAS ou Ebola → cocher « Catégorie 2 » + « Obligatoirement notifiable à l’OMS » (AD).","Rejeter « arrêté de novembre 1990 » ou « décembre 2013 » pour SRAS et Ebola.","Dans une liste MDO : cocher Rubéole, Peste, Méningite à méningocoque ; exclure Grippe (simple), Lyme, Ankylostomiase."]}},"memorize":[{"id":"M_L2.3_1","category":"Seuil / Chiffre","title":"Décret 22-250 du 30 juin 2022 (MDO)","content":"\u003cstrong\u003e44 maladies Catégorie 1\u003c/strong\u003e (surveillance nationale) + \u003cstrong\u003e14 maladies Catégorie 2\u003c/strong\u003e (surveillance internationale, notifiables à l’OMS). Déclarants : \u003cstrong\u003emédecins et biologistes\u003c/strong\u003e.","highlight":true},{"id":"M_L2.3_2","category":"Liste","title":"Les 14 MDO de Catégorie 2 (OMS)","content":"Choléra, Fièvre jaune, \u003cstrong\u003eEbola\u003c/strong\u003e, Variole, Poliomyélite, \u003cstrong\u003eSRAS\u003c/strong\u003e, SARS-CoV-2, MERS, \u003cstrong\u003eGrippe par nouveau sous-type\u003c/strong\u003e, Dengue, Chikungunya, Vallée du Rift, West Nile, Autres fièvres hémorragiques.","highlight":true},{"id":"M_L2.3_3","category":"Piège QCM","title":"Pièges classiques MDO dans la BM","content":"\u003cstrong\u003eOUI (Cat. 1) :\u003c/strong\u003e Rubéole, Peste, Méningite à méningocoque, TIAC. \u003cstrong\u003eNON :\u003c/strong\u003e Grippe saisonnière, Ankylostomiase, Maladie de Lyme.","highlight":true},{"id":"M_L2.3_4","category":"Classification","title":"Prophylaxie en 3 axes","content":"1) \u003cstrong\u003eRéservoir\u003c/strong\u003e (isolement, traitement, MDO) ; 2) \u003cstrong\u003eTransmission\u003c/strong\u003e (IEC, hygiène, vecteurs) ; 3) \u003cstrong\u003eRéceptivité\u003c/strong\u003e (vaccination, séroprophylaxie SAS/SAT, chimioprophylaxie).","highlight":false},{"id":"M_L2.3_5","category":"Définition","title":"Modélisation en surveillance (Ch. 12 Q2)","content":"\u003cstrong\u003eÉtude prévisionnelle et tendancielle\u003c/strong\u003e de l’évolution des maladies transmissibles.","highlight":false}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]}]$medjson$::jsonb, $medjson$[]$medjson$::jsonb, $medjson${"analyzedAt":null,"engine":"curated","totalPages":0,"lowConfidencePages":[],"warnings":[],"status":"none"}$medjson$::jsonb, NULL, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, module_id, code, title, short_title, professor, source_files, bm_count, bm_shared_note, bm_recent_count, unique_concepts, priority, priority_score, vigilance_2026, summary, status, version, lessons, attachments, ai_extraction, ppt_import, created_at, updated_at, published_at) VALUES ('C3', 'M1', 'C3', 'Épidémiologie des maladies non transmissibles (MNT)', 'Épidémiologie des MNT', 'Faculté de médecine Batna 2 (2025/2026)', $medjson$["EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx (30 slides)"]$medjson$::jsonb, 7, '+ 5 recoupements directs avec C1 (Prévention)', 3, 4, 'high', 76, FALSE, 'Fardeau mondial (74 %) et algérien (80 %) des MNT, classification des facteurs de risque, transition épidémiologique, histoire naturelle, les 4 niveaux de prévention, surveillance STEPS OMS, DALYs et « Best Buys ».', 'published', 1, $medjson$[{"id":"L3.1","courseId":"C3","order":1,"title":"Fardeau MNT (Monde/Algérie), facteurs de risque \u0026 transition","durationMin":11,"sourceRef":"Slides 4–14","bmCount":2,"bmRefs":["Ch. 11 Q1 (2022)","Ch. 19 Q2 (2025)"],"priority":"high","priorityScore":62,"understand":{"intro":"Les MNT sont des maladies chroniques, non infectieuses, de longue durée et de progression lente. Elles dominent aujourd’hui la mortalité mondiale et algérienne suite à la transition épidémiologique.","sections":[{"heading":"Les 4 catégories majeures (+ troubles mentaux) \u0026 chiffres clés","paragraphs":["Les 4 grands groupes sont les \u003cstrong\u003eMCV\u003c/strong\u003e (coronaropathies, AVC, HTA), les \u003cstrong\u003eCancers\u003c/strong\u003e, les \u003cstrong\u003eMaladies Respiratoires Chroniques\u003c/strong\u003e (BPCO, asthme) et le \u003cstrong\u003eDiabète\u003c/strong\u003e (surtout type 2)."],"bullets":["\u003cstrong\u003eDans le monde :\u003c/strong\u003e \u003cstrong\u003e74 % des décès\u003c/strong\u003e (41 millions/an), dont \u003cstrong\u003e86 % dans les PRFI\u003c/strong\u003e ; coût estimé à 7 000 milliards USD (2020–2035).","\u003cstrong\u003eEn Algérie (transition dès les années 1980) :\u003c/strong\u003e espérance de vie \u003cstrong\u003e77 ans\u003c/strong\u003e (2013), MNT = \u003cstrong\u003e80 % des décès\u003c/strong\u003e (\u003cstrong\u003eMCV 35 %\u003c/strong\u003e, \u003cstrong\u003eCancers 15 %\u003c/strong\u003e, \u003cstrong\u003eDiabète \u003e 14 %\u003c/strong\u003e, \u003cstrong\u003eObésité femmes \u003e 27 %\u003c/strong\u003e)."]},{"heading":"Facteur de risque vs Marqueur de risque \u0026 les 4 familles de FDR","paragraphs":["En QCM (`Ch. 11 Q1`), un \u003cstrong\u003efacteur de risque\u003c/strong\u003e est défini comme \u003cstrong\u003eune variable qui augmente la probabilité de survenue de la maladie\u003c/strong\u003e (ce n’est JAMAIS une constante et il se distingue d’un simple marqueur non modifiable)."],"bullets":["\u003cstrong\u003eComportementaux :\u003c/strong\u003e tabagisme (\u003cstrong\u003e8,7 M décès/an\u003c/strong\u003e), alcool (\u003cstrong\u003e2,3 M\u003c/strong\u003e), alimentation malsaine (sel, sucre, graisses), sédentarité.","\u003cstrong\u003eBiologiques :\u003c/strong\u003e HTA (1er FDR cardiovasculaire), hyperglycémie, dyslipidémie, surpoids/obésité.","\u003cstrong\u003eSociaux \u0026 environnementaux :\u003c/strong\u003e pauvreté, faible éducation, urbanisation rapide, pollution air/eau.","\u003cstrong\u003eNon modifiables (marqueurs) :\u003c/strong\u003e âge, sexe, hérédité."]}],"tables":[{"title":"Chiffres clés MNT : Monde vs Algérie","headers":["Indicateur","Monde","Algérie"],"rows":[["Part des MNT dans les décès","74 % (41 millions/an)","~80 % des décès"],["Principales causes / prévalences","86 % des décès prématurés dans PRFI","MCV 35 % ; Cancers 15 % ; Diabète \u003e 14 % ; Obésité femmes \u003e 27 %"],["Transition épidémiologique","Recul infectieux → hausse espérance de vie","Amorcée années 1980 ; EV = 77 ans (2013)"]]}],"darija":"في الـ MNT، الـ \u003cstrong\u003eFacteur de risque\u003c/strong\u003e هو \u003cstrong\u003eمتغير (variable) يزيد احتمال ظهور المرض\u003c/strong\u003e (عمره ما يكون constante !). والـ \u003cstrong\u003eTransition épidémiologique\u003c/strong\u003e (طاحت في 2025) علامتها الأساسية هي \u003cstrong\u003eزيادة أمل الحياة (augmentation de l’espérance de vie)\u003c/strong\u003e وتراجع الأمراض المعدية مقابل ارتفاع الأمراض المزمنة (80 % من الوفيات في الجزائر).","triad":{"toUnderstand":["Pourquoi la hausse de l’espérance de vie est la marque centrale de la transition épidémiologique.","La distinction entre facteur de risque modifiable (causal) et marqueur non modifiable (âge, sexe, hérédité)."],"toMemorize":["Définition FDR : variable qui augmente la probabilité de survenue de la maladie.","Chiffres Algérie : MNT 80 %, MCV 35 %, Cancers 15 %, Diabète \u003e 14 %, Obésité femmes \u003e 27 %, EV 77 ans.","Monde : 74 % décès (41 M/an), tabac 8,7 M/an, alcool 2,3 M/an."],"toRecognizeInQcm":["Facteur de risque → cocher « variable qui augmente la probabilité… », rejeter « constante » et « marqueur de risque ».","Transition épidémiologique → cocher « augmentation de l’espérance de vie »."]}},"memorize":[{"id":"M_L3.1_1","category":"Définition","title":"Facteur de risque dans les MNT","content":"\u003cstrong\u003eVariable\u003c/strong\u003e (jamais une constante !) qui \u003cstrong\u003eaugmente la probabilité de survenue de la maladie\u003c/strong\u003e (≠ marqueur de risque).","highlight":true},{"id":"M_L3.1_2","category":"Seuil / Chiffre","title":"Fardeau MNT — Monde vs Algérie","content":"\u003cstrong\u003eMonde :\u003c/strong\u003e 74 % des décès (41 M/an, 86 % PRFI). \u003cstrong\u003eAlgérie :\u003c/strong\u003e ~\u003cstrong\u003e80 %\u003c/strong\u003e des décès (MCV 35 %, Cancers 15 %, Diabète \u003e 14 %, Obésité femmes \u003e 27 %, EV 77 ans).","highlight":true},{"id":"M_L3.1_3","category":"Classification","title":"Les 4 familles de FDR des MNT","content":"1) \u003cstrong\u003eComportementaux\u003c/strong\u003e (tabac 8,7 M, alcool 2,3 M, diète, sédentarité), 2) \u003cstrong\u003eBiologiques\u003c/strong\u003e (HTA, diabète, lipides, obésité), 3) \u003cstrong\u003eSocio-environnementaux\u003c/strong\u003e, 4) \u003cstrong\u003eNon modifiables\u003c/strong\u003e (âge, sexe, hérédité).","highlight":false},{"id":"M_L3.1_4","category":"Définition","title":"Transition épidémiologique","content":"Recul des maladies infectieuses, \u003cstrong\u003eaugmentation de l’espérance de vie\u003c/strong\u003e et prédominance des MNT (amorcée en Algérie dans les années 1980).","highlight":true}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L3.2","courseId":"C3","order":2,"title":"Histoire naturelle \u0026 les 4 niveaux de prévention des MNT","durationMin":10,"sourceRef":"Slides 17–22","bmCount":5,"bmRefs":["Ch. 11 Q2–Q4 (2021–2022, ND)","Ch. 29 Q1–Q2 (2025)"],"priority":"very_high","priorityScore":100,"understand":{"intro":"3 des 4 questions du chapitre BM 11 et 2 questions de 2025 portent sur la prévention des MNT — en particulier la prévention secondaire (dépistage / baisse de prévalence) et la prévention quaternaire (surmédicalisation).","sections":[{"heading":"Chronologie / Histoire naturelle des MNT (4 stades)","paragraphs":["Avant l’apparition des symptômes, une MNT évolue silencieusement pendant des années — c’est cette fenêtre qui rend le dépistage efficace :"],"bullets":["\u003cstrong\u003e1) Exposition prolongée aux FDR\u003c/strong\u003e (incubation / phase de susceptibilité) → cible de la \u003cstrong\u003eprévention primaire\u003c/strong\u003e.","\u003cstrong\u003e2) Stade préclinique\u003c/strong\u003e (anomalies biologiques sans symptômes) → cible de la \u003cstrong\u003eprévention secondaire (dépistage)\u003c/strong\u003e.","\u003cstrong\u003e3) Stade clinique\u003c/strong\u003e (symptômes, diagnostic) → prise en charge et \u003cstrong\u003eprévention tertiaire\u003c/strong\u003e.","\u003cstrong\u003e4) Complications à long terme / phase terminale\u003c/strong\u003e (multimorbidité, incapacités)."]}],"tables":[{"title":"Application exacte des 4 niveaux de prévention aux MNT","headers":["Niveau","Effet épidémiologique","Exemples spécifiques MNT (tombés en QCM)"],"rows":[["Primaire","Diminue l’INCIDENCE (nouveaux cas)","Arrêter le tabac pour prévenir le cancer pulmonaire (Ch. 29 Q2 B), nutrition, activité physique"],["Secondaire","Diminue la PRÉVALENCE (« nouveaux et anciens cas » — Ch. 11 Q2 D)","Dépistage : mammographie, FCV, coloscopie, glycémie, scanner chez ancien fumeur"],["Tertiaire","Prévient complications et invalidité","Traiter une rétinopathie diabétique, réadaptation post-IDM"],["Quaternaire","Réduit les interventions inutiles / surmédicalisation (Ch. 29 Q1 B)","Éviter bilans ou prescriptions sans bénéfice clinique prouvé"]]}],"darija":"ركز مليح على هاد الفخ في `Ch. 11 Q2` : كي يقولك « diminuer les nouveaux et anciens cas » راهي معناها \u003cstrong\u003ePrévalence = Prévention secondaire\u003c/strong\u003e ! وكي يقولك « scanner thoracique chez un ancien fumeur » راهي \u003cstrong\u003eSecondaire (dépistage)\u003c/strong\u003e ماشي Primaire (الـ Primaire هي توقيف الدخان قبل المرض).","triad":{"toUnderstand":["Le lien entre les 4 stades de l’histoire naturelle d’une MNT et les 4 niveaux de prévention.","Pourquoi le dépistage (secondaire) cible le stade préclinique asymptomatique."],"toMemorize":["Prévention secondaire = diminuer la prévalence (« nouveaux et anciens cas ») + déceler précocement par dépistage.","Prévention quaternaire = réduire la prescription d’interventions inutiles (surmédicalisation)."],"toRecognizeInQcm":["Arrêt du tabac → Primaire ; Mammographie / scanner fumeur → Secondaire ; Rétinopathie diabétique → Tertiaire.","« nouveaux et anciens cas » = synonyme exact de « prévalence » → Secondaire."]}},"memorize":[{"id":"M_L3.2_1","category":"Liste","title":"Chronologie des MNT (4 stades)","content":"Exposition aux FDR → \u003cstrong\u003eStade préclinique\u003c/strong\u003e (asymptomatique) → \u003cstrong\u003eStade clinique\u003c/strong\u003e → \u003cstrong\u003eComplications / phase terminale\u003c/strong\u003e.","highlight":false},{"id":"M_L3.2_2","category":"Piège QCM","title":"Prévention secondaire des MNT (3× en BM)","content":"Déceler précocement (axe principal : \u003cstrong\u003edépistage\u003c/strong\u003e) pour \u003cstrong\u003ediminuer la prévalence\u003c/strong\u003e (= diminuer les \u003cstrong\u003enouveaux et anciens cas\u003c/strong\u003e).","highlight":true},{"id":"M_L3.2_3","category":"Définition","title":"Prévention quaternaire (2025)","content":"Objectif principal : \u003cstrong\u003eréduire la prescription d’interventions inutiles\u003c/strong\u003e et protéger contre la \u003cstrong\u003esurmédicalisation\u003c/strong\u003e.","highlight":true}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L3.3","courseId":"C3","order":3,"title":"Surveillance MNT, enquête STEPS OMS, DALYs \u0026 « Best Buys »","durationMin":9,"sourceRef":"Slides 23–29","bmCount":0,"bmRefs":[],"priority":"low","priorityScore":25,"understand":{"intro":"Bien que cette section n’ait pas encore donné lieu à un QCM dans la BM 2012–2025, elle contient 4 notions phares du cours 2025/2026 (STEPS, DALYs, taux standardisé, Best Buys) particulièrement faciles à évaluer en examen.","sections":[{"heading":"Outils de surveillance \u0026 indicateurs de charge morbide","paragraphs":["Contrairement aux MT aiguës (MDO), la surveillance des MNT repose sur des dispositifs au long cours :"],"bullets":["\u003cstrong\u003eRegistres de morbidité :\u003c/strong\u003e registres du cancer, du diabète, des AVC.","\u003cstrong\u003eEnquête STEPS de l’OMS :\u003c/strong\u003e approche standardisée de surveillance des FDR en \u003cstrong\u003e3 étapes\u003c/strong\u003e : Step 1 (questionnaire comportemental), Step 2 (mesures physiques : poids, taille, TA), Step 3 (mesures biochimiques : glycémie, lipides).","\u003cstrong\u003eStratégie OMS « Best Buys » :\u003c/strong\u003e interventions au meilleur rapport coût-efficacité (taxation du tabac et boissons sucrées, réduction du sel, étiquetage nutritionnel, promotion activité physique)."]}],"tables":[{"title":"Indicateurs de comparaison \u0026 de charge des MNT","headers":["Indicateur","Définition \u0026 Utilité"],"rows":[["Taux brut de mortalité","Nombre de décès / population totale sans ajustement d’âge (biaisé par la structure d’âge)"],["Taux standardisé sur l’âge","Ajusté sur une population de référence → permet des comparaisons équitables entre pays"],["DALYs (AVAI)","Années de vie ajustées sur l’incapacité = YLL (années perdues par décès prématuré) + YLD (années vécues avec incapacité)"]]}],"darija":"الـ \u003cstrong\u003eDALYs\u003c/strong\u003e تجمع زوج حوايج : السنين لي ضاعو بالموت المبكر (YLL) + السنين لي عاشهم المريض بالإعاقة (YLD). و\u003cstrong\u003eSTEPS\u003c/strong\u003e تاع l’OMS فيها 3 مراحل : استبيان → قياسات جسدية (طول/وزن/ضغط) → تحاليل دم (سكر/دهون).","triad":{"toUnderstand":["Pourquoi on utilise des taux standardisés (et non bruts) pour comparer la mortalité MNT entre pays jeunes et pays âgés.","Comment les DALYs capturent à la fois mortalité prématurée et incapacité chronique."],"toMemorize":["DALYs = YLL (mortalité prématurée) + YLD (incapacité).","STEPS OMS = 3 étapes (questionnaire, mesures physiques, biochimie).","Best Buys = mesures très coût-efficaces (taxation tabac, réduction sel, étiquetage)."],"toRecognizeInQcm":["Comparaison équitable entre pays de structures d’âge différentes → Taux standardisé.","Indicateur combinant mortalité prématurée et morbidité/incapacité → DALYs."]}},"memorize":[{"id":"M_L3.3_1","category":"Formule","title":"DALYs (AVAI)","content":"\u003cstrong\u003eDALY = YLL + YLD\u003c/strong\u003e (années de vie perdues par mortalité prématurée + années vécues avec incapacité).","highlight":true},{"id":"M_L3.3_2","category":"Classification","title":"Enquête STEPS (OMS)","content":"Surveillance standardisée des FDR des MNT en \u003cstrong\u003e3 étapes\u003c/strong\u003e : (1) Questionnaire, (2) Mesures physiques, (3) Mesures biochimiques.","highlight":true},{"id":"M_L3.3_3","category":"Distinction","title":"Taux brut vs Taux standardisé","content":"Le \u003cstrong\u003etaux standardisé\u003c/strong\u003e ajuste sur la structure d’âge pour comparer équitablement deux populations ou pays.","highlight":false},{"id":"M_L3.3_4","category":"Définition","title":"Stratégie OMS « Best Buys »","content":"Interventions de santé publique très \u003cstrong\u003ecoût-efficaces\u003c/strong\u003e (taxation tabac, réduction sel, étiquetage nutritionnel, lutte contre sédentarité).","highlight":false}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]}]$medjson$::jsonb, $medjson$[]$medjson$::jsonb, $medjson${"analyzedAt":null,"engine":"curated","totalPages":0,"lowConfidencePages":[],"warnings":[],"status":"none"}$medjson$::jsonb, NULL, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, module_id, code, title, short_title, professor, source_files, bm_count, bm_shared_note, bm_recent_count, unique_concepts, priority, priority_score, vigilance_2026, summary, status, version, lessons, attachments, ai_extraction, ppt_import, created_at, updated_at, published_at) VALUES ('C4', 'M2', 'C4', 'Investigation d’une épidémie', 'Investigation Épidémie', 'Dr F. BEICHI (Université Batna 2)', $medjson$["investigation d\u0027une épidémie.pdf (8 pages)"]$medjson$::jsonb, 12, '+ 2 liens directs en C5 (TIAC Ch. 6 Q1–Q2) — 5 QCM en 2025 !', 5, 8, 'very_high', 86, FALSE, 'Définitions (épidémie, outbreak, endémie, pandémie, source ponctuelle vs persistante), objectifs, phase descriptive (fausses épidémies, collecte de cas, courbe épidémique, taux d’attaque) et phase analytique (cohorte rétrospective vs cas-témoins).', 'published', 1, $medjson$[{"id":"L4.1","courseId":"C4","order":1,"title":"Définitions de base (Épidémie, Outbreak, Sources) \u0026 objectifs","durationMin":10,"sourceRef":"§ I et II, pages 2–3","bmCount":5,"bmRefs":["Ch. 19 Q1 (2025)","Ch. 19 Q4 (2025)","Ch. 19 Q5 (2025)","Ch. 19 Q6 (2025)","Ch. 19 Q15 (ND)"],"priority":"very_high","priorityScore":86,"understand":{"intro":"Quatre questions sur 5 tombées en 2025 dans le chapitre Investigation portent directement sur les définitions des pages 2 et 3 ! Chaque mot compte.","sections":[{"heading":"Objectifs généraux d’une investigation épidémiologique","paragraphs":["L’investigation est une intervention \u003cstrong\u003erapide et limitée dans le temps\u003c/strong\u003e (contrairement à la surveillance qui est permanente)."],"bullets":["\u003cstrong\u003eObjectifs principaux (Ch. 19 Q1 C) :\u003c/strong\u003e \u003cstrong\u003einterrompre la transmission / arrêter l’épidémie\u003c/strong\u003e et \u003cstrong\u003eprévenir la survenue de nouveaux cas / épisodes\u003c/strong\u003e.","\u003cstrong\u003eObjectifs secondaires :\u003c/strong\u003e approfondir les connaissances sur la maladie/agent, évaluer ou créer un système de surveillance, enseigner l’épidémiologie de terrain."]},{"heading":"Source ponctuelle vs Source persistante \u0026 Véhicule","paragraphs":["La distinction sur la durée d’émission de l’agent pathogène est tombée en 2025 (`Ch. 19 Q4`) :"],"bullets":["\u003cstrong\u003eSource ponctuelle :\u003c/strong\u003e libère l’agent pathogène sur une \u003cstrong\u003ecourte période uniquement\u003c/strong\u003e (ex. repas contaminé dans une TIAC) → un seul pic bref.","\u003cstrong\u003eSource persistante :\u003c/strong\u003e libère l’agent de manière \u003cstrong\u003econtinue/prolongée\u003c/strong\u003e (ex. pollution/eau contaminée en continu — piège : PAS « épisodique » !).","\u003cstrong\u003eVéhicule :\u003c/strong\u003e support physique assurant la diffusion entre la source et la population (ex. aliment, eau)."]}],"tables":[{"title":"Distinction Temps / Espace des phénomènes épidémiques","headers":["Terme","Temps","Espace","Définition clé"],"rows":[["Épidémie","Limité","Limité","Excès de cas par rapport au niveau habituel/attendu (Ch. 19 Q6 B \u0026 Q15 CD)"],["Outbreak (cas groupés)","Limité","Très circonscrit","Épidémie de taille limitée géographiquement ou dans le temps (Ch. 19 Q5 B)"],["Endémie","Illimité (constante)","Limité","Présence habituelle continue ou discontinue dans une région"],["Pandémie","Limité (vagues)","Illimité","Épidémie très étendue géographiquement (plusieurs continents)"],["Éclosion","Début","Limité","Développement initial d’une épidémie"]]}],"darija":"فرق ساهل بزاف وطاح 4 مرات في 2025 : \u003cstrong\u003eÉpidémie\u003c/strong\u003e = حالات زايدة على المتوقع ومحدودة في الزمان والمكان. \u003cstrong\u003eOutbreak\u003c/strong\u003e = وباء صغير ومحدود. \u003cstrong\u003eSource ponctuelle\u003c/strong\u003e = تطلق الميكروب لمدة \u003cstrong\u003eقصيرة برك\u003c/strong\u003e (pic واحد)؛ أما \u003cstrong\u003eSource persistante\u003c/strong\u003e = تطلقو بشكل \u003cstrong\u003eمستمر (continue)\u003c/strong\u003e ماشي متقطع (épisodique) !","triad":{"toUnderstand":["La différence entre une investigation (ponctuelle, rapide) et la surveillance (permanente).","Comment la dynamique d’exposition (source ponctuelle vs persistante) façonne la courbe épidémique."],"toMemorize":["Épidémie = excès de cas par rapport au niveau attendu, limitée dans le temps ET l’espace.","Outbreak = épidémie limitée géographiquement ou dans le temps.","Objectif principal = interrompre la transmission et prévenir de nouveaux cas."],"toRecognizeInQcm":["« source persistante émet de manière épisodique » → FAUX (c’est continu !).","« augmentation saisonnière prévue » → FAUX (ce n’est pas une épidémie)."]}},"memorize":[{"id":"M_L4.1_1","category":"Définition","title":"Épidémie \u0026 Outbreak","content":"\u003cstrong\u003eÉpidémie :\u003c/strong\u003e excès de cas par rapport au niveau attendu, \u003cstrong\u003elimitée dans le temps et l’espace\u003c/strong\u003e. \u003cstrong\u003eOutbreak :\u003c/strong\u003e épidémie limitée géographiquement ou dans le temps.","highlight":true},{"id":"M_L4.1_2","category":"Distinction","title":"Source ponctuelle vs Source persistante","content":"\u003cstrong\u003ePonctuelle :\u003c/strong\u003e libère l’agent sur une \u003cstrong\u003ecourte période\u003c/strong\u003e (pic unique). \u003cstrong\u003ePersistante :\u003c/strong\u003e émission \u003cstrong\u003econtinue\u003c/strong\u003e (jamais « épisodique » !).","highlight":true},{"id":"M_L4.1_3","category":"Distinction","title":"Endémie vs Pandémie","content":"\u003cstrong\u003eEndémie :\u003c/strong\u003e illimitée dans le temps, limitée dans l’espace. \u003cstrong\u003ePandémie :\u003c/strong\u003e illimitée dans l’espace (continents).","highlight":false},{"id":"M_L4.1_4","category":"Liste","title":"Objectif principal de l’investigation","content":"\u003cstrong\u003eInterrompre la transmission (arrêter l’épidémie)\u003c/strong\u003e et \u003cstrong\u003eprévenir de nouveaux cas / épisodes\u003c/strong\u003e.","highlight":true}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L4.2","courseId":"C4","order":2,"title":"Phase descriptive (Étapes 1–5) : courbe épidémique \u0026 taux d’attaque","durationMin":14,"sourceRef":"§ III.3.2 Étapes 1 à 5, pages 4–6","bmCount":5,"bmRefs":["Ch. 19 Q3 (2025)","Ch. 19 Q8 (2022)","Ch. 14 Q49 (ND)","Ch. 19 Q13 (2022)","Ch. 17 Q32 (2019)"],"priority":"very_high","priorityScore":80,"bmWarning":"⚠️ Erreur corrigé BM sur Ch. 14 Q49 : le BM ne donne que B pour la courbe épidémique alors que le cours (p. 6) prouve que B (incubation), C (type de transmission) et D (nature de la source) sont tous trois justes !","understand":{"intro":"La phase descriptive répond aux questions « Qui, Où, Quand ? » à travers les 5 premières étapes de l’investigation, pour faire émerger des hypothèses solides.","sections":[{"heading":"Les 5 étapes de la phase descriptive","paragraphs":["Ces étapes peuvent se chevaucher sur le terrain, mais suivent une logique rigoureuse :"],"bullets":["\u003cstrong\u003eÉtape 1 — Affirmer la réalité de l’épidémie :\u003c/strong\u003e cas observés \u003e cas attendus, après avoir éliminé les \u003cstrong\u003e5 causes de fausse épidémie\u003c/strong\u003e (variation saisonnière, erreur diagnostique, contamination de milieux de culture au labo, doublons de déclaration, notification groupée).","\u003cstrong\u003eÉtape 2 — Confirmer le diagnostic :\u003c/strong\u003e examen clinique + prélèvements microbiologiques.","\u003cstrong\u003eÉtape 3 — Définir un cas :\u003c/strong\u003e critères cliniques/biologiques + temps/lieu/personne. Si la maladie est mal connue, \u003cstrong\u003eprivilégier la sensibilité\u003c/strong\u003e (cas certains, probables, possibles).","\u003cstrong\u003eÉtape 4 — Collecter les cas et les données (Ch. 19 Q3 B) :\u003c/strong\u003e à partir des \u003cstrong\u003edossiers hospitaliers, registres et laboratoires de diagnostic\u003c/strong\u003e. Donnée temporelle indispensable = \u003cstrong\u003edate de début des symptômes\u003c/strong\u003e (jamais la date de déclaration !).","\u003cstrong\u003eÉtape 5 — Décrire l’épidémie :\u003c/strong\u003e Temps (\u003cstrong\u003ecourbe épidémique\u003c/strong\u003e), Lieu (cartographie), Personne (âge, sexe, \u003cstrong\u003etaux d’attaque\u003c/strong\u003e)."]}],"tables":[{"title":"Ce que donne (et NE donne PAS) la courbe épidémique (Étape 5A)","headers":["Renseignement apporté ?","Détail exact du cours (p. 6)"],"rows":[["✅ OUI — Durée d’incubation","Permet d’estimer la période probable d’exposition et la durée d’incubation"],["✅ OUI — Type de transmission","Oriente entre source commune et transmission interhumaine (vagues successives)"],["✅ OUI — Nature de la source","Oriente entre source ponctuelle (pic bref) et source persistante (plateau/prolongé)"],["❌ NON — Certitude sur l’agent causal","NE renseigne JAMAIS avec certitude sur la nature du germe (seul le laboratoire / Étape 8 le confirme !)"]]}],"darija":"\u003cstrong\u003eLa courbe épidémique\u003c/strong\u003e تعطيك 3 حوايج : \u003cstrong\u003eIncubation + Type de transmission + Nature de la source\u003c/strong\u003e (يعني \u003cstrong\u003eBCD\u003c/strong\u003e). بصح \u003cstrong\u003eعمرها ما تأكدلك باليقين (avec certitude) اسم الميكروب\u003c/strong\u003e ! والـ \u003cstrong\u003eTaux d’attaque\u003c/strong\u003e = عدد المرضى ÷ عدد السكان المعرضين للخطر.","triad":{"toUnderstand":["Pourquoi on trace la courbe épidémique avec la date de début des symptômes (et non la date de notification).","Pourquoi on privilégie la sensibilité au début d’une épidémie mal connue (éviter de manquer des cas)."],"toMemorize":["Courbe épidémique = incubation + transmission + source (JAMAIS certitude sur l’agent causal).","Taux d’attaque = Nombre de sujets atteints / Population exposée (de la zone).","Collecte des cas = dossiers hospitaliers, registres et laboratoires de diagnostic."],"toRecognizeInQcm":["« renseigne avec certitude sur l’agent causal » → PIÈGE FAUX !","« nombre de sujets atteints / population de la zone » lors d’une épidémie → Taux d’attaque (Ch. 19 Q13 \u0026 Ch. 17 Q32)."]}},"memorize":[{"id":"M_L4.2_1","category":"Liste","title":"Les 5 causes de fausse épidémie (Étape 1)","content":"1) Variation saisonnière, 2) Erreur diagnostique, 3) Contamination des milieux de culture, 4) Doublons, 5) Notification groupée.","highlight":false},{"id":"M_L4.2_2","category":"Piège QCM","title":"Courbe épidémique (Étape 5A)","content":"Informe sur : \u003cstrong\u003edurée d’incubation\u003c/strong\u003e, \u003cstrong\u003etype de transmission\u003c/strong\u003e et \u003cstrong\u003enature de la source\u003c/strong\u003e. \u003cstrong\u003eNE renseigne JAMAIS avec certitude sur l’agent causal !\u003c/strong\u003e","highlight":true},{"id":"M_L4.2_3","category":"Formule","title":"Taux d’attaque (TA)","content":"TA = \u003cspan class=\"math-frac\"\u003e\u003cspan\u003eNombre de sujets atteints (nouveaux cas)\u003c/span\u003e\u003cspan\u003eNombre de sujets de la population exposée\u003c/span\u003e\u003c/span\u003e × 100.","highlight":true},{"id":"M_L4.2_4","category":"Liste","title":"Collecte des cas (Étape 4 — 2025)","content":"Repose sur les \u003cstrong\u003edossiers hospitaliers, registres et laboratoires de diagnostic\u003c/strong\u003e. Date clé : \u003cstrong\u003edate de début des symptômes\u003c/strong\u003e.","highlight":true}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L4.3","courseId":"C4","order":3,"title":"Phase analytique (Étapes 6–10) : cohorte, cas-témoins \u0026 mesures","durationMin":10,"sourceRef":"§ III.3.2 Étapes 6 à 10, pages 6–7","bmCount":2,"bmRefs":["Ch. 19 Q9 (2022)","Ch. 19 Q14 (2019)","+ Ch. 6 Q1–Q2 (2024)"],"priority":"high","priorityScore":67,"understand":{"intro":"Une fois les hypothèses formulées par la phase descriptive (Étape 6), la phase analytique (Étape 7) teste statistiquement le lien entre l’exposition suspectée et la maladie, sans jamais retarder les mesures de contrôle.","sections":[{"heading":"Étapes 6 à 10 : de l’hypothèse aux mesures de prévention","paragraphs":["L’investigation suit toujours l’ordre \u003cstrong\u003ephase descriptive PUIS phase analytique\u003c/strong\u003e :"],"bullets":["\u003cstrong\u003eÉtape 6 :\u003c/strong\u003e Formuler des hypothèses (agent, source, véhicule, mode de transmission).","\u003cstrong\u003eÉtape 7 — Tester les hypothèses (Phase étiologique/analytique) :\u003c/strong\u003e utilisation d’une \u003cstrong\u003eétude de cohorte rétrospective\u003c/strong\u003e (Ch. 19 Q14 C) ou d’une \u003cstrong\u003eétude cas-témoins\u003c/strong\u003e.","\u003cstrong\u003eÉtape 8 — Preuve biologique :\u003c/strong\u003e prélèvements sur les cas, les sources et les véhicules (aliments/eau).","\u003cstrong\u003eÉtape 9 — Rapport d’investigation\u003c/strong\u003e et diffusion aux autorités.","\u003cstrong\u003eÉtape 10 — Mesures de prévention et contrôle :\u003c/strong\u003e \u003cstrong\u003eNE PAS attendre la fin de l’investigation\u003c/strong\u003e — mesures générales dès le début, puis mesures spécifiques dès l’identification de la source."]}],"tables":[{"title":"Phase analytique (Étape 7) : Cohorte rétrospective vs Cas-témoins","headers":["Critère","Enquête de cohorte rétrospective","Enquête cas-témoins"],"rows":[["Quand l’utiliser ?","Population exposée bien définie et circonscrite (ex. invités d’un banquet, cantine)","Population vaste ou mal connue (ex. toute une ville)"],["Ce qu’on compare","Taux d’attaque chez les exposés vs les non-exposés (Risque Relatif)","Proportion d’exposés parmi les cas vs parmi les témoins (Odds Ratio)"]]}],"darija":"ديما نبداو بالـ \u003cstrong\u003ePhase descriptive\u003c/strong\u003e (التصديق على الوباء + تحديد الأشخاص المعرضين للخطر) ومبعد \u003cstrong\u003ePhase analytique / étiologique\u003c/strong\u003e (باستعمال \u003cstrong\u003eCohorte rétrospective\u003c/strong\u003e ولا \u003cstrong\u003eCas-témoins\u003c/strong\u003e). و\u003cstrong\u003eما نستناوش نهاية التحقيق\u003c/strong\u003e باش نبداو إجراءات الوقاية (Étape 10) !","triad":{"toUnderstand":["La frontière exacte entre ce qui appartient à la phase descriptive (Étapes 1–6) et à la phase analytique/conclusive (Étapes 7–10).","Quand choisir cohorte rétrospective vs cas-témoins sur le terrain."],"toMemorize":["Phase descriptive = affirmation de l’épidémie + identification des personnes à risque (Ch. 19 Q9 AB).","Phase étiologique = approche cohorte rétrospective (Ch. 19 Q14 C) ou cas-témoins.","Mesures de prévention : dès le début (générales), puis spécifiques (ne pas attendre la fin)."],"toRecognizeInQcm":["La rédaction du rapport et l’étude analytique approfondie ne font PAS partie de la phase descriptive (Ch. 19 Q9).","Phase étiologique → cocher « approche cohorte » (pas transversale ni expérimentale)."]}},"memorize":[{"id":"M_L4.3_1","category":"Distinction","title":"Phase descriptive vs Phase analytique","content":"\u003cstrong\u003eDescriptive (Étapes 1–6) :\u003c/strong\u003e affirmer l’épidémie, confirmer diag, définir/collecter cas, décrire T/L/P, identifier personnes à risque. \u003cstrong\u003eAnalytique (Étape 7) :\u003c/strong\u003e tester les hypothèses (\u003cstrong\u003ecohorte rétrospective\u003c/strong\u003e ou \u003cstrong\u003ecas-témoins\u003c/strong\u003e).","highlight":true},{"id":"M_L4.3_2","category":"Distinction","title":"Cohorte rétrospective vs Cas-témoins","content":"\u003cstrong\u003eCohorte rétrospective :\u003c/strong\u003e compare les \u003cstrong\u003etaux d’attaque\u003c/strong\u003e (exposés vs non-exposés). \u003cstrong\u003eCas-témoins :\u003c/strong\u003e compare les \u003cstrong\u003eproportions d’exposés\u003c/strong\u003e (cas vs témoins).","highlight":true},{"id":"M_L4.3_3","category":"Piège QCM","title":"Règle d’or de l’Étape 10","content":"\u003cstrong\u003eNe jamais attendre la fin de l’investigation\u003c/strong\u003e pour instaurer des mesures de contrôle (générales d’abord, spécifiques ensuite).","highlight":true}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]}]$medjson$::jsonb, $medjson$[]$medjson$::jsonb, $medjson${"analyzedAt":null,"engine":"curated","totalPages":0,"lowConfidencePages":[],"warnings":[],"status":"none"}$medjson$::jsonb, NULL, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, module_id, code, title, short_title, professor, source_files, bm_count, bm_shared_note, bm_recent_count, unique_concepts, priority, priority_score, vigilance_2026, summary, status, version, lessons, attachments, ai_extraction, ppt_import, created_at, updated_at, published_at) VALUES ('C5', 'M2', 'C5', 'Conduite à tenir devant une TIAC & Prévention', 'CAT TIAC & Prévention', 'Dr NOURANI Imane + Instructions MS 2024 & 2026', $medjson$["CAT TIAC.pdf (20 slides)","Cours_Epidemiologie_TIAC.pdf (Instr. N°19/2026, 9 p.)","INSTRUCTION TIAC.pdf (Instr. N°18/2024, 4 p.)"]$medjson$::jsonb, 5, '5 QCM en 2024 + 2 instructions ministérielles 2024–2026 dans votre dossier', 5, 4, 'high', 68, TRUE, 'Définition TIAC (exception botulisme = 1 cas), urgence médico-épidémiologique, déclaration et investigation, germes et incubations, règles de prélèvement (ne pas congeler), traitement (Imodium proscrit) et prévention (5 Clés OMS, marche en avant, plat témoin).', 'published', 1, $medjson$[{"id":"L5.1","courseId":"C5","order":1,"title":"Définition, urgence, déclaration obligatoire \u0026 investigation TIAC","durationMin":10,"sourceRef":"CAT TIAC slides 2–10 ; Instr. 2026 p. 1 \u0026 4–5","bmCount":5,"bmRefs":["Ch. 6 Q1 (2024)","Ch. 6 Q2 (2024)","Ch. 6 Q3 (2024)","Ch. 6 Q4 (2024)","Ch. 6 Q5 (2024)"],"priority":"high","priorityScore":65,"understand":{"intro":"Toutes les 5 questions de la BM Ch. 6 (2024) portent sur cette première leçon : définition, caractère d’urgence, déclaration obligatoire, facteurs favorisants et enquête descriptive puis analytique.","sections":[{"heading":"Définition exacte, statut \u0026 chiffres Algérie","paragraphs":["Une \u003cstrong\u003eTIAC\u003c/strong\u003e est l’apparition d’\u003cstrong\u003eau moins 2 cas groupés similaires\u003c/strong\u003e d’une symptomatologie en général gastro-intestinale rapportable à une même origine alimentaire ou hydrique, \u003cstrong\u003eSAUF pour le botulisme où 1 seul cas suffit\u003c/strong\u003e !"],"bullets":["\u003cstrong\u003eStatut :\u003c/strong\u003e maladie transmissible, \u003cstrong\u003eNON contagieuse\u003c/strong\u003e, à \u003cstrong\u003edéclaration obligatoire (MDO)\u003c/strong\u003e, constituant une \u003cstrong\u003eurgence médicale et épidémiologique\u003c/strong\u003e (Ch. 6 Q5 A).","\u003cstrong\u003eGravité :\u003c/strong\u003e généralement bénigne (~10 % hospitalisation, 0,005 % décès) ; facteurs de gravité = germe (inoculum, virulence) + hôte (immunodéprimé, femme enceinte, âges extrêmes).","\u003cstrong\u003eÉcart documentaire Algérie :\u003c/strong\u003e ~3 000 cas/an dans les slides (`CAT TIAC.pdf`) vs ~10 000 cas/an depuis 2022 dans `Instr. N°19/2026` — connaître les deux repères !"]},{"heading":"Déclaration, circuit \u0026 enquête en 2 temps","paragraphs":["Dès suspicion d’une TIAC, le médecin doit agir immédiatement :"],"bullets":["\u003cstrong\u003eDéclaration (Ch. 6 Q3 B) :\u003c/strong\u003e \u003cstrong\u003esignalement rapide immédiat\u003c/strong\u003e (par téléphone au SEMEP) \u003cstrong\u003eET notification écrite sur un relevé des MDO\u003c/strong\u003e (déclaration « zéro cas » hebdomadaire).","\u003cstrong\u003eCircuit intersectoriel :\u003c/strong\u003e Médecin → \u003cstrong\u003eSEMEP\u003c/strong\u003e → \u003cstrong\u003eDSP / MS / INSP\u003c/strong\u003e + enquête conjointe avec \u003cstrong\u003eBHC\u003c/strong\u003e (Bureau d’Hygiène Communale) et \u003cstrong\u003eDCP\u003c/strong\u003e (Commerce) → Prélèvements à l’\u003cstrong\u003eIPA\u003c/strong\u003e ou Labo d’Hygiène de Wilaya.","\u003cstrong\u003eEnquête épidémiologique (Ch. 6 Q1–Q2 C) :\u003c/strong\u003e toujours une \u003cstrong\u003eétape descriptive suivie d’une étape analytique\u003c/strong\u003e.","\u003cstrong\u003eFacteurs favorisants (Ch. 6 Q4 B) :\u003c/strong\u003e erreurs dans le processus de préparation des aliments, rupture de chaîne du froid, délai prolongé préparation-consommation."]}],"tables":[{"title":"Synthèse des 5 points tombés en 2024 (BM Ch. 6)","headers":["Thème QCM 2024","Réponse exacte à retenir"],"rows":[["Nature de la TIAC (Q5)","Urgence médicale ET épidémiologique"],["Déclaration (Q3)","Signalement rapide + notification sur un relevé des MDO"],["Investigation (Q1 \u0026 Q2)","Enquête descriptive PUIS enquête analytique"],["Facteurs favorisants (Q4)","Erreurs dans le processus de préparation des aliments"]]}],"darija":"الـ TIAC لازم \u003cstrong\u003eزوج حالات على الأقل (≥ 2 cas)\u003c/strong\u003e من نفس الماكلة، \u003cstrong\u003eإلا الـ Botulisme حالة وحدة تكفي !\u003c/strong\u003e وهي مرض \u003cstrong\u003etransmissible بصح NON contagieuse\u003c/strong\u003e، وتصريحها يكون بـ \u003cstrong\u003esignalement rapide + relevé MDO\u003c/strong\u003e، والتحقيق ديما \u003cstrong\u003edescriptive ومن بعد analytique\u003c/strong\u003e.","triad":{"toUnderstand":["Pourquoi la TIAC est une urgence à la fois médicale (soins/réhydratation) et épidémiologique (retirer l’aliment contaminé avant d’autres cas).","Le rôle conjoint du SEMEP, du BHC, de la DCP et de l’IPA."],"toMemorize":["Définition TIAC (≥ 2 cas, SAUF botulisme = 1 cas) ; transmissible NON contagieuse.","Déclaration = signalement rapide + relevé MDO ; Enquête = descriptive PUIS analytique."],"toRecognizeInQcm":["Respect de la chaîne du froid et délai réduit = facteurs PROTECTEURS (ne pas cocher comme favorisants !).","Ne pas inverser l’ordre : descriptive d’abord, analytique ensuite."]}},"memorize":[{"id":"M_L5.1_1","category":"Définition","title":"Définition TIAC \u0026 exception botulisme","content":"\u003cstrong\u003e≥ 2 cas groupés similaires\u003c/strong\u003e de symptomatologie généralement gastro-intestinale de même origine alimentaire/hydrique, \u003cstrong\u003eSAUF botulisme : 1 seul cas suffit\u003c/strong\u003e.","highlight":true},{"id":"M_L5.1_2","category":"Piège QCM","title":"Statut épidémiologique de la TIAC","content":"Maladie transmissible, \u003cstrong\u003eNON contagieuse\u003c/strong\u003e, MDO, \u003cstrong\u003eurgence médicale et épidémiologique\u003c/strong\u003e.","highlight":true},{"id":"M_L5.1_3","category":"Liste","title":"Déclaration \u0026 Enquête TIAC","content":"\u003cstrong\u003eSignalement rapide + notification sur relevé MDO\u003c/strong\u003e au SEMEP (→ DSP, MS, INSP + BHC/DCP). Enquête : \u003cstrong\u003edescriptive PUIS analytique\u003c/strong\u003e.","highlight":true}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L5.2","courseId":"C5","order":2,"title":"Germes, incubations, prélèvements \u0026 traitement des TIAC","durationMin":13,"sourceRef":"Cours_Epidemiologie_TIAC.pdf (Instr. N°19/2026), p. 1–8","bmCount":0,"bmRefs":[],"priority":"low","priorityScore":30,"understand":{"intro":"⚠️ Vigilance 2026 : votre dossier contient l’Instruction ministérielle détaillée N°19 (2026) avec le tableau complet des germes, les normes strictes de prélèvement et les contre-indications thérapeutiques.","sections":[{"heading":"Règles d’or des prélèvements (Annexe 2 — NE PAS CONGELER !)","paragraphs":["\u003cstrong\u003eInterdiction absolue :\u003c/strong\u003e \u003cstrong\u003eNE JAMAIS congeler les prélèvements\u003c/strong\u003e (sauf cas de force majeure), sous peine de détruire les germes recherchés !"],"bullets":["\u003cstrong\u003eSelles :\u003c/strong\u003e \u003cstrong\u003e≥ 10 g\u003c/strong\u003e avant toute antibiothérapie, pot hermétique, transport immédiat à 25 °C (\u003c 2 h [Instr.] / \u003c 24 h [slides]) ou à +4 °C (max 24 h).","\u003cstrong\u003eVomissures :\u003c/strong\u003e \u003cstrong\u003e10–20 g\u003c/strong\u003e dès les premiers symptômes, à 25 °C (\u003c 2 h) ou +4 °C (max 24 h).","\u003cstrong\u003eAliment suspect / plat témoin :\u003c/strong\u003e \u003cstrong\u003e250 g\u003c/strong\u003e, transport immédiat à \u003cstrong\u003e+4 °C\u003c/strong\u003e.","\u003cstrong\u003eEau :\u003c/strong\u003e \u003cstrong\u003e1 litre\u003c/strong\u003e en flacon stérile, transport immédiat à \u003cstrong\u003e+4 °C\u003c/strong\u003e."]},{"heading":"Prise en charge thérapeutique","paragraphs":["La priorité clinique est de corriger la déshydratation sans aggraver un syndrome invasif/toxinique :"],"bullets":["\u003cstrong\u003eRéhydratation :\u003c/strong\u003e per os / SRO (1–2 L le 1er jour si modérée) ou voie IV si sévère.","\u003cstrong\u003eRégime :\u003c/strong\u003e supprimer lait (sauf yaourt), café, gras, crudités ; réalimentation précoce (yaourt, riz, carottes, pâtes, bananes).","\u003cstrong\u003eAnti-diarrhéiques — PIÈGE MAJEUR :\u003c/strong\u003e \u003cstrong\u003eLopéramide (Imodium®) PROSCRIT si syndrome dysentérique\u003c/strong\u003e (risque de colo-stase !) ; Diosmectite (Smecta®) et Racécadotril (Tiorfan®) recommandés.","\u003cstrong\u003eAntibiothérapie :\u003c/strong\u003e réservée aux cas graves/terrains fragiles, adaptée à l’antibiogramme."]}],"tables":[{"title":"Tableau complet des germes de TIAC (Incubation, Aliments, Clinique)","headers":["Mécanisme","Germe","Incubation","Aliments typiques","Signes / Complications clés"],"rows":[["Toxinique","Staphylococcus aureus","1–6 h (très courte)","Pâtisseries, glaces, œufs mayonnaise","Vomissements + diarrhée SANS fièvre ; collapsus"],["Toxinique","Bacillus cereus","1–16 h","Riz, purée de légumes","Vomissements, diarrhées"],["Toxinique","Clostridium perfringens","8–24 h","Viandes, sauces (refroidissement lent)","Douleurs abdo, diarrhée SANS fièvre ; entérocolite nécrosante"],["Toxinique","E. coli EHEC","3–8 jours","Viande crue/peu cuite, lait cru","Diarrhée sanglante → SHU, IRA"],["Invasif","Salmonella non typhoïdique","12–72 h","Œufs, volailles, viandes, produits laitiers","FIÈVRE (38–40 °C) + diarrhée aiguë invasive"],["Invasif","Shigella","24–72 h","Eau contaminée, interhumaine","Syndrome dysentérique (glairo-sanglant), SHU, convulsions"],["Invasif","Campylobacter","2–10 jours","Volaille, lait non pasteurisé","Diarrhée, fièvre → Guillain-Barré, arthrite réactionnelle"],["Extra-digestif","Listeria monocytogenes","3–30 jours","Fromage, charcuterie, foie gras","Femme enceinte (avortement), nouveau-né (méningite)"],["Extra-digestif","Clostridium botulinum","—","Conserves déformées / bombées","Paralysies ; 1 SEUL CAS suffit pour déclarer une TIAC !"]]}],"darija":"احفظها بالزربة : \u003cstrong\u003e1–6 سوايع بلا سخانة + باتيسري/مايونيز = Staph\u003c/strong\u003e ؛ \u003cstrong\u003eالروز = Bacillus cereus\u003c/strong\u003e ؛ \u003cstrong\u003eاللحم والمرقة بردو بشوية بلا سخانة = C. perfringens\u003c/strong\u003e ؛ \u003cstrong\u003e12–72 سا + سخانة 39° + بيض/دجاج = Salmonelle\u003c/strong\u003e ؛ \u003cstrong\u003eمرأة حامل + فرماج = Listeria\u003c/strong\u003e. و\u003cstrong\u003eجامي تجمد العينات (ne pas congeler)\u003c/strong\u003e و\u003cstrong\u003eImodium ممنوع في الـ dysenterie !\u003c/strong\u003e","triad":{"toUnderstand":["La logique : toxine préformée = incubation très courte (1–6 h) sans fièvre vs germe invasif = incubation plus longue (12–72 h) avec fièvre.","Pourquoi le lopéramide est dangereux dans un syndrome dysentérique (stase colique des germes/toxines)."],"toMemorize":["Ne jamais congeler les prélèvements ; Selles ≥ 10 g (avant ATB), Aliment 250 g, Eau 1 L (+4 °C).","Imodium® proscrit si dysenterie ; incubations Staph (1–6 h) vs Salmonella (12–72 h)."],"toRecognizeInQcm":["Vomissements sans fièvre 3 h après pâtisserie → S. aureus.","Congélation des selles/aliments pour envoi à l’IPA → FAUX !","Lopéramide devant diarrhée glairo-sanglante fébrile → FAUX (proscrit) !"]}},"memorize":[{"id":"M_L5.2_1","category":"Classification","title":"Trio d’incubations phares","content":"\u003cstrong\u003eS. aureus :\u003c/strong\u003e 1–6 h (sans fièvre, pâtisseries). \u003cstrong\u003eC. perfringens :\u003c/strong\u003e 8–24 h (viandes/sauces refroidissement lent, sans fièvre). \u003cstrong\u003eSalmonella :\u003c/strong\u003e 12–72 h (\u003cstrong\u003efièvre 38–40 °C\u003c/strong\u003e, œufs/volailles).","highlight":true},{"id":"M_L5.2_2","category":"Seuil / Chiffre","title":"Normes de prélèvements TIAC","content":"\u003cstrong\u003eNE JAMAIS CONGELER\u003c/strong\u003e (sauf force majeure) ! Selles \u003cstrong\u003e≥ 10 g\u003c/strong\u003e (avant ATB), Vomis 10–20 g, Aliment \u003cstrong\u003e250 g\u003c/strong\u003e (+4 °C), Eau \u003cstrong\u003e1 litre\u003c/strong\u003e flacon stérile (+4 °C).","highlight":true},{"id":"M_L5.2_3","category":"Piège QCM","title":"Contre-indication thérapeutique majeure","content":"\u003cstrong\u003eLopéramide (Imodium®) PROSCRIT\u003c/strong\u003e si syndrome dysentérique (colo-stase). Préférer SRO + Smecta® / Tiorfan®.","highlight":true},{"id":"M_L5.2_4","category":"Liste","title":"Complications spécifiques à reconnaître","content":"\u003cstrong\u003eEHEC / Shigella\u003c/strong\u003e → SHU ; \u003cstrong\u003eCampylobacter\u003c/strong\u003e → Guillain-Barré ; \u003cstrong\u003eListeria\u003c/strong\u003e → femme enceinte (avortement) \u0026 nouveau-né (méningite).","highlight":false}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L5.3","courseId":"C5","order":3,"title":"Prévention : 5 Clés OMS, marche en avant \u0026 plat témoin","durationMin":9,"sourceRef":"INSTRUCTION TIAC.pdf (N°18/2024) \u0026 CAT TIAC slides 16–19","bmCount":0,"bmRefs":[],"priority":"low","priorityScore":30,"understand":{"intro":"Les mesures préventives combinent les 5 Clés de l’OMS pour la sécurité sanitaire des aliments et les règles réglementaires de l’Instruction N°18 du 01/08/2024 pour la restauration collective.","sections":[{"heading":"Les 5 Clés de l’OMS pour des aliments plus sûrs","paragraphs":["Toute prévention individuelle ou collective s’articule autour de 5 règles simples :"],"bullets":["\u003cstrong\u003e1) Propreté\u003c/strong\u003e (lavage mains, surfaces, lutte nuisibles).","\u003cstrong\u003e2) Séparation aliments crus / aliments cuits\u003c/strong\u003e (éviter contamination croisée).","\u003cstrong\u003e3) Cuisson soigneuse\u003c/strong\u003e (≥ 70 °C à cœur).","\u003cstrong\u003e4) Maintien à bonne température\u003c/strong\u003e (ne pas laisser \u003e 2 h à température ambiante ; réfrigérer \u003c 5 °C / 4 °C ; maintenir chaud \u003e 60 °C OMS / \u003e 65 °C Instr. 2024).","\u003cstrong\u003e5) Utiliser de l’eau et des produits sûrs.\u003c/strong\u003e"]},{"heading":"Restauration collective (Instruction N°18 du 01/08/2024)","paragraphs":["Des normes précises encadrent les cuisines collectives (cantines, résidences universitaires, hôpitaux) :"],"bullets":["\u003cstrong\u003ePrincipe de la « marche en avant » :\u003c/strong\u003e « jamais un circuit sale ne doit couper un circuit propre ».","\u003cstrong\u003eTempératures :\u003c/strong\u003e plats chauds maintenus à \u003cstrong\u003e\u003e 65 °C\u003c/strong\u003e ; plats froids entre \u003cstrong\u003e2 et 4 °C\u003c/strong\u003e (servis en \u003c 1 h, consommés le jour même) ; \u003cstrong\u003erestes systématiquement jetés\u003c/strong\u003e.","\u003cstrong\u003ePlat témoin :\u003c/strong\u003e échantillon de \u003cstrong\u003e50–100 g conservé à +4 °C pendant ≥ 72 heures\u003c/strong\u003e selon Instr. 2024 \u003cem\u003e(⚠️ note : les slides CAT TIAC.pdf indiquent 5 jours — retenir les deux !)\u003c/em\u003e.","\u003cstrong\u003eHygiène matériel \u0026 personnel :\u003c/strong\u003e ustensiles viande hachée désinfectés à l’\u003cstrong\u003eeau javellisée 12°\u003c/strong\u003e ; visite médicale du personnel de cuisine \u003cstrong\u003eà l’embauche + tous les trimestres\u003c/strong\u003e."]}],"tables":[{"title":"Repères chiffrés de prévention TIAC (attention aux écarts entre supports)","headers":["Paramètre","Instruction N°18 (2024)","Slides CAT TIAC / OMS"],"rows":[["Cuisson à cœur","Cuisson complète","≥ 70 °C (OMS)"],["Maintien au chaud","\u003e 65 °C","\u003e 60 °C (OMS)"],["Chaîne du froid / plats froids","2 à 4 °C (servir \u003c 1 h, consommer le jour même)","\u003c 5 °C ; pas \u003e 2 h à temp. ambiante"],["Plat témoin","50–100 g à +4 °C pendant ≥ 72 h","5 jours (CAT TIAC slide 10)"]]}],"darija":"في المطاعم الجماعية (restauration collective) : قاعدة \u003cstrong\u003eLa marche en avant\u003c/strong\u003e معناها « جامي الطريق الوسخ يقطع الطريق النظيف ». والماكلة السخونة فوق \u003cstrong\u003e65 °C\u003c/strong\u003e، الباردة بين \u003cstrong\u003e2 و 4 °C\u003c/strong\u003e، والباقي يترمى (restes jetés)، و\u003cstrong\u003eplat témoin\u003c/strong\u003e يتخبى على +4 °C لمدة \u003cstrong\u003e≥ 72 سا\u003c/strong\u003e (في الـ slides مكتوبة 5 أيام).","triad":{"toUnderstand":["Pourquoi la zone de danger bactérien se situe entre +4 °C et +60/65 °C.","À quoi sert le plat témoin (analyse microbiologique immédiate en cas de TIAC)."],"toMemorize":["Les 5 Clés OMS (propreté, cru/cuit, cuisson ≥ 70 °C, températures, produits sûrs).","Marche en avant ; chaud \u003e 65 °C ; froid 2–4 °C ; plat témoin 50–100 g à +4 °C (≥ 72 h / 5 j) ; personnel cuisine = visite embauche + trimestrielle."],"toRecognizeInQcm":["Définition de la marche en avant (circuit sale ne croise jamais circuit propre).","Conservation des restes pour le lendemain en restauration collective → INTERDIT !"]}},"memorize":[{"id":"M_L5.3_1","category":"Liste","title":"Les 5 Clés de l’OMS","content":"1) Propreté, 2) Séparation cru/cuit, 3) Cuisson (≥ 70 °C), 4) Températures (\u003c 5 °C / \u003e 60 °C, ≤ 2 h ambiante), 5) Eau et produits sûrs.","highlight":true},{"id":"M_L5.3_2","category":"Définition","title":"Principe de la marche en avant","content":"En cuisine collective : \u003cstrong\u003e« jamais un circuit sale ne doit couper un circuit propre »\u003c/strong\u003e.","highlight":true},{"id":"M_L5.3_3","category":"Seuil / Chiffre","title":"Plat témoin \u0026 Températures (Instr. 2024)","content":"Chaud \u003cstrong\u003e\u003e 65 °C\u003c/strong\u003e ; Froid \u003cstrong\u003e2–4 °C\u003c/strong\u003e ; Restes \u003cstrong\u003ejetés\u003c/strong\u003e ; Plat témoin : \u003cstrong\u003e50–100 g à +4 °C pendant ≥ 72 h\u003c/strong\u003e *(5 jours dans les slides)* ; Javel \u003cstrong\u003e12°\u003c/strong\u003e ; Visite médicale personnel : \u003cstrong\u003eembauche + trimestrielle\u003c/strong\u003e.","highlight":true}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]}]$medjson$::jsonb, $medjson$[]$medjson$::jsonb, $medjson${"analyzedAt":null,"engine":"curated","totalPages":0,"lowConfidencePages":[],"warnings":[],"status":"none"}$medjson$::jsonb, NULL, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, module_id, code, title, short_title, professor, source_files, bm_count, bm_shared_note, bm_recent_count, unique_concepts, priority, priority_score, vigilance_2026, summary, status, version, lessons, attachments, ai_extraction, ppt_import, created_at, updated_at, published_at) VALUES ('C6', 'M2', 'C6', 'Épidémiologie des IAS & Hygiène hospitalière', 'IAS & Hygiène', 'Pr A. TOBBI & Dr H. BENALDJIA (CHU Batna)', $medjson$["Les infections associées aux soins.pptx (27 slides) + Volet Hygiène des mains (BM Ch. 10)"]$medjson$::jsonb, 28, '24 QCM Ch. 10 + 4 QCM 2025 Ch. 16 (copier-coller !) — ⚠️ 4 erreurs corrigé BM', 7, 6, 'very_high', 95, FALSE, 'Définition IAS (IN + ILS) et délais (> 48 h, 30 j chirurgie, 1 an prothèse), les 5 sites d’IN et leurs germes, organisation CNHH/CLIN (1998), flore cutanée résidente vs transitoire et hygiène des mains / SHA.', 'published', 1, $medjson$[{"id":"L6.1","courseId":"C6","order":1,"title":"Définition IAS/IN/ILS, délais (\u003e 48 h / 30 j / 1 an) \u0026 CNHH/CLIN","durationMin":11,"sourceRef":"Slides 5–9 \u0026 22–25","bmCount":5,"bmRefs":["Ch. 10 Q5, Q13, Q14, Q21","Ch. 16 Q1 (2025)"],"priority":"very_high","priorityScore":95,"bmWarning":"⚠️ 2 erreurs majeures du corrigé BM : Ch. 10 Q14 (prothèse genou 2 mois = ISO [A], PAS C car délai = 1 an !) et Ch. 10 Q21 (IAS inclut aussi le milieu libéral ILS = D [1-2-4], PAS A).","understand":{"intro":"Les critères chronologiques d’une IAS et sa portée (hôpital + milieu libéral) reviennent constamment (2021, 2022, 2025) et comportent les pièges les plus sévères du corrigé BM.","sections":[{"heading":"Définition \u0026 délais chronologiques officiels (Slides 5–7)","paragraphs":["Une \u003cstrong\u003eIAS\u003c/strong\u003e survient au cours ou au décours d’une prise en charge (diagnostique, thérapeutique ou préventive), et n’était ni présente ni en incubation à l’admission :"],"bullets":["\u003cstrong\u003eIAS = IN + ILS :\u003c/strong\u003e comprend les \u003cstrong\u003eInfections Nosocomiales\u003c/strong\u003e (acquises en établissement de santé ; concernent patients, \u003cstrong\u003epersonnel et visiteurs\u003c/strong\u003e ; peuvent apparaître après la sortie) \u003cstrong\u003eET\u003c/strong\u003e les \u003cstrong\u003eInfections Liées aux Soins en milieu libéral / extrahospitalier (ILS)\u003c/strong\u003e.","\u003cstrong\u003eDélai standard d’hospitalisation :\u003c/strong\u003e \u003cstrong\u003e\u003e 48 heures\u003c/strong\u003e (ou supérieur à la période d’incubation).","\u003cstrong\u003eInfection du Site Opératoire (ISO) sans implant :\u003c/strong\u003e jusqu’à \u003cstrong\u003e30 jours\u003c/strong\u003e après l’intervention.","\u003cstrong\u003eISO avec implant ou prothèse :\u003c/strong\u003e jusqu’à \u003cstrong\u003e1 AN\u003c/strong\u003e après la pose !"]},{"heading":"Épidémiologie \u0026 organisation en Algérie (Slides 9 \u0026 22–25)","paragraphs":["L’Algérie a structuré la lutte contre les IN dès 1998 :"],"bullets":["\u003cstrong\u003ePrévalence IN Algérie (2005) :\u003c/strong\u003e \u003cstrong\u003e14 %\u003c/strong\u003e (France : 6–7 % ; USA SENIC : 3,6 % ; CHU Batna ISO neurochirurgie 2015 : \u003cstrong\u003e5,30 %\u003c/strong\u003e).","\u003cstrong\u003eCNHH (Comité National d’Hygiène Hospitalière) :\u003c/strong\u003e créé le \u003cstrong\u003e28 mars 1998\u003c/strong\u003e (niveau national).","\u003cstrong\u003eCLIN (Comité de Lutte contre les Infections Nosocomiales) :\u003c/strong\u003e créé le \u003cstrong\u003e27 novembre 1998\u003c/strong\u003e (dans chaque établissement).","\u003cstrong\u003eStratégie nationale :\u003c/strong\u003e Surveillance (« l’information appelant l’action ») + Mesures d’hygiène (\u003cstrong\u003ePrécautions standard\u003c/strong\u003e : par tous les professionnels, pour tous les patients, pour tous les soins)."]}],"tables":[{"title":"Les 3 seuils temporels absolus des IAS","headers":["Situation clinique","Seuil temporel exact","Exemple QCM"],"rows":[["Hospitalisation standard","\u003e 48 heures","Avant 12 h ou avant 24 h = FAUX (Ch. 16 Q1 D)"],["Chirurgie sans implant","Jusqu’à 30 jours","Infection plaie opératoire à J15 = ISO"],["Chirurgie AVEC implant ou prothèse","Jusqu’à 1 AN","Endophtalmie à J3 sur implant cataracte (Q13 A) \u0026 prothèse genou à 2 mois (Q14 A !)"]]}],"darija":"الديلي تاع الـ IAS : العادي \u003cstrong\u003eأكثر من 48 ساعة (\u003e 48 h)\u003c/strong\u003e، الجراحة العادية \u003cstrong\u003e30 يوم\u003c/strong\u003e، بصح كي يركبو \u003cstrong\u003eimplant ولا prothèse\u003c/strong\u003e (كيما prothèse du genou) الديلي يولي \u003cstrong\u003eعام كامل (1 an)\u003c/strong\u003e ! والـ IAS تشمل المستشفى (IN) \u003cstrong\u003eو\u003c/strong\u003eالعيادات الخاصة (ILS).","triad":{"toUnderstand":["Pourquoi le concept d’IAS a remplacé celui d’IN (inclusion des soins ambulatoires/libéraux).","Pourquoi le diagnostic d’IAS est chronologique et clinique (ne nécessite pas de connaître le germe au préalable)."],"toMemorize":["Seuils : \u003e 48 h (standard) | 30 jours (chirurgie) | 1 an (implant/prothèse).","IAS = IN + ILS ; Prévalence Algérie (2005) = 14 % ; CNHH (28/03/1998) \u0026 CLIN (27/11/1998)."],"toRecognizeInQcm":["« survient avant 24 h / avant 12 h / uniquement en milieu hospitalier » → TOUT FAUX → cocher « Aucune réponse n’est juste » (Ch. 16 Q1 D).","Prothèse du genou à 2 mois → c’est bien une ISO (A), ne pas suivre l’erreur C du BM !"]}},"memorize":[{"id":"M_L6.1_1","category":"Seuil / Chiffre","title":"Les 3 délais IAS / ISO","content":"Standard : \u003cstrong\u003e\u003e 48 heures\u003c/strong\u003e d’hospitalisation | Chirurgie (ISO) : \u003cstrong\u003e30 jours\u003c/strong\u003e | Implant ou prothèse : \u003cstrong\u003e1 an\u003c/strong\u003e.","highlight":true},{"id":"M_L6.1_2","category":"Définition","title":"IAS = IN + ILS","content":"Survient au cours ou au décours d’une prise en charge ; comprend les \u003cstrong\u003eIN\u003c/strong\u003e (hôpital — patients, personnel, visiteurs) ET les \u003cstrong\u003eILS\u003c/strong\u003e (milieu libéral).","highlight":true},{"id":"M_L6.1_3","category":"Seuil / Chiffre","title":"Organisation \u0026 chiffres Algérie","content":"Prévalence IN Algérie (2005) = \u003cstrong\u003e14 %\u003c/strong\u003e (Batna ISO neurochirurgie 2015 = 5,30 %). \u003cstrong\u003eCNHH : 28 mars 1998\u003c/strong\u003e ; \u003cstrong\u003eCLIN : 27 novembre 1998\u003c/strong\u003e.","highlight":false}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L6.2","courseId":"C6","order":2,"title":"Les 5 localisations d’IN, germes majeurs \u0026 colonisation cathéter","durationMin":12,"sourceRef":"Slides 15–20","bmCount":10,"bmRefs":["Ch. 10 Q1–Q3 (2024)","Ch. 16 Q2–Q4 (2025)","Ch. 10 Q9 (2021)","Ch. 10 Q22–Q24 (ND)"],"priority":"very_high","priorityScore":95,"bmWarning":"⚠️ Erreur corrigé BM sur Ch. 10 Q22 : la colonisation de cathéter = culture positive significative + ABSENCE de signes locaux et généraux (C : 1-2-3), PAS D (1-4 avec érythème) !","understand":{"intro":"Ce trio « IUN / Pneumonie / Cathéter » est un jackpot absolu à l’examen : 3 questions exactes sont tombées en 2024 (Ch. 10 Q1–Q3) et ont été reposées MOT POUR MOT en 2025 (Ch. 16 Q2–Q4) !","sections":[{"heading":"Bactériémie vs Septicémie \u0026 Caractéristiques des germes","paragraphs":["En plus des 4 sites d’organes majeurs, le cours distingue deux tableaux sanguins et rappelle la microbiologie globale des IAS :"],"bullets":["\u003cstrong\u003eBactériémie :\u003c/strong\u003e passage \u003cstrong\u003ebref et transitoire\u003c/strong\u003e de bactéries dans le sang.","\u003cstrong\u003eSepticémie :\u003c/strong\u003e \u003cstrong\u003edécharges massives et répétées\u003c/strong\u003e de bactéries à partir d’un foyer septique.","\u003cstrong\u003eMicro-organismes (Ch. 10 Q24 ABC) :\u003c/strong\u003e les \u003cstrong\u003ebactéries\u003c/strong\u003e sont les 1ers micro-organismes en fréquence décroissante (les virus existent aussi !), posant un problème majeur de \u003cstrong\u003erésistance aux antibiotiques\u003c/strong\u003e ; les \u003cstrong\u003evisiteurs\u003c/strong\u003e peuvent constituer un réservoir.","\u003cstrong\u003eColonisation d’un cathéter (Ch. 10 Q22) :\u003c/strong\u003e culture positive au seuil significatif + \u003cstrong\u003eabsence de signes locaux\u003c/strong\u003e (pas d’érythème !) + \u003cstrong\u003eabsence de signes généraux\u003c/strong\u003e."]}],"tables":[{"title":"Tableau d’or des localisations d’IN (Jackpot 2024 \u0026 2025)","headers":["Site d’IN","Rang clé en QCM","Germe n°1 à cocher","FDR majeur"],"rows":[["Urinaire (IUN)","1ère en FRÉQUENCE (la plus fréquente — Q9 A)","E. coli (\u003e Entérocoques, Pseudomonas)","Sondage vésical +++"],["Pneumonie nosocomiale","1ère cause de DÉCÈS par IN (2024 \u0026 2025 !)","Bacilles Gram Négatif — BGN (60 %) \u003e S. aureus 30 % \u003e Candida 10 %","Intubation endotrachéale +++"],["Cathéters","Fréquente en réanimation","Staphylocoques (50 %) \u003e BGN 10 % \u003e levures (2024 \u0026 2025 !)","Cathéter central non tunnellisé, voies multiples, site fémoral"],["ISO (Site opératoire)","Allongement du séjour ≈ 1 semaine","Cocci Gram+ (S. aureus), Entérobactéries, Pseudomonas","Score ASA élevé, séjour préop, type chirurgie, dépilation"]]}],"darija":"احفظ هاد الثلاثي لي طاح في 2024 وعاود طاح حرفيا في 2025 : \u003cstrong\u003eأكثر وحدة تنتشر = Urinaire (IUN)\u003c/strong\u003e ؛ \u003cstrong\u003eأكثر وحدة تقتل (1ère cause de décès) = Pneumonie والميكروب تاعها BGN (60 %)\u003c/strong\u003e ؛ \u003cstrong\u003eالـ Cathéter = Staphylocoques (50 %)\u003c/strong\u003e ! و\u003cstrong\u003eColonisation\u003c/strong\u003e معناها \u003cstrong\u003eما كانش érythème\u003c/strong\u003e (بلا علامات محلية ولا عامة).","triad":{"toUnderstand":["La différence entre site le plus fréquent (urinaire) et site le plus mortel (pneumonie).","La différence entre colonisation (asymptomatique) et infection locale (érythème/pus)."],"toMemorize":["IUN = 1ère fréquence ; Pneumonie = 1ère cause de décès + BGN (60 %) ; Cathéter = Staphylocoques (50 %).","Bactériémie (passage bref) vs Septicémie (décharges massives et répétées).","Facteurs IAS (Ch. 10 Q23 B) : FDR patient + qualité des soins + utilisation des techniques médicales."],"toRecognizeInQcm":["« Il n’y a pas d’infection nosocomiale d’origine virale » → FAUX (Ch. 10 Q24 D) !","Ne pas confondre BGN (Pneumonies) et Staphylocoques (Cathéters)."]}},"memorize":[{"id":"M_L6.2_1","category":"Classification","title":"Trio QCM 2024–2025 (Sites \u0026 Germes)","content":"\u003cstrong\u003eIUN :\u003c/strong\u003e 1ère en fréquence. \u003cstrong\u003ePneumonie :\u003c/strong\u003e 1ère cause de décès + \u003cstrong\u003eBGN (60 %)\u003c/strong\u003e. \u003cstrong\u003eCathéter :\u003c/strong\u003e \u003cstrong\u003eStaphylocoques (50 %)\u003c/strong\u003e.","highlight":true},{"id":"M_L6.2_2","category":"Définition","title":"Colonisation du cathéter (⚠️ Erreur BM)","content":"1) Culture positive significative + 2) \u003cstrong\u003eAbsence de signes locaux\u003c/strong\u003e (PAS d’érythème !) + 3) \u003cstrong\u003eAbsence de signes généraux\u003c/strong\u003e.","highlight":true},{"id":"M_L6.2_3","category":"Distinction","title":"Bactériémie vs Septicémie","content":"\u003cstrong\u003eBactériémie :\u003c/strong\u003e passage bref/transitoire. \u003cstrong\u003eSepticémie :\u003c/strong\u003e décharges massives et répétées à partir d’un foyer septique.","highlight":false},{"id":"M_L6.2_4","category":"Liste","title":"Microbiologie \u0026 réservoirs IAS","content":"Bactéries = 1er micro-organisme (mais virus existent !) ; problème de \u003cstrong\u003erésistance aux ATB\u003c/strong\u003e ; \u003cstrong\u003evisiteurs\u003c/strong\u003e = réservoir possible.","highlight":false}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L6.3","courseId":"C6","order":3,"title":"Flore cutanée, hygiène des mains, SHA, gants \u0026 précautions standard","durationMin":13,"sourceRef":"Volet Hygiène des mains (BM Ch. 10 : 13 QCM) + Slide 25","bmCount":13,"bmRefs":["Ch. 10 Q4, Q6–Q8, Q10–Q12, Q15–Q20 (2019–2022, ND)"],"priority":"very_high","priorityScore":80,"bmWarning":"⚠️ Erreur corrigé BM sur Ch. 10 Q6 : le BM met ABC (incluant pain de savon et serviette !), contredisant Ch. 10 Q10 \u0026 Q20. La vraie réponse est AD (zéro bijou + pas d’appareil électrique de séchage).","understand":{"intro":"Près de la moitié des questions de la BM Ch. 10 (13 QCM !) porte sur la flore des mains, les pré-requis, les produits recommandés, les contre-indications de la SHA et les erreurs à éviter. Ce volet n’est pas détaillé dans le PPTX fourni : cette leçon vous donne 100 % des règles testées.","sections":[{"heading":"Pré-requis, produits recommandés \u0026 erreurs à éviter","paragraphs":["L’hygiène des mains est la mesure n°1 des précautions standard :"],"bullets":["\u003cstrong\u003ePré-requis absolus (Ch. 10 Q7 ABD) :\u003c/strong\u003e ongles courts, pas de vernis, \u003cstrong\u003eZÉRO bijou (même l’alliance lisse est INTERDITE !)\u003c/strong\u003e, manches courtes.","\u003cstrong\u003eProduits recommandés (Ch. 10 Q10 ACD) :\u003c/strong\u003e savon doux liquide, savon antiseptique liquide, gel ou solution hydro-alcoolique (SHA).","\u003cstrong\u003eErreurs formellement proscrites (Ch. 10 Q15, Q20) :\u003c/strong\u003e \u003cstrong\u003esavon en pain\u003c/strong\u003e, remplissage d’un flacon non nettoyé-désinfecté, rinçage insuffisant, \u003cstrong\u003eséchage insuffisant ou par air chaud électrique\u003c/strong\u003e, serviette en tissu réutilisable, \u003cstrong\u003eassociation de 2 antiseptiques (FAUX !)\u003c/strong\u003e.","\u003cstrong\u003eContre-indications de la SHA (Ch. 10 Q11 ABD) :\u003c/strong\u003e \u003cstrong\u003emains mouillées\u003c/strong\u003e, \u003cstrong\u003emains poudrées/talquées\u003c/strong\u003e, \u003cstrong\u003emains visiblement souillées\u003c/strong\u003e (condition requise : mains sèches et visuellement propres).","\u003cstrong\u003eGants, lavage simple \u0026 toux :\u003c/strong\u003e gants = double protection soignant + patient (lavage/SHA \u003cstrong\u003eobligatoire\u003c/strong\u003e après retrait !) ; ponction lombaire ≠ lavage simple (geste invasif !) ; toux = coude ou mouchoir usage unique couvrant nez ET bouche (Ch. 10 Q12 AB)."]}],"tables":[{"title":"Flore résidente vs Flore transitoire (3 QCM BM : Q8, Q16, Q19)","headers":["Caractéristique","Flore résidente","Flore transitoire"],"rows":[["Origine / Acquisition","Ancienne, profonde, propre à l’individu","Acquisition récente (environnement hospitalier, malades)"],["Pathogénicité","Rarement pathogène — risque faible d’infections manuportées","Constituée de germes pathogènes (BMR, infections manuportées)"],["Élimination par hygiène","DIFFICILE à enlever par les gestes courants (réduite seulement)","FACILE à enlever (lavage simple / SHA)"]]}],"darija":"احفظ 3 موانع الـ \u003cstrong\u003eSHA\u003c/strong\u003e (Contre-indications) : \u003cstrong\u003eيدين مشمخين (mouillées) + فيهم البودرة (poudrées) + وسخين باينين (visiblement souillées)\u003c/strong\u003e. ممنوع تماما \u003cstrong\u003esavon en pain\u003c/strong\u003e، ممنوع \u003cstrong\u003eالخاتم حتى alliance lisse\u003c/strong\u003e، ممنوع \u003cstrong\u003eخلط 2 antiseptiques\u003c/strong\u003e، وممنوع \u003cstrong\u003eالمجفف الكهربائي\u003c/strong\u003e !","triad":{"toUnderstand":["Pourquoi la flore transitoire (superficielle, récente, pathogène) est la cible principale de la SHA.","Pourquoi la SHA est inefficace/irritante sur mains mouillées, souillées ou poudrées."],"toMemorize":["3 contre-indications SHA : mains mouillées, poudrées/talquées, visiblement souillées.","Pré-requis : ongles courts, sans vernis, 0 bijou (alliance lisse interdite).","Flore résidente (difficile à enlever, risque faible) vs transitoire (facile à enlever, pathogène)."],"toRecognizeInQcm":["« alliance lisse autorisée » → FAUX ; « association de 2 antiseptiques » → FAUX ; « ponction lombaire = lavage simple » → FAUX.","« couvrir la bouche seulement » en toussant → FAUX (nez ET bouche !)."]}},"memorize":[{"id":"M_L6.3_1","category":"Distinction","title":"Flore résidente vs Flore transitoire","content":"\u003cstrong\u003eRésidente :\u003c/strong\u003e risque faible, rarement pathogène, \u003cstrong\u003edifficile à enlever\u003c/strong\u003e. \u003cstrong\u003eTransitoire :\u003c/strong\u003e acquisition récente (environnement/malades), germes pathogènes, \u003cstrong\u003efacile à enlever\u003c/strong\u003e.","highlight":true},{"id":"M_L6.3_2","category":"Liste","title":"3 Contre-indications de la SHA","content":"1) Mains \u003cstrong\u003emouillées\u003c/strong\u003e, 2) Mains \u003cstrong\u003epoudrées/talquées\u003c/strong\u003e, 3) Mains \u003cstrong\u003evisiblement souillées\u003c/strong\u003e. (Condition requise : mains sèches et propres).","highlight":true},{"id":"M_L6.3_3","category":"Liste","title":"Pré-requis \u0026 Produits recommandés","content":"\u003cstrong\u003ePré-requis :\u003c/strong\u003e ongles courts, sans vernis, \u003cstrong\u003epas de bijoux (alliance lisse interdite !)\u003c/strong\u003e. \u003cstrong\u003eProduits :\u003c/strong\u003e savon doux liquide, savon antiseptique liquide, SHA (\u003cstrong\u003eJAMAIS pain de savon\u003c/strong\u003e).","highlight":true},{"id":"M_L6.3_4","category":"Piège QCM","title":"Gants, antiseptiques, séchage \u0026 toux","content":"Gants = double protection + lavage obligatoire après retrait ; \u003cstrong\u003ejamais 2 antiseptiques associés\u003c/strong\u003e ; \u003cstrong\u003epas de séchoir air chaud\u003c/strong\u003e ; essuie-mains usage unique ; toux = coude ou mouchoir couvrant \u003cstrong\u003enez ET bouche\u003c/strong\u003e.","highlight":false}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]}]$medjson$::jsonb, $medjson$[]$medjson$::jsonb, $medjson${"analyzedAt":null,"engine":"curated","totalPages":0,"lowConfidencePages":[],"warnings":[],"status":"none"}$medjson$::jsonb, NULL, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, module_id, code, title, short_title, professor, source_files, bm_count, bm_shared_note, bm_recent_count, unique_concepts, priority, priority_score, vigilance_2026, summary, status, version, lessons, attachments, ai_extraction, ppt_import, created_at, updated_at, published_at) VALUES ('C7', 'M3', 'C7', 'Programmes nationaux en milieu spécifique : Santé scolaire', 'Santé Scolaire (UDS)', 'Dr NOURANI Imane (Université Batna 2)', $medjson$["santé scolaire.pdf (39 slides, dont 10 fiches d’évaluation)"]$medjson$::jsonb, 8, '100 % tombés en 2025 (7 QCM Ch. 26 + 1 QCM Ch. 13 Q3 Trachome) !', 8, 5, 'very_high', 80, FALSE, 'Définition d’un programme de santé, population cible, objectif principal, organisation des UDS et équipes EPSP, vaccination scolaire (1AP/1AM/1AS), trachome au Sud, santé bucco-dentaire (« Stop à la carie ») et évaluation.', 'published', 1, $medjson$[{"id":"L7.1","courseId":"C7","order":1,"title":"Programme de santé, population cible, objectif \u0026 UDS / EPSP","durationMin":11,"sourceRef":"Slides 10–15","bmCount":5,"bmRefs":["Ch. 26 Q1 (2025, /)","Ch. 26 Q3 (2025, /)","Ch. 26 Q5 (2025)","Ch. 26 Q6 (2025)","Ch. 26 Q7 (2025)"],"priority":"very_high","priorityScore":80,"bmWarning":"ℹ️ Corrigés manquants (/) dans la BM pour Ch. 26 Q1 à Q4 (tous 2025) : résolus dans cette leçon grâce aux diapositives exactes de Dr Nourani (Q1 = A, Q3 = D).","understand":{"intro":"Explosion en 2025 : 8 QCM d’un seul coup sur ce cours de Dr Nourani ! Cette première leçon concentre 5 de ces 8 questions autour de la définition des UDS, du rattachement aux EPSP, de l’objectif principal et de la population cible.","sections":[{"heading":"Définition d’un programme, objectif \u0026 population cible","paragraphs":["Un \u003cstrong\u003eprogramme de santé\u003c/strong\u003e (slide 10) est un ensemble de ressources réunies et mises en œuvre dans une population définie, de façon cohérente dans le temps et l’espace, pour atteindre des objectifs déterminés (\u003cstrong\u003e7 notions fondamentales\u003c/strong\u003e : problème identifié, population cible, objectifs quantitatifs mesurables, activités, ressources, évaluation, temps)."],"bullets":["\u003cstrong\u003ePopulation cible (Ch. 26 Q7 A, slide 12) :\u003c/strong\u003e 1) \u003cstrong\u003eEnfants scolarisés\u003c/strong\u003e, 2) \u003cstrong\u003ePersonnel enseignant\u003c/strong\u003e, 3) \u003cstrong\u003ePersonnel administratif ou de service\u003c/strong\u003e.","\u003cstrong\u003eObjectif principal (Ch. 26 Q5 B, slide 13) :\u003c/strong\u003e fournir à l’enfant et à l’adolescent un ensemble de prestations sur le plan \u003cstrong\u003epréventif, curatif et éducatif\u003c/strong\u003e pour un \u003cstrong\u003edéveloppement harmonieux\u003c/strong\u003e physique, mental, intellectuel et social."]},{"heading":"Organisation des UDS \u0026 rattachement EPSP (Piège Q1 vs Q3 !)","paragraphs":["Ne jamais confondre le lieu de rattachement de l’équipe et le local en milieu scolaire :"],"bullets":["\u003cstrong\u003eUDS (Unités de Dépistage et de Suivi — Ch. 26 Q3 D \u0026 Q6 B) :\u003c/strong\u003e local dédié à la prise en charge sanitaire en milieu scolaire, implanté au niveau des \u003cstrong\u003ecollèges et lycées\u003c/strong\u003e, prenant en charge la santé des enfants scolarisés d’une même \u003cstrong\u003ecirconscription\u003c/strong\u003e.","\u003cstrong\u003eÉquipe de santé scolaire (Ch. 26 Q1 A) :\u003c/strong\u003e composée de \u003cstrong\u003e5 profils\u003c/strong\u003e (médecin, infirmier, chirurgien-dentiste, assistant médical, psychologue), exerçant au sein des \u003cstrong\u003eEPSP (structures de santé de proximité de terrain)\u003c/strong\u003e."]}],"tables":[{"title":"Distinction clé QCM 2025 : Ch. 26 Q1 vs Q3 vs Q6","headers":["Question BM 2025","Ce qui est demandé","Réponse exacte (Cours slide 15)"],"rows":[["Ch. 26 Q1 (corrigé /)","L’équipe de santé exerce au sein de…","A — Des structures de santé de proximité de terrain (EPSP)"],["Ch. 26 Q3 (corrigé /)","La prise en charge en milieu scolaire se fait au niveau…","D — Des Unités de Dépistage et de Suivi (UDS)"],["Ch. 26 Q6 (corrigé B)","Mission principale des UDS","B — Prendre en charge la santé des enfants scolarisés dans une circonscription spécifique"]]}],"darija":"رد بالك من الفرق بين `Q1` و `Q3` في 2025 : \u003cstrong\u003eفريق الصحة المدرسية (L’équipe)\u003c/strong\u003e يتبع للـ \u003cstrong\u003eEPSP\u003c/strong\u003e (structures de santé de proximité = `Q1 A`)؛ أما \u003cstrong\u003eالتكفل داخل الوسط المدرسي\u003c/strong\u003e فيدار في الـ \u003cstrong\u003eUDS\u003c/strong\u003e (`Q3 D`) لي تخدم على نفس الـ \u003cstrong\u003ecirconscription\u003c/strong\u003e وتكون في المتوسطات والثانويات.","triad":{"toUnderstand":["La complémentarité entre l’EPSP (structure de proximité employant les équipes) et l’UDS (unité implantée en collège/lycée par circonscription).","Pourquoi le programme inclut aussi les enseignants et le personnel administratif/de service."],"toMemorize":["Population cible : enfants scolarisés + enseignants + personnel administratif/de service.","Objectif principal : prestations préventives, curatives et éducatives pour un développement harmonieux.","Composition UDS (5 profils) : médecin, infirmier, chirurgien-dentiste, assistant médical, psychologue."],"toRecognizeInQcm":["« structures de santé privées / CHU / pédiatrie » → FAUX pour la santé scolaire.","« enfants scolarisés et enseignants » → Population cible principale (Ch. 26 Q7 A)."]}},"memorize":[{"id":"M_L7.1_1","category":"Définition","title":"Objectif principal de la santé scolaire (2025)","content":"Fournir aux enfants et adolescents des prestations \u003cstrong\u003epréventives, curatives et éducatives\u003c/strong\u003e pour un \u003cstrong\u003edéveloppement harmonieux\u003c/strong\u003e (physique, mental, intellectuel et social).","highlight":true},{"id":"M_L7.1_2","category":"Liste","title":"Population cible (2025)","content":"1) \u003cstrong\u003eEnfants scolarisés\u003c/strong\u003e, 2) \u003cstrong\u003ePersonnel enseignant\u003c/strong\u003e, 3) \u003cstrong\u003ePersonnel administratif ou de service\u003c/strong\u003e.","highlight":true},{"id":"M_L7.1_3","category":"Distinction","title":"UDS vs EPSP (Piège 2025 Q1 / Q3 / Q6)","content":"\u003cstrong\u003eUDS :\u003c/strong\u003e implantées en collèges/lycées, prennent en charge les élèves d’une \u003cstrong\u003ecirconscription\u003c/strong\u003e. \u003cstrong\u003eÉquipe (5 profils) :\u003c/strong\u003e rattachée aux \u003cstrong\u003eEPSP (structures de santé de proximité de terrain)\u003c/strong\u003e.","highlight":true},{"id":"M_L7.1_4","category":"Liste","title":"Les 5 professionnels de l’équipe UDS","content":"Médecin, infirmier, chirurgien-dentiste, assistant médical, psychologue.","highlight":false}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L7.2","courseId":"C7","order":2,"title":"Vaccination scolaire (1AP/1AM/1AS), couverture \u0026 trachome (Sud)","durationMin":9,"sourceRef":"Slides 13, 18–19, 26–27 \u0026 33","bmCount":3,"bmRefs":["Ch. 26 Q2 (2025, /)","Ch. 26 Q4 (2025, /)","Ch. 13 Q3 (2025)"],"priority":"high","priorityScore":75,"understand":{"intro":"Trois QCM précis de 2025 ont testé les classes cibles de la vaccination, son indicateur d’évaluation et la campagne spécifique des wilayas du Sud (le trachome — question piège mal classée dans Ch. 13 !).","sections":[{"heading":"Vaccination en milieu scolaire \u0026 indicateur d’évaluation","paragraphs":["Conformément au calendrier national de vaccination en vigueur :"],"bullets":["\u003cstrong\u003eClasses cibles vaccination (Ch. 26 Q4 D) :\u003c/strong\u003e la 1ère année de chaque cycle : \u003cstrong\u003e1ère AP, 1ère AM et 1ère AS\u003c/strong\u003e (+ rattrapage des non-vaccinés à la rentrée).","\u003cstrong\u003eIndicateur d’évaluation de la vaccination (Ch. 26 Q2 C) :\u003c/strong\u003e le \u003cstrong\u003etaux de couverture vaccinale par antigène\u003c/strong\u003e = (Nombre d’élèves vaccinés / Population cible)."]},{"heading":"Campagne accélérée d’élimination du trachome dans les wilayas du Sud","paragraphs":["Slide 19 : la maladie spécifiquement ciblée par la campagne accélérée d’élimination en milieu scolaire dans les \u003cstrong\u003ewilayas du Sud\u003c/strong\u003e est le \u003cstrong\u003eTRACHOME\u003c/strong\u003e :"],"bullets":["Dépistage actif systématique et traitement des cas.","Hygiène quotidienne : lavage des mains et du visage chaque matin.","Amélioration de l’eau, assainissement et lutte contre les mouches."]}],"tables":[{"title":"Comparaison anti-piège : Vaccination vs Bucco-dentaire vs Visite systématique","headers":["Activité scolaire","Classes cibles exactes","Indicateur clé"],"rows":[["Vaccination scolaire (Q4)","1ère AP, 1ère AM, 1ère AS (+ rattrapage)","Taux de couverture vaccinale par antigène (Q2)"],["Dépistage bucco-dentaire","Préscolaire, 1ère AP, 4ème AP, 2ème AM, 1ère AS","Indices carieux cao (dents temp.) \u0026 CAO (dents 6 ans)"],["Visite médicale systématique","Tous les élèves (préscolaire + 1AP à 3AS, public \u0026 privé agréé)","% d’élèves examinés = Examinés / Inscrits"]]}],"darija":"احفظها مليح : التلقيح المدرسي = غير السنوات اللولى تاع كل طور (\u003cstrong\u003e1AP, 1AM, 1AS\u003c/strong\u003e) ويتقيم بـ \u003cstrong\u003eTaux de couverture vaccinale par antigène\u003c/strong\u003e. والحملة تاع ولايات الجنوب راهي ضد \u003cstrong\u003eLe Trachome (التراخوما)\u003c/strong\u003e — عليها في `Ch. 13 Q3` كانت الإجابة \u003cstrong\u003eD (Aucune des réponses)\u003c/strong\u003e !","triad":{"toUnderstand":["Pourquoi la vaccination cible l’entrée de chaque cycle (1AP, 1AM, 1AS).","Pourquoi Ch. 13 Q3 a pour bonne réponse « Aucune des réponses » (le trachome n’était pas dans A, B, C)."],"toMemorize":["Vaccination scolaire = 1ère AP, 1ère AM, 1ère AS.","Évaluation vaccination = Taux de couverture vaccinale par antigène.","Campagne wilayas du Sud = Élimination du TRACHOME."],"toRecognizeInQcm":["2ème AM dans une question sur la vaccination → PIÈGE FAUX (2ème AM c’est pour les dents !).","Wilayas du Sud + tuberculose / marasme → FAUX (c’est le Trachome !)."]}},"memorize":[{"id":"M_L7.2_1","category":"Seuil / Chiffre","title":"Classes cibles de vaccination scolaire (2025)","content":"\u003cstrong\u003e1ère AP, 1ère AM, 1ère AS\u003c/strong\u003e (+ séances de rattrapage à la rentrée).","highlight":true},{"id":"M_L7.2_2","category":"Formule","title":"Évaluation de la vaccination scolaire (2025)","content":"\u003cstrong\u003eTaux de couverture vaccinale par antigène\u003c/strong\u003e = \u003cspan class=\"math-frac\"\u003e\u003cspan\u003eVaccinés (B)\u003c/span\u003e\u003cspan\u003ePopulation cible (A)\u003c/span\u003e\u003c/span\u003e.","highlight":true},{"id":"M_L7.2_3","category":"Piège QCM","title":"Campagne des wilayas du Sud (2025)","content":"Campagne accélérée d’élimination du \u003cstrong\u003eTRACHOME\u003c/strong\u003e (dépistage, traitement, lavage mains/visage, eau/assainissement, lutte mouches).","highlight":true}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L7.3","courseId":"C7","order":3,"title":"Santé bucco-dentaire (« Stop à la carie »), cantines \u0026 évaluation","durationMin":9,"sourceRef":"Slides 20–36","bmCount":0,"bmRefs":[],"priority":"low","priorityScore":25,"understand":{"intro":"Complément direct du cours de Dr Nourani (0 QCM en 2025, mais très propice à de nouveaux QCM 2026) : le programme bucco-dentaire, le contrôle d’hygiène des cantines et la périodicité des rapports d’évaluation.","sections":[{"heading":"Santé bucco-dentaire (« Stop à la carie ») \u0026 Contrôle d’hygiène","paragraphs":["Les soins dentaires et la salubrité des établissements complètent le dépistage médical :"],"bullets":["\u003cstrong\u003eClasses cibles bucco-dentaires (slide 20) :\u003c/strong\u003e \u003cstrong\u003ePréscolaire, 1ère AP, 4ème AP, 2ème AM et 1ère AS\u003c/strong\u003e.","\u003cstrong\u003eOrganisation des soins dentaires :\u003c/strong\u003e la polyclinique de l’EPSP réserve \u003cstrong\u003e≥ 2 après-midi par semaine\u003c/strong\u003e aux élèves ; contrôle \u003cstrong\u003etrimestriel\u003c/strong\u003e.","\u003cstrong\u003eIndices carieux (slides 34–36) :\u003c/strong\u003e \u003cstrong\u003ecao\u003c/strong\u003e (dents temporaires = cariées + absentes + obturées) et \u003cstrong\u003eCAO\u003c/strong\u003e (dents permanentes de 6 ans) ; Indice = CAO / effectif examiné.","\u003cstrong\u003eCantines scolaires (slide 22) :\u003c/strong\u003e les travailleurs des cantines subissent des examens médicaux \u003cstrong\u003eau moins 2 fois par an\u003c/strong\u003e.","\u003cstrong\u003eÉvaluation \u0026 rapports (slides 26–27) :\u003c/strong\u003e 3 types d’indicateurs (dépistage/résultats, activités, coûts) ; rapports \u003cstrong\u003etrimestriels\u003c/strong\u003e élaborés par les \u003cstrong\u003eSEMEP des EPSP\u003c/strong\u003e et transmis aux directeurs d’établissements et à la \u003cstrong\u003eDSP\u003c/strong\u003e ; Comité de wilaya réuni au début de l’année scolaire + chaque trimestre."]}],"tables":[{"title":"Repères chiffrés d’hygiène et d’évaluation scolaire","headers":["Élément","Norme / Fréquence exacte du cours"],"rows":[["Classes bucco-dentaires","Préscolaire, 1ère AP, 4ème AP, 2ème AM, 1ère AS"],["Créneau polyclinique EPSP (dentaire)","≥ 2 après-midi par semaine"],["Visite médicale personnel cantines","≥ 2 fois par an"],["Rapports d’évaluation (SEMEP / EPSP → DSP)","Trimestriels (+ réunion Comité de wilaya début d’année et chaque trimestre)"]]}],"darija":"باش ما تتخلطش في 2026 : \u003cstrong\u003eالأسنان (Stop à la carie)\u003c/strong\u003e = \u003cstrong\u003ePréscolaire, 1AP, 4AP, 2AM, 1AS\u003c/strong\u003e، وعمال المطاعم المدرسية يديرو فحص طبي \u003cstrong\u003eمرتين في العام على الأقل (≥ 2 fois/an)\u003c/strong\u003e، والتقارير تبعث \u003cstrong\u003eكل ثلاثي (trimestriels)\u003c/strong\u003e من SEMEP تاع الـ EPSP للـ DSP.","triad":{"toUnderstand":["La différence entre indices cao (dents de lait) et CAO (dents permanentes de 6 ans).","Le rôle de coordination du SEMEP de l’EPSP et du Comité de wilaya."],"toMemorize":["Classes bucco-dentaires : Préscolaire, 1AP, 4AP, 2AM, 1AS.","Polyclinique EPSP ≥ 2 après-midi/semaine ; Cantines ≥ 2 visites médicales/an ; Rapports trimestriels."],"toRecognizeInQcm":["Différence de classes cibles entre vaccination (1AP/1AM/1AS) et bucco-dentaire (ajout Préscolaire, 4AP, 2AM).","Périodicité des rapports d’évaluation : trimestrielle (pas annuelle uniquement)."]}},"memorize":[{"id":"M_L7.3_1","category":"Liste","title":"Classes cibles bucco-dentaires (« Stop à la carie »)","content":"\u003cstrong\u003ePréscolaire, 1ère AP, 4ème AP, 2ème AM, 1ère AS\u003c/strong\u003e (polyclinique EPSP : \u003cstrong\u003e≥ 2 après-midi/semaine\u003c/strong\u003e).","highlight":true},{"id":"M_L7.3_2","category":"Seuil / Chiffre","title":"Cantines \u0026 Rapports d’évaluation","content":"Personnel cantines : examens médicaux \u003cstrong\u003e≥ 2 fois/an\u003c/strong\u003e. Rapports \u003cstrong\u003etrimestriels\u003c/strong\u003e par les \u003cstrong\u003eSEMEP des EPSP\u003c/strong\u003e → directeurs + \u003cstrong\u003eDSP\u003c/strong\u003e.","highlight":true},{"id":"M_L7.3_3","category":"Formule","title":"Indices carieux cao / CAO","content":"\u003cstrong\u003ecao\u003c/strong\u003e = dents temporaires (cariées + absentes + obturées) ; \u003cstrong\u003eCAO\u003c/strong\u003e = dents permanentes de 6 ans ; Indice = CAO / examinés.","highlight":false}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]}]$medjson$::jsonb, $medjson$[]$medjson$::jsonb, $medjson${"analyzedAt":null,"engine":"curated","totalPages":0,"lowConfidencePages":[],"warnings":[],"status":"none"}$medjson$::jsonb, NULL, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, module_id, code, title, short_title, professor, source_files, bm_count, bm_shared_note, bm_recent_count, unique_concepts, priority, priority_score, vigilance_2026, summary, status, version, lessons, attachments, ai_extraction, ppt_import, created_at, updated_at, published_at) VALUES ('C8', 'M3', 'C8', 'Certification de la Cause Médicale de Décès (CMD) & Décret 22-178', 'Certificat Décès (CMD)', 'Dr NOURANI Imane (SEMEP CHU Batna, 2024–2025)', $medjson$["Certification-de-la-Cause-Medicale-de-Deces2(3).pptx (43 slides)","modele de cmd et circuit.pptx (19 slides)","Republique-Algerienne-Democratique-et-populaire.pptx (16 slides)","Formulaire Cértificat médical de décès(1).docx"]$medjson$::jsonb, 0, '⚠️ 0 QCM en BM 2012–2025, MAIS 4 fichiers complets 2024–2025 de Dr Nourani (forte vigilance 2026 !)', 0, 0, 'low', 30, TRUE, 'Décret exécutif n° 22-178 (28/04/2022), 2 volets (nominatif vs anonyme scellé), délais (24 h / 20 j Sud), circuit APC→DSP→INSP, rédaction Partie I (cause initiale vs directe, ACR exclu), Partie II, Partie III (légiste), 4 groupes CIM-10 exclus, règles tumeurs (C97, C34) et décès maternel (42 j).', 'published', 1, $medjson$[{"id":"L8.1","courseId":"C8","order":1,"title":"Décret n° 22-178, les 2 volets, délais \u0026 circuit APC → DSP → INSP","durationMin":11,"sourceRef":"Republique-Algerienne…pptx (Art. 1–11) \u0026 modele de cmd et circuit.pptx","bmCount":0,"bmRefs":[],"priority":"low","priorityScore":30,"understand":{"intro":"⚠️ Alerte stratégique 2026 : même si la BM (2012–2025) ne contient encore aucune question sur ce thème, votre dossier comprend 4 fichiers 2024–2025 très détaillés de la même enseignante (Dr Nourani) qui a introduit 8 QCM Santé scolaire en 2025. Maîtrisez-le solidement !","sections":[{"heading":"Cadre juridique : Décret exécutif n° 22-178 du 28 avril 2022","paragraphs":["Ce décret de \u003cstrong\u003e11 articles\u003c/strong\u003e abroge l’ancien décret 16-80 du 24/02/2016 et fixe le modèle officiel du Certificat Médical de Décès (CMD) en Algérie :"],"bullets":["\u003cstrong\u003eArt. 2 (Médecins habilités) :\u003c/strong\u003e établi par \u003cstrong\u003etout médecin autorisé à exercer\u003c/strong\u003e (secteur public/fonctionnaire, contractuel, santé militaire, sûreté nationale, secteur privé/libéral).","\u003cstrong\u003eArt. 4 (Nombre d’exemplaires) :\u003c/strong\u003e délivré en \u003cstrong\u003eUN SEUL EXEMPLAIRE\u003c/strong\u003e !","\u003cstrong\u003eArt. 5 (Structure en 2 volets) :\u003c/strong\u003e \u003cstrong\u003ePartie supérieure nominative\u003c/strong\u003e (volet administratif remis à l’officier d’état civil pour autorisation d’inhumation) + \u003cstrong\u003ePartie inférieure anonyme\u003c/strong\u003e (volet médical \u003cstrong\u003eimmédiatement close/scellée par le médecin\u003c/strong\u003e pour secret médical, destinée aux autorités sanitaires).","\u003cstrong\u003eArt. 8 :\u003c/strong\u003e modèle numérique téléchargeable sur la plateforme du Ministère de la Santé."]},{"heading":"Délais légaux \u0026 circuit du volet médical","paragraphs":["Encadré par la Circulaire interministérielle Santé / Intérieur du 16 avril 2017 :"],"bullets":["\u003cstrong\u003eDélai de déclaration par la famille à l’APC (état civil) :\u003c/strong\u003e \u003cstrong\u003e24 heures\u003c/strong\u003e, porté à \u003cstrong\u003e20 jours pour les wilayas du Sud\u003c/strong\u003e.","\u003cstrong\u003eCircuit complet :\u003c/strong\u003e \u003cstrong\u003eMédecin\u003c/strong\u003e → \u003cstrong\u003eFamille\u003c/strong\u003e → \u003cstrong\u003eOfficier d’État Civil (APC)\u003c/strong\u003e (conserve le volet supérieur, transmet le volet inférieur \u003cstrong\u003emensuellement\u003c/strong\u003e avec bordereau) → \u003cstrong\u003eDSP\u003c/strong\u003e (récupération mensuelle par le \u003cstrong\u003eSEMEP\u003c/strong\u003e, contrôle qualité, formation médecins) → \u003cstrong\u003eINSP\u003c/strong\u003e (service des causes de décès : exploitation, codification CIM-10, archivage)."]}],"tables":[{"title":"Architecture des 2 volets \u0026 3 signalements particuliers du formulaire","headers":["Volet / Rubrique","Confidentialité","Destinataire \u0026 Rôle"],"rows":[["Partie supérieure","Nominative (identité du défunt)","Officier d’état civil (APC) → acte de décès \u0026 permis d’inhumer"],["Partie inférieure (I, II, III)","Anonyme \u0026 immédiatement scellée par le médecin","Autorités sanitaires : APC → DSP (SEMEP) → INSP (statistiques CIM-10)"],["3 signalements médicolégaux/sanitaires","Cases dédiées","1) Obstacle médicolégal ; 2) Prothèse fonctionnant avec PILE ; 3) Mise immédiate en CERCUEIL HERMÉTIQUE (contagion)"]]}],"darija":"الـ \u003cstrong\u003eCMD\u003c/strong\u003e في الجزائر يحكمو \u003cstrong\u003eDécret 22-178 (28 avril 2022)\u003c/strong\u003e : يعمرو \u003cstrong\u003eأي طبيب مرخص\u003c/strong\u003e في \u003cstrong\u003eنسخة وحدة (1 seul exemplaire)\u003c/strong\u003e ! فيه زوج أجزاء : الفوقاني بالاسم (للبلدية APC)، والتحتاني \u003cstrong\u003eمجهول الهوية (anonyme) ومغلق فورا\u003c/strong\u003e من عند الطبيب (يمشي كل شهر : \u003cstrong\u003eAPC → DSP/SEMEP → INSP\u003c/strong\u003e). والديلي تاع التصريح : \u003cstrong\u003e24 ساعة\u003c/strong\u003e (و\u003cstrong\u003e20 يوم\u003c/strong\u003e في ولايات الجنوب).","triad":{"toUnderstand":["Pourquoi le volet médical inférieur est détachable, anonyme et scellé par le médecin lui-même (respect du secret médical).","Le rôle de chaque maillon du circuit (APC = administratif, SEMEP/DSP = contrôle qualité mensuel, INSP = codification CIM-10)."],"toMemorize":["Décret 22-178 du 28 avril 2022 (11 articles, abroge 16-80) ; 1 seul exemplaire.","Délai déclaration APC : 24 h (20 jours wilayas du Sud) ; envoi APC→DSP = mensuel.","3 signalements : obstacle médicolégal, prothèse à pile, cercueil hermétique."],"toRecognizeInQcm":["« Délivré en 2 exemplaires » → FAUX (1 seul exemplaire !).","« Réservé aux médecins du secteur public uniquement » → FAUX (tout médecin autorisé, y compris privé/libéral)."]}},"memorize":[{"id":"M_L8.1_1","category":"Seuil / Chiffre","title":"Décret exécutif n° 22-178 (28 avril 2022)","content":"\u003cstrong\u003e11 articles\u003c/strong\u003e (abroge décret 16-80/2016) ; établi par \u003cstrong\u003etout médecin autorisé\u003c/strong\u003e (public, privé, militaire, sûreté) ; délivré en \u003cstrong\u003eun seul exemplaire\u003c/strong\u003e.","highlight":true},{"id":"M_L8.1_2","category":"Distinction","title":"Les 2 volets du CMD (Art. 5)","content":"\u003cstrong\u003ePartie supérieure :\u003c/strong\u003e nominative (volet administratif → APC). \u003cstrong\u003ePartie inférieure :\u003c/strong\u003e anonyme (volet médical \u003cstrong\u003eimmédiatement clos/scellé\u003c/strong\u003e → DSP/INSP).","highlight":true},{"id":"M_L8.1_3","category":"Seuil / Chiffre","title":"Délais \u0026 Circuit administratif","content":"Déclaration famille à l’APC : \u003cstrong\u003e24 h\u003c/strong\u003e (\u003cstrong\u003e20 jours\u003c/strong\u003e Sud). Circuit (envoi \u003cstrong\u003emensuel\u003c/strong\u003e) : \u003cstrong\u003eMédecin → Famille → APC → DSP (SEMEP) → INSP\u003c/strong\u003e.","highlight":true},{"id":"M_L8.1_4","category":"Liste","title":"Les 3 signalements particuliers","content":"1) Obstacle médicolégal à l’inhumation, 2) Prothèse fonctionnant avec \u003cstrong\u003epile\u003c/strong\u003e, 3) Mise immédiate en \u003cstrong\u003ecercueil hermétique\u003c/strong\u003e (contagion).","highlight":false}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L8.2","courseId":"C8","order":2,"title":"Rédaction Partie I (cause initiale, ACR exclu), Partie II \u0026 Partie III","durationMin":12,"sourceRef":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx, slides 10–23 \u0026 Art. 6","bmCount":0,"bmRefs":[],"priority":"low","priorityScore":30,"understand":{"intro":"Savoir reconstruire correctement la chaîne causale de la Partie I et distinguer mort naturelle (Art. 6.1) vs mort violente/indéterminée (Art. 6.2) constitue le cœur clinique et médico-légal du cours.","sections":[{"heading":"Règles d’or de rédaction du volet médical (OMS)","paragraphs":["Une rédaction rigoureuse est indispensable pour produire des statistiques de mortalité fiables :"],"bullets":["Écriture lisible, en \u003cstrong\u003emajuscules\u003c/strong\u003e, \u003cstrong\u003eSANS aucune abréviation\u003c/strong\u003e (pas d’« IDM », « AVC », « EP »), \u003cstrong\u003eun seul événement par ligne\u003c/strong\u003e, sans ligne vide intermédiaire, ordre chronologique respecté.","\u003cstrong\u003eINTERDICTION ABSOLUE :\u003c/strong\u003e \u003cstrong\u003eNe JAMAIS inscrire « Arrêt cardiaque / ACR »\u003c/strong\u003e, un mode de décès (asphyxie terminale, défaillance multiviscérale isolée) ou un symptôme comme cause initiale !","\u003cstrong\u003eStatistiques mondiales OMS :\u003c/strong\u003e seule la \u003cstrong\u003ecause initiale\u003c/strong\u003e (dernière ligne remplie de la Partie I) est retenue pour la tabulation nationale et internationale."]},{"heading":"Mort naturelle (Art. 6.1) vs Mort violente / suspecte / indéterminée (Art. 6.2)","paragraphs":["La conduite du médecin constatant change radicalement selon la nature du décès :"],"bullets":["\u003cstrong\u003eMort naturelle (Art. 6.1) :\u003c/strong\u003e le médecin remplit la partie supérieure ET la partie inférieure (\u003cstrong\u003eParties I et II\u003c/strong\u003e), puis la clôt immédiatement.","\u003cstrong\u003eMort violente, suspecte ou indéterminée (Art. 6.2) :\u003c/strong\u003e le médecin constatant remplit \u003cstrong\u003eUNIQUEMENT la partie supérieure\u003c/strong\u003e, coche l’obstacle médicolégal et avise les autorités pour levée de corps. Seul le \u003cstrong\u003emédecin légiste\u003c/strong\u003e remplit la \u003cstrong\u003ePartie III\u003c/strong\u003e !"]}],"tables":[{"title":"Structure exacte du volet médical (avec exemples du cours)","headers":["Rubrique","Rôle exact","Exemple du cours"],"rows":[["Partie I — a) Cause directe","Complication terminale immédiate ayant entraîné la mort","Hémorragie de varices œsophagiennes / Embolie pulmonaire / Choc cardiogénique"],["Partie I — b, c) Intermédiaires","Étapes morbides reliant la cause initiale à la directe","Hypertension portale ← Cirrhose / Fracture pathologique ← Métastase fémur"],["Partie I — d) Cause INITIALE","Maladie ou traumatisme déclencheur (SEULE retenue par l’OMS !)","Hépatite virale B chronique / Cancer du sein / HTA chronique / AVP"],["Partie II","Autres états morbides importants contributifs SANS lien direct avec Partie I","Alcoolisme (dans un ulcère duodénal perforé) ; Varices (jamais répété en Partie I)"],["Partie III","Réservée EXCLUSIVEMENT au MÉDECIN LÉGISTE","Mort violente, suspecte, indéterminée, CNI"]]}],"darija":"ديما اقرا الـ \u003cstrong\u003ePartie I من التحت للفوق\u003c/strong\u003e : السطر التحتاني (\u003cstrong\u003ed — Cause initiale\u003c/strong\u003e) هو المرض الأصلي لي بدى الحكاية كامل وهو لي يدخل في إحصائيات l’OMS؛ والسطر الفوقاني (\u003cstrong\u003ea — Cause directe\u003c/strong\u003e) هو آخر مضاعفة. \u003cstrong\u003eجامي تكتب Arrêt cardiaque (ACR)\u003c/strong\u003e ! وكي تكون الموت عنيفة ولا مشبوهة : تعمر \u003cstrong\u003eغير الجزء الفوقاني\u003c/strong\u003e والـ \u003cstrong\u003ePartie III\u003c/strong\u003e للطبيب الشرعي وحدو.","triad":{"toUnderstand":["Comment remonter la chaîne causale « dû à » de la ligne a) vers la ligne d).","Pourquoi la Partie II ne doit jamais répéter une affection déjà placée en Partie I."],"toMemorize":["Partie I : a = directe ← b/c = intermédiaires ← d = INITIALE (stats OMS).","ACR = mode de décès, JAMAIS cause initiale ; aucune abréviation autorisée.","Art. 6.2 (mort violente) : constatant = partie supérieure uniquement ; Partie III = médecin légiste."],"toRecognizeInQcm":["Placer la cause initiale en a) ou inscrire ACR comme cause initiale → FAUX !","Médecin traitant remplissant la Partie III → FAUX (réservée au médecin légiste)."]}},"memorize":[{"id":"M_L8.2_1","category":"Classification","title":"Chaîne causale de la Partie I","content":"\u003cstrong\u003ea)\u003c/strong\u003e Cause directe/immédiate ← \u003cstrong\u003eb, c)\u003c/strong\u003e Causes intermédiaires ← \u003cstrong\u003ed) Cause INITIALE\u003c/strong\u003e (maladie/traumatisme déclencheur — \u003cstrong\u003eseule retenue par l’OMS\u003c/strong\u003e).","highlight":true},{"id":"M_L8.2_2","category":"Piège QCM","title":"Interdictions absolues de rédaction","content":"\u003cstrong\u003eJAMAIS d’arrêt cardiaque (ACR)\u003c/strong\u003e ou mode de décès en cause initiale ; \u003cstrong\u003eSANS abréviations\u003c/strong\u003e ; 1 seul événement par ligne ; pas de ligne vide intermédiaire.","highlight":true},{"id":"M_L8.2_3","category":"Distinction","title":"Art. 6.1 (Naturelle) vs Art. 6.2 (Violente/Suspecte)","content":"\u003cstrong\u003eNaturelle :\u003c/strong\u003e médecin remplit Parties I et II et clôt. \u003cstrong\u003eViolente/indéterminée :\u003c/strong\u003e médecin remplit \u003cstrong\u003euniquement la partie supérieure\u003c/strong\u003e et avise les autorités ; \u003cstrong\u003ePartie III = médecin légiste seul\u003c/strong\u003e.","highlight":true}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L8.3","courseId":"C8","order":3,"title":"Codification CIM-10 (4 groupes exclus), tumeurs \u0026 décès maternel","durationMin":11,"sourceRef":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx, slides 24–40","bmCount":0,"bmRefs":[],"priority":"low","priorityScore":30,"understand":{"intro":"Les règles OMS de codification CIM-10 déterminent la cause initiale statistique à partir du certificat rempli — avec 4 groupes formellement exclus, des règles précises pour les cancers et la définition du décès maternel.","sections":[{"heading":"Principe général OMS \u0026 les 4 groupes CIM-10 EXCLUS comme cause initiale","paragraphs":["\u003cstrong\u003ePrincipe général OMS :\u003c/strong\u003e l’affection mentionnée \u003cstrong\u003eseule à la dernière ligne de la Partie I\u003c/strong\u003e est sélectionnée comme cause initiale si elle peut logiquement engendrer toutes les affections inscrites au-dessus (si plusieurs affections figurent sur la dernière ligne, rechercher des infos complémentaires)."],"bullets":["\u003cstrong\u003e1) B95–B97 :\u003c/strong\u003e agents bactériens ou viraux isolés (sans préciser la maladie clinique).","\u003cstrong\u003e2) G97, H95, N99 :\u003c/strong\u003e affections post-actes médicaux ou chirurgicaux (coder la pathologie initiale qui a motivé l’acte).","\u003cstrong\u003e3) O80–O84 :\u003c/strong\u003e accouchement normal/simple (ne peut jamais être cause initiale de décès).","\u003cstrong\u003e4) S00–T98 :\u003c/strong\u003e lésions traumatiques seules (ex. traumatisme crânien seul exclu → coder la \u003cstrong\u003ecause externe\u003c/strong\u003e, ex. AVP `V041`, chute, pendaison !)."]},{"heading":"Règles particulières des tumeurs malignes \u0026 Décès maternel","paragraphs":["Deux chapitres spéciaux très détaillés dans les cas cliniques de Dr Nourani :"],"bullets":["\u003cstrong\u003eTumeurs — Code C97 :\u003c/strong\u003e deux tumeurs malignes primitives indépendantes toutes deux en \u003cstrong\u003ePartie I\u003c/strong\u003e → coder \u003cstrong\u003eC97\u003c/strong\u003e. \u003cstrong\u003ePiège :\u003c/strong\u003e si la 2ème tumeur est en \u003cstrong\u003ePartie II\u003c/strong\u003e, on \u003cstrong\u003eignore la Partie II\u003c/strong\u003e (PAS de C97 !).","\u003cstrong\u003eLésion pulmonaire (C34) :\u003c/strong\u003e associée à une autre tumeur primitive, une lésion du poumon est présumée \u003cstrong\u003emétastatique\u003c/strong\u003e sauf mention contraire — \u003cstrong\u003eSAUF « cancer bronchique »\u003c/strong\u003e qui est considéré comme \u003cstrong\u003etumeur primitive\u003c/strong\u003e !","\u003cstrong\u003eDécès maternel :\u003c/strong\u003e décès survenant durant la grossesse, l’accouchement/avortement ou dans les \u003cstrong\u003e42 jours\u003c/strong\u003e suivant la fin de la gestation (chirurgie récente signalée si \u003c 4 semaines avant décès)."]}],"tables":[{"title":"Codes CIM-10 \u0026 seuils spéciaux à connaître par cœur (C8)","headers":["Code / Seuil","Règle exacte du cours"],"rows":[["B95–B97 / G97,H95,N99 / O80–O84 / S00–T98","Les 4 groupes CIM-10 FORMELLEMENT EXCLUS comme cause initiale"],["Traumatisme (ex. Trauma crânien)","Ne pas coder S00–T98 en cause initiale → coder la CAUSE EXTERNE (AVP, pendaison…)"],["C97","2 tumeurs primitives indépendantes en PARTIE I (ignorer la Partie II pour C97 !)"],["C34 (Poumon) vs Cancer bronchique","Poumon + autre tumeur = présumé métastase ; « Cancer bronchique » = tumeur PRIMITIVE"],["42 jours / 4 semaines","Décès maternel = jusqu’à 42 jours post-gestation ; chirurgie récente = 4 semaines"]]}],"darija":"احفظ 4 مجموعات CIM-10 الممنوعة كـ cause initiale : \u003cstrong\u003eB95–B97\u003c/strong\u003e (ميكروب وحدو)، \u003cstrong\u003eG97/H95/N99\u003c/strong\u003e (مضاعفة عملية)، \u003cstrong\u003eO80–O84\u003c/strong\u003e (ولادة طبيعية)، و\u003cstrong\u003eS00–T98\u003c/strong\u003e (جرح ولا كسر وحدو ← لازم تكتب السبب الخارجي كيما AVP!). وفي السرطان : زوج أورام أولية في Partie I = \u003cstrong\u003eC97\u003c/strong\u003e (إذا الثاني في Partie II تجاهلو). ووفيات الأمهات = حتى \u003cstrong\u003e42 يوم\u003c/strong\u003e بعد الولادة.","triad":{"toUnderstand":["Pourquoi la cause externe (AVP, chute) prime toujours sur la nature de la lésion (trauma crânien S00–T98) en santé publique (prévention des accidents).","La différence entre 2 tumeurs en Partie I (C97) et 1 en Partie I + 1 en Partie II."],"toMemorize":["Les 4 groupes CIM-10 exclus : B95–B97, G97/H95/N99, O80–O84, S00–T98.","C97 (2 tumeurs primitives en Partie I) ; C34 (métastase présumée ≠ cancer bronchique primitif) ; Décès maternel = 42 jours."],"toRecognizeInQcm":["Trauma crânien S00–T98 choisi comme cause initiale → FAUX (c’est l’AVP !).","2ème tumeur en Partie II → NE PAS coder C97 !"]}},"memorize":[{"id":"M_L8.3_1","category":"Liste","title":"Les 4 groupes CIM-10 EXCLUS comme cause initiale","content":"1) \u003cstrong\u003eB95–B97\u003c/strong\u003e (agents seuls), 2) \u003cstrong\u003eG97 / H95 / N99\u003c/strong\u003e (post-actes), 3) \u003cstrong\u003eO80–O84\u003c/strong\u003e (accouchement normal), 4) \u003cstrong\u003eS00–T98\u003c/strong\u003e (lésions traumatiques seules → coder la \u003cstrong\u003ecause externe\u003c/strong\u003e).","highlight":true},{"id":"M_L8.3_2","category":"Distinction","title":"Règles tumeurs : C97 \u0026 Poumon (C34)","content":"\u003cstrong\u003eC97 :\u003c/strong\u003e 2 tumeurs primitives indépendantes en \u003cstrong\u003ePartie I\u003c/strong\u003e (ignorer Partie II). Poumon (\u003cstrong\u003eC34\u003c/strong\u003e) + autre cancer = présumé métastase, \u003cstrong\u003eSAUF cancer bronchique = primitif\u003c/strong\u003e.","highlight":true},{"id":"M_L8.3_3","category":"Seuil / Chiffre","title":"Décès maternel \u0026 chirurgie récente","content":"Décès maternel = grossesse, accouchement/avortement ou \u003cstrong\u003e≤ 42 jours\u003c/strong\u003e après fin de gestation. Chirurgie récente = \u003cstrong\u003e≤ 4 semaines\u003c/strong\u003e.","highlight":true}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]}]$medjson$::jsonb, $medjson$[]$medjson$::jsonb, $medjson${"analyzedAt":null,"engine":"curated","totalPages":0,"lowConfidencePages":[],"warnings":[],"status":"none"}$medjson$::jsonb, NULL, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, module_id, code, title, short_title, professor, source_files, bm_count, bm_shared_note, bm_recent_count, unique_concepts, priority, priority_score, vigilance_2026, summary, status, version, lessons, attachments, ai_extraction, ppt_import, created_at, updated_at, published_at) VALUES ('C9', 'M3', 'C9', 'Financement du système de santé', 'Financement Santé', 'Faculté de médecine Batna 2 (2023–2024)', $medjson$["financement du systèmede santé résumé (1).pdf (22 slides)"]$medjson$::jsonb, 6, '5 QCM Ch. 15 + 1 QCM Ch. 40 Q1 (2021–2023)', 0, 4, 'high', 65, FALSE, 'Problématique de rareté des ressources, les 4 sources de financement en Algérie (État, CNAS/CASNOS, Privé, ressources externes), critères d’évaluation (Équité, Efficacité, Pérennité) et les 3 niveaux d’analyse (Macro, Méso, Micro).', 'published', 1, $medjson$[{"id":"L9.1","courseId":"C9","order":1,"title":"Les 4 sources de financement en Algérie (État, CNAS/CASNOS, Privé)","durationMin":10,"sourceRef":"Slides 4–12","bmCount":4,"bmRefs":["Ch. 15 Q1 (2023, /)","Ch. 40 Q1 (2023, /)","Ch. 15 Q3 (2022)","Ch. 15 Q5 (ND)"],"priority":"high","priorityScore":65,"understand":{"intro":"Face à la rareté des ressources et à la croissance continue des dépenses de santé, le financement en Algérie combine 4 grandes sources complémentaires.","sections":[{"heading":"Les 4 sources de financement du système de santé","paragraphs":["Chaque source possède ses propres recettes, acteurs et rôles :"],"bullets":["\u003cstrong\u003e1) Financement public (État / fiscalité) :\u003c/strong\u003e primordial (utilité publique) ; en Algérie, \u003cstrong\u003e93,43 %\u003c/strong\u003e consacré aux établissements publics (EPSP, EHS, CHU) ; dépenses publiques = 69,8 % (2000) / 74,4 % (2001).","\u003cstrong\u003e2) Assurance-maladie / Sécurité sociale (Ch. 15 Q1 A) :\u003c/strong\u003e \u003cstrong\u003eCNAS\u003c/strong\u003e (travailleurs salariés) et \u003cstrong\u003eCASNOS\u003c/strong\u003e (non-salariés) ; financée par les \u003cstrong\u003ecotisations obligatoires des employeurs et travailleurs\u003c/strong\u003e ; couvre \u003cstrong\u003e5 risques\u003c/strong\u003e (maladie, maternité, invalidité, AT, MP) ; remboursement médicaments = \u003cstrong\u003e80 %\u003c/strong\u003e (\u003cstrong\u003eticket modérateur = 20 %\u003c/strong\u003e) et \u003cstrong\u003e100 %\u003c/strong\u003e maladies chroniques/catégories protégées.","\u003cstrong\u003e3) Financement privé :\u003c/strong\u003e \u003cstrong\u003edirect\u003c/strong\u003e (ménages/usagers) ou \u003cstrong\u003eindirect\u003c/strong\u003e (employeurs, bienfaisance). Contribution symbolique des ménages aux hôpitaux publics = \u003cstrong\u003e1,20 %\u003c/strong\u003e du budget de fonctionnement (depuis 1974 / arrêté 1995 ; exonérés = démunis, chroniques, PNS, catégories protégées).","\u003cstrong\u003e4) Ressources externes :\u003c/strong\u003e dons et aides internationales (OMS, UNICEF)."]},{"heading":"Coût d’investissement vs Coût de fonctionnement (Ch. 15 Q3)","paragraphs":["En gestion de projet sanitaire :"],"bullets":["\u003cstrong\u003eCoût d’investissement (en capital — Ch. 15 Q3 A) :\u003c/strong\u003e coûts des \u003cstrong\u003eterrains, bâtiments, équipements lourds et semi-lourds\u003c/strong\u003e (non répétitifs).","\u003cstrong\u003eCoût de fonctionnement :\u003c/strong\u003e coûts \u003cstrong\u003erépétitifs\u003c/strong\u003e nécessaires à l’exploitation (salaires, consommables, petites réparations)."]}],"tables":[{"title":"Sécurité sociale en Algérie : repères exacts","headers":["Organisme / Règle","Population / Chiffre exact"],"rows":[["CNAS vs CASNOS","CNAS = travailleurs salariés | CASNOS = travailleurs non-salariés"],["Recettes principales (Ch. 15 Q1)","Cotisations obligatoires à la charge des employeurs et des travailleurs"],["Taux de remboursement","80 % (ticket modérateur 20 %) ; 100 % maladies chroniques \u0026 catégories protégées"],["5 risques couverts","Maladie, Maternité, Invalidité, Accidents de travail (AT), Maladies professionnelles (MP)"]]}],"darija":"ركز على الفرق في 2023 : تمويل \u003cstrong\u003ela sécurité sociale (`Ch.15 Q1`)\u003c/strong\u003e يجي من \u003cstrong\u003ecotisations\u003c/strong\u003e العمال وأرباب العمل (`A`). أما تمويل \u003cstrong\u003ele système de santé كامل (`Ch.40 Q1`)\u003c/strong\u003e يجمع الدولة (الضرائب) + السيكو (cotisations) + العائلات ! و\u003cstrong\u003eCNAS\u003c/strong\u003e للأجراء، \u003cstrong\u003eCASNOS\u003c/strong\u003e لغير الأجراء، والتعويض \u003cstrong\u003e80 %\u003c/strong\u003e (والـ ticket modérateur = \u003cstrong\u003e20 %\u003c/strong\u003e).","triad":{"toUnderstand":["La différence entre financement de la sécurité sociale (cotisations) et financement global du système de santé (État + Sécu + ménages + externe).","La distinction coût d’investissement (capital non répétitif) vs coût de fonctionnement (répétitif)."],"toMemorize":["CNAS (salariés) vs CASNOS (non-salariés) ; remboursement 80 % (ticket modérateur 20 %) / 100 % chroniques.","Coût d’investissement = terrains, bâtiments, équipements lourds/semi-lourds.","Participation ménages aux hôpitaux publics = 1,20 % du budget fonctionnement."],"toRecognizeInQcm":["« coûts répétitifs / petites réparations » → fonctionnement (PAS investissement !).","Sécurité sociale = cotisations employeurs/travailleurs (pas la fiscalité directe)."]}},"memorize":[{"id":"M_L9.1_1","category":"Liste","title":"Les 4 sources de financement","content":"1) \u003cstrong\u003ePublic (État/fiscalité)\u003c/strong\u003e, 2) \u003cstrong\u003eAssurance-maladie (CNAS/CASNOS — cotisations)\u003c/strong\u003e, 3) \u003cstrong\u003ePrivé\u003c/strong\u003e (direct ménages / indirect), 4) \u003cstrong\u003eRessources externes\u003c/strong\u003e (OMS, UNICEF).","highlight":true},{"id":"M_L9.1_2","category":"Seuil / Chiffre","title":"CNAS / CASNOS \u0026 Remboursement","content":"\u003cstrong\u003eCNAS\u003c/strong\u003e = salariés ; \u003cstrong\u003eCASNOS\u003c/strong\u003e = non-salariés. Remboursement = \u003cstrong\u003e80 %\u003c/strong\u003e (ticket modérateur \u003cstrong\u003e20 %\u003c/strong\u003e) ; \u003cstrong\u003e100 %\u003c/strong\u003e maladies chroniques/protégées. 5 risques : maladie, maternité, invalidité, AT, MP.","highlight":true},{"id":"M_L9.1_3","category":"Définition","title":"Coût d’investissement (Ch. 15 Q3)","content":"Coût en capital : \u003cstrong\u003eterrains, bâtiments, équipements lourds et semi-lourds\u003c/strong\u003e (≠ coûts répétitifs d’exploitation / petites réparations).","highlight":true}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L9.2","courseId":"C9","order":2,"title":"Critères d’évaluation (Équité, Efficacité, Pérennité) \u0026 rôle du Privé","durationMin":8,"sourceRef":"Slides 9 \u0026 18–19","bmCount":2,"bmRefs":["Ch. 15 Q2 (2022)","Ch. 15 Q4 (2021)","+ Ch. 15 Q5 (ND)"],"priority":"medium","priorityScore":57,"understand":{"intro":"L’équité est tombée deux années de suite (2021 et 2022) dans exactement les mêmes termes ! La matrice Équité / Efficacité pour Public, Sécu et Privé permet de répondre en 3 secondes sans hésitation.","sections":[{"heading":"Les 3 critères d’évaluation d’un système de financement","paragraphs":["Tout système de financement s’évalue selon 3 axes :"],"bullets":["\u003cstrong\u003eÉquité (Ch. 15 Q2 \u0026 Q4 A) :\u003c/strong\u003e permet d’apprécier l’\u003cstrong\u003eaccès aux soins\u003c/strong\u003e (accès financier pour tous, sans barrière excluant les plus démunis).","\u003cstrong\u003eEfficacité :\u003c/strong\u003e capacité à utiliser de façon optimale les ressources en évitant le gaspillage et la mauvaise gestion.","\u003cstrong\u003ePérennité :\u003c/strong\u003e capacité à assurer la \u003cstrong\u003econtinuité des services\u003c/strong\u003e prodigués dans le temps."]}],"tables":[{"title":"Matrice comparative Public / Sécurité sociale / Privé (Slides 18–19)","headers":["Source de financement","Équité (accès aux soins)","Efficacité / Gestion","Avantages \u0026 Limites clés"],"rows":[["Public (État)","✅ OUI (assure l’équité)","⚠️ Pas entièrement efficace (lourdeurs bureaucratiques)","Solidarité nationale, mais risque de gaspillage"],["Assurance-maladie (Sécu)","✅ OUI (assure l’équité)","✅ Efficace SI contrôle rigoureux","Mutualisation du risque entre cotisants"],["Privé","❌ NON (exclusion des pauvres, inéquité)","✅ Plus efficace (évite gaspillage et mauvaise gestion)","Fournit d’autres ressources à la santé (Ch. 15 Q5 B) et allège l’État"]]}],"darija":"قاعدة ساهلة : \u003cstrong\u003eÉquité = accès aux soins\u003c/strong\u003e (طاحت في 2021 و 2022) ؛ \u003cstrong\u003ePérennité = continuité des services\u003c/strong\u003e. الـ \u003cstrong\u003ePublic + Sécu\u003c/strong\u003e يضمنو الـ Équité. أما الـ \u003cstrong\u003ePrivé\u003c/strong\u003e يعطي موارد إضافية ويمنع التبذير (évite le gaspillage) بصح \u003cstrong\u003eما يضمنش الـ Équité\u003c/strong\u003e (يقصي الفقراء).","triad":{"toUnderstand":["Pourquoi le financement privé évite le gaspillage mais crée une barrière financière excluant les pauvres.","Pourquoi l’équité (accès) et la pérennité (continuité) sont deux critères distincts."],"toMemorize":["Équité = apprécie l’accès aux soins ; Pérennité = continuité des services.","Financement privé : fournit d’autres ressources + évite gaspillage, MAIS n’assure PAS l’équité."],"toRecognizeInQcm":["« Le financement privé ne permet pas d’éviter le gaspillage » → PIÈGE FAUX (il permet au contraire d’éviter le gaspillage !).","« Le financement privé assure l’équité » → FAUX !"]}},"memorize":[{"id":"M_L9.2_1","category":"Définition","title":"Équité vs Pérennité (2× en BM)","content":"\u003cstrong\u003eÉquité :\u003c/strong\u003e apprécie l’\u003cstrong\u003eaccès aux soins\u003c/strong\u003e. \u003cstrong\u003ePérennité :\u003c/strong\u003e apprécie la \u003cstrong\u003econtinuité des services\u003c/strong\u003e. \u003cstrong\u003eEfficacité :\u003c/strong\u003e gestion sans gaspillage.","highlight":true},{"id":"M_L9.2_2","category":"Distinction","title":"Avantages \u0026 limites du financement privé","content":"\u003cstrong\u003eAvantages :\u003c/strong\u003e allège l’État, \u003cstrong\u003efournit d’autres ressources\u003c/strong\u003e, \u003cstrong\u003eévite le gaspillage\u003c/strong\u003e. \u003cstrong\u003eInconvénients :\u003c/strong\u003e \u003cstrong\u003einéquité\u003c/strong\u003e et \u003cstrong\u003eexclusion des pauvres\u003c/strong\u003e.","highlight":true}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L9.3","courseId":"C9","order":3,"title":"Les 3 niveaux d’analyse économique (Macro, Méso, Micro)","durationMin":7,"sourceRef":"Slides 13–17 \u0026 21","bmCount":0,"bmRefs":[],"priority":"low","priorityScore":20,"understand":{"intro":"L’analyse économique du financement s’opère à trois échelles emboîtées (Macro / Méso / Micro) qu’il faut savoir associer à leurs exemples exacts du cours.","sections":[{"heading":"Macro-économique, Méso-économique et Micro-économique","paragraphs":["Chaque niveau répond à une question différente et mobilise des indicateurs propres :"],"bullets":["\u003cstrong\u003eMacro-économique :\u003c/strong\u003e échelle nationale ou régionale ; agrégats globaux tels que le ratio \u003cstrong\u003eDNS / PIB\u003c/strong\u003e (Algérie : 4,57 % en 1993 → \u003cstrong\u003e7,23 % en 2014 \u0026 2018\u003c/strong\u003e ; USA : 12 % ; recoupe `Ch. 18 Q15` CMT+DCS = macro-économie).","\u003cstrong\u003eMéso-économique :\u003c/strong\u003e échelle du \u003cstrong\u003esecteur de la santé lui-même\u003c/strong\u003e (répartition par poste budgétaire : les \u003cstrong\u003edépenses de personnel représentent ~80 %\u003c/strong\u003e du budget d’un établissement).","\u003cstrong\u003eMicro-économique :\u003c/strong\u003e échelle d’une \u003cstrong\u003eunité particulière\u003c/strong\u003e (gestion financière d’un CHU, consommation de médicaments, coût d’une intervention chirurgicale ou d’un GHM)."]}],"tables":[{"title":"Tableau récapitulatif des 3 niveaux d’analyse","headers":["Niveau","Échelle","Indicateurs / Exemples exacts du cours"],"rows":[["Macro-économique","Pays / Région","DNS / PIB (Algérie 7,23 % en 2018 ; USA 12 %), agrégats nationaux"],["Méso-économique","Secteur de la santé","Structure budgétaire du secteur : dépenses de personnel ≈ 80 %"],["Micro-économique","Établissement / Acte / Patient","Gestion d’un CHU, consommation médicaments, coût d’une intervention / GHM"]]}],"darija":"\u003cstrong\u003eMacro\u003c/strong\u003e = على مستوى الدولة كاملة (\u003cstrong\u003eDNS/PIB\u003c/strong\u003e : الجزائر 7,23 % في 2018). \u003cstrong\u003eMéso\u003c/strong\u003e = على مستوى قطاع الصحة (80 % أجور العمال). \u003cstrong\u003eMicro\u003c/strong\u003e = على مستوى مستشفى واحد (CHU) ولا تكلفة عملية ولا دواء.","triad":{"toUnderstand":["La gradation d’échelle : Pays (Macro) → Secteur santé (Méso) → Un établissement ou un acte précis (Micro)."],"toMemorize":["Macro = DNS/PIB (Algérie 7,23 % en 2018) ; Méso = 80 % dépenses personnel ; Micro = gestion d’un CHU, coût d’un acte/GHM."],"toRecognizeInQcm":["Ratio DNS/PIB → Macro-économique (jamais micro !).","Gestion d’un CHU particulier → Micro-économique (ne pas confondre avec méso !)."]}},"memorize":[{"id":"M_L9.3_1","category":"Classification","title":"Macro vs Méso vs Micro-économique","content":"\u003cstrong\u003eMacro :\u003c/strong\u003e pays/région (\u003cstrong\u003eDNS/PIB\u003c/strong\u003e : Algérie 7,23 % en 2018). \u003cstrong\u003eMéso :\u003c/strong\u003e secteur santé (dépenses personnel = \u003cstrong\u003e80 %\u003c/strong\u003e). \u003cstrong\u003eMicro :\u003c/strong\u003e gestion d’un CHU, consommation médicaments, coût d’une intervention/GHM.","highlight":true}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]}]$medjson$::jsonb, $medjson$[]$medjson$::jsonb, $medjson${"analyzedAt":null,"engine":"curated","totalPages":0,"lowConfidencePages":[],"warnings":[],"status":"none"}$medjson$::jsonb, NULL, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, module_id, code, title, short_title, professor, source_files, bm_count, bm_shared_note, bm_recent_count, unique_concepts, priority, priority_score, vigilance_2026, summary, status, version, lessons, attachments, ai_extraction, ppt_import, created_at, updated_at, published_at) VALUES ('C10', 'M4', 'C10', 'Élaboration du questionnaire d’une étude', 'Questionnaire d’Étude', 'Dr CHIBOUB B. (Université Batna 2)', $medjson$["12-Elaboration du questionnaire d’une étude.pdf (2 pages)"]$medjson$::jsonb, 2, 'Tombé 2 années de suite (2024 Ch. 9 Q1 & 2025 Ch. 34 Q1) — cours ultra-court de 2 pages !', 2, 1, 'medium', 57, FALSE, 'Place du questionnaire dans la phase de planification, règles de présentation (titre sans le mot « Questionnaire »), les 7 étapes élémentaires, types de questions (fermées/ordonnées ≤ 3/ouvertes), pré-test (4 objectifs) et modes d’administration (e-mailing 5 %).', 'published', 1, $medjson$[{"id":"L10.1","courseId":"C10","order":1,"title":"Place dans la planification, présentation \u0026 les 7 étapes","durationMin":7,"sourceRef":"Page 1","bmCount":2,"bmRefs":["Ch. 9 Q1 (2024)","Ch. 34 Q1 (2025)"],"priority":"medium","priorityScore":57,"understand":{"intro":"Ce cours de seulement 2 pages offre le meilleur ratio temps/points du programme : la question sur la phase de planification est tombée en 2024 ET de nouveau en 2025 !","sections":[{"heading":"Définition, moment d’élaboration \u0026 présentation","paragraphs":["Parmi les 4 méthodes de recueil d’information (enquête par questionnaire, entretien, observation, étude des documents), le \u003cstrong\u003equestionnaire\u003c/strong\u003e est une technique de collecte de données \u003cstrong\u003equantifiables\u003c/strong\u003e, constituée d’une série de questions précises, claires, écrites, dans un ordre logique."],"bullets":["\u003cstrong\u003eMoment d’élaboration (tombé en 2024 ET 2025 !) :\u003c/strong\u003e il est \u003cstrong\u003eélaboré dans la phase de planification\u003c/strong\u003e de l’étude (jamais à la fin du travail/protocole, jamais dans la « Discussion »), et répond directement aux \u003cstrong\u003eobjectifs de l’étude\u003c/strong\u003e.","\u003cstrong\u003ePrésentation :\u003c/strong\u003e en-tête simplifiée, introduction brève, et un \u003cstrong\u003etitre attrayant\u003c/strong\u003e — \u003cstrong\u003eÉVITER le mot « Questionnaire »\u003c/strong\u003e dans le titre (jugé péjoratif !)."]},{"heading":"Les 7 étapes élémentaires dans l’ordre","paragraphs":["L’élaboration suit rigoureusement 7 étapes successives :"],"bullets":["\u003cstrong\u003e1) Définir l’objectif\u003c/strong\u003e (ce sont les objectifs qui guident la rédaction).","\u003cstrong\u003e2) Choisir les types de questions\u003c/strong\u003e.","\u003cstrong\u003e3) Structurer le questionnaire\u003c/strong\u003e (regrouper par thème, aller du \u003cstrong\u003egénéral au spécifique\u003c/strong\u003e, commencer par des \u003cstrong\u003equestions simples\u003c/strong\u003e pour mettre en confiance, veiller à la longueur et l’utilité).","\u003cstrong\u003e4) Choisir les modalités d’administration\u003c/strong\u003e (cible, taille suffisante, mode).","\u003cstrong\u003e5) Tester le questionnaire (Pré-test systématique)\u003c/strong\u003e.","\u003cstrong\u003e6) Administrer le questionnaire\u003c/strong\u003e.","\u003cstrong\u003e7) Traiter le questionnaire (Dépouillement)\u003c/strong\u003e : bon outil, \u003cstrong\u003ecodifier les questions ouvertes\u003c/strong\u003e, organiser saisie, analyser et rédiger le rapport."]}],"tables":[{"title":"Synthèse des 7 étapes (Dr Chiboub)","headers":["Étape","Règle clé à retenir"],"rows":[["1. Objectif","Guide toute la rédaction (un questionnaire répond toujours à l’objectif)"],["2. Types de questions","Privilégier les fermées ; éviter les ouvertes ; classement ordonné ≤ 3 items"],["3. Structuration","Par thème, du général au spécifique (entonnoir), début par questions simples"],["4–6. Modalités, Pré-test, Administration","Pré-test OBLIGATOIRE avant l’administration finale"],["7. Traitement / Dépouillement","Codification préalable des questions ouvertes + saisie + analyse + rapport"]]}],"darija":"السؤال لي طاح في 2024 وعاود في 2025 : الـ questionnaire يتخدم في \u003cstrong\u003eمرحلة التخطيط (phase de planification)\u003c/strong\u003e ماشي في اللخر ! وتفادى تكتب كلمة « Questionnaire » في العنوان، وابدا بأسئلة ساهلة ومن العام للخاص.","triad":{"toUnderstand":["Pourquoi le questionnaire doit être finalisé et pré-testé durant la planification avant le terrain."],"toMemorize":["Élaboré dans la phase de planification ; répond à l’objectif ; éviter le mot « Questionnaire » dans le titre.","Les 7 étapes dans l’ordre ; structure du général au spécifique + début par questions simples."],"toRecognizeInQcm":["« Fait à la fin du travail/protocole » ou « détaillé dans la Discussion » → FAUX !","« Ne répond pas à l’objectif de l’étude » → FAUX !"]}},"memorize":[{"id":"M_L10.1_1","category":"Piège QCM","title":"Place du questionnaire (2024 \u0026 2025)","content":"\u003cstrong\u003eÉlaboré dans la phase de planification\u003c/strong\u003e de l’étude et répond directement à ses objectifs (collecte de données quantifiables).","highlight":true},{"id":"M_L10.1_2","category":"Liste","title":"Les 7 étapes d’élaboration","content":"1) Objectif → 2) Types de questions → 3) Structurer (général → spécifique, questions simples au début) → 4) Modalités → 5) \u003cstrong\u003ePré-test\u003c/strong\u003e → 6) Administrer → 7) Traiter/dépouiller.","highlight":true},{"id":"M_L10.1_3","category":"Piège QCM","title":"Règle du titre","content":"Titre attrayant : \u003cstrong\u003eéviter le mot « Questionnaire »\u003c/strong\u003e (terme péjoratif).","highlight":false}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L10.2","courseId":"C10","order":2,"title":"Types de questions, pré-test (4 buts) \u0026 modes d’administration","durationMin":7,"sourceRef":"Pages 1–2","bmCount":0,"bmRefs":[],"priority":"low","priorityScore":20,"understand":{"intro":"Cette deuxième page contient toutes les distinctions techniques : avantages/inconvénients de chaque type de question, les 4 objectifs exacts du pré-test et les taux de retour des modes d’administration.","sections":[{"heading":"Les 4 objectifs du pré-test (Étape 5) \u0026 Modes d’administration (Étape 6)","paragraphs":["Le pré-test est une étape \u003cstrong\u003esystématique et indispensable\u003c/strong\u003e sur un petit échantillon avant de lancer l’enquête :"],"bullets":["\u003cstrong\u003eLes 4 vérifications du pré-test :\u003c/strong\u003e 1) Conception/compréhension des questions, 2) Adaptation des modalités de réponse, 3) Oublis éventuels, 4) \u003cstrong\u003eTemps réel de passation\u003c/strong\u003e.","\u003cstrong\u003eFace à face :\u003c/strong\u003e contact direct, permet d’observer les réactions et de reformuler si besoin.","\u003cstrong\u003eTéléphone :\u003c/strong\u003e rapide et économique, mais nécessite une mise à jour des numéros.","\u003cstrong\u003eCourriel / E-mailing :\u003c/strong\u003e rapide mais \u003cstrong\u003epeu efficace (~5 % de taux de retour seulement !)\u003c/strong\u003e."]}],"tables":[{"title":"Comparaison des types de questions (Page 1)","headers":["Type de question","Avantages","Inconvénients / Limites"],"rows":[["Fermée à choix unique","Rapidité, simplicité de traitement","Peu pratique pour étudier les comportements complexes"],["Fermée à choix multiples","Simplicité de traitement et dépouillement","Influence les réponses, liste parfois trop longue"],["Fermée ordonnée (classement)","Classement par préférence, précision","Classement NON supérieur à 3 propositions (≤ 3) !"],["Ouverte (À ÉVITER)","Richesse de contenu, spontanéité","Dépouillement et analyse longs (nécessite codification à l’Étape 7)"]]}],"darija":"احفظ 3 أرقام/قواعد في الصفحة الثانية : الترتيب (question ordonnée) ما يفوتش \u003cstrong\u003e3 اختيارات (≤ 3 propositions)\u003c/strong\u003e ؛ الـ \u003cstrong\u003eQuestions ouvertes\u003c/strong\u003e نتفاداوهم ونكوديوهوم في اللخر ؛ والـ \u003cstrong\u003eE-mailing\u003c/strong\u003e ضعيف يرجع غير \u003cstrong\u003e5 %\u003c/strong\u003e !","triad":{"toUnderstand":["Pourquoi les questions ouvertes compliquent l’analyse statistique (codification manuelle requise)."],"toMemorize":["Classement hiérarchique : ≤ 3 propositions ; Questions ouvertes : à éviter (codifier au dépouillement).","4 buts du pré-test : conception, adaptation des modalités, oublis, temps réel de passation.","E-mailing : taux de retour faible (~5 %)."],"toRecognizeInQcm":["« Privilégier les questions ouvertes pour faciliter le dépouillement » → FAUX !","« L’e-mailing assure un taux de retour élevé (\u003e 70 %) » → FAUX (5 % seulement !)."]}},"memorize":[{"id":"M_L10.2_1","category":"Seuil / Chiffre","title":"Types de questions \u0026 seuils","content":"Fermée ordonnée : \u003cstrong\u003e≤ 3 propositions\u003c/strong\u003e à classer. Questions \u003cstrong\u003eouvertes : à éviter\u003c/strong\u003e (dépouillement long, codification requise à l’Étape 7).","highlight":true},{"id":"M_L10.2_2","category":"Liste","title":"Les 4 vérifications du Pré-test (Étape 5)","content":"1) Conception des questions, 2) Adaptation des modalités, 3) Oublis éventuels, 4) \u003cstrong\u003eTemps réel de passation\u003c/strong\u003e.","highlight":true},{"id":"M_L10.2_3","category":"Seuil / Chiffre","title":"Modes d’administration","content":"Face à face (contact/réactions), Téléphone (rapide/économique), \u003cstrong\u003eE-mailing = peu efficace (~5 % de retour)\u003c/strong\u003e.","highlight":false}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]}]$medjson$::jsonb, $medjson$[]$medjson$::jsonb, $medjson${"analyzedAt":null,"engine":"curated","totalPages":0,"lowConfidencePages":[],"warnings":[],"status":"none"}$medjson$::jsonb, NULL, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, module_id, code, title, short_title, professor, source_files, bm_count, bm_shared_note, bm_recent_count, unique_concepts, priority, priority_score, vigilance_2026, summary, status, version, lessons, attachments, ai_extraction, ppt_import, created_at, updated_at, published_at) VALUES ('C11', 'M4', 'C11', 'Statistique descriptive (+ TD)', 'Statistique Descriptive', 'Pr H. BENALDJIA (Université Batna 2, 2026–2027)', $medjson$["statistique descriptive 2026.pdf (69 slides)","TD statistique descriptive.pptx (25 slides)"]$medjson$::jsonb, 29, 'Cours n°2 en volume dans la BM (28 QCM Ch. 37 + 1 QCM Ch. 17 Q14) — ⚠️ 3 erreurs corrigé BM', 7, 8, 'very_high', 100, FALSE, 'Types de variables, fréquences relatives, ratio et sex-ratio, choix du graphique selon la variable (10 QCM !), tendance centrale (moyenne, médiane, mode), quantiles (quartiles/déciles/percentiles) et dispersion (étendue, variance, écart-type, CV — 10 QCM !).', 'published', 1, $medjson$[{"id":"L11.1","courseId":"C11","order":1,"title":"Types de variables, fréquences, ratio \u0026 représentations graphiques","durationMin":14,"sourceRef":"Slides 4–36 + TD","bmCount":15,"bmRefs":["Ch. 37 Q1 (2025)","Q6–Q8 (2022–2024)","Q12–Q13, Q15–Q16, Q19–Q22, Q25, Q28","Ch. 17 Q14 (2022)"],"priority":"very_high","priorityScore":100,"understand":{"intro":"Sujet n°1 ex-aequo de toute la plateforme (Score 100/100) ! 10 QCM testent directement le choix du graphique selon le type de variable, et 5 autres testent les types de variables, fréquences relatives et ratio/sex-ratio.","sections":[{"heading":"Types de variables, Fréquence relative, Ratio \u0026 Sex-ratio","paragraphs":["Avant de choisir un tableau ou un graphique, il faut identifier avec précision la nature de la variable :"],"bullets":["\u003cstrong\u003eQualitative nominale :\u003c/strong\u003e modalités sans ordre (sexe, groupe sanguin, état civil).","\u003cstrong\u003eQualitative ordinale :\u003c/strong\u003e modalités ordonnées (satisfaction, \u003cstrong\u003estades d’une affection chronique\u003c/strong\u003e — tombé en 2025 `Ch. 37 Q1` !).","\u003cstrong\u003eQuantitative discontinue (discrète) :\u003c/strong\u003e valeurs entières isolées (\u003cstrong\u003enombre de rappels d’un vaccin\u003c/strong\u003e — `Ch. 37 Q19 D`, fréquence cardiaque, fratrie).","\u003cstrong\u003eQuantitative continue :\u003c/strong\u003e toutes valeurs réelles dans un intervalle (\u003cstrong\u003epoids\u003c/strong\u003e — `Ch. 37 Q6 \u0026 Q7`, taille, glycémie, TA).","\u003cstrong\u003eFréquence relative (Ch. 37 Q16 A) :\u003c/strong\u003e rapport entre la fréquence absolue (\u003cem\u003en\u003csub\u003ei\u003c/sub\u003e\u003c/em\u003e) et l’effectif total (\u003cem\u003eN\u003c/em\u003e). Fréquences cumulées : uniquement pour variables ordonnées.","\u003cstrong\u003eRatio (Ch. 17 Q14 C \u0026 Ch. 37 Q12) :\u003c/strong\u003e rapport des effectifs/fréquences de \u003cstrong\u003e2 modalités d’une MÊME variable\u003c/strong\u003e (ex. \u003cstrong\u003eSex-ratio = Masculin / Féminin\u003c/strong\u003e — `Ch. 37 Q21 A`, exemple cours : 15/35 = 0,43)."]}],"tables":[{"title":"Tableau d’or : Quel graphique pour quelle variable ? (10 QCM BM !)","headers":["Type de variable","Graphique(s) adapté(s)","Caractéristiques \u0026 Pièges QCM"],"rows":[["Qualitative (nominale ou ordinale : sexe, stades)","Diagramme en barres (barres ESPACÉES) + Diagramme circulaire (≤ 6 modalités)","1 % = 3,6° (PAS 4,6° !). JAMAIS remplacé par un histogramme !"],["Quantitative discontinue / discrète (nb rappels vaccin)","Diagramme en bâtons (bâtonnets)","Bâtons fins verticaux sur valeurs entières"],["Quantitative continue (poids, taille, âge)","Histogramme (barres JUXTAPOSÉES) + Polygone de fréquence + Boîte à moustaches","Polygone = ligne brisée joignant les milieux des sommets, compare plusieurs distributions ; surfaces = effectifs simples (PAS cumulés !)"]]}],"darija":"هاد الجدول يجيبلك نقاط مضمونة : \u003cstrong\u003eQualitatif\u003c/strong\u003e (الجنس، مراحل مرض) ← \u003cstrong\u003eDiagramme en barres (متباعدين)\u003c/strong\u003e + \u003cstrong\u003eCirculaire (1 % = 3,6°)\u003c/strong\u003e. \u003cstrong\u003eQuantitatif continu\u003c/strong\u003e (الوزن، الطول) ← \u003cstrong\u003eHistogramme (أعمدة لاصقين juxtaposées)\u003c/strong\u003e + \u003cstrong\u003ePolygone de fréquence\u003c/strong\u003e. و\u003cstrong\u003eRatio\u003c/strong\u003e = زوج modalités من \u003cstrong\u003eنفس المتغير\u003c/strong\u003e (Sex-ratio = رجال ÷ نساء).","triad":{"toUnderstand":["Pourquoi les barres sont juxtaposées dans un histogramme (continuité des classes) et espacées dans un diagramme en barres (catégories distinctes).","Pourquoi un titre de tableau/graphique (TD) doit mentionner Quoi, Qui, Où, Quand + effectif N + unités."],"toMemorize":["Qualitative → Barres espacées + Circulaire (1 % = 3,6°) ; Discrète → Bâtons ; Continue → Histogramme (juxtaposé) + Polygone.","Ratio = 2 modalités d’une MÊME variable ; Sex-ratio = Masculin / Féminin.","Polygone de fréquence = ligne brisée joignant les milieux des sommets de l’histogramme."],"toRecognizeInQcm":["« Stades d’une affection chronique » (2025) = qualitative ordinale → Diagramme à barres + Circulaire (AD).","« Poids d’une série d’individus » (2024 ×2) = quantitative continue → Histogramme (A).","« 2 modalités de 2 variables différentes » pour un ratio → PIÈGE FAUX !"]}},"memorize":[{"id":"M_L11.1_1","category":"Classification","title":"Association Variables ↔ Graphiques (10× en BM)","content":"\u003cstrong\u003eQualitative :\u003c/strong\u003e Barres espacées + Circulaire. \u003cstrong\u003eQuanti discrète :\u003c/strong\u003e Bâtons. \u003cstrong\u003eQuanti continue :\u003c/strong\u003e \u003cstrong\u003eHistogramme\u003c/strong\u003e (barres juxtaposées) + \u003cstrong\u003ePolygone de fréquence\u003c/strong\u003e.","highlight":true},{"id":"M_L11.1_2","category":"Formule","title":"Angle du diagramme circulaire","content":"\u003cstrong\u003e1 % = 3,6°\u003c/strong\u003e (Angle = Fréquence % × 3,6°). \u003cem\u003ePiège BM Ch. 37 Q22 D : « 4,6° » est FAUX !\u003c/em\u003e","highlight":true},{"id":"M_L11.1_3","category":"Formule","title":"Ratio \u0026 Sex-ratio","content":"\u003cstrong\u003eRatio :\u003c/strong\u003e rapport des fréquences de \u003cstrong\u003e2 modalités d’une MÊME variable\u003c/strong\u003e. \u003cstrong\u003eSex-ratio\u003c/strong\u003e = \u003cspan class=\"math-frac\"\u003e\u003cspan\u003eEffectif Masculin\u003c/span\u003e\u003cspan\u003eEffectif Féminin\u003c/span\u003e\u003c/span\u003e.","highlight":true},{"id":"M_L11.1_4","category":"Définition","title":"Polygone de fréquence (Ch. 37 Q28)","content":"Graphe pour \u003cstrong\u003evariable quantitative continue\u003c/strong\u003e, construit en joignant le \u003cstrong\u003epoint milieu du sommet\u003c/strong\u003e de chaque rectangle de l’histogramme (aspect de \u003cstrong\u003eligne brisée\u003c/strong\u003e).","highlight":false}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L11.2","courseId":"C11","order":2,"title":"Paramètres de tendance centrale \u0026 de position (Quantiles)","durationMin":10,"sourceRef":"Slides 38–61","bmCount":4,"bmRefs":["Ch. 37 Q17 (2019)","Ch. 37 Q23 (ND)","Ch. 37 Q26 (ND)","Ch. 37 Q27 (ND)"],"priority":"high","priorityScore":70,"understand":{"intro":"Les paramètres de réduction se répartissent en 3 familles qu’il ne faut jamais mélanger en QCM : Tendance centrale (moyenne, médiane, mode), Position (quartiles, déciles, percentiles) et Dispersion (leçon suivante).","sections":[{"heading":"Les 3 paramètres de tendance centrale","paragraphs":["Ils résument le « centre » d’une distribution et s’expriment tous dans \u003cstrong\u003ela même unité que la variable\u003c/strong\u003e :"],"bullets":["\u003cstrong\u003eMoyenne arithmétique (Ch. 37 Q23 ACE) :\u003c/strong\u003e \u003cem\u003eM\u003c/em\u003e = Σx\u003csub\u003ei\u003c/sub\u003e / N (ou pondérée Σn\u003csub\u003ei\u003c/sub\u003ex\u003csub\u003ei\u003c/sub\u003e / N). Localise le centre, a \u003cstrong\u003el’unité de la variable\u003c/strong\u003e, et est \u003cstrong\u003edifférente de la médiane si la distribution est dissymétrique\u003c/strong\u003e (sensible aux valeurs extrêmes !). Ex. cours slide 41 : \u003ccode\u003e3,3,3,3,4,4,5,5,5,5,7,9\u003c/code\u003e (N=12) → M = 56/12 = 4,7.","\u003cstrong\u003eMédiane (Ch. 37 Q17 BC) :\u003c/strong\u003e valeur du milieu qui partage la série en 2 moitiés égales (50 % / 50 %). \u003cstrong\u003eNécessite obligatoirement de ranger les valeurs par ordre croissant\u003c/strong\u003e au préalable ! S’exprime dans l’unité de la variable. Si N impair : rang (N+1)/2 (ex. N=27 → 14e valeur = 163 cm) ; si N pair : demi-somme des 2 valeurs centrales.","\u003cstrong\u003eMode (Ch. 37 Q26 ABC) :\u003c/strong\u003e valeur la plus fréquente (dominante) ; s’observe dans une série, se calcule dans une distribution groupée ; \u003cstrong\u003eégal à la médiane dans une distribution symétrique\u003c/strong\u003e ; \u003cstrong\u003epeut ne pas exister\u003c/strong\u003e (ou être bi/plurimodal)."]},{"heading":"Les paramètres de position : Quantiles","paragraphs":["Ils divisent une série ordonnée en parts égales d’effectif (ce ne sont PAS des paramètres de dispersion !) :"],"bullets":["\u003cstrong\u003eQuartiles (Ch. 37 Q27 AC) :\u003c/strong\u003e au nombre de \u003cstrong\u003e3\u003c/strong\u003e (Q₁, Q₂, Q₃), divisent la distribution en \u003cstrong\u003e4 parties égales\u003c/strong\u003e (25 % chacune) ; \u003cstrong\u003eQ₂ = Médiane\u003c/strong\u003e.","\u003cstrong\u003eDéciles :\u003c/strong\u003e au nombre de \u003cstrong\u003e9\u003c/strong\u003e (D₁ à D₉), divisent en \u003cstrong\u003e10 parties égales\u003c/strong\u003e ; \u003cstrong\u003eD₅ = Médiane\u003c/strong\u003e.","\u003cstrong\u003ePercentiles (Centiles) :\u003c/strong\u003e au nombre de \u003cstrong\u003e99\u003c/strong\u003e, divisent en \u003cstrong\u003e100 parties égales\u003c/strong\u003e ; P₅₀ = Médiane."]}],"tables":[{"title":"Comparaison Moyenne / Médiane / Mode / Quantiles","headers":["Paramètre","Famille","Condition / Propriété clé"],"rows":[["Moyenne arithmétique","Tendance centrale","Même unité que la variable ; sensible aux valeurs extrêmes ; ≠ médiane si dissymétrique"],["Médiane (= Q₂ = D₅)","Tendance centrale / Position","Ranger par ordre croissant d’abord ; même unité ; robuste aux extrêmes"],["Mode","Tendance centrale","Valeur la plus fréquente ; peut ne pas exister ; = médiane si symétrique unimodale"],["Quartiles / Déciles / Percentiles","Position (Quantiles)","3 quartiles (4 parts) | 9 déciles (10 parts) | 99 percentiles (100 parts) — PAS de dispersion !"]]}],"darija":"رد بالك من 3 أفخاخ : (1) \u003cstrong\u003eLa médiane\u003c/strong\u003e لازم قبل كل شي ترتب الأرقام تصاعديا (ordre croissant) وعندها نفس وحدة المتغير. (2) \u003cstrong\u003eLa moyenne\u003c/strong\u003e عندها نفس وحدة المتغير وتختلف على la médiane كي تكون السلسلة غير متناظرة (dissymétrique). (3) \u003cstrong\u003eLes quartiles\u003c/strong\u003e عددهم \u003cstrong\u003e3\u003c/strong\u003e (يقسمو على 4) و\u003cstrong\u003eQ₂ = Médiane\u003c/strong\u003e وهما paramètres de \u003cstrong\u003eposition\u003c/strong\u003e ماشي dispersion !","triad":{"toUnderstand":["Pourquoi la moyenne s’écarte de la médiane dans une distribution asymétrique (attraction par les extrêmes)."],"toMemorize":["Moyenne, Médiane, Mode = tendance centrale (même unité que la variable).","Médiane = nécessite tri croissant ; = Q₂ = D₅.","3 quartiles (4 parts), 9 déciles (10 parts), 99 percentiles (100 parts)."],"toRecognizeInQcm":["« La moyenne est sans unité » → FAUX (c’est le CV qui est sans unité !).","« Les quartiles sont des paramètres de dispersion » → FAUX (ce sont des paramètres de position !)."]}},"memorize":[{"id":"M_L11.2_1","category":"Définition","title":"Moyenne, Médiane \u0026 Mode","content":"\u003cstrong\u003eMoyenne :\u003c/strong\u003e centre, même unité, ≠ médiane si dissymétrique. \u003cstrong\u003eMédiane :\u003c/strong\u003e exige \u003cstrong\u003eordre croissant\u003c/strong\u003e, même unité, = Q₂. \u003cstrong\u003eMode :\u003c/strong\u003e valeur dominante, peut ne pas exister, = médiane si symétrique.","highlight":true},{"id":"M_L11.2_2","category":"Seuil / Chiffre","title":"Les Quantiles (Position)","content":"\u003cstrong\u003eQuartiles :\u003c/strong\u003e \u003cstrong\u003e3\u003c/strong\u003e valeurs → 4 parts (Q₂ = Médiane). \u003cstrong\u003eDéciles :\u003c/strong\u003e \u003cstrong\u003e9\u003c/strong\u003e valeurs → 10 parts (D₅ = Médiane). \u003cstrong\u003ePercentiles :\u003c/strong\u003e \u003cstrong\u003e99\u003c/strong\u003e valeurs → 100 parts.","highlight":true}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L11.3","courseId":"C11","order":3,"title":"Paramètres de dispersion (Étendue, Variance, Écart-type, CV)","durationMin":13,"sourceRef":"Slides 62–69","bmCount":10,"bmRefs":["Ch. 37 Q2–Q5 (2024)","Q9–Q11 (2022)","Q14, Q18 (2019)","Q24 (ND)"],"priority":"very_high","priorityScore":95,"bmWarning":"⚠️ 3 erreurs dans le corrigé BM Ch. 37 : Q14 (Étendue = C [max − min], PAS A [amplitude classe] !), Q11 (CV = BC, pas seulement C) et Q24 (CV = BDE, pas seulement BE).","understand":{"intro":"Deuxième pilier géant du Cours 11 : 10 QCM dans la BM ! La variance (4×) et le coefficient de variation (4×) sont parmi les définitions les plus répétées de toute l’épidémiologie à Batna.","sections":[{"heading":"Les 4 paramètres de dispersion \u0026 exemples exacts du cours","paragraphs":["Les paramètres de dispersion mesurent à quel point les observations sont regroupées ou étalées autour du centre :"],"bullets":["\u003cstrong\u003eÉtendue (Ch. 37 Q9 C \u0026 Q14 C) :\u003c/strong\u003e paramètre de dispersion = \u003cstrong\u003eValeur maximale − Valeur minimale\u003c/strong\u003e (\u003cem\u003eX\u003csub\u003emax\u003c/sub\u003e − X\u003csub\u003emin\u003c/sub\u003e\u003c/em\u003e). \u003cem\u003eNe jamais confondre avec l’amplitude d’une classe (borne sup − borne inf d’une classe) !\u003c/em\u003e","\u003cstrong\u003eVariance S² (4× en BM : Q2, Q3, Q10, Q18) :\u003c/strong\u003e mesure de l’\u003cstrong\u003eétalement des valeurs observées par rapport à la valeur moyenne\u003c/strong\u003e. \u003cstrong\u003ePlus elle est élevée, plus les données sont éloignées de la moyenne.\u003c/strong\u003e Formule slide 65 : \u003cem\u003eS² = Σ(x\u003csub\u003ei\u003c/sub\u003e − m)² / N\u003c/em\u003e \u003cem\u003e(note : l’exemple numérique slide 67 utilise N−1 sur échantillon : Série 1 \u003ccode\u003e15,20,25,30,35\u003c/code\u003e → S² = 62,5, S = 7,9 ; Série 2 \u003ccode\u003e5,15,25,35,45\u003c/code\u003e → S² = 250, S = 15,8)\u003c/em\u003e.","\u003cstrong\u003eÉcart-type S :\u003c/strong\u003e \u003cstrong\u003eracine carrée de la variance\u003c/strong\u003e (\u003cem\u003eS = √S²\u003c/em\u003e), exprimé dans la même unité que la variable. Plus il est faible, plus les données sont concentrées autour de la moyenne.","\u003cstrong\u003eCoefficient de variation CV (4× en BM : Q4, Q5, Q11, Q24) :\u003c/strong\u003e \u003cem\u003eCV = (s / m) × 100\u003c/em\u003e. Exprime le degré de dispersion (l’écart-type) en fonction de la moyenne ; \u003cstrong\u003esans unité de mesure\u003c/strong\u003e (exprimé en \u003cstrong\u003e%\u003c/strong\u003e) ; permet de comparer la variabilité de \u003cstrong\u003e2 variables d’unités différentes\u003c/strong\u003e dans une même population."]}],"tables":[{"title":"Récapitulatif des 4 formules de dispersion \u0026 pièges BM","headers":["Paramètre","Formule exacte","Unité","Piège classique en QCM"],"rows":[["Étendue","Xmax − Xmin","Unité de la variable","≠ amplitude d’une classe (⚠️ erreur BM Ch. 37 Q14 !)"],["Variance (S²)","Σ(xi − m)² / N  (ou N−1 éch.)","(Unité)²","≠ racine carrée de l’écart-type (c’est l’inverse !)"],["Écart-type (S)","√(Variance) = √(S²)","Unité de la variable","C’est S qui est la racine carrée de S² !"],["Coefficient de variation (CV)","(s / m) × 100","SANS unité (en %)","≠ moyenne / écart-type ! Exprimé en % (⚠️ BM Q11 \u0026 Q24)"]]}],"darija":"احفظ 3 قواعد حديدية : (1) \u003cstrong\u003eLa variance\u003c/strong\u003e = تباعد القيم على \u003cstrong\u003eالمتوسط (moyenne)\u003c/strong\u003e (كلما تكبر كلما القيم بعاد). (2) \u003cstrong\u003eL’écart-type\u003c/strong\u003e هو الجذر التربيعي تاع la variance (ماشي العكس!). (3) \u003cstrong\u003eCV = écart-type ÷ moyenne × 100\u003c/strong\u003e، \u003cstrong\u003eبلا وحدة\u003c/strong\u003e ويخرج بـ \u003cstrong\u003e%\u003c/strong\u003e. و\u003cstrong\u003eÉtendue = max − min\u003c/strong\u003e (تجاهل غلطة الـ BM في Q14!).","triad":{"toUnderstand":["Pourquoi le CV (sans dimension) est le seul outil permettant de comparer la dispersion d’un poids (en kg) et d’une glycémie (en g/L)."],"toMemorize":["Variance = mesure de l’étalement par rapport à la moyenne.","CV = (écart-type / moyenne) × 100 ; sans unité ; exprimé en %.","Étendue = Xmax − Xmin (paramètre de dispersion)."],"toRecognizeInQcm":["« CV = moyenne / écart-type » → PIÈGE FAUX (toujours s / m !).","« La variance est la racine carrée de l’écart-type » → PIÈGE FAUX !","« CV exprimé dans la même unité que la variable » → PIÈGE FAUX (sans unité, en % !)."]}},"memorize":[{"id":"M_L11.3_1","category":"Définition","title":"Variance (4× en BM)","content":"Mesure de l’\u003cstrong\u003eétalement des valeurs observées par rapport à la valeur moyenne\u003c/strong\u003e. Plus elle est élevée, plus les données sont éloignées de la moyenne. \u003cstrong\u003eÉcart-type = √Variance\u003c/strong\u003e.","highlight":true},{"id":"M_L11.3_2","category":"Formule","title":"Coefficient de variation — CV (4× en BM)","content":"\u003cstrong\u003eCV = \u003cspan class=\"math-frac\"\u003e\u003cspan\u003eécart-type (s)\u003c/span\u003e\u003cspan\u003emoyenne (m)\u003c/span\u003e\u003c/span\u003e × 100\u003c/strong\u003e. Paramètre de dispersion, \u003cstrong\u003esans unité\u003c/strong\u003e, exprimé en \u003cstrong\u003e%\u003c/strong\u003e, compare 2 variables d’unités différentes.","highlight":true},{"id":"M_L11.3_3","category":"Formule","title":"Étendue (⚠️ Erreur BM Q14)","content":"Paramètre de dispersion : \u003cstrong\u003eÉtendue = Valeur maximale − Valeur minimale\u003c/strong\u003e (≠ amplitude d’une classe !).","highlight":true}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]}]$medjson$::jsonb, $medjson$[]$medjson$::jsonb, $medjson${"analyzedAt":null,"engine":"curated","totalPages":0,"lowConfidencePages":[],"warnings":[],"status":"none"}$medjson$::jsonb, NULL, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, module_id, code, title, short_title, professor, source_files, bm_count, bm_shared_note, bm_recent_count, unique_concepts, priority, priority_score, vigilance_2026, summary, status, version, lessons, attachments, ai_extraction, ppt_import, created_at, updated_at, published_at) VALUES ('C12', 'M4', 'C12', 'Test d’hypothèse : Comparaison de 2 pourcentages (Test du χ²)', 'Test du Chi-deux (χ²)', 'Pr AOUIDANE (Université Batna 2)', $medjson$["test d\u0027hypothèse  comparaison de 2 pourcentage.ppsx.pptx (29 slides)"]$medjson$::jsonb, 2, 'Tombe chaque année (2024 Ch. 42 Q4 & 2025 Ch. 43 Q1 reclassée !)', 2, 1, 'high', 67, FALSE, 'Démarche hypothético-déductive (H₀ / H₁), risque α (a priori) vs p-value (a posteriori), χ² de conformité vs d’homogénéité, calcul complet sur tableau 2×2 (Cij ≥ 5, χ²o, ddl = (L−1)(C−1), seuil 3,841) et règle de décision.', 'published', 1, $medjson$[{"id":"L12.1","courseId":"C12","order":1,"title":"Démarche hypothético-déductive, risque α vs p-value \u0026 types de χ²","durationMin":10,"sourceRef":"Slides 5–15","bmCount":0,"bmRefs":[],"priority":"low","priorityScore":25,"understand":{"intro":"Avant de faire le calcul du χ², il faut comprendre parfaitement le sens de H₀, H₁, du risque α et de la p-value pour ne tomber dans aucun piège de formulation théorique.","sections":[{"heading":"Les 4 étapes de la démarche hypothético-déductive","paragraphs":["Le \u003cstrong\u003ebut d’un test statistique\u003c/strong\u003e (slide 5) est de déterminer si la différence observée entre deux échantillons est due au \u003cstrong\u003ehasard\u003c/strong\u003e (fluctuations d’échantillonnage) ou si elle est \u003cstrong\u003eréelle\u003c/strong\u003e :"],"bullets":["\u003cstrong\u003e1) Hypothèse nulle (H₀) :\u003c/strong\u003e absence de différence (\u003cem\u003eP\u003csub\u003eA\u003c/sub\u003e = P\u003csub\u003eB\u003c/sub\u003e\u003c/em\u003e) — hypothèse de départ que l’on cherche à invalider/rejeter.","\u003cstrong\u003e2) Hypothèse alternative (H₁) :\u003c/strong\u003e retenue si H₀ est rejetée ; en formulation \u003cstrong\u003ebilatérale\u003c/strong\u003e : \u003cem\u003eP\u003csub\u003eA\u003c/sub\u003e ≠ P\u003csub\u003eB\u003c/sub\u003e\u003c/em\u003e (sans préciser le sens).","\u003cstrong\u003e3) Risque de 1ère espèce (α) :\u003c/strong\u003e risque de \u003cstrong\u003erejeter à tort H₀\u003c/strong\u003e (conclure à une différence qui n’existe pas) ; fixé \u003cstrong\u003ea priori\u003c/strong\u003e avant tout calcul (généralement \u003cstrong\u003eα = 0,05 = 5 %\u003c/strong\u003e).","\u003cstrong\u003e4) Degré de signification (p-value) :\u003c/strong\u003e probabilité d’observer une valeur du test au moins aussi grande si H₀ est vraie ; déterminé \u003cstrong\u003ea posteriori\u003c/strong\u003e après calcul."]}],"tables":[{"title":"2 Distinctions fondamentales du cours du Pr Aouidane","headers":["Concept A","Concept B","Différence clé"],"rows":[["Risque α (seuil)","Degré de signification (p-value)","α est fixé A PRIORI (ex. 5 %) avant calcul ; p est déterminé A POSTERIORI après calcul"],["χ² de conformité (ajustement)","χ² d’homogénéité","Conformité = 1 échantillon vs distribution théorique connue ; Homogénéité = ≥ 2 échantillons comparés entre eux"],["Effectifs (Oij, Cij)","Pourcentages (%)","Le test du χ² compare des pourcentages mais se calcule TOUJOURS sur des EFFECTIFS !"]]}],"darija":"الفرق بين \u003cstrong\u003eα\u003c/strong\u003e و \u003cstrong\u003ep\u003c/strong\u003e ساهل : \u003cstrong\u003eα\u003c/strong\u003e نحددوه \u003cstrong\u003eقبل الحساب (a priori = 5 %)\u003c/strong\u003e وهو خطر نرفضو H₀ بالغلط؛ أما \u003cstrong\u003ep-value\u003c/strong\u003e تخرج \u003cstrong\u003eبعد الحساب (a posteriori)\u003c/strong\u003e من الجدول. و\u003cstrong\u003eχ² de conformité\u003c/strong\u003e = عينة وحدة ضد نظرية، أما \u003cstrong\u003ed’homogénéité\u003c/strong\u003e = زوج عينات ولا أكثر ضد بعضاهم.","triad":{"toUnderstand":["Pourquoi on teste toujours H₀ (égalité) pour voir si les données la contredisent au-delà du hasard."],"toMemorize":["α = risque de rejeter H₀ à tort, fixé a priori (5 %) ; p = déterminé a posteriori.","χ² de conformité (1 échantillon vs théorique) vs χ² d’homogénéité (≥ 2 échantillons).","Le χ² se calcule toujours sur des EFFECTIFS (jamais directement sur des pourcentages)."],"toRecognizeInQcm":["« α est calculé a posteriori » → FAUX (c’est a priori !).","« On applique directement la formule du χ² sur les pourcentages » → FAUX (sur les effectifs !)."]}},"memorize":[{"id":"M_L12.1_1","category":"Distinction","title":"Risque α vs Degré de signification (p)","content":"\u003cstrong\u003eRisque α :\u003c/strong\u003e risque de rejeter à tort H₀, fixé \u003cstrong\u003ea priori\u003c/strong\u003e (5 %). \u003cstrong\u003ep-value :\u003c/strong\u003e déterminée \u003cstrong\u003ea posteriori\u003c/strong\u003e après calcul de χ²o.","highlight":true},{"id":"M_L12.1_2","category":"Distinction","title":"χ² de conformité vs χ² d’homogénéité","content":"\u003cstrong\u003eConformité (ajustement) :\u003c/strong\u003e 1 échantillon vs distribution théorique. \u003cstrong\u003eHomogénéité :\u003c/strong\u003e ≥ 2 échantillons entre eux. Toujours calculé sur des \u003cstrong\u003eeffectifs\u003c/strong\u003e !","highlight":true}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]},{"id":"L12.2","courseId":"C12","order":2,"title":"Calcul pas à pas du χ² sur tableau 2×2 (Cij ≥ 5, ddl, seuil 3,841)","durationMin":13,"sourceRef":"Slides 16–27","bmCount":2,"bmRefs":["Ch. 43 Q1 (2025 — reclassé !)","Ch. 42 Q4 (2024 — incomplet)"],"priority":"high","priorityScore":67,"bmWarning":"ℹ️ Anomalies BM signalées : Ch. 42 Q4 (2024) est imprimée sans tableau ni options, et Ch. 43 Q1 (2025) a été classée par erreur dans « Validité d’un test diagnostic » avec une photo de tableau corrompue (mais sa logique χ² = 0,40 \u003c 3,841 ⇒ non significatif est exacte !).","understand":{"intro":"Un exercice pratique de tableau 2×2 est tombé en 2024 ET en 2025 ! La recette en 4 étapes ci-dessous est toujours identique et vous garantit des points faciles.","sections":[{"heading":"La recette en 4 étapes + exemple exact du cours (Slide 27)","paragraphs":["Pour tout tableau de contingence à \u003cem\u003eL\u003c/em\u003e lignes et \u003cem\u003eC\u003c/em\u003e colonnes (\u003cem\u003eN\u003c/em\u003e observations) :"],"bullets":["\u003cstrong\u003eÉtape 1 — Effectifs théoriques C\u003csub\u003eij\u003c/sub\u003e :\u003c/strong\u003e C\u003csub\u003eij\u003c/sub\u003e = (Total ligne \u003cem\u003ei\u003c/em\u003e × Total colonne \u003cem\u003ej\u003c/em\u003e) / N. \u003cstrong\u003eCondition absolue : tous les effectifs THÉORIQUES C\u003csub\u003eij\u003c/sub\u003e doivent être ≥ 5\u003c/strong\u003e (pas les effectifs observés !).","\u003cstrong\u003eÉtape 2 — Calcul de χ²\u003csub\u003eo\u003c/sub\u003e :\u003c/strong\u003e χ²\u003csub\u003eo\u003c/sub\u003e = Σ (O\u003csub\u003eij\u003c/sub\u003e − C\u003csub\u003eij\u003c/sub\u003e)² / C\u003csub\u003eij\u003c/sub\u003e (somme sur les 4 cases pour un tableau 2×2).","\u003cstrong\u003eÉtape 3 — Degrés de liberté :\u003c/strong\u003e ddl = (L − 1)(C − 1). Pour un 2×2 : \u003cstrong\u003eddl = 1\u003c/strong\u003e → valeur critique au risque α = 5 % : \u003cstrong\u003eχ²\u003csub\u003e5%\u003c/sub\u003e = 3,841\u003c/strong\u003e.","\u003cstrong\u003eÉtape 4 — Prise de décision (slides 25–27) :\u003c/strong\u003e Si χ²\u003csub\u003eo\u003c/sub\u003e \u003e 3,841 (\u003cem\u003ep\u003c/em\u003e \u003c 0,05) → \u003cstrong\u003eRejet de H₀\u003c/strong\u003e (différence \u003cstrong\u003estatistiquement significative\u003c/strong\u003e). Si χ²\u003csub\u003eo\u003c/sub\u003e ≤ 3,841 (\u003cem\u003ep\u003c/em\u003e ≥ 0,05) → \u003cstrong\u003eNon-rejet de H₀\u003c/strong\u003e (NE JAMAIS dire « on accepte H₀ » ! Différence non significative, due au hasard).","\u003cstrong\u003eExemple du cours (slide 27) :\u003c/strong\u003e χ²\u003csub\u003eo\u003c/sub\u003e = 3,125 (ddl = 1). Comme 2,706 \u003c 3,125 \u003c 3,841, on a 0,05 \u003c \u003cem\u003ep\u003c/em\u003e \u003c 0,10 → \u003cstrong\u003enon-rejet de H₀\u003c/strong\u003e (différence non significative)."]}],"tables":[{"title":"Ligne essentielle de la table du χ² à connaître par cœur (ddl = 1)","headers":["Risque α","0,10 (10 %)","0,05 (5 %) ★","0,01 (1 %)","0,001 (0,1 %)"],"rows":[["Valeur critique χ²α (ddl = 1)","2,706","3,841","6,635","10,827"]]}],"darija":"في جدول 2×2 (ddl = 1) عند α = 5 %، الرقم السحري هو \u003cstrong\u003e3,841\u003c/strong\u003e ! إذا خرجلك \u003cstrong\u003eχ² كبير على 3,841\u003c/strong\u003e ← \u003cstrong\u003eRejet de H₀ (Significatif)\u003c/strong\u003e. إذا خرج \u003cstrong\u003eصغير على 3,841\u003c/strong\u003e (كيما 3,125 في الكور ولا 0,40 في QCM 2025) ← \u003cstrong\u003eNon-rejet de H₀ (Non significatif)\u003c/strong\u003e — وما تقولش jamais « on accepte H₀ » ! وديما الشرط على \u003cstrong\u003eeffectifs théoriques Cij ≥ 5\u003c/strong\u003e.","triad":{"toUnderstand":["Comment encadrer la p-value grâce à la table (ex. 2,706 \u003c 3,125 \u003c 3,841 ⇒ 0,05 \u003c p \u003c 0,10)."],"toMemorize":["Cij = (Total ligne × Total colonne) / N ; condition : tous les Cij ≥ 5 (théoriques !).","χ²o = Σ (Oij − Cij)² / Cij ; ddl = (L − 1)(C − 1) ; seuil 5 % pour ddl=1 : 3,841.","Toujours dire « non-rejet de H₀ » (jamais « acceptation de H₀ »)."],"toRecognizeInQcm":["« Condition d’application : effectifs observés ≥ 5 » → PIÈGE FAUX (effectifs THÉORIQUES Cij ≥ 5 !).","χ²o = 0,40 \u003c 3,841 → Test statistiquement non significatif (Ch. 43 Q1 BD)."]}},"memorize":[{"id":"M_L12.2_1","category":"Formule","title":"Effectif théorique \u0026 Condition d’application","content":"C\u003csub\u003eij\u003c/sub\u003e = \u003cspan class=\"math-frac\"\u003e\u003cspan\u003eTotal ligne i × Total col. j\u003c/span\u003e\u003cspan\u003eN\u003c/span\u003e\u003c/span\u003e. Condition absolue : \u003cstrong\u003etous les effectifs THÉORIQUES C\u003csub\u003eij\u003c/sub\u003e ≥ 5\u003c/strong\u003e.","highlight":true},{"id":"M_L12.2_2","category":"Formule","title":"Formule du χ² observé \u0026 ddl","content":"\u003cstrong\u003eχ²\u003csub\u003eo\u003c/sub\u003e = Σ \u003cspan class=\"math-frac\"\u003e\u003cspan\u003e(O\u003csub\u003eij\u003c/sub\u003e − C\u003csub\u003eij\u003c/sub\u003e)²\u003c/span\u003e\u003cspan\u003eC\u003csub\u003eij\u003c/sub\u003e\u003c/span\u003e\u003c/span\u003e\u003c/strong\u003e ; \u003cstrong\u003eddl = (L − 1)(C − 1)\u003c/strong\u003e (= 1 pour un tableau 2×2).","highlight":true},{"id":"M_L12.2_3","category":"Seuil / Chiffre","title":"Seuil critique (ddl = 1) \u0026 Décision","content":"Pour ddl = 1, α = 5 % : \u003cstrong\u003eχ²\u003csub\u003e5%\u003c/sub\u003e = 3,841\u003c/strong\u003e (10 % : 2,706 ; 1 % : 6,635). Si χ²\u003csub\u003eo\u003c/sub\u003e \u003e 3,841 → \u003cstrong\u003eRejet de H₀ (Significatif)\u003c/strong\u003e ; si ≤ 3,841 → \u003cstrong\u003eNon-rejet de H₀ (Non significatif)\u003c/strong\u003e.","highlight":true}],"revisionVersion":1,"majorUpdateNote":"","needsReview":false,"pageRefs":[]}]$medjson$::jsonb, $medjson$[]$medjson$::jsonb, $medjson${"analyzedAt":null,"engine":"curated","totalPages":0,"lowConfidencePages":[],"warnings":[],"status":"none"}$medjson$::jsonb, NULL, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz, '2026-11-12T18:00:10.5106582Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, module_id, code, title, short_title, professor, source_files, bm_count, bm_shared_note, bm_recent_count, unique_concepts, priority, priority_score, vigilance_2026, summary, status, version, lessons, attachments, ai_extraction, ppt_import, created_at, updated_at, published_at) VALUES ('PPT_9C017779', 'M3', 'PPT1', 'Certification de la Cause Médicale de Décès', 'Certification de la Cause Mé…', 'Support PowerPoint — Faculté de Médecine', $medjson$["Certification-de-la-Cause-Medicale-de-Deces2(3).pptx (43 diapos)"]$medjson$::jsonb, 0, '', 0, 20, 'medium', 55, FALSE, 'Présentation PowerPoint importée (« Certification-de-la-Cause-Medicale-de-Deces2(3).pptx », 43 diapositives, 0 tableau(x), 0 graphique(s), 14 note(s) présentateur). En brouillon pour révision administrateur.', 'published', 1, $medjson$[{"id":"PPT_9C017779_L1","courseId":"PPT_9C017779","order":1,"chapterTitle":"Certification de la Cause Médicale de Décès","title":"Certification de la Cause Médicale de Décès","durationMin":21,"sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","sourceRef":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositives 1–7","slideRange":"Diapositives 1–7","slideRefs":[{"slideNum":1,"title":"Certification de la Cause Médicale de Décès"},{"slideNum":2,"title":"Objectifs du cours"},{"slideNum":3,"title":"Plan"},{"slideNum":4,"title":"La disponibilité des données sur la mortalité est fondamentale pour le développement d\u0027un pays.…"},{"slideNum":5,"title":"Enregistrement systématique"},{"slideNum":6,"title":"Qui"},{"slideNum":7,"title":"Établissements de santé"}],"pageRefs":[1,2,3,4,5,6,7],"bmCount":0,"bmRefs":[],"priority":"medium","priorityScore":55,"bmWarning":"","revisionVersion":1,"majorUpdateNote":"","needsReview":true,"hasManualFlags":true,"extractionNote":"Relecture manuelle recommandée : Diapositive 2 : Image/schéma (image1.png, 595x595 px) contenant peu ou pas de texte OCR (0 mots) — vérification visuelle recommandée. ; Image/schéma (image5.png, 595x595 px) contenant peu ou pas de texte OCR (0 mots) — vérification visuelle recommandée. ; Image/schéma (image3.png, 595x595 px) contenant peu ou pas de texte OCR (0 mots) — vérification visuelle recommandée. ; Image/schéma (image7.png, 595x595 px) contenant peu ou pas de texte OCR (0 mots) — vérification visuelle recommandée. | Diapositive 7 : Image/schéma (image19.png, 1052x223 px) contenant peu ou pas de texte OCR (0 mots) — vérification visuelle recommandée.","understand":{"intro":"Section extraite fidèlement de « Certification-de-la-Cause-Medicale-de-Deces2(3).pptx » (Diapositives 1–7, 7 diapositive(s)). L\u0027ordre original des diapositives, les tableaux, graphiques et notes présentateur ont été préservés.","sections":[{"heading":"Diapositive 1 — Certification de la Cause Médicale de Décès","slideNum":1,"slideTitle":"Certification de la Cause Médicale de Décès","paragraphs":["REPUBLIQUE ALGERIENNE DEMOCRATIQUE ET POPULAIRE","Ministère De L’enseignement Supérieur Et Recherche Scientifique","Ministère De La Sante","SEMEP-CHU Batna","Dr NOURANI Imane","MAHU en Epidémiologie","imane.nourani@univ-batna2.dz","2024-2025","\u003cem\u003e[Note du présentateur — Diapositive 1] :\u003c/em\u003e La certification des causes médicales de décès est un acte à la fois médicale, juridique et épidémiologique. Elle engage la responsabilité du médecin et conditionne la qualité des statistiques de mortalité, qui sont essentielles pour orienter les politiques de santé publique. C\u0027est pourquoi il est fondamental de maîtriser les règles, les principes et les textes réglementaires qui encadrent la rédaction du certificat médical de décès. » L\u0027objectif est d\u0027aligner les pratiques entre tous les professionnels de santé afin d\u0027assurer une certification fiable, homogène et conforme aux textes réglementaires. »"],"bullets":[]},{"heading":"Diapositive 2 — Objectifs du cours","slideNum":2,"slideTitle":"Objectifs du cours","paragraphs":["Améliorer les compétences","Renforcer votre maîtrise de la délivrance du CMD","Fiabiliser les informations","Garantir la qualité des données collectées","Maîtriser la codification","Utiliser correctement la CIM10","Identifier la cause initiale","Différencier la cause initiale des autres causes","\u003cem\u003e[Note du présentateur — Diapositive 2] :\u003c/em\u003e Cette formation vise à améliorer la qualité de la délivrance du Certificat Médical de Décès. Elle permet aux médecins d\u0027identifier correctement la cause initiale du décès, de la distinguer des causes immédiates, et de fiabiliser les informations recueillies. de garantir des données de mortalité de qualité et une codification conforme à la CIM-10, utiles pour la santé publique et la recherche"],"bullets":[]},{"heading":"Diapositive 3 — Plan","slideNum":3,"slideTitle":"Plan","paragraphs":["\u003cem\u003e[Note du présentateur — Diapositive 3] :\u003c/em\u003e Introduction Dans cette formation, on va s\u0027intéresser à un acte médical essentiel mais souvent sous-estimé : la certification des causes de décès. Le certificat médical de décès n\u0027est pas فقط وثيقة إدارية, c\u0027est un outil épidémiologique et médico-légal fondamental. 🔹 Perceptions de la certification des causes de décès On va d\u0027abord discuter du commentaire des professionnels perçoivent la certification : parfois vue comme une formalité, alors qu\u0027en réalité elle a un impact direct sur les statistiques de mortalité, la planification sanitaire et même les décisions de santé publique. 🔹 Contenu du certificat médical de décès (CMD) Ensuite, on va détailler ce qui contient exactement un CMD : les données administratives, les informations médicales, et surtout la partie « causes du décès », qui doit être claire, logique et conforme aux normes internationales. 🔹 Rédaction du CMD On verra comment rédiger correctement un CMD : distinguer la cause immédiate, les causes intermédiaires et la cause initiale, éviter les termes vagues, et assurer une cohérence médicale dans la chaîne causale."],"bullets":["Introduction","Perceptions de la certification des causes de décès","Contenu du certificatmédical de décès","Rédaction du CMD","Principe général de l’OMS","Particularités de codification CIM10","Notion d\u0027arrêtcardiaque"]},{"heading":"Diapositive 4 — La disponibilité des données sur la mortalité est fondamentale pour le développement d\u0027un pays.…","slideNum":4,"slideTitle":"La disponibilité des données sur la mortalité est fondamentale pour le développement d\u0027un pays.…","paragraphs":["\u003cem\u003e[Note du présentateur — Diapositive 4] :\u003c/em\u003e Les MNT 78,0%, notamment cardiovasculaires, constituent une cause majeure de mortalité dans le monde. À l\u0027horizon 2030, l\u0027OMS vise une réduction de 25 % de la mortalité prématurée liée au MNT, fondée sur la prévention, la surveillance et l\u0027amélioration de la prise en charge. Des données fiables sur la mortalité cardiovasculaire sont essentielles pour suivre ces objectifs et orienter les actions de santé publique"],"bullets":["La disponibilité des données sur la mortalité est fondamentale pour le développement d\u0027un pays. Elle permet de répondre efficacement aux épidémies actuelles et émergentes.","La collected\u0027informationspertinentesoriente la stratégie de santé publique face aux urgences sanitaires.","Introduction"]},{"heading":"Diapositive 5 — Enregistrement systématique","slideNum":5,"slideTitle":"Enregistrement systématique","paragraphs":["Les décès doivent être enregistrés au moment où ils surviennent avec toutes les informations pertinentes.","Décompte régulier","Compilation périodique des données dans des intervalles de temps définis pour suivre les tendances.","Analyse des données","L\u0027étude de la mortalité apporte des renseignements démographiques et sanitaires sur la population.","Ces données permettent d\u0027identifier les problèmes de santé prioritaires d\u0027un pays et d\u0027orienter","les politiques de santé publique.","\u003cem\u003e[Note du présentateur — Diapositive 5] :\u003c/em\u003e l\u0027importance de l\u0027enregistrement et de l\u0027analyse de la mortalité Les données sur les décès doivent être compilées régulièrement . On les rassemble à des intervalles définis (mensuels, trimestriels, annuels) pour observer les tendances de mortalité. Cela permet de suivre l\u0027évolution de certaines maladies ou causes de décès dans le temps. maladies cardiovasculaires 27,2%, comme les infarctus du myocarde ou les AVC, qui sont souvent influencés par le rythme circadien. Ces incidents sont fréquemment observés en début de journée en raison d’une combinaison de facteurs, tels que l’augmentation matinale des niveaux de cortisol et de l’activation du système nerveux sympathique L’enregistrement régulier, par exemple chaque semaine, permet de suivre les maladies saisonnières comme la grippe. On voit alors les pics d’hiver, on les compare aux années précédentes, et si le nombre de décès augmente plus que prévu, on peut réagir vite en renforçant la vaccination, les campagnes d’information et l’organisation des soins"],"bullets":["Introduction"]},{"heading":"Diapositive 6 — Qui","slideNum":6,"slideTitle":"Qui","paragraphs":["Identification précise du défunt et ses caractéristiques démographiques.","Quand","Moment exact du décès pour détecter les tendances temporelles.","Où","Localisation géographique pour identifier les zones à risque.","Pourquoi","Cause médicale précise pour orienter les interventions sanitaires.","L\u0027OMS souligne que ces informations sont essentielles pour guider les interventions sanitaires et réduire les décès prématurés, notamment liés aux maladies non transmissibles.","\u003cem\u003e[Note du présentateur — Diapositive 6] :\u003c/em\u003e Données essentielles de mortalité"],"bullets":["Introduction"]},{"heading":"Diapositive 7 — Établissements de santé","slideNum":7,"slideTitle":"Établissements de santé","paragraphs":["CHU, EPH, EPSP, EHS, Cliniques privées","ORS","Regroupement de plusieurs wilayas","Wilaya DSP","Détection des phénomènes inhabituels","Le certificat médical de décès correctement rempli permet de détecter des phénomènes inhabituels comme la pandémie de COVID, les overdoses, les suicides, ou les homicides.","INSP","\u003cem\u003e[Note du présentateur — Diapositive 7] :\u003c/em\u003e Niveaux de surveillance de la mortalité"],"bullets":["Introduction"]}],"tables":[],"darija":"","triad":{"toUnderstand":["Diapositive 1 : Certification de la Cause Médicale de Décès","Diapositive 2 : Objectifs du cours","Diapositive 3 : Plan"],"toMemorize":["Plan (7 points) (Diapositive 3)","La disponibilité des données sur la mortalité est fondamentale pour le développement d\u0027un pays.… (3 points) (Diapositive 4)"],"toRecognizeInQcm":["Terminologie exacte, valeurs chiffrées et classifications de Certification-de-la-Cause-Medicale-de-Deces2(3).pptx (Diapositives 1–7)."]}},"memorize":[{"id":"M_PPT_9C017779_L1_1","category":"Liste / Énumération","title":"Plan (7 points)","content":"Introduction • Perceptions de la certification des causes de décès • Contenu du certificatmédical de décès • Rédaction du CMD • Principe général de l’OMS • Particularités de codification CIM10","pageRef":"Diapositive 3","slideNum":3,"slideTitle":"Plan","sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","highlight":true},{"id":"M_PPT_9C017779_L1_2","category":"Liste / Énumération","title":"La disponibilité des données sur la mortalité est fondamentale pour le développement d\u0027un pays.… (3 points)","content":"La disponibilité des données sur la mortalité est fondamentale pour le développement d\u0027un pays. Elle permet de répondre efficacement aux épidémies actuelles et émergentes. • La collected\u0027informationspertinentesoriente la stratégie de santé publique face aux urgences sanitaires. • Introduction","pageRef":"Diapositive 4","slideNum":4,"slideTitle":"La disponibilité des données sur la mortalité est fondamentale pour le développement d\u0027un pays.…","sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","highlight":true}]},{"id":"PPT_9C017779_L2","courseId":"PPT_9C017779","order":2,"chapterTitle":"2. Perceptions de la certification des causes de décès","title":"2. Perceptions de la certification des causes de décès","durationMin":22,"sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","sourceRef":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositives 8–16","slideRange":"Diapositives 8–16","slideRefs":[{"slideNum":8,"title":"2. Perceptions de la certification des causes de décès"},{"slideNum":9,"title":"4.Rédaction du CMD: La cause de décès pour les statistiques"},{"slideNum":10,"title":"Une femme de 65 ans décède à l\u0027hôpital. Le dossier médical mentionne :"},{"slideNum":11,"title":"Patiente : 32 ans, G3P2 Âge gestationnel : 38 SA Antécédents :"},{"slideNum":12,"title":"Un enfant de 3 ans décède dans un centre de santé rural. Le dossier mentionne :"},{"slideNum":13,"title":"Exemple concret sur terrain"},{"slideNum":14,"title":"Exemple concret sur terrain"},{"slideNum":15,"title":"3.Contenu du certificat médical de décès"},{"slideNum":16,"title":"4.Rédaction du CMD : aspects fondamentaux"}],"pageRefs":[8,9,10,11,12,13,14,15,16],"bmCount":0,"bmRefs":[],"priority":"medium","priorityScore":55,"bmWarning":"","revisionVersion":1,"majorUpdateNote":"","needsReview":true,"hasManualFlags":true,"extractionNote":"Relecture manuelle recommandée : Diapositive 8 : Image/schéma (image20.png, 833x555 px) contenant peu ou pas de texte OCR (0 mots) — vérification visuelle recommandée. ; Image/schéma (image21.png, 833x555 px) contenant peu ou pas de texte OCR (0 mots) — vérification visuelle recommandée. | Diapositive 16 : Image/schéma (image26.png, 720x1080 px) contenant peu ou pas de texte OCR (0 mots) — vérification visuelle recommandée.","understand":{"intro":"Section extraite fidèlement de « Certification-de-la-Cause-Medicale-de-Deces2(3).pptx » (Diapositives 8–16, 9 diapositive(s)). L\u0027ordre original des diapositives, les tableaux, graphiques et notes présentateur ont été préservés.","sections":[{"heading":"Diapositive 8 — 2. Perceptions de la certification des causes de décès","slideNum":8,"slideTitle":"2. Perceptions de la certification des causes de décès","paragraphs":["Perception négative","Souvent considérée comme une bureaucratie inutile et une charge administrative supplémentaire par les professionnels de santé.","Réalité importante","Impact majeur sur la politique de santé publique mondiale et régionale grâce aux informations précieuses qu\u0027elle fournit.","\u003cem\u003e[Note du présentateur — Diapositive 8] :\u003c/em\u003e Cette diapo présente les deux perceptions opposées de la certification des causes de décès , un processus important en santé publique. Perception négative (à gauche) Vision courante parmi les professionnels de santé : 🔴 Bureaucratie inutile - Considérée comme une charge administrative sans vraie valeur 📋 Tâche supplémentaire - Perçue comme un travail administratif qui consomme du temps 😞 Sentiment négatif - L\u0027image du médecin stressé et surchargé symbolise cette vision négative Réalité importante (à droite) Impact réel souvent méconnu : ✅ Données cruciales pour la santé publique - Les certifications de décès fournissent des informations précieuses 🌍 Influence politique majeure - Ces données alimentent les politiques de santé publique à l\u0027échelle mondiale et régionale 📊 Fondement des décisions - Les graphiques et statistiques montrent comment ces informations guident les stratégies sanitaires Message clé Le contraste montre un décalage entre perception et réalité : alors que les professionnels voient cette tâche comme un fardeau administratif, elle est en réalité essentielle pour piloter les politiques de santé publique et prendre des décisions basées sur des données fiables. C\u0027est un appel à changer les mentalités et reconnaître l\u0027importance stratégique de ce processus."],"bullets":[]},{"heading":"Diapositive 9 — 4.Rédaction du CMD: La cause de décès pour les statistiques","slideNum":9,"slideTitle":"4.Rédaction du CMD: La cause de décès pour les statistiques","paragraphs":["Question fondamentale","Quelle est la cause de décès retenue pour les statistiques de causes de mortalité ?","Importance statistique","L\u0027identification correcte de cette cause est essentielle pour les analyses épidémiologiques nationales et internationales.","Comparaisons","Les données standardisées permettent des comparaisons entre différentes régions et pays.","\u003cstrong\u003e[Texte extrait par OCR depuis image/schéma — Diapositive 9] :\u003c/strong\u003e System.Collections.ArrayList","\u003cem\u003e[Note du présentateur — Diapositive 9] :\u003c/em\u003e Cette diapositive illustre comment la certification médicale des causes de décès (CMD) transforme les données brutes en informations standardisées et exploitables. Cette diapo souligne que le CMD n\u0027est pas qu\u0027une formalité administrative, mais un processus critique de standardisation qui transforme la variabilité individuelle en données homogènes et exploitables à grande échelle. C\u0027est le fondement de la santé publique basée sur les preuves."],"bullets":[]},{"heading":"Diapositive 10 — Une femme de 65 ans décède à l\u0027hôpital. Le dossier médical mentionne :","slideNum":10,"slideTitle":"Une femme de 65 ans décède à l\u0027hôpital. Le dossier médical mentionne :","paragraphs":["Diabète depuis 15 ans","Hypertension artérielle","Insuffisance rénale chronique","Infection urinaire aiguë","Septicémie","Arrêt cardiaque","Exemple concret sur terrain : Décès d\u0027une patiente de 65 ans : Scénario réel","Sans standardisation","Différents médecins certifieraient :","Médecin A → \"Cause : Diabète\" (maladie chronique)","Médecin B → \"Cause : Insuffisance rénale\" (complication chronique)","Médecin C → \"Cause : Septicémie\" (événement aigu)","Médecin D → \"Cause : Arrêt cardiaque\" (dernier événement)","Résultat : Même décès, 4 causes différentes → Données incohérentes et inutilisables","Avec la CMD standardisée (Solution)","Le médecin suit les règles de sélection de l\u0027OMS :","Chaîne causale retenue :","Cause immédiate → Arrêt cardiaque","Cause intermédiaire → Septicémie (conséquence directe)","Cause initiale (à retenir pour les stats) → Infection urinaire sur insuffisance rénale","Pour les statistiques mondiales : Infection urinaire + Insuffisance rénale","\u003cem\u003e[Note du présentateur — Diapositive 10] :\u003c/em\u003e Un patient est admis au PUMC du CHU pour une pneumonie sévère . Il est diabétique depuis 15 ans. Il décède après 5 jours d\u0027hospitalisation. 👉 Sur le Certificat Médical de Décès, on écrit : Chaîne des causes : 🟢 Cause directe de décès :➡️ Insuffisance respiratoire aiguë 🟡 Cause intermédiaire :➡️ Pneumonie bactérienne sévère 🔴 Cause initiale :➡️ Diabète sucré mal équilibré"],"bullets":[]},{"heading":"Diapositive 11 — Patiente : 32 ans, G3P2 Âge gestationnel : 38 SA Antécédents :","slideNum":11,"slideTitle":"Patiente : 32 ans, G3P2 Âge gestationnel : 38 SA Antécédents :","paragraphs":["HTA gravidique au 3ᵉ trimestre","Suivi prénatal irrégulier","prééclampsie sévère","Éclampsie","césarienne en urgence, hgie , état de choc","Décès maternel d\u0027une patiente de 32 ans : Scénario réel","Sans standardisation","Différents médecins certifieraient :","Médecin A → \"Cause état de choc","Médecin B → \"Cause : Hémorragie du post-partum sévère","Médecin D → \"Cause : Arrêt cardiaque\" (dernier événement)","Résultat : Même décès, 4 causes différentes → Données incohérentes et inutilisables","Avec la CMD standardisée (Solution)","Le médecin suit les règles de sélection de l\u0027OMS :","Chaîne causale retenue :","Cause immédiate → État de choc hémorragique","Cause intermédiaire → choc hémorragique","Cause initiale (à retenir pour les stats) → Prééclampsie sévère compliquée d\u0027éclampsie","Pour les statistiques mondiales : Prééclampsie sévère compliquée d\u0027éclampsie","\u003cem\u003e[Note du présentateur — Diapositive 11] :\u003c/em\u003e Un patient est admis au PUMC du CHU pour une pneumonie sévère . Il est diabétique depuis 15 ans. Il décède après 5 jours d\u0027hospitalisation. 👉 Sur le Certificat Médical de Décès, on écrit : Chaîne des causes : 🟢 Cause directe de décès :➡️ Insuffisance respiratoire aiguë 🟡 Cause intermédiaire :➡️ Pneumonie bactérienne sévère 🔴 Cause initiale :➡️ Diabète sucré mal équilibré"],"bullets":[]},{"heading":"Diapositive 12 — Un enfant de 3 ans décède dans un centre de santé rural. Le dossier mentionne :","slideNum":12,"slideTitle":"Un enfant de 3 ans décède dans un centre de santé rural. Le dossier mentionne :","paragraphs":["Diarrhée aiguë depuis 5 jours","Déshydratation sévère","Malnutrition chronique","Anémie","Convulsions","Choc hypovolémique","Arrêt cardiaque","Exemple concret sur terrain : Décès d\u0027un enfant de 3 ans Scénario réel en Algérie","Sans standardisation","Différents praticiens diraient :","Pédiatre urbain → \"Diarrhée infectieuse\"","Médecin rural → \"Déshydratation\"","Médecin Nutritionniste → \"Malnutrition\"","Autre médecin → \"Arrêt cardiaque\"","Statistiques nationales confuses","On ne sait pas si le problème est sanitaire (eau) ou nutritionnel","Cause initiale (retenue pour stats) : Diarrhée infectieuse","↓","Cause intermédiaire : Déshydratation sévère","↓","Cause immédiate : Choc hypovolémique","↓","Arrêt cardiaque (dernière étape)"],"bullets":[]},{"heading":"Diapositive 13 — Exemple concret sur terrain","slideNum":13,"slideTitle":"Exemple concret sur terrain","paragraphs":["Un patient est admis au PUMC du CHU pour une pneumonie sévère . Il est diabétique depuis 15 ans.","Il décède après 5 jours d\u0027hospitalisation.","👉 Sur le Certificat Médical de Décès, on écrit :","Chaîne des causes :","🟢 Cause directe de décès :Insuffisance respiratoire aiguë","🟡 Cause intermédiaire :Pneumonie bactérienne sévère","🔴 Cause initiale :Diabète sucré mal équilibré","🎯 Intérêt pour chaque niveau","✅ Pour le Directeur du CHU (gestion \u0026 prise en charge)","La cause directe + intermédiaire montrer :","➡️ Utile pour : ✔️ organisation des services ✔️ besoins en oxygène, lits, antibiotiques, réanimation ✔️ formation du personnel"],"bullets":["Le motif réel d\u0027hospitalisation","Le type de pathologie pris en charge au PUMC","La lourdeur des cas traités (pneumonies graves, détresses respiratoires…)"]},{"heading":"Diapositive 14 — Exemple concret sur terrain","slideNum":14,"slideTitle":"Exemple concret sur terrain","paragraphs":["Un patient est admis au urgences cardiologiques (UC) pour un infarctus du myocarde. Il présente des antécédents d\u0027hypertension artérielle (HTA) chronique non traitée. Il décède d\u0027un choc cardiogénique 48 heures après son admission","👉 Sur le Certificat Médical de Décès, on écrit :","Chaîne des causes :","🟡 Cause intermédiaire : Infarctus du myocarde","🔴 Cause initiale :Hypertension artérielle (HTA) chronique","🎯 Intérêt pour chaque niveau","✅ Pour le Directeur du CHU et le chef service (gestion \u0026 prise en charge)","La cause directe + intermédiaire montrer :","➡️ Utile pour : ✔️ plateaux techniques (coronarographie, salles de cathétérisme), en équipements de suppléance (assistance circulatoire, ECMO) et en médicaments de haute technicité (vasopresseurs, thrombolytiques).","organisation des services ✔️ besoins en personnel spécialisé et de cibler les programmes de formation continue pour l\u0027équipe paramédicale et médicale"],"bullets":["🟢 Cause directe de décès :Choc cardiogénique","Le motif réel d\u0027hospitalisation","Le type de pathologie pris en charge au UC","La lourdeur des cas traités (IDM, Choc cardiogénique…)"]},{"heading":"Diapositive 15 — 3.Contenu du certificat médical de décès","slideNum":15,"slideTitle":"3.Contenu du certificat médical de décès","paragraphs":["Cause principale et immédiate","Indiquée habituellement sur le certificat","Facteurs déclencheurs","Éléments ayant conduit à la pathologie identifiée","Antécédents médicaux","Base d\u0027action pour les politiques de santé","Les véritables causes de décès comprennent les facteurs qui ont conduit à la pathologie identifiée, notamment les antécédents médicaux, qui sont essentiels pour orienter les politiques de santé."],"bullets":[]},{"heading":"Diapositive 16 — 4.Rédaction du CMD : aspects fondamentaux","slideNum":16,"slideTitle":"4.Rédaction du CMD : aspects fondamentaux","paragraphs":["Établissement par un médecin","Le certificat de décès établi par le médecin délivre l\u0027autorisation à l\u0027inhumation.","Modèle standardisé","Le document doit être conforme au modèle type défini par l\u0027OMS.","Harmonisation internationale","Cette standardisation permet l\u0027harmonisation de l\u0027information et les comparaisons internationales."],"bullets":[]}],"tables":[],"darija":"","triad":{"toUnderstand":["Diapositive 8 : 2. Perceptions de la certification des causes de décès","Diapositive 9 : 4.Rédaction du CMD: La cause de décès pour les statistiques","Diapositive 10 : Une femme de 65 ans décède à l\u0027hôpital. Le dossier médical mentionne :"],"toMemorize":["Une femme de 65 ans décède à l\u0027hôpital. Le dossier médical mentionne : (Diapo 10) (Diapositive 10)","Exemple concret sur terrain (Diapositive 10)","Décès maternel d\u0027une patiente de 32 ans (Diapositive 11)"],"toRecognizeInQcm":["Terminologie exacte, valeurs chiffrées et classifications de Certification-de-la-Cause-Medicale-de-Deces2(3).pptx (Diapositives 8–16)."]}},"memorize":[{"id":"M_PPT_9C017779_L2_1","category":"Formule / Valeur clé","title":"Une femme de 65 ans décède à l\u0027hôpital. Le dossier médical mentionne : (Diapo 10)","content":"Diabète depuis 15 ans","pageRef":"Diapositive 10","slideNum":10,"slideTitle":"Une femme de 65 ans décède à l\u0027hôpital. Le dossier médical mentionne :","sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","highlight":true},{"id":"M_PPT_9C017779_L2_2","category":"Formule / Valeur clé","title":"Exemple concret sur terrain","content":"Décès d\u0027une patiente de 65 ans : Scénario réel","pageRef":"Diapositive 10","slideNum":10,"slideTitle":"Une femme de 65 ans décède à l\u0027hôpital. Le dossier médical mentionne :","sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","highlight":true},{"id":"M_PPT_9C017779_L2_3","category":"Formule / Valeur clé","title":"Décès maternel d\u0027une patiente de 32 ans","content":"Scénario réel","pageRef":"Diapositive 11","slideNum":11,"slideTitle":"Patiente : 32 ans, G3P2 Âge gestationnel : 38 SA Antécédents :","sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","highlight":true},{"id":"M_PPT_9C017779_L2_4","category":"Formule / Valeur clé","title":"Un enfant de 3 ans décède dans un centre de santé rural. Le dossier mentionne : (Diapo 12)","content":"Diarrhée aiguë depuis 5 jours","pageRef":"Diapositive 12","slideNum":12,"slideTitle":"Un enfant de 3 ans décède dans un centre de santé rural. Le dossier mentionne :","sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","highlight":true},{"id":"M_PPT_9C017779_L2_5","category":"Formule / Valeur clé","title":"Exemple concret sur terrain","content":"Décès d\u0027un enfant de 3 ans Scénario réel en Algérie","pageRef":"Diapositive 12","slideNum":12,"slideTitle":"Un enfant de 3 ans décède dans un centre de santé rural. Le dossier mentionne :","sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","highlight":true},{"id":"M_PPT_9C017779_L2_6","category":"Classification / Distinction","title":"Un enfant de 3 ans décède dans un centre de santé rural. Le dossier mentionne : (Diapo 12)","content":"Arrêt cardiaque (dernière étape)","pageRef":"Diapositive 12","slideNum":12,"slideTitle":"Un enfant de 3 ans décède dans un centre de santé rural. Le dossier mentionne :","sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","highlight":false},{"id":"M_PPT_9C017779_L2_7","category":"Formule / Valeur clé","title":"Exemple concret sur terrain (Diapo 13)","content":"Un patient est admis au PUMC du CHU pour une pneumonie sévère . Il est diabétique depuis 15 ans.","pageRef":"Diapositive 13","slideNum":13,"slideTitle":"Exemple concret sur terrain","sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","highlight":true}]},{"id":"PPT_9C017779_L3","courseId":"PPT_9C017779","order":3,"chapterTitle":"Médecin autorisé","title":"Médecin autorisé","durationMin":21,"sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","sourceRef":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositives 17–23","slideRange":"Diapositives 17–23","slideRefs":[{"slideNum":17,"title":"Médecin autorisé"},{"slideNum":18,"title":"4.Rédaction du CMD :Structure du certificat médical de décès"},{"slideNum":19,"title":"4.Rédaction du CMD:"},{"slideNum":20,"title":"4.Rédaction du CMD:"},{"slideNum":21,"title":"4. Redaction du CMD: Conseils pratiques pour la redaction"},{"slideNum":22,"title":"Chaîne logique des causes de décès"},{"slideNum":23,"title":"Importance de la validation de la cause initiale"}],"pageRefs":[17,18,19,20,21,22,23],"bmCount":0,"bmRefs":[],"priority":"medium","priorityScore":55,"bmWarning":"","revisionVersion":1,"majorUpdateNote":"","needsReview":true,"hasManualFlags":true,"extractionNote":"Relecture manuelle recommandée : Diapositive 17 : Image/schéma (image27.png, 720x1080 px) contenant peu ou pas de texte OCR (0 mots) — vérification visuelle recommandée. | Diapositive 21 : Image/schéma (image38.png, 1200x1200 px) contenant peu ou pas de texte OCR (0 mots) — vérification visuelle recommandée.","understand":{"intro":"Section extraite fidèlement de « Certification-de-la-Cause-Medicale-de-Deces2(3).pptx » (Diapositives 17–23, 7 diapositive(s)). L\u0027ordre original des diapositives, les tableaux, graphiques et notes présentateur ont été préservés.","sections":[{"heading":"Diapositive 17 — Médecin autorisé","slideNum":17,"slideTitle":"Médecin autorisé","paragraphs":["Établi par tout médecin autorisé à exercer, quel que soit le secteur d\u0027activité.","Format réglementé","Rédigé sur un modèle standard fixé par le décret N°22-178 du 28/04/2022.","Rédaction précise","Le médecin doit rédiger lisiblement et mentionner toutes les données pertinentes.","Confidentialité assurée","Obligation d\u0027assurer la confidentialité des causes","médicales de décès.","4.Rédaction du CMD : aspects Pratiques"],"bullets":[]},{"heading":"Diapositive 18 — 4.Rédaction du CMD :Structure du certificat médical de décès","slideNum":18,"slideTitle":"4.Rédaction du CMD :Structure du certificat médical de décès","paragraphs":["Partie I","Description de la chaîne d\u0027événements ayant conduit au décès :","Partie II","Maladies, affections ou traumatismes importants ayant contribué au décès mais sans lien direct avec la cause initiale.","Ce sont les comorbidités qui ont pu avoir un impact sur la survenue du décès.","Partie III","Obstacle médicolégal éventuel à signaler.","Le certificat comprend une structure hiérarchique allant de la cause directe (a) aux causes intermédiaires (b et c) jusqu\u0027à la cause initiale (d), avec une section séparée pour les autres états morbides importants."],"bullets":["Cause directe (finale) en ligne supérieure","Cause initiale sur la dernière ligne"]},{"heading":"Diapositive 19 — 4.Rédaction du CMD:","slideNum":19,"slideTitle":"4.Rédaction du CMD:","paragraphs":["La cause initiale","Définition officielle","C\u0027est la maladie ou le traumatisme qui a déclenché l\u0027évolution morbide conduisant directement au décès, ou les circonstances de l\u0027accident ou de la violence.","Exclusions importantes","La définition n\u0027inclut pas les symptômes, ni les modes de décès, tels qu\u0027une défaillance cardiaque ou respiratoire.","Localisation dans le CMD","La cause initiale est généralement indiquée en dernier lieu dans la partie I du certificat (ligne d).","\u003cstrong\u003e[Texte extrait par OCR depuis image/schéma — Diapositive 19] :\u003c/strong\u003e System.Collections.ArrayList"],"bullets":[]},{"heading":"Diapositive 20 — 4.Rédaction du CMD:","slideNum":20,"slideTitle":"4.Rédaction du CMD:","paragraphs":["Priorité des causes de décès","Maladie primaire","Priorité sur les complications","Maladie grave","Priorité sur la maladie légère","Cause probable","La plus susceptible d\u0027avoir entraîné la mort","Pour déterminer la cause initiale de décès, choisissez la maladie ou l\u0027affection la plus susceptible d\u0027avoir entraîné la mort, en donnant priorité à la maladie primaire plutôt qu\u0027à ses complications.","\u003cstrong\u003e[Texte extrait par OCR depuis image/schéma — Diapositive 20] :\u003c/strong\u003e System.Collections.ArrayList","\u003cem\u003e[Note du présentateur — Diapositive 20] :\u003c/em\u003e Cette diapo explique comment choisir la cause initiale de décès quand on remplit le certificat. 1. Maladie primaire C’est la maladie de base, celle qui a commencé l’histoire. On lui donne la priorité par rapport à ses complications.Exemple : diabète avec gangrène → la maladie primaire est le diabète, pas seulement la gangrène. 2. Maladie grave vs maladie légère Si plusieurs maladies sont présentes, on privilégie la maladie la plus grave, celle qui a le plus de chances d’avoir entraîné la mort.Exemple : grippe + insuffisance cardiaque sévère → on retient plutôt l’insuffisance cardiaque. Cause probable Quand on n’est pas sûr à 100%, on choisit la cause la plus probable d’avoir provoqué le décès. On évite de mettre une petite pathologie qui explique mal la mort. 4. Phrase simple à retenir Pour la cause initiale de décès, on choisit : « La maladie de départ, la plus grave et la plus probable d’avoir conduit à la mort, avant ses complications. »"],"bullets":[]},{"heading":"Diapositive 21 — 4. Redaction du CMD: Conseils pratiques pour la redaction","slideNum":21,"slideTitle":"4. Redaction du CMD: Conseils pratiques pour la redaction","paragraphs":["LISIBILITÉ","COMPLÉTUDE","CHRONOLOGIE","COHÉRENCE","\u003cstrong\u003e[Texte extrait par OCR depuis image/schéma — Diapositive 21] :\u003c/strong\u003e System.Collections.ArrayList"],"bullets":["Écriturelisible","En majuscule, sans abréviation","Plusieurs événements","Toutes les lignes de la chaîne causale doivent être remplies","Un seul événement par ligne","Ordre chronologique précis","La maladie de la deuxième partie ne peut pas être mentionnée dans la première"]},{"heading":"Diapositive 22 — Chaîne logique des causes de décès","slideNum":22,"slideTitle":"Chaîne logique des causes de décès","paragraphs":["Cause directe (a)","Complication finale ayant directement entraîné le décès","Cause intermédiaire (b)","Conséquence de la cause suivante","Cause intermédiaire (c)","Conséquence de la cause initiale","Cause initiale (d)","Maladie ou traumatisme ayant déclenché la chaîne","d\u0027événements","Dans un CMD correctement rempli, toutes les causes constituent une chaîne logique chronologiquement ordonnée d\u0027événements interdépendants. Les pathologies décrites dans la ligne supérieure résultent des causes décrites plus bas.","4.Rédaction du CMD:","\u003cstrong\u003e[Texte extrait par OCR depuis image/schéma — Diapositive 22] :\u003c/strong\u003e System.Collections.ArrayList"],"bullets":[]},{"heading":"Diapositive 23 — Importance de la validation de la cause initiale","slideNum":23,"slideTitle":"Importance de la validation de la cause initiale","paragraphs":["pour valider la cause initiale du décès.","le code conforme à la CIM10.","CIM10 assure la comparabilitéinternationale des données",".","4.Rédaction du CMD","\u003cstrong\u003e[Texte extrait par OCR depuis image/schéma — Diapositive 23] :\u003c/strong\u003e System.Collections.ArrayList","\u003cem\u003e[Note du présentateur — Diapositive 23] :\u003c/em\u003e es informations sur les maladies et les décès sont standardisées, ce qui permet aux pays de parler le même langage en santé publique et de comparer leurs données facilement . Un décès à cause d\u0027un infarctus du myocarde a le code I21 . Si tous les hôpitaux du monde utilisent ce code pour ce type de décès, on peut comparer les taux de mortalité par infarctus entre pays ."],"bullets":["Toutes les informations du certificat sont importantes","Codification precise: La validation permetd\u0027attribuer","Référenceinternationale: La codification selon la"]}],"tables":[],"darija":"","triad":{"toUnderstand":["Diapositive 17 : Médecin autorisé","Diapositive 18 : 4.Rédaction du CMD :Structure du certificat médical de décès","Diapositive 19 : 4.Rédaction du CMD:"],"toMemorize":["Médecin autorisé (Diapo 17) (Diapositive 17)","4.Rédaction du CMD: (Diapo 19) (Diapositive 19)","4.Rédaction du CMD: (Diapo 19) (Diapositive 19)"],"toRecognizeInQcm":["Terminologie exacte, valeurs chiffrées et classifications de Certification-de-la-Cause-Medicale-de-Deces2(3).pptx (Diapositives 17–23)."]}},"memorize":[{"id":"M_PPT_9C017779_L3_1","category":"Définition / Règle","title":"Médecin autorisé (Diapo 17)","content":"Rédigé sur un modèle standard fixé par le décret N°22-178 du 28/04/2022.","pageRef":"Diapositive 17","slideNum":17,"slideTitle":"Médecin autorisé","sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","highlight":true},{"id":"M_PPT_9C017779_L3_2","category":"Définition / Règle","title":"4.Rédaction du CMD: (Diapo 19)","content":"Définition officielle","pageRef":"Diapositive 19","slideNum":19,"slideTitle":"4.Rédaction du CMD:","sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","highlight":true},{"id":"M_PPT_9C017779_L3_3","category":"Définition / Règle","title":"4.Rédaction du CMD: (Diapo 19)","content":"La définition n\u0027inclut pas les symptômes, ni les modes de décès, tels qu\u0027une défaillance cardiaque ou respiratoire.","pageRef":"Diapositive 19","slideNum":19,"slideTitle":"4.Rédaction du CMD:","sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","highlight":true},{"id":"M_PPT_9C017779_L3_4","category":"Liste / Énumération","title":"4. Redaction du CMD: Conseils pratiques pour la redaction (7 points)","content":"Écriturelisible • En majuscule, sans abréviation • Plusieurs événements • Toutes les lignes de la chaîne causale doivent être remplies • Un seul événement par ligne • Ordre chronologique précis","pageRef":"Diapositive 21","slideNum":21,"slideTitle":"4. Redaction du CMD: Conseils pratiques pour la redaction","sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","highlight":false},{"id":"M_PPT_9C017779_L3_5","category":"Liste / Énumération","title":"Importance de la validation de la cause initiale (3 points)","content":"Toutes les informations du certificat sont importantes • Codification precise: La validation permetd\u0027attribuer • Référenceinternationale: La codification selon la","pageRef":"Diapositive 23","slideNum":23,"slideTitle":"Importance de la validation de la cause initiale","sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","highlight":false}]},{"id":"PPT_9C017779_L4","courseId":"PPT_9C017779","order":4,"chapterTitle":"5. Principe général de l\u0027OMS","title":"5. Principe général de l\u0027OMS","durationMin":21,"sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","sourceRef":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositives 24–30","slideRange":"Diapositives 24–30","slideRefs":[{"slideNum":24,"title":"5. Principe général de l\u0027OMS"},{"slideNum":25,"title":"5.1 Concept d\u0027enchaînement"},{"slideNum":26,"title":"5.2 Catégories exclues pour la cause initiale"},{"slideNum":27,"title":"5.3 Particularité des tumeurs"},{"slideNum":28,"title":"Tumeurs malignes de sièges multiples"},{"slideNum":29,"title":"Tumeurs métastatiques"},{"slideNum":30,"title":"Particularité des tumeurspulmonaires C34"}],"pageRefs":[24,25,26,27,28,29,30],"bmCount":0,"bmRefs":[],"priority":"medium","priorityScore":55,"bmWarning":"","revisionVersion":1,"majorUpdateNote":"","needsReview":true,"hasManualFlags":true,"extractionNote":"Relecture manuelle recommandée : Diapositive 24 : Image/schéma (image47.png, 720x1080 px) contenant peu ou pas de texte OCR (0 mots) — vérification visuelle recommandée. | Diapositive 26 : Image/schéma (image52.png, 406x406 px) contenant peu ou pas de texte OCR (1 mots) — vérification visuelle recommandée. ; Image/schéma (image55.png, 406x406 px) contenant peu ou pas de texte OCR (3 mots) — vérification visuelle recommandée. ; Image/schéma (image54.png, 406x406 px) contenant peu ou pas de texte OCR (2 mots) — vérification visuelle recommandée. ; Image/schéma (image53.png, 406x406 px) contenant peu ou pas de texte OCR (3 mots) — vérification visuelle recommandée. | Diapositive 29 : Image/schéma (image75.png, 597x597 px) contenant peu ou pas de texte OCR (0 mots) — vérification visuelle recommandée. ; Image/schéma (image65.png, 597x597 px) contenant peu ou pas de texte OCR (0 mots) — vérification visuelle recommandée. ; Image/schéma (image69.png, 597x597 px) contenant peu ou pas de texte OCR (0 mots) — vérification visuelle recommandée. ; Image/schéma (image73.png, 597x597 px) contenant peu ou pas de texte OCR (0 mots) — vérification visuelle recommandée. ; Image/schéma (image67.png, 597x597 px) contenant peu ou pas de texte OCR (0 mots) — vérification visuelle recommandée. ; Image/schéma (image77.png, 597x597 px) contenant peu ou pas de texte OCR (0 mots) — vérification visuelle recommandée. ; Image/schéma (image71.png, 597x597 px) contenant peu ou pas de texte OCR (0 mots) — vérification visuelle recommandée.","understand":{"intro":"Section extraite fidèlement de « Certification-de-la-Cause-Medicale-de-Deces2(3).pptx » (Diapositives 24–30, 7 diapositive(s)). L\u0027ordre original des diapositives, les tableaux, graphiques et notes présentateur ont été préservés.","sections":[{"heading":"Diapositive 24 — 5. Principe général de l\u0027OMS","slideNum":24,"slideTitle":"5. Principe général de l\u0027OMS","paragraphs":["Enchainement logique","Les affections doivent former une chaîne causale cohérente pour être valides.","Position déterminante","L\u0027affection mentionnée seule à la dernière ligne de la partie I est prioritaire.","Condition de validité","Elle doit pouvoir donner naissance à toutes les affections mentionnées aux lignes précédentes."],"bullets":[]},{"heading":"Diapositive 25 — 5.1 Concept d\u0027enchaînement","slideNum":25,"slideTitle":"5.1 Concept d\u0027enchaînement","paragraphs":["Définition","L\u0027enchaînement se rapporte à deux affections ou plus, mentionnées sur des lignes successives de la partie I.","Relation causale","Chaque affection doit être une cause plausible de celle mentionnée à la ligne précédente.","Exemple","a) Embolie pulmonaire (cause directe)","b) Fracture pathologique (cause intermédiaire)","c) Cancer secondaire du fémur (cause intermédiaire)","d) Cancer du sein (cause initiale)","\u003cstrong\u003e[Texte extrait par OCR depuis image/schéma — Diapositive 25] :\u003c/strong\u003e System.Collections.ArrayList"],"bullets":[]},{"heading":"Diapositive 26 — 5.2 Catégories exclues pour la cause initiale","slideNum":26,"slideTitle":"5.2 Catégories exclues pour la cause initiale","paragraphs":["Certaines catégories ne doivent pas être utilisées pour coder la cause initiale de décès : B95-B97 (agents d\u0027infections), G97/H95/N99 (affections post-actes médicaux), O80-O84 (accouchement), S00-T98 (lésions traumatiques et conséquences de causes externes).","\u003cem\u003e[Note du présentateur — Diapositive 26] :\u003c/em\u003e Cause initiale = ce qui a abordé la mort On ne met pas : bactéries, complications post-op, simples accouchements, blessures seules Sinon, les statistiques sur les causes de décès seraient incorrectes ou trompeuses ."],"bullets":[]},{"heading":"Diapositive 27 — 5.3 Particularité des tumeurs","slideNum":27,"slideTitle":"5.3 Particularité des tumeurs","paragraphs":["Règle importante","Si unetumeurmaligne est la cause initiale de décès, il est essentiel de préciser le site primitif pour garantir un codage CIM10 correct.","Exemple de codage :","I.","a) Coma b) c) Métastases cérébrales d) Kc du foie","II. RAS","Catégories de codage","Site primitif","Localisation initiale de la tumeur","Type histologique","Nature cellulaire de la tumeur","Stade / Extension","Niveau de propagation","Autres facteurs","Informations complémentaires"],"bullets":[]},{"heading":"Diapositive 28 — Tumeurs malignes de sièges multiples","slideNum":28,"slideTitle":"Tumeurs malignes de sièges multiples","paragraphs":["DÉFINITION","Existence de deux tumeurs primitives dans des sites anatomiquesdifférents","Ou de types morphologiques différents","CLASSIFICATION","Tumeurs malignes primitives multiples indépendantes","C97","CRITÈRES","Les lésions n\u0027appartiennent pas au même système","Aucune indication de relation primitive/secondaire"],"bullets":[]},{"heading":"Diapositive 29 — Tumeurs métastatiques","slideNum":29,"slideTitle":"Tumeurs métastatiques","paragraphs":["Cerveau","Cœur","Diaphragme","Foie","Ganglions lymphatiques","Poumon","Os","Pour les métastases, certaines localisations sont plus fréquentes que d\u0027autres et doivent être traitées différemment. Si l\u0027une de ces localisations existe seule sur le certificat et n\u0027est pas qualifiée de métastatique, il faut la considérer comme primitive."],"bullets":[]},{"heading":"Diapositive 30 — Particularité des tumeurspulmonaires C34","slideNum":30,"slideTitle":"Particularité des tumeurspulmonaires C34","paragraphs":["LOCALISATION","PROBLÉMATIQUE","Le poumon est un site fréquent de métastases","Mais aussi un site de tumeurs primitives","Ambiguïté fréquente","RÈGLE","D\u0027INTERPRÉTATION","Lésion pulmonaire associée à une autre lésion","Considéréecomme metastases","Sauf indication contraire","CAS","DES BRONCHES","Cancer bronchique mentionné","Tumeur primitive","Localisation précise requise"],"bullets":[]}],"tables":[],"darija":"","triad":{"toUnderstand":["Diapositive 24 : 5. Principe général de l\u0027OMS","Diapositive 25 : 5.1 Concept d\u0027enchaînement","Diapositive 26 : 5.2 Catégories exclues pour la cause initiale"],"toMemorize":["5.2 Catégories exclues pour la cause initiale (Diapo 26) (Diapositive 26)","Cause initiale = ce qui a abordé la mort On ne met pas (Diapositive 26)","5.3 Particularité des tumeurs (Diapo 27) (Diapositive 27)"],"toRecognizeInQcm":["Terminologie exacte, valeurs chiffrées et classifications de Certification-de-la-Cause-Medicale-de-Deces2(3).pptx (Diapositives 24–30)."]}},"memorize":[{"id":"M_PPT_9C017779_L4_1","category":"Classification / Distinction","title":"5.2 Catégories exclues pour la cause initiale (Diapo 26)","content":"Certaines catégories ne doivent pas être utilisées pour coder la cause initiale de décès : B95-B97 (agents d\u0027infections), G97/H95/N99 (affections post-actes médicaux), O80-O84 (accouchement), S00-T98 (lésions traumatiques et conséquences de causes externes).","pageRef":"Diapositive 26","slideNum":26,"slideTitle":"5.2 Catégories exclues pour la cause initiale","sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","highlight":false},{"id":"M_PPT_9C017779_L4_2","category":"Formule / Valeur clé","title":"Cause initiale = ce qui a abordé la mort On ne met pas","content":"bactéries, complications post-op, simples accouchements, blessures seules Sinon, les statistiques sur les causes de décès seraient incorrectes ou trompeuses .","pageRef":"Diapositive 26","slideNum":26,"slideTitle":"5.2 Catégories exclues pour la cause initiale","sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx","highlight":true},{"id":"M_PPT_9C017779_L4_3","category":"Classification / Distinction","title":"5.3 Particularité des tumeurs (Diapo 27)","content":"Catégories de codage","pageRef":"Diapositive 27","slideNum":27,"slideTitle":"5.3 Particularité des tumeurs","sourceFile":"Certification-de-la-Cause-Medicale-de-Deces2(3).pptx