INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_1', 'C1', 'L1.1', 'definition', 'Définissez l’approche prospective de la santé selon le Pr Boumaraf.', 'Approche dynamique considérant la santé comme un processus (capacité d’adaptation et d’interaction à l’environnement) tenant compte des moyens de contrôle des facteurs endogènes et exogènes.', 'Attention à l’erreur BM Ch. 2 Q1 : ce n’est PAS la définition OMS physique/mental/social !', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_2', 'C1', 'L1.1', 'difference', 'Quelle différence distingue l’approche conventionnelle de l’approche globaliste de la santé ?', 'Conventionnelle = absence de maladie, définie EN DEHORS de tout critère socio-économique et culturel. Globaliste = fait biologique ET social (OMS 1946 : bien-être physique, mental et social).', 'Piège BM Ch. 14 Q2.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_3', 'C1', 'L1.1', 'list', 'Citez 3 déterminants extrinsèques de la santé et 1 déterminant intrinsèque.', 'Extrinsèques : infrastructures sanitaires, environnement microbiologique, culture et comportements. Intrinsèque : patrimoine génétique / biologie.', 'Testé en BM Ch. 19 Q11.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_4', 'C1', 'L1.2', 'difference', 'Quel indicateur épidémiologique réduit la prévention primaire vs la prévention secondaire ?', 'Prévention primaire → diminue l’INCIDENCE (nouveaux cas). Prévention secondaire → diminue la PRÉVALENCE (nouveaux + anciens cas) et la durée d’évolution grâce au dépistage précoce.', 'Sujet n°1 ex-aequo (10 QCM BM).', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_5', 'C1', 'L1.2', 'short_answer', 'À quel niveau de prévention correspond l’ioduration du sel contre le goitre et le crétinisme ?', 'Prévention PRIMAIRE (mesure collective empêchant la survenue de nouveaux cas).', 'Piège classique BM Ch. 2 Q2 B.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_6', 'C1', 'L1.2', 'definition', 'Définissez la prévention quaternaire et la prophylaxie.', 'Prévention quaternaire : protéger patient et soignant contre la surmédicalisation, les actes invasifs inutiles et les IAS. Prophylaxie : prévention dirigée spécifiquement contre une maladie transmissible.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_7', 'C1', 'L1.3', 'cloze', 'Complétez : En Algérie, l’instauration de la gratuité des soins a eu lieu en ______ durant la phase de transition.', 'Janvier 1974 (accompagnée de la réforme des études médicales et de la création du secteur sanitaire).', 'Tombé 2× dans la BM (Ch. 29 Q14 & Ch. 41 Q6).', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_8', 'C1', 'L1.3', 'list', 'Énumérez les 4 critères qui font d’un problème une priorité de santé publique.', '1) Gravité (létalité, séquelles, incapacités), 2) Fréquence / ampleur (prévalence élevée), 3) Impact socio-économique, 4) Perception sociale (+ maladie curable ou évitable).', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_9', 'C1', 'L1.3', 'short_answer', 'Quel médecin a établi en 1854–1855 le lien entre le choléra et la pompe à eau de Broad Street à Londres ?', 'John Snow (réfutant la théorie des miasmes).', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_10', 'C2', 'L2.1', 'difference', 'Distinguez pouvoir pathogène, virulence et contagiosité d’un agent infectieux.', 'Pouvoir pathogène = capacité à provoquer des manifestations morbides. Virulence = intensité du pouvoir pathogène / aptitude à reproduire la maladie. Contagiosité = capacité à se propager dans une collectivité (R₀).', '3 QCM dans la BM (Ch. 12 Q5, Q10 & Ch. 19 Q10).', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_11', 'C2', 'L2.1', 'short_answer', 'Quels résultats l’Algérie a-t-elle obtenus sur la poliomyélite, le paludisme autochtone et la tuberculose pulmonaire ?', 'Poliomyélite : ÉRADICATION. Paludisme autochtone : ÉRADICATION / disparition. Tuberculose pulmonaire : DIMINUTION de l’incidence (NON éliminée !).', 'Tombé en 2024 (Ch. 12 Q3) et 2025 (Ch. 13 Q1).', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_12', 'C2', 'L2.1', 'cloze', 'Complétez : Toutes les maladies contagieuses sont transmissibles, mais ______ (donnez 2 exemples).', 'l’inverse est FAUX ! Exemples de maladies transmissibles NON contagieuses : tétanos, paludisme, TIAC, toxoplasmose.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_13', 'C2', 'L2.1', 'formula', 'Que représente R₀ et comment comparer le R₀ de la rougeole à celui du SARS-CoV-2 ?', 'R₀ = nombre moyen de sujets infectés par un cas contagieux dans une population entièrement susceptible. R₀(rougeole) est nettement SUPÉRIEUR à R₀(SARS-CoV-2).', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_14', 'C2', 'L2.2', 'list', 'Citez les 4 étapes de la surveillance épidémiologique et sa finalité ultime.', 'Processus CONTINU en 4 étapes : 1) Collecte → 2) Compilation/tabulation → 3) Analyse/interprétation → 4) Diffusion. Finalité : produire de l’information pour l’ACTION (contrôle).', 'Conditionnée par la rapidité de traitement et de diffusion.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_15', 'C2', 'L2.2', 'difference', 'Comparez surveillance passive, active et sentinelle avec un exemple algérien pour chacune.', 'Passive : attend la remontée des données (MDO, TIAC). Active : recherche périodique des cas (PFA). Sentinelle : échantillon volontaire de médecins/labos (GROG grippe dans 6 wilayas).', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_16', 'C2', 'L2.2', 'formula', 'Donnez les formules de la Sensibilité et de la Spécificité d’un système de surveillance.', 'Sensibilité = VP / (VP + FN) [identifie la maladie / vrais positifs]. Spécificité = VN / (VN + FP) [identifie l’absence de maladie / vrais négatifs].', 'BM Ch. 38 Q4 & Q10.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_17', 'C2', 'L2.2', 'definition', 'Que signifient Représentativité, Souplesse, Simplicité et Acceptabilité en surveillance ?', 'Représentativité = maladie bien décrite temps/lieu/personne. Souplesse = adaptation changements définition de cas / nouvelles sources. Simplicité = structure légère, recueil rapide. Acceptabilité = taux de participation + qualité des rapports.', '7 QCM dans BM Ch. 38 !', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_18', 'C2', 'L2.3', 'formula', 'Combien de maladies compte chaque catégorie du Décret MDO n° 22-250 du 30 juin 2022 ?', 'Catégorie 1 (surveillance nationale) : 44 maladies. Catégorie 2 (surveillance internationale, notifiables OMS) : 14 maladies. Déclarants : médecins et biologistes.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_19', 'C2', 'L2.3', 'short_answer', 'Dans quelle catégorie MDO se classent le SRAS et Ebola ? Quelle obligation internationale impliquent-ils ?', 'Catégorie 2 du nouveau listing MDO (Décret 22-250) → obligatoirement notifiables à l’OMS.', 'Tombé 3× dans la BM (Ch. 12 Q7, Q11, Q13).', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_20', 'C2', 'L2.3', 'list', 'Parmi : Rubéole, Grippe saisonnière, Peste, Lyme, Méningite à méningocoque, Ankylostomiase — lesquelles sont MDO en Algérie ?', 'OUI (Cat. 1) : Rubéole, Peste, Méningite à méningocoque. NON : Grippe saisonnière (seul un NOUVEAU sous-type est Cat. 2 !), Lyme, Ankylostomiase.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_21', 'C2', 'L2.3', 'list', 'Quels sont les 3 axes de la prophylaxie des maladies transmissibles ?', '1) Action sur le réservoir (isolement, traitement, MDO), 2) Action sur la transmission (IEC, hygiène, vecteurs), 3) Protection du sujet réceptif (vaccination, séroprophylaxie SAS/SAT, chimioprophylaxie).', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_22', 'C3', 'L3.1', 'definition', 'Comment définir exactement un facteur de risque dans les MNT (et qu’est-ce qu’il N’EST PAS) ?', 'Une VARIABLE qui augmente la probabilité de survenue de la maladie. Ce n’est JAMAIS une constante et il diffère d’un simple marqueur de risque non modifiable.', 'BM Ch. 11 Q1.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_23', 'C3', 'L3.1', 'formula', 'Quels sont les chiffres clés des MNT dans le monde et en Algérie ?', 'Monde : 74 % des décès (41 M/an, 86 % PRFI). Algérie : ~80 % des décès (MCV 35 %, Cancers 15 %, Diabète > 14 %, Obésité femmes > 27 %, EV 77 ans).', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_24', 'C3', 'L3.1', 'short_answer', 'Quel marqueur démographique caractérise essentiellement la transition épidémiologique ?', 'L’augmentation de l’espérance de vie (accompagnée du recul des maladies infectieuses et de la montée des MNT).', 'BM Ch. 19 Q2 (2025).', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_25', 'C3', 'L3.2', 'cloze', 'Complétez : Dans les MNT, la prévention secondaire vise à diminuer les ______ (= la prévalence) grâce au ______.', '« nouveaux et anciens cas » (= prévalence) grâce au « dépistage » (stade préclinique).', 'BM Ch. 11 Q2, Q3, Q4.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_26', 'C3', 'L3.2', 'list', 'Citez dans l’ordre les 4 stades de l’histoire naturelle (chronologie) d’une MNT.', '1) Exposition prolongée aux FDR → 2) Stade préclinique (asymptomatique) → 3) Stade clinique → 4) Complications à long terme / phase terminale.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_27', 'C3', 'L3.2', 'difference', 'Distinguez l’arrêt du tabac (cancer poumon) et le scanner thoracique chez un ancien fumeur en termes de niveau de prévention.', 'Arrêt du tabac = Prévention PRIMAIRE. Scanner thoracique chez ancien fumeur = Prévention SECONDAIRE (dépistage).', 'BM Ch. 29 Q2 (2025).', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_28', 'C3', 'L3.3', 'formula', 'De quelles deux composantes est formé l’indicateur DALY (AVAI) ?', 'DALY = YLL (années de vie perdues par mortalité prématurée) + YLD (années vécues avec incapacité).', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_29', 'C3', 'L3.3', 'list', 'Quelles sont les 3 étapes de l’enquête STEPS de l’OMS pour surveiller les FDR des MNT ?', 'Step 1 : Questionnaire comportemental ; Step 2 : Mesures physiques (poids, taille, TA) ; Step 3 : Mesures biochimiques (glycémie, lipides).', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_30', 'C3', 'L3.3', 'difference', 'Pourquoi préférer le taux standardisé au taux brut pour comparer la mortalité par MNT entre deux pays ?', 'Le taux standardisé ajuste sur la structure d’âge des populations, éliminant l’effet confondant du vieillissement pour une comparaison équitable.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_31', 'C4', 'L4.1', 'definition', 'Définissez « Épidémie » et « Outbreak (cas groupés) ».', 'Épidémie = excès de cas par rapport au niveau attendu dans une population, un lieu et un temps donnés (limitée dans le temps ET l’espace). Outbreak = épidémie limitée géographiquement ou dans le temps.', 'Tombés en 2025 (Ch. 19 Q5 & Q6).', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_32', 'C4', 'L4.1', 'difference', 'Quelle est la différence principale entre une source ponctuelle et une source persistante ?', 'Source ponctuelle : libère l’agent sur une courte période uniquement (pic unique bref, ex. TIAC). Source persistante : libère l’agent de manière CONTINUE (et NON épisodique !).', 'BM Ch. 19 Q4 (2025).', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_33', 'C4', 'L4.1', 'short_answer', 'Quel est l’objectif principal d’une investigation épidémiologique ?', 'Interrompre la transmission (arrêter l’épidémie) et prévenir la survenue de nouveaux cas / épisodes.', 'BM Ch. 19 Q1 (2025).', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_34', 'C4', 'L4.2', 'list', 'Quelles 3 informations fournit la courbe épidémique, et quelle affirmation est un piège FAUX ?', 'OUI : 1) Durée d’incubation, 2) Type de transmission, 3) Nature de la source. FAUX : elle NE renseigne JAMAIS avec certitude sur l’agent causal (seul le labo le confirme !).', '⚠️ Erreur BM Ch. 14 Q49 !', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_35', 'C4', 'L4.2', 'formula', 'Comment s’appelle et comment se calcule le rapport « nombre de sujets atteints / population exposée de la zone » durant une épidémie ?', 'Le Taux d’attaque : TA = (Nombre de sujets atteints / Population exposée au risque) × 100.', 'BM Ch. 19 Q13 & Ch. 17 Q32.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_36', 'C4', 'L4.2', 'list', 'Citez les 5 causes de « fausse épidémie » à éliminer à l’Étape 1, ainsi que la date essentielle à recueillir à l’Étape 4.', '5 fausses épidémies : variation saisonnière, erreur diagnostique, contamination milieux de culture, doublons, notification groupée. Date essentielle = date de DÉBUT DES SYMPTÔMES.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_37', 'C4', 'L4.3', 'difference', 'Que compare une cohorte rétrospective vs une étude cas-témoins à l’Étape 7 ?', 'Cohorte rétrospective : compare les TAUX D’ATTAQUE chez les exposés vs les non-exposés. Cas-témoins : compare la PROPORTION D’EXPOSÉS parmi les cas vs parmi les témoins.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_38', 'C4', 'L4.3', 'cloze', 'Complétez (Étape 10) : Les mesures de prévention et de contrôle doivent être appliquées ______, en commençant par des mesures ______ puis ______.', '« le plus tôt possible sans attendre la fin de l’investigation », mesures « générales » puis « spécifiques ».', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_39', 'C4', 'L4.3', 'short_answer', 'Dans quel ordre obligatoire se déroulent les deux grandes phases d’une investigation épidémiologique ?', 'Toujours Phase DESCRIPTIVE d’abord, suivie de la Phase ANALYTIQUE (étiologique).', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_40', 'C5', 'L5.1', 'definition', 'Définissez une TIAC en précisant l’exception absolue.', 'Apparition d’au moins 2 cas groupés similaires d’une symptomatologie en général gastro-intestinale rapportable à une même origine alimentaire ou hydrique, SAUF le BOTULISME où 1 seul cas suffit.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_41', 'C5', 'L5.1', 'short_answer', 'Comment se fait la déclaration d’une TIAC et quel est son statut de contagiosité ?', 'Par un signalement rapide immédiat (SEMEP) + une notification sur relevé des MDO. C’est une urgence médicale et épidémiologique, maladie transmissible NON contagieuse.', 'BM Ch. 6 Q3 & Q5 (2024).', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_42', 'C5', 'L5.1', 'list', 'Quels acteurs interviennent dans le circuit d’alerte et d’investigation d’une TIAC en Algérie ?', 'Médecin traitant → SEMEP → DSP, MS, INSP + enquête conjointe avec BHC (Bureau d’Hygiène Communale) et DCP (Commerce) → Prélèvements IPA / Labo d’hygiène de wilaya.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_43', 'C5', 'L5.2', 'difference', 'Comparez les TIAC à S. aureus, C. perfringens et Salmonella (incubation, fièvre, aliments).', 'S. aureus : 1–6 h, SANS fièvre, pâtisseries/glaces/mayonnaise. C. perfringens : 8–24 h, SANS fièvre, viandes/sauces refroidissement lent. Salmonella : 12–72 h, AVEC fièvre (38–40 °C), œufs/volailles.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_44', 'C5', 'L5.2', 'formula', 'Quelles sont les quantités et la règle d’interdiction absolue pour les prélèvements de TIAC ?', 'NE JAMAIS CONGELER (sauf force majeure) ! Selles ≥ 10 g (avant ATB), Vomis 10–20 g, Aliment 250 g (+4 °C), Eau 1 litre flacon stérile (+4 °C).', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_45', 'C5', 'L5.2', 'short_answer', 'Quel médicament est formellement PROSCRIT en cas de TIAC avec syndrome dysentérique, et quel germe menace la femme enceinte ?', 'Médicament proscrit : Lopéramide (Imodium®) [colo-stase]. Germe femme enceinte : Listeria monocytogenes (avortement ; nouveau-né = méningite ; 3–30 j, fromages/charcuterie).', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_46', 'C5', 'L5.3', 'list', 'Citez les 5 Clés de l’OMS pour la sécurité sanitaire des aliments.', '1) Propreté, 2) Séparation cru/cuit, 3) Cuisson soigneuse (≥ 70 °C), 4) Températures sûres (< 5 °C / > 60 °C, ≤ 2 h ambiante), 5) Eau et produits sûrs.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_47', 'C5', 'L5.3', 'definition', 'Énoncez le principe de la « marche en avant » en restauration collective.', '« Jamais un circuit sale ne doit couper un circuit propre ».', 'Instruction N°18 (2024).', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_48', 'C5', 'L5.3', 'formula', 'Quelles sont les normes de température et de plat témoin en restauration collective (Instr. 2024 vs slides) ?', 'Chaud > 65 °C ; Froid 2–4 °C ; Restes jetés ; Plat témoin : 50–100 g à +4 °C pendant ≥ 72 h (Instr. 2024) / 5 jours (slides) ; Javel 12° ; Visite personnel : embauche + trimestrielle.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_49', 'C6', 'L6.1', 'formula', 'Quels sont les 3 délais chronologiques officiels d’une IAS / ISO ?', 'Hospitalisation standard : > 48 heures. Chirurgie sans implant (ISO) : 30 jours. Chirurgie AVEC implant ou prothèse : 1 AN.', '⚠️ Erreur BM Ch. 10 Q14 : prothèse genou 2 mois = bien une ISO !', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_50', 'C6', 'L6.1', 'definition', 'Que recouvre exactement le sigle IAS (distinction IN vs ILS) ?', 'IAS = IN (Infections Nosocomiales en établissement de santé : patients, personnel, visiteurs) + ILS (Infections Liées aux Soins en milieu libéral / extrahospitalier).', '⚠️ Erreur BM Ch. 10 Q21 !', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_51', 'C6', 'L6.1', 'formula', 'Quelles sont la prévalence nationale des IN en Algérie (2005) et les dates de création du CNHH et du CLIN ?', 'Prévalence Algérie (2005) = 14 % (Batna ISO neurochirurgie 2015 = 5,30 %). CNHH : 28 mars 1998. CLIN : 27 novembre 1998.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_52', 'C6', 'L6.2', 'list', 'Donnez le site d’IN le plus fréquent, la 1ère cause de décès (avec son germe n°1) et le germe n°1 sur cathéter.', '1ère fréquence : Infection urinaire (IUN, E. coli). 1ère cause de décès : Pneumonie nosocomiale (BGN = 60 %). Cathéter : Staphylocoques (50 %).', 'Jackpot 2024 ET 2025 !', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_53', 'C6', 'L6.2', 'definition', 'Quels sont les 3 critères définissant la colonisation d’un cathéter ?', '1) Culture positive au taux significatif, 2) ABSENCE de signes locaux (pas d’érythème !), 3) ABSENCE de signes généraux d’infection.', '⚠️ Erreur BM Ch. 10 Q22 : érythème = infection locale, PAS colonisation !', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_54', 'C6', 'L6.2', 'difference', 'Différenciez bactériémie et septicémie selon le cours.', 'Bactériémie = passage bref et transitoire de bactéries dans le sang. Septicémie = décharges massives et répétées à partir d’un foyer septique.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_55', 'C6', 'L6.3', 'difference', 'Comparez la flore cutanée résidente et la flore transitoire.', 'Résidente : ancienne, propre à l’individu, rarement pathogène (risque faible), DIFFICILE à enlever. Transitoire : récente (environnement/malades), germes pathogènes, FACILE à enlever (lavage/SHA).', '3 QCM BM (Q8, Q16, Q19).', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_56', 'C6', 'L6.3', 'list', 'Citez les 3 contre-indications de la friction par solution hydro-alcoolique (SHA).', '1) Mains mouillées, 2) Mains poudrées ou talquées, 3) Mains visiblement souillées. (Utiliser uniquement sur mains sèches et visuellement propres).', 'BM Ch. 10 Q11.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_57', 'C6', 'L6.3', 'list', 'Citez 4 erreurs majeures à proscrire lors de l’hygiène des mains (et la règle sur l’alliance lisse).', 'Proscrits : savon en pain, serviette tissu réutilisable, séchoir air chaud électrique, association de 2 antiseptiques, remplissage flacon non désinfecté. Alliance lisse = INTERDITE !', '⚠️ Erreur BM Ch. 10 Q6.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_58', 'C7', 'L7.1', 'definition', 'Quel est l’objectif principal et quelle est la population cible du Programme National de Santé Scolaire ?', 'Objectif : prestations préventives, curatives et éducatives pour un développement harmonieux (physique, mental, intellectuel, social). Cible : enfants scolarisés, enseignants et personnel administratif/de service.', 'BM Ch. 26 Q5 & Q7 (2025).', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_59', 'C7', 'L7.1', 'difference', 'Où exerce l’équipe de santé scolaire (rattachement) vs où se fait la prise en charge en milieu scolaire ?', 'L’équipe (5 profils : médecin, infirmier, dentiste, assistant médical, psychologue) est rattachée aux EPSP (structures de santé de proximité de terrain — Q1 A). La prise en charge en milieu scolaire se fait dans les UDS (collèges/lycées, par circonscription — Q3 D & Q6 B).', 'Piège BM 2025 Q1 vs Q3.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_60', 'C7', 'L7.1', 'list', 'Citez les 5 profils professionnels composant une équipe de santé scolaire (UDS).', '1) Médecin, 2) Infirmier, 3) Chirurgien-dentiste, 4) Assistant médical, 5) Psychologue.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_61', 'C7', 'L7.2', 'formula', 'Quelles sont les classes cibles de la vaccination scolaire et son indicateur d’évaluation ?', 'Classes cibles : 1ère AP, 1ère AM, 1ère AS (+ rattrapage). Indicateur : Taux de couverture vaccinale par antigène (Vaccinés / Population cible).', 'BM Ch. 26 Q2 & Q4 (2025, /).', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_62', 'C7', 'L7.2', 'short_answer', 'Quelle maladie est ciblée par la campagne accélérée d’élimination en milieu scolaire dans les wilayas du Sud ?', 'Le TRACHOME (dépistage actif, traitement, lavage mains/visage le matin, eau/assainissement, lutte mouches).', 'BM Ch. 13 Q3 (2025 → Aucune des réponses !).', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_63', 'C7', 'L7.3', 'list', 'Quelles sont les 5 classes cibles du programme bucco-dentaire (« Stop à la carie ») ?', 'Préscolaire, 1ère AP, 4ème AP, 2ème AM et 1ère AS (polyclinique EPSP réserve ≥ 2 après-midi/semaine).', 'À ne PAS confondre avec la vaccination (1AP/1AM/1AS) !', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_64', 'C7', 'L7.3', 'formula', 'Quelle est la fréquence des visites médicales du personnel des cantines et celle des rapports d’évaluation SEMEP/EPSP ?', 'Personnel cantines : ≥ 2 fois par an. Rapports d’évaluation : TRIMESTRIELS (SEMEP des EPSP → directeurs d’établissements + DSP).', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_65', 'C7', 'L7.3', 'difference', 'Que mesure l’indice « cao » par rapport à l’indice « CAO » en santé bucco-dentaire scolaire ?', 'cao (minuscules) = dents temporaires (cariées + absentes + obturées). CAO (majuscules) = dents permanentes de 6 ans.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_66', 'C8', 'L8.1', 'formula', 'Citez le numéro et la date du décret CMD algérien, le nombre d’exemplaires délivrés et les délais de déclaration à l’APC.', 'Décret exécutif n° 22-178 du 28 avril 2022 (11 art., abroge 16-80) ; délivré en 1 SEUL exemplaire ; déclaration APC = 24 heures (20 jours dans les wilayas du Sud).', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_67', 'C8', 'L8.1', 'difference', 'Comparez les 2 volets du CMD et décrivez le circuit mensuel du volet médical.', 'Partie supérieure = nominative (volet administratif → APC). Partie inférieure = anonyme, immédiatement scellée par le médecin (volet médical). Circuit mensuel : Médecin → Famille → APC → DSP (SEMEP) → INSP.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_68', 'C8', 'L8.1', 'list', 'Quels sont les 3 signalements particuliers à cocher sur le formulaire algérien du CMD ?', '1) Obstacle médicolégal à l’inhumation, 2) Prothèse fonctionnant avec pile, 3) Mise immédiate en cercueil hermétique (risque de contagion).', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_69', 'C8', 'L8.2', 'difference', 'Comparez Partie I (lignes a à d), Partie II et Partie III du volet médical du CMD.', 'Partie I : chaîne causale de haut en bas (a = cause directe ← b/c = intermédiaires ← d = CAUSE INITIALE retenue par l’OMS). Partie II : comorbidités contributives sans lien direct. Partie III : réservée au MÉDECIN LÉGISTE.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_70', 'C8', 'L8.2', 'short_answer', 'Que fait le médecin constatant en cas de mort violente, suspecte ou indéterminée (Art. 6.2) ?', 'Il remplit UNIQUEMENT la partie supérieure (administrative), coche l’obstacle médicolégal et avise les autorités compétentes. Le médecin légiste remplira la Partie III.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_71', 'C8', 'L8.2', 'cloze', 'Complétez : Sur le CMD, on écrit en majuscules, ______ abréviations, et il est formellement interdit d’inscrire ______ comme cause initiale.', '« SANS » abréviations ; « l’arrêt cardiaque (ACR) » (ou tout mode de décès / symptôme isolé) comme cause initiale.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_72', 'C8', 'L8.3', 'list', 'Quels sont les 4 groupes de codes CIM-10 formellement EXCLUS comme cause initiale de décès ?', '1) B95–B97 (agents infectieux seuls), 2) G97/H95/N99 (post-actes), 3) O80–O84 (accouchement normal), 4) S00–T98 (lésions traumatiques seules → coder la cause externe ex. AVP !).', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_73', 'C8', 'L8.3', 'short_answer', 'Quand utilise-t-on le code C97 en cancérologie, et quelle est la règle pour une lésion pulmonaire (C34) ?', 'C97 = 2 tumeurs malignes primitives indépendantes toutes deux en PARTIE I (ignorer la Partie II !). Poumon (C34) + autre tumeur = présumé métastase, SAUF « cancer bronchique » = tumeur primitive.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_74', 'C8', 'L8.3', 'formula', 'Quel délai définit le décès maternel (et quel délai définit une chirurgie récente sur le CMD) ?', 'Décès maternel : grossesse, accouchement/avortement ou dans les 42 JOURS après la fin de la gestation. Chirurgie récente : ≤ 4 semaines avant le décès.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_75', 'C9', 'L9.1', 'list', 'Citez les 4 sources de financement du système de santé et les 5 risques couverts par la sécurité sociale en Algérie.', '4 sources : Public (État), Assurance-maladie (CNAS/CASNOS), Privé (direct/indirect), Ressources externes (OMS/UNICEF). 5 risques : maladie, maternité, invalidité, AT, MP.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_76', 'C9', 'L9.1', 'formula', 'Différenciez CNAS et CASNOS et donnez les taux de remboursement médicaments / ticket modérateur.', 'CNAS = salariés ; CASNOS = non-salariés (financées par cotisations employeurs/travailleurs). Remboursement = 80 % (ticket modérateur = 20 %) ; 100 % maladies chroniques/protégées.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_77', 'C9', 'L9.1', 'definition', 'Que regroupe le coût d’investissement (coût en capital) d’un projet sanitaire ?', 'Les coûts de terrains, de bâtiments, d’équipements lourds et semi-lourds (non répétitifs, contrairement aux coûts de fonctionnement).', 'BM Ch. 15 Q3.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_78', 'C9', 'L9.2', 'difference', 'Que permet d’apprécier l’Équité vs la Pérennité d’un système de financement ?', 'Équité = apprécie l’ACCÈS AUX SOINS. Pérennité = apprécie la CONTINUITÉ DES SERVICES dans le temps.', 'BM Ch. 15 Q2 & Q4 (2×).', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_79', 'C9', 'L9.2', 'short_answer', 'Quels sont les avantages et inconvénients majeurs du financement privé des dépenses de santé ?', 'Avantages : fournit d’autres ressources, allège l’État, ÉVITE le gaspillage. Inconvénients : inéquité et exclusion des pauvres.', 'BM Ch. 15 Q5.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_80', 'C9', 'L9.3', 'difference', 'Distinguez les niveaux Macro, Méso et Micro-économique avec 1 indicateur/exemple du cours chacun.', 'Macro = échelle nationale (DNS/PIB : Algérie 7,23 % en 2018 ; USA 12 %). Méso = secteur santé (dépenses personnel = 80 % du budget). Micro = gestion d’un CHU, conso médicaments, coût d’un acte/GHM.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_81', 'C9', 'L9.3', 'formula', 'Quelle part du budget de fonctionnement des hôpitaux publics provient de la contribution symbolique des ménages en Algérie ?', '1,20 % (depuis 1974 / arrêté 1995 ; exonérés : démunis, chroniques, PNS, catégories protégées). Et 93,43 % du budget État va aux établissements publics.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_82', 'C10', 'L10.1', 'cloze', 'Complétez : Dans une étude épidémiologique, le questionnaire est élaboré dans la ______ et son titre doit éviter le mot ______.', '« phase de planification » ; éviter le mot « Questionnaire » (terme péjoratif).', 'Tombé en 2024 (Ch. 9 Q1) ET en 2025 (Ch. 34 Q1) !', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_83', 'C10', 'L10.1', 'list', 'Citez les 7 étapes élémentaires d’élaboration d’un questionnaire dans l’ordre.', '1) Définir l’objectif, 2) Choisir types de questions, 3) Structurer (général → spécifique, simples au début), 4) Modalités d’administration, 5) Pré-test, 6) Administrer, 7) Traiter / dépouiller.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_84', 'C10', 'L10.2', 'list', 'Quels sont les 4 éléments vérifiés lors du pré-test (Étape 5) ?', '1) Conception des questions, 2) Adaptation des modalités de réponse, 3) Oublis éventuels, 4) Temps réel de passation.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_85', 'C10', 'L10.2', 'formula', 'Combien de propositions maximum pour une question fermée ordonnée, et quel est le taux de retour moyen de l’e-mailing ?', 'Question fermée ordonnée : ≤ 3 propositions à classer. E-mailing : peu efficace, ~5 % de retour seulement. Questions ouvertes : à éviter (codification requise à l’Étape 7).', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_86', 'C11', 'L11.1', 'list', 'Associez chaque type de variable (Qualitative, Quanti discrète, Quanti continue) à son/ses graphique(s) exact(s).', 'Qualitative (nominale/ordinale : stades) → Diagramme en barres (espacées) + Circulaire. Quanti discrète (nb rappels vaccin) → Diagramme en bâtons. Quanti continue (poids) → Histogramme (juxtaposées) + Polygone.', '10 QCM BM !', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_87', 'C11', 'L11.1', 'formula', 'Combien de degrés représente 1 % dans un diagramme circulaire ? Calculez l’angle pour 25 %.', '1 % = 3,6° (PAS 4,6° !). Pour 25 % : 25 × 3,6° = 90°.', 'Piège BM Ch. 37 Q22 D.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_88', 'C11', 'L11.1', 'definition', 'Définissez un Ratio et donnez la formule du Sex-ratio.', 'Ratio = rapport des fréquences/effectifs de 2 modalités d’une MÊME variable (jamais 2 variables différentes !). Sex-ratio = Effectif Masculin / Effectif Féminin.', 'BM Ch. 17 Q14, Ch. 37 Q12 & Q21.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_89', 'C11', 'L11.1', 'difference', 'Quelle différence graphique majeure oppose l’histogramme et le diagramme en barres ?', 'Histogramme : variable quantitative CONTINUE, barres JUXTAPOSÉES (accolées). Diagramme en barres : variable QUALITATIVE, barres ESPACÉES.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_90', 'C11', 'L11.2', 'short_answer', 'Quelle étape préalable est indispensable pour calculer la médiane, et quelle est son unité ?', 'Ranger les valeurs observées par ordre croissant (ou décroissant). Elle s’exprime dans la MÊME unité que la variable (= Q₂ = D₅).', 'BM Ch. 37 Q17.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_91', 'C11', 'L11.2', 'formula', 'Combien y a-t-il de quartiles, de déciles et de percentiles, et à quelle famille de paramètres appartiennent-ils ?', '3 quartiles (4 parts), 9 déciles (10 parts), 99 percentiles (100 parts). Ce sont des paramètres de POSITION (PAS de dispersion !).', 'BM Ch. 37 Q27.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_92', 'C11', 'L11.2', 'cloze', 'Complétez : La moyenne arithmétique a ______ unité que la variable, et est ______ de la médiane si la distribution est dissymétrique.', '« la même » unité que la variable ; « différente » de la médiane si dissymétrique.', 'BM Ch. 37 Q23.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_93', 'C11', 'L11.3', 'formula', 'Donnez la formule, l’unité et l’utilité principale du Coefficient de Variation (CV).', 'CV = (écart-type / moyenne) × 100. Paramètre de dispersion SANS unité (exprimé en %). Sert à comparer la variabilité de 2 variables d’unités différentes.', '4× en BM (⚠️ Q11 = BC, Q24 = BDE).', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_94', 'C11', 'L11.3', 'definition', 'Définissez la variance et précisez son lien exact avec l’écart-type.', 'Mesure de l’étalement des valeurs observées par rapport à la moyenne (plus elle est élevée, plus les données sont éloignées de la moyenne). L’écart-type est la racine carrée de la variance (S = √S²).', '4× en BM.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_95', 'C11', 'L11.3', 'difference', 'Distinguez « Étendue » et « Amplitude d’une classe ».', 'Étendue = Valeur MAX − Valeur MIN de toute la série (paramètre de dispersion). Amplitude d’une classe = Borne sup − Borne inf d’une classe.', '⚠️ Erreur BM Ch. 37 Q14 (vraie réponse C, PAS A !).', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_96', 'C12', 'L12.1', 'difference', 'Distinguez le risque α et le degré de signification (p-value).', 'Risque α = risque de rejeter à tort H₀ (1ère espèce), fixé A PRIORI (5 %). p-value = probabilité sous H₀ d’observer un χ² au moins aussi grand, déterminée A POSTERIORI après calcul.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_97', 'C12', 'L12.1', 'difference', 'Quelle différence distingue le χ² de conformité (ajustement) du χ² d’homogénéité ?', 'χ² de conformité : compare 1 échantillon observé à une distribution théorique connue. χ² d’homogénéité : compare 2 ou plusieurs échantillons entre eux.', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_98', 'C12', 'L12.1', 'short_answer', 'Le test du χ² servant à comparer deux pourcentages s’applique-t-il directement sur des pourcentages ou sur des effectifs ?', 'TOUJOURS sur des EFFECTIFS (tableau de contingence), jamais directement sur des pourcentages !', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_99', 'C12', 'L12.2', 'formula', 'Écrivez les 3 formules du test du χ² : effectif théorique Cij, statistique χ²o et degrés de liberté ddl.', 'Cij = (Total ligne i × Total colonne j) / N ; χ²o = Σ (Oij − Cij)² / Cij ; ddl = (L − 1)(C − 1).', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_100', 'C12', 'L12.2', 'cloze', 'Complétez : La condition d’application du test du χ² exige que tous les effectifs ______ soient ≥ ______.', '« THÉORIQUES (Cij) » soient ≥ « 5 » (et PAS les effectifs observés !).', '', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_101', 'C12', 'L12.2', 'formula', 'Quelle est la valeur critique du χ² pour ddl = 1 au risque α = 5 %, et quelle conclusion tirer si χ²o = 3,125 (exemple du cours) ?', 'χ²(5 %, ddl=1) = 3,841 (10 % = 2,706 ; 1 % = 6,635). Avec χ²o = 3,125 < 3,841 (0,05 < p < 0,10) → NON-REJET de H₀ (différence non significative ; ne jamais dire « on accepte H₀ » !).', 'Slide 27 Pr Aouidane.', '', NULL, '', '', 'course_generated', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_9C017779_L1_1', 'PPT_9C017779', 'PPT_9C017779_L1', 'list', 'Citez les points clés listés dans la Diapositive 3 pour : Plan (7 points).', 'Introduction • Perceptions de la certification des causes de décès • Contenu du certificatmédical de décès • Rédaction du CMD • Principe général de l’OMS • Particularités de codification CIM10', 'Source : Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositive 3 (Plan)', 'Diapositive 3', 3, 'Plan', 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_9C017779_L1_2', 'PPT_9C017779', 'PPT_9C017779_L1', 'list', 'Citez les points clés listés dans la Diapositive 4 pour : La disponibilité des données sur la mortalité est fondamentale pour le développement d''un pays.… (3 points).', 'La disponibilité des données sur la mortalité est fondamentale pour le développement d''un pays. Elle permet de répondre efficacement aux épidémies actuelles et émergentes. • La collected''informationspertinentesoriente la stratégie de santé publique face aux urgences sanitaires. • Introduction', 'Source : Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositive 4 (La disponibilité des données sur la mortalité est fondamentale pour le développement d''un pays.…)', 'Diapositive 4', 4, 'La disponibilité des données sur la mortalité est fondamentale pour le développement d''un pays.…', 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_9C017779_L2_1', 'PPT_9C017779', 'PPT_9C017779_L2', 'formula', 'D''après la Diapositive 10 (« Une femme de 65 ans décède à l''hôpital. Le dossier médical mentionne : »), quelle formule ou valeur précise faut-il retenir sur : Une femme de 65 ans décède à l''hôpital. Le dossier médical mentionne : (Diapo 10) ?', 'Diabète depuis 15 ans', 'Source : Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositive 10 (Une femme de 65 ans décède à l''hôpital. Le dossier médical mentionne :)', 'Diapositive 10', 10, 'Une femme de 65 ans décède à l''hôpital. Le dossier médical mentionne :', 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_9C017779_L2_2', 'PPT_9C017779', 'PPT_9C017779_L2', 'formula', 'D''après la Diapositive 10 (« Une femme de 65 ans décède à l''hôpital. Le dossier médical mentionne : »), quelle formule ou valeur précise faut-il retenir sur : Exemple concret sur terrain ?', 'Décès d''une patiente de 65 ans : Scénario réel', 'Source : Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositive 10 (Une femme de 65 ans décède à l''hôpital. Le dossier médical mentionne :)', 'Diapositive 10', 10, 'Une femme de 65 ans décède à l''hôpital. Le dossier médical mentionne :', 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_9C017779_L2_3', 'PPT_9C017779', 'PPT_9C017779_L2', 'formula', 'D''après la Diapositive 11 (« Patiente : 32 ans, G3P2 Âge gestationnel : 38 SA Antécédents : »), quelle formule ou valeur précise faut-il retenir sur : Décès maternel d''une patiente de 32 ans ?', 'Scénario réel', 'Source : Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositive 11 (Patiente : 32 ans, G3P2 Âge gestationnel : 38 SA Antécédents :)', 'Diapositive 11', 11, 'Patiente : 32 ans, G3P2 Âge gestationnel : 38 SA Antécédents :', 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_9C017779_L2_4', 'PPT_9C017779', 'PPT_9C017779_L2', 'formula', 'D''après la Diapositive 12 (« Un enfant de 3 ans décède dans un centre de santé rural. Le dossier mentionne : »), quelle formule ou valeur précise faut-il retenir sur : Un enfant de 3 ans décède dans un centre de santé rural. Le dossier mentionne : (Diapo 12) ?', 'Diarrhée aiguë depuis 5 jours', 'Source : Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositive 12 (Un enfant de 3 ans décède dans un centre de santé rural. Le dossier mentionne :)', 'Diapositive 12', 12, 'Un enfant de 3 ans décède dans un centre de santé rural. Le dossier mentionne :', 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_9C017779_L3_1', 'PPT_9C017779', 'PPT_9C017779_L3', 'definition', 'Selon la Diapositive 17 (« Médecin autorisé »), comment définir ou énoncer : Médecin autorisé (Diapo 17) ?', 'Rédigé sur un modèle standard fixé par le décret N°22-178 du 28/04/2022.', 'Source : Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositive 17 (Médecin autorisé)', 'Diapositive 17', 17, 'Médecin autorisé', 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_9C017779_L3_2', 'PPT_9C017779', 'PPT_9C017779_L3', 'definition', 'Selon la Diapositive 19 (« 4.Rédaction du CMD: »), comment définir ou énoncer : 4.Rédaction du CMD: (Diapo 19) ?', 'Définition officielle', 'Source : Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositive 19 (4.Rédaction du CMD:)', 'Diapositive 19', 19, '4.Rédaction du CMD:', 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_9C017779_L3_3', 'PPT_9C017779', 'PPT_9C017779_L3', 'definition', 'Selon la Diapositive 19 (« 4.Rédaction du CMD: »), comment définir ou énoncer : 4.Rédaction du CMD: (Diapo 19) ?', 'La définition n''inclut pas les symptômes, ni les modes de décès, tels qu''une défaillance cardiaque ou respiratoire.', 'Source : Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositive 19 (4.Rédaction du CMD:)', 'Diapositive 19', 19, '4.Rédaction du CMD:', 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_9C017779_L3_4', 'PPT_9C017779', 'PPT_9C017779_L3', 'list', 'Citez les points clés listés dans la Diapositive 21 pour : 4. Redaction du CMD: Conseils pratiques pour la redaction (7 points).', 'Écriturelisible • En majuscule, sans abréviation • Plusieurs événements • Toutes les lignes de la chaîne causale doivent être remplies • Un seul événement par ligne • Ordre chronologique précis', 'Source : Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositive 21 (4. Redaction du CMD: Conseils pratiques pour la redaction)', 'Diapositive 21', 21, '4. Redaction du CMD: Conseils pratiques pour la redaction', 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_9C017779_L4_1', 'PPT_9C017779', 'PPT_9C017779_L4', 'difference', 'Que précise la Diapositive 26 (« 5.2 Catégories exclues pour la cause initiale ») à propos de : 5.2 Catégories exclues pour la cause initiale (Diapo 26) ?', 'Certaines catégories ne doivent pas être utilisées pour coder la cause initiale de décès : B95-B97 (agents d''infections), G97/H95/N99 (affections post-actes médicaux), O80-O84 (accouchement), S00-T98 (lésions traumatiques et conséquences de causes externes).', 'Source : Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositive 26 (5.2 Catégories exclues pour la cause initiale)', 'Diapositive 26', 26, '5.2 Catégories exclues pour la cause initiale', 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_9C017779_L4_2', 'PPT_9C017779', 'PPT_9C017779_L4', 'formula', 'D''après la Diapositive 26 (« 5.2 Catégories exclues pour la cause initiale »), quelle formule ou valeur précise faut-il retenir sur : Cause initiale = ce qui a abordé la mort On ne met pas ?', 'bactéries, complications post-op, simples accouchements, blessures seules Sinon, les statistiques sur les causes de décès seraient incorrectes ou trompeuses .', 'Source : Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositive 26 (5.2 Catégories exclues pour la cause initiale)', 'Diapositive 26', 26, '5.2 Catégories exclues pour la cause initiale', 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
