INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_9C017779_L4_4', 'PPT_9C017779', 'PPT_9C017779_L4', 'definition', 'Selon la Diapositive 30 (« Particularité des tumeurspulmonaires C34 »), comment définir ou énoncer : Particularité des tumeurspulmonaires C34 (Diapo 30) ?', 'Le poumon est un site fréquent de métastases', 'Source : Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositive 30 (Particularité des tumeurspulmonaires C34)', 'Diapositive 30', 30, 'Particularité des tumeurspulmonaires C34', 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
