INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_9C017779_L5_2', 'PPT_9C017779', 'PPT_9C017779_L5', 'short_answer', 'Que précise la Diapositive 31 (« 6. En cas de manque de données ») à propos de : 6. En cas de manque de données (Diapo 31) ?', 'Le principegénéral ne s''applique pas lorsqueplusieursaffectionssontmentionnées dans la dernièreligne de la partie I.', 'Source : Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositive 31 (6. En cas de manque de données)', 'Diapositive 31', 31, '6. En cas de manque de données', 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
