INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_9C017779_L6_1', 'PPT_9C017779', 'PPT_9C017779_L6', 'formula', 'D''après la Diapositive 41 (« Certificat 17 »), quelle formule ou valeur précise faut-il retenir sur : Certificat 17 (Diapo 41) ?', 'I. a) Détresse respiratoire néonatale b) Maladie des membranes hyalines c) Grande prématurité d) Accouchement prématuré à 30 SA', 'Source : Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositive 41 (Certificat 17)', 'Diapositive 41', 41, 'Certificat 17', 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_9C017779_L6_2', 'PPT_9C017779', 'PPT_9C017779_L6', 'definition', 'Selon la Diapositive 42 (« Erreurs à éviter »), comment définir ou énoncer : Erreurs à éviter (Diapo 42) ?', 'C''est un mode de décès, pas une maladie déclenchante', 'Source : Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositive 42 (Erreurs à éviter)', 'Diapositive 42', 42, 'Erreurs à éviter', 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_9C017779_L6_3', 'PPT_9C017779', 'PPT_9C017779_L6', 'difference', 'Que précise la Diapositive 42 (« Erreurs à éviter ») à propos de : Erreurs à éviter (Diapo 42) ?', 'Utiliser des catégories exclues', 'Source : Certification-de-la-Cause-Medicale-de-Deces2(3).pptx · Diapositive 42 (Erreurs à éviter)', 'Diapositive 42', 42, 'Erreurs à éviter', 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_86518E68_L1_1', 'PPT_86518E68', 'PPT_86518E68_L1', 'list', 'Citez les points clés listés dans la Diapositive 2 pour : Objectifs du cours (6 points).', 'Définirles MNT • Comprendreleur importance en santé publique • Identifier les facteurs de risque • Expliquer les méthodes épidémiologiques • Connaître les stratégies de prévention • Explorer les systèmes de surveillance', 'Source : EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx · Diapositive 2 (Objectifs du cours)', 'Diapositive 2', 2, 'Objectifs du cours', 'EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_86518E68_L1_2', 'PPT_86518E68', 'PPT_86518E68_L1', 'list', 'Citez les points clés listés dans la Diapositive 3 pour : Définition des MNT (3 points).', 'Les maladies non transmissibles (MNT) sont des affections chroniques qui ne sont pas causées par des agents infectieux et ne se transmettent pas d''une personne à une autre. • Elles se caractérisent par une longue durée et une progression généralement lente. • Les MNT comprennent les maladies cardiovasculaires (MCV), les cancers, les maladies respiratoires chroniques (comme la BPCO et l''asthme), le diabète et les troubles mentaux.', 'Source : EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx · Diapositive 3 (Définition des MNT)', 'Diapositive 3', 3, 'Définition des MNT', 'EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_86518E68_L1_3', 'PPT_86518E68', 'PPT_86518E68_L1', 'difference', 'Que précise la Diapositive 4 (« Principales catégories de MNT ») à propos de : Cancers ?', 'Divers types de cancers tels que le cancer du poumon, du sein, du côlon et', 'Source : EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx · Diapositive 4 (Principales catégories de MNT)', 'Diapositive 4', 4, 'Principales catégories de MNT', 'EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_86518E68_L1_4', 'PPT_86518E68', 'PPT_86518E68_L1', 'list', 'Citez les points clés listés dans la Diapositive 4 pour : Principales catégories de MNT (4 points).', 'Maladies cardiovasculaires : Incluent les cardiopathies coronariennes, les accidents vasculaires cérébraux (AVC) et l''hypertension artérielle (HTA). • Cancers : Divers types de cancers tels que le cancer du poumon, du sein, du côlon et • Maladies respiratoires chroniques : Comme la bronchopneumopathie chronique obstructive • Diabète : Principalement le diabète de type 2, souvent lié à l''obésité et à un mode de vie sédentaire.', 'Source : EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx · Diapositive 4 (Principales catégories de MNT)', 'Diapositive 4', 4, 'Principales catégories de MNT', 'EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_86518E68_L2_1', 'PPT_86518E68', 'PPT_86518E68_L2', 'list', 'Citez les points clés listés dans la Diapositive 8 pour : Facteurs sociaux et environnementaux (5 points).', 'Pauvreté et inégalités socio-économiques : Accès limité aux ressources de santé, à une alimentation saine et à un environnement de vie adéquat. • Niveau d''éducation : Faible niveau d''instruction associé à une moindre sensibilisation aux risques pour la santé et à une adoption plus fréquente de comportements à risque. • Urbanisation rapide et non planifiée : Exposition accrue au stress, à la pollution et à des modes de vie sédentaires. • Conditions de travail précaires : Exposition à des risques professionnels, stress lié au travail et manque d''accès aux soins de santé. • Pollution de l''air et de l''eau : Augmentation de l''incidence des maladies respiratoires et autres problèmes de santé liés à la pollution environnementale.', 'Source : EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx · Diapositive 8 (Facteurs sociaux et environnementaux)', 'Diapositive 8', 8, 'Facteurs sociaux et environnementaux', 'EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_86518E68_L2_2', 'PPT_86518E68', 'PPT_86518E68_L2', 'difference', 'Que précise la Diapositive 9 (« Facteurs non modifiables ») à propos de : Sexe ?', 'Certains MNT sont plus fréquentes chez un sexe que chez l''autre, en raison de différences hormonales, génétiques et comportementales.', 'Source : EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx · Diapositive 9 (Facteurs non modifiables)', 'Diapositive 9', 9, 'Facteurs non modifiables', 'EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_86518E68_L2_3', 'PPT_86518E68', 'PPT_86518E68_L2', 'list', 'Citez les points clés listés dans la Diapositive 9 pour : Facteurs non modifiables (3 points).', 'Âge : Le risque de nombreuses MNT augmente avec l''âge, en raison de l''accumulation de dommages cellulaires et de l''altération des fonctions physiologiques. • Sexe : Certains MNT sont plus fréquentes chez un sexe que chez l''autre, en raison de différences hormonales, génétiques et comportementales. • Hérédité : Les antécédents familiaux de certaines MNT augmentent le risque de développer ces maladies, en raison de la transmission de gènes prédisposant.', 'Source : EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx · Diapositive 9 (Facteurs non modifiables)', 'Diapositive 9', 9, 'Facteurs non modifiables', 'EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_86518E68_L2_4', 'PPT_86518E68', 'PPT_86518E68_L2', 'list', 'Citez les points clés listés dans la Diapositive 10 pour : Transition épidémiologique (Monde) (4 points).', 'Réduction des maladies infectieuses : Amélioration de l''hygiène, vaccination et développement d''antibiotiques ont conduit à une diminution des maladies infectieuses comme causes de mortalité. • Urbanisation rapide : Migration vers les villes entraîne des changements de mode de vie, une exposition à de nouveaux facteurs de risque et des défis en matière de santé publique. • Vieillissement : Augmentation de l''espérance de vie et proportion croissante de personnes âgées dans la population, ce qui accroît la prévalence des maladies chroniques. • Industrialisation et globalisation : Modification des modes de production, de consommation et de communication, avec des impacts sur l''alimentation, l''activité physique et l''exposition à des substances nocives.', 'Source : EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx · Diapositive 10 (Transition épidémiologique (Monde))', 'Diapositive 10', 10, 'Transition épidémiologique (Monde)', 'EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_86518E68_L3_1', 'PPT_86518E68', 'PPT_86518E68_L3', 'list', 'Citez les points clés listés dans la Diapositive 15 pour : Épidémiologie expérimentale (3 points).', 'Essais cliniques randomisés : Méthode rigoureuse pour évaluer l''efficacité de nouvelles interventions (médicaments, vaccins, thérapies) en comparant aléatoirement des groupes de participants recevant l''intervention à des groupes témoins recevant un placebo ou un traitement standard. • Études d''intervention : Évaluation de l''impact de programmes ou de politiques de santé publique sur la prévention ou le contrôle des maladies, en mesurant les changements dans les taux de morbidité ou de mortalité après la mise en œuvre de l''intervention. • Études animales en recherche étiologique : Utilisation de modèles animaux pour étudier les mécanismes biologiques par lesquels les facteurs de risque environnementaux ou génétiques peuvent causer des maladies, permettant ainsi d''établir des liens de causalité et de mieux comprendre la pathogenèse des maladies.', 'Source : EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx · Diapositive 15 (Épidémiologie expérimentale)', 'Diapositive 15', 15, 'Épidémiologie expérimentale', 'EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_86518E68_L3_2', 'PPT_86518E68', 'PPT_86518E68_L3', 'list', 'Citez les points clés listés dans la Diapositive 16 pour : Multimorbidité (3 points).', 'Présence simultanée de plusieurs maladies non transmissibles (MNT) chez un même individu, par exemple, diabète, hypertension et maladies cardiovasculaires. • Diminution significative de la qualité de vie due aux symptômes combinés, aux limitations fonctionnelles et au fardeau du traitement. • Difficultés accrues dans la prise en charge thérapeutique en raison des interactions médicamenteuses, des contre-indications et de la nécessité d''une approche personnalisée et coordonnée.', 'Source : EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx · Diapositive 16 (Multimorbidité)', 'Diapositive 16', 16, 'Multimorbidité', 'EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_86518E68_L4_1', 'PPT_86518E68', 'PPT_86518E68_L4', 'list', 'Citez les points clés listés dans la Diapositive 20 pour : Prevention secondaire: Baisse de la prevalence de la maladie (3 points).', 'Dépistage précoce : Identification précoce des maladies non transmissibles (MNT) chez les individus asymptomatiques ou à risque. • Mammographie, coloscopie, glycémie : Tests de dépistage réguliers pour le cancer du sein, le cancer colorectal et le diabète, respectivement. Ces examens permettent une détection précoce et une intervention rapide. • Exemples de programmes : Programmes de dépistage du cancer du col de l''utérus par frottis cervico-vaginal, programmes de dépistage de l''hypertension artérielle en milieu de travail, et programmes de dépistage du glaucome pour les personnes âgées.', 'Source : EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx · Diapositive 20 (Prevention secondaire: Baisse de la prevalence de la maladie)', 'Diapositive 20', 20, 'Prevention secondaire: Baisse de la prevalence de la maladie', 'EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_86518E68_L4_2', 'PPT_86518E68', 'PPT_86518E68_L4', 'list', 'Citez les points clés listés dans la Diapositive 21 pour : Préventiontertiaire: Baisse de la prevalence des complications (3 points).', 'Réadaptation cardiaque : Programmes structurés d''exercices et de soutien psychologique pour améliorer la fonction cardiaque et la qualité de vie après un événement cardiovasculaire. • Suivi du diabète : Surveillance régulière de la glycémie, ajustement du traitement et éducation thérapeutique pour prévenir les complications à long terme. • Prévention des complications : Gestion des complications des MNT, telles que les ulcères du pied diabétique, les accidents vasculaires cérébraux (AVC) et les insuffisances rénales, grâce à des interventions médicales et chirurgicales appropriées.', 'Source : EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx · Diapositive 21 (Préventiontertiaire: Baisse de la prevalence des complications)', 'Diapositive 21', 21, 'Préventiontertiaire: Baisse de la prevalence des complications', 'EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_86518E68_L4_3', 'PPT_86518E68', 'PPT_86518E68_L4', 'list', 'Citez les points clés listés dans la Diapositive 22 pour : Prévention quaternaire (3 points).', 'Éviter les soins inutiles : Identifier et réduire les interventions médicales qui n''apportent pas de bénéfice clinique significatif au patient, diminuant ainsi les risques liés aux traitements inutiles. • Réduire la surmédicalisation : Lutter contre la prescription excessive de médicaments et la réalisation d''examens complémentaires non indispensables, en privilégiant une approche plus mesurée et personnalisée des soins. • Promotion de la pertinence des soins : Encourager une prise de décision partagée entre le professionnel de santé et le patient, basée sur les preuves scientifiques et les préférences du patient, afin de garantir des soins adaptés et efficaces.', 'Source : EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx · Diapositive 22 (Prévention quaternaire)', 'Diapositive 22', 22, 'Prévention quaternaire', 'EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_86518E68_L4_4', 'PPT_86518E68', 'PPT_86518E68_L4', 'list', 'Citez les points clés listés dans la Diapositive 24 pour : Surveillance des MNT (2/2) (3 points).', 'Enquêtes STEPS (OMS) : Réalisation d''enquêtes régulières selon la méthodologie STEPS de l''OMS pour collecter des données standardisées sur les facteurs de risque et les comportements de santé liés aux MNT. • Indicateurs clés : Suivi des indicateurs d''incidence, de prévalence et de mortalité des principaux MNT pour évaluer l''impact des interventions et orienter les politiques de santé publique. • Systèmes informatisés et e-santé : Utilisation de systèmes d''information et de technologies de l''e-santé pour améliorer la collecte, l''analyse et la diffusion des données de surveillance, ainsi que pour renforcer la coordination des soins et la communication avec les patients.', 'Source : EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx · Diapositive 24 (Surveillance des MNT (2/2))', 'Diapositive 24', 24, 'Surveillance des MNT (2/2)', 'EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_86518E68_L5_1', 'PPT_86518E68', 'PPT_86518E68_L5', 'list', 'Citez les points clés listés dans la Diapositive 27 pour : Éducation pour la santé (3 points).', 'Campagnes publiques : Lancement de campagnes de sensibilisation à grande échelle, utilisant divers canaux de communication (télévision, radio, affiches, événements communautaires) pour informer le public sur les MNT et promouvoir des comportements sains. • Écoles, médias, réseaux sociaux : Intégration de l''éducation à la santé dans les programmes scolaires, collaboration avec les médias pour diffuser des messages éducatifs, et utilisation des réseaux sociaux pour atteindre les jeunes et encourager l''adoption de modes de vie sains. • Empowerment des patients : Fournir aux patients les connaissances, les compétences et le soutien nécessaires pour prendre en charge leur propre santé, en les encourageant à participer activement aux décisions concernant leur traitement et leur suivi, et en les aidant à adopter des comportements favorables à la santé.', 'Source : EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx · Diapositive 27 (Éducation pour la santé)', 'Diapositive 27', 27, 'Éducation pour la santé', 'EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_86518E68_L5_2', 'PPT_86518E68', 'PPT_86518E68_L5', 'list', 'Citez les points clés listés dans la Diapositive 29 pour : Conclusion (3 points).', 'Les MNT représentent un défi mondial croissant : En raison du vieillissement de la population, de l''urbanisation rapide et de l''évolution des modes de vie, les maladies non transmissibles constituent un fardeau de plus en plus lourd pour les systèmes de santé et les économies du monde entier. • La prévention, la surveillance et la recherche sont essentielles : Pour réduire l''impact des MNT, il est crucial d''investir dans des programmes de prévention efficaces ciblant les facteurs de risque communs, de mettre en place des systèmes de surveillance pour suivre l''évolution des maladies et d''encourager la recherche pour améliorer les stratégies de prévention et de traitement. • Une action intersectorielle est nécessaire : La lutte contre les MNT nécessite une approche coordonnée impliquant les secteurs de la santé, de l''éducation, de l''agriculture, de l''environnement et des finances, ainsi que la participation active de la société civile et du secteur privé.', 'Source : EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx · Diapositive 29 (Conclusion)', 'Diapositive 29', 29, 'Conclusion', 'EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_86518E68_L5_3', 'PPT_86518E68', 'PPT_86518E68_L5', 'list', 'Citez les points clés listés dans la Diapositive 30 pour : Sources (6 points).', 'Organisation Mondiale de la Santé (OMS), 2022: Publications et rapports sur les maladies non transmissibles, les facteurs de risque et les stratégies de prévention. • Global Burden of Disease (GBD), 2019: Études complètes sur la mortalité, la morbidité et les facteurs de risque associés aux MNT à l''échelle mondiale. • Institut National de Santé Publique (INSP), 2020: Données et analyses épidémiologiques sur les MNT en Algérie. • The Lancet, 2011: Articles de recherche et revues sur les aspects cliniques, épidémiologiques et de santé publique des MNT. • WHO STEPS: Outil de surveillance des facteurs de risque des MNT développé par l''OMS. • WHO Multimorbidity, 2021: Rapport sur la multimorbidité et les défis liés à la prise en charge des personnes atteintes de plusieurs MNT.', 'Source : EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx · Diapositive 30 (Sources)', 'Diapositive 30', 30, 'Sources', 'EPIDEMIOLOGIE-DES-MALADIES-NON-TRANSMISSIBLES (1).pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_3F82C653_L1_1', 'PPT_3F82C653', 'PPT_3F82C653_L1', 'list', 'Citez les points clés listés dans la Diapositive 2 pour : Objectifs spécifiques (4 points).', 'Définir l’Hygiène Hospitalière ; • Définir les infections associées aux soins ; • Présenter les infections associées aux soins ; • Décrire les principales mesures de prévention .', 'Source : Les infections associées aux soins.pptx · Diapositive 2 (Objectifs spécifiques)', 'Diapositive 2', 2, 'Objectifs spécifiques', 'Les infections associées aux soins.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
