INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_3F82C653_L3_4', 'PPT_3F82C653', 'PPT_3F82C653_L3', 'list', 'Citez les points clés listés dans la Diapositive 18 pour : 5. Localisation des I.N courantes (6 points).', 'Terrain : sujet âgé, immuno dépression, antibiothérapie prolongé... • Score ASA élevé. • Type de chirurgie: propre, contaminé,…. • Durée du séjour préopératoire. • Préparation de l''opéré(e) : l’hygiène corporelle, type de dépilation. • Intervention elle-même.', 'Source : Les infections associées aux soins.pptx · Diapositive 18 (5. Localisation des I.N courantes)', 'Diapositive 18', 18, '5. Localisation des I.N courantes', 'Les infections associées aux soins.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
