INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_3F82C653_L4_2', 'PPT_3F82C653', 'PPT_3F82C653_L4', 'list', 'Citez les points clés listés dans la Diapositive 20 pour : 5. Localisation des I.N courantes (4 points).', 'Veineuse(cathéter infecté), • Chirurgicale(intervention sur les voies digestives….), • Médicales(investigation à l’aide de sonde), • Cutanée(surinfection de plaies….).', 'Source : Les infections associées aux soins.pptx · Diapositive 20 (5. Localisation des I.N courantes)', 'Diapositive 20', 20, '5. Localisation des I.N courantes', 'Les infections associées aux soins.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
