INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_0EDCCDA7_L1_1', 'PPT_0EDCCDA7', 'PPT_0EDCCDA7_L1', 'list', 'Citez les points clés listés dans la Diapositive 2 pour : PLAN (6 points).', 'Introduction • Modèle du certificat médical de décès • Circuit administratif du certificats de décès • Ses principaux intervenants. • Problèmes rencontrés dans la pratique • Conclusion', 'Source : modele de cmd et circuit.pptx · Diapositive 2 (PLAN)', 'Diapositive 2', 2, 'PLAN', 'modele de cmd et circuit.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_0EDCCDA7_L1_2', 'PPT_0EDCCDA7', 'PPT_0EDCCDA7_L1', 'definition', 'Selon la Diapositive 3 (« Le certificat médical de décès est un document officiel, indispensable, qui doit obligatoiremen… »), comment définir ou énoncer : Le certificat médical de décès est un document officiel, indispensable, qui doit obligatoiremen… (Diapo 3) ?', 'Le certificat médical de décès est un document officiel, indispensable, qui doit obligatoirement être rédigé par un médecin. Ce document revêt une importance capitale. Il permet d''entamer les démarches administratives, comme la déclaration auprès de l''état civil mais il sert également à fournir des informations sur les différents causes et circonstance du décès. Ces données sont essentielles pour suivre l''évolution des maladies, identifier des tendances épidémiologiques, et évaluer l''impact des politiques de santé.', 'Source : modele de cmd et circuit.pptx · Diapositive 3 (Le certificat médical de décès est un document officiel, indispensable, qui doit obligatoiremen…)', 'Diapositive 3', 3, 'Le certificat médical de décès est un document officiel, indispensable, qui doit obligatoiremen…', 'modele de cmd et circuit.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_0EDCCDA7_L2_1', 'PPT_0EDCCDA7', 'PPT_0EDCCDA7_L2', 'list', 'Citez les points clés listés dans la Diapositive 5 pour : a) Un volet administratif : Partie supérieure, nominative destinée au bureau de de l’état civil. (7 points).', 'La commune de décès et la wilaya de décès. • Nom, prénom • Sexe • Date et lieu de naissance. • Date et heure de décès. • Age', 'Source : modele de cmd et circuit.pptx · Diapositive 5 (a) Un volet administratif : Partie supérieure, nominative destinée au bureau de de l’état civil.)', 'Diapositive 5', 5, 'a) Un volet administratif : Partie supérieure, nominative destinée au bureau de de l’état civil.', 'modele de cmd et circuit.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_0EDCCDA7_L2_2', 'PPT_0EDCCDA7', 'PPT_0EDCCDA7_L2', 'list', 'Citez les points clés listés dans la Diapositive 6 pour : Date, et l’heure du décès. (6 points).', 'Date, et l’heure du décès. • Nature du décès : • naturelle : La mort naturelle découle de l’évolution finale d’une maladie • violente : en cas d''un suicide, d''un homicide ou d''un accident. • indéterminée :lorsque les circonstances de la mort ne peuvent être clairement établies. • Signature et cachet', 'Source : modele de cmd et circuit.pptx · Diapositive 6 (Date, et l’heure du décès.)', 'Diapositive 6', 6, 'Date, et l’heure du décès.', 'modele de cmd et circuit.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_0EDCCDA7_L2_3', 'PPT_0EDCCDA7', 'PPT_0EDCCDA7_L2', 'list', 'Citez les points clés listés dans la Diapositive 7 pour : b)Le volet médical: (anonyme) contient les mêmes informations que le volet administratif , et i… (3 points).', 'La cause directe (a) (maladie terminale, traumatisme ou complication ayant directement entraîné la mort) , • Les causes intermédiaires (b) et (c) • La cause initiale du décès (d) (maladie ou traumatisme étant à l''origine de la séquence des événements morbides ayant entraîné la mort)', 'Source : modele de cmd et circuit.pptx · Diapositive 7 (b)Le volet médical: (anonyme) contient les mêmes informations que le volet administratif , et i…)', 'Diapositive 7', 7, 'b)Le volet médical: (anonyme) contient les mêmes informations que le volet administratif , et i…', 'modele de cmd et circuit.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_0EDCCDA7_L2_4', 'PPT_0EDCCDA7', 'PPT_0EDCCDA7_L2', 'formula', 'D''après la Diapositive 9 (« La déclaration de décès est effectuée par la famille du défunt auprès du bureau de l''état civil dans un délai de 24 heures »), quelle formule ou valeur précise faut-il retenir sur : La déclaration de décès est effectuée par la famille du défunt auprès du bureau de l''état civil dans un délai de 24 heures (Diapo 9) ?', '(20jours pour les wilayas du sud). L''officier conserve la première partie du certificat(volet administratif), tandis que la partie inférieure(volet médical) est envoyée mensuellement à la direction de la santé et de la population. Cette dernière la transmet au service de causes de décès de l''Institut national de santé publique (INSP).', 'Source : modele de cmd et circuit.pptx · Diapositive 9 (La déclaration de décès est effectuée par la famille du défunt auprès du bureau de l''état civil dans un délai de 24 heures)', 'Diapositive 9', 9, 'La déclaration de décès est effectuée par la famille du défunt auprès du bureau de l''état civil dans un délai de 24 heures', 'modele de cmd et circuit.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_0EDCCDA7_L3_1', 'PPT_0EDCCDA7', 'PPT_0EDCCDA7_L3', 'list', 'Citez les points clés listés dans la Diapositive 13 pour : La commune: (4 points).', 'L’officier de l’État civil contrôle les données démographiques. • Exige le modèle standard du cmd. • Reporte le numéro de l’acte de décès dans les cases indiqués dans la partie supérieure et au verso du cmd. • Établit mensuellement un bordereau d’envoi des parties inférieures des cmds en précisant la période couverte, le nombre des cmds récupérés et les numéro du premier et du dernier acte de décès.', 'Source : modele de cmd et circuit.pptx · Diapositive 13 (La commune:)', 'Diapositive 13', 13, 'La commune:', 'modele de cmd et circuit.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_0EDCCDA7_L3_2', 'PPT_0EDCCDA7', 'PPT_0EDCCDA7_L3', 'list', 'Citez les points clés listés dans la Diapositive 14 pour : La DSP: (4 points).', 'Assure la disponibilité des formulaires des cmds et met à la disposition des établissements publics, privés des quantités suffisantes. • Veille à ce que les SEMEP récupèrent les cmds auprès des services des communes chaque mois. • Le médecin coordinateur vérifie la complétude et la qualité des cmds avec la possibilité de faire un relevé mensuel des déclarations et les transmet à l’INSP. • Organise des ateliers de formation des médecins praticiens dans le secteur public et privé+++', 'Source : modele de cmd et circuit.pptx · Diapositive 14 (La DSP:)', 'Diapositive 14', 14, 'La DSP:', 'modele de cmd et circuit.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_0EDCCDA7_L3_3', 'PPT_0EDCCDA7', 'PPT_0EDCCDA7_L3', 'list', 'Citez les points clés listés dans la Diapositive 15 pour : L’INSP (4 points).', 'Réception, trie et contrôle des cmds(Rôle de la dsp!) • Assure l’exploitation, le traitement et l’analyse des causes médicales de décès. • La formation et la mise à niveau régulière des capacités des médecins praticiens publics et privés. • La conservation des archives des cmds.', 'Source : modele de cmd et circuit.pptx · Diapositive 15 (L’INSP)', 'Diapositive 15', 15, 'L’INSP', 'modele de cmd et circuit.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_0EDCCDA7_L4_1', 'PPT_0EDCCDA7', 'PPT_0EDCCDA7_L4', 'list', 'Citez les points clés listés dans la Diapositive 16 pour : 4)Problème rencontrés dans la pratique: (10 points).', 'CMD transmis irrégulièrement • Ecriture illisible • Abréviations personnelles • sexe et âge non mentionnés • ACR+++ causes externes non mentionnées • CMD vide.', 'Source : modele de cmd et circuit.pptx · Diapositive 16 (4)Problème rencontrés dans la pratique:)', 'Diapositive 16', 16, '4)Problème rencontrés dans la pratique:', 'modele de cmd et circuit.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_0EDCCDA7_L4_2', 'PPT_0EDCCDA7', 'PPT_0EDCCDA7_L4', 'list', 'Citez les points clés listés dans la Diapositive 18 pour : Rôle essentiel des médecins des bureaux des entrées dans l''assurance de la qualité des certificats médicaux de décès (4 points).', 'Les cmds soient remplis de manière complète et appropriée, sans omission d''informations cruciales. • La distinction entre la cause initiale du décès et les causes sous-jacentes soit clairement établie.(enchaînement respecté ) • Les diagnostics mentionnés soient précis. • Des conseils sur les bonnes pratiques soient donnés pour compléter correctement un CMD.', 'Source : modele de cmd et circuit.pptx · Diapositive 18 (Rôle essentiel des médecins des bureaux des entrées dans l''assurance de la qualité des certificats médicaux de décès)', 'Diapositive 18', 18, 'Rôle essentiel des médecins des bureaux des entrées dans l''assurance de la qualité des certificats médicaux de décès', 'modele de cmd et circuit.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_467EA182_L1_1', 'PPT_467EA182', 'PPT_467EA182_L1', 'definition', 'Selon la Diapositive 3 (« I. CONDITION D''APPLICATION DU DECRET »), comment définir ou énoncer : I. CONDITION D''APPLICATION DU DECRET (Diapo 3) ?', 'Le décret constitue un texte juridique fondamental qui établit l''ensemble des règles et procédures régissant la constatation médicale d''un décès et les modalités précises de délivrance du certificat correspondant.', 'Source : Republique-Algerienne-Democratique-et-populaire.pptx · Diapositive 3 (I. CONDITION D''APPLICATION DU DECRET)', 'Diapositive 3', 3, 'I. CONDITION D''APPLICATION DU DECRET', 'Republique-Algerienne-Democratique-et-populaire.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_467EA182_L1_2', 'PPT_467EA182', 'PPT_467EA182_L1', 'definition', 'Selon la Diapositive 3 (« I. CONDITION D''APPLICATION DU DECRET »), comment définir ou énoncer : I. CONDITION D''APPLICATION DU DECRET (Diapo 3) ?', 'Ce certificat est désormais standardisé conformément au décret exécutif n° 22-178 du 28 avril 2022 qui définit précisément le modèle officiel du certificat médical de décès.', 'Source : Republique-Algerienne-Democratique-et-populaire.pptx · Diapositive 3 (I. CONDITION D''APPLICATION DU DECRET)', 'Diapositive 3', 3, 'I. CONDITION D''APPLICATION DU DECRET', 'Republique-Algerienne-Democratique-et-populaire.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_467EA182_L1_3', 'PPT_467EA182', 'PPT_467EA182_L1', 'definition', 'Selon la Diapositive 4 (« Professionnels habilités »), comment définir ou énoncer : Professionnels habilités (Diapo 4) ?', 'En Algérie, ce décret définit les conditions dans lesquelles un médecin ou un professionnel de santé est habilité à constater le décès d''une personne et à attester un certificat de décès', 'Source : Republique-Algerienne-Democratique-et-populaire.pptx · Diapositive 4 (Professionnels habilités)', 'Diapositive 4', 4, 'Professionnels habilités', 'Republique-Algerienne-Democratique-et-populaire.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_467EA182_L1_4', 'PPT_467EA182', 'PPT_467EA182_L1', 'definition', 'Selon la Diapositive 4 (« Professionnels habilités »), comment définir ou énoncer : Professionnels habilités (Diapo 4) ?', 'Le décret précise également les responsabilités des différents acteurs impliqués, notamment les professionnels de santé et les services de l''état civil, et peut inclure des dispositions relatives à la transmission électronique de ces données dans le cadre de la modernisation administrative.', 'Source : Republique-Algerienne-Democratique-et-populaire.pptx · Diapositive 4 (Professionnels habilités)', 'Diapositive 4', 4, 'Professionnels habilités', 'Republique-Algerienne-Democratique-et-populaire.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_467EA182_L2_1', 'PPT_467EA182', 'PPT_467EA182_L2', 'definition', 'Selon la Diapositive 5 (« II.LES OBJECTIFS DE DECRET »), comment définir ou énoncer : II.LES OBJECTIFS DE DECRET (Diapo 5) ?', 'Le décret relatif au certificat de décès en Algérie poursuit plusieurs objectifs essentiels pour la gestion des décès:', 'Source : Republique-Algerienne-Democratique-et-populaire.pptx · Diapositive 5 (II.LES OBJECTIFS DE DECRET)', 'Diapositive 5', 5, 'II.LES OBJECTIFS DE DECRET', 'Republique-Algerienne-Democratique-et-populaire.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_467EA182_L2_2', 'PPT_467EA182', 'PPT_467EA182_L2', 'formula', 'D''après la Diapositive 6 (« II.LES OBJECTIFS DE DECRET »), quelle formule ou valeur précise faut-il retenir sur : II.LES OBJECTIFS DE DECRET (Diapo 6) ?', 'La déclaration doit être faite dans un délai de 24 heures à compter du décès, sauf pour les habitants des wilayas du sud, où le délai est de 20 jours.', 'Source : Republique-Algerienne-Democratique-et-populaire.pptx · Diapositive 6 (II.LES OBJECTIFS DE DECRET)', 'Diapositive 6', 6, 'II.LES OBJECTIFS DE DECRET', 'Republique-Algerienne-Democratique-et-populaire.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_467EA182_L2_3', 'PPT_467EA182', 'PPT_467EA182_L2', 'definition', 'Selon la Diapositive 7 (« III.LES ARTICLES »), comment définir ou énoncer : III.LES ARTICLES (Diapo 7) ?', 'Dans ce décret nous avons 11 articles', 'Source : Republique-Algerienne-Democratique-et-populaire.pptx · Diapositive 7 (III.LES ARTICLES)', 'Diapositive 7', 7, 'III.LES ARTICLES', 'Republique-Algerienne-Democratique-et-populaire.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_467EA182_L2_4', 'PPT_467EA182', 'PPT_467EA182_L2', 'list', 'Citez les points clés listés dans la Diapositive 8 pour : ARTICLE 2 : (4 points).', 'Médecins du secteur public: De fonctionnaire en état de service. • Médecins contractuels: De contractuel. • Médecins des services spécialisés: D''employé en état de service de la santé militaire ou des services de la sûreté nationale. • Médecins du secteur privé: Des médecins à titre libérale.', 'Source : Republique-Algerienne-Democratique-et-populaire.pptx · Diapositive 8 (ARTICLE 2 :)', 'Diapositive 8', 8, 'ARTICLE 2 :', 'Republique-Algerienne-Democratique-et-populaire.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_467EA182_L3_1', 'PPT_467EA182', 'PPT_467EA182_L3', 'list', 'Citez les points clés listés dans la Diapositive 10 pour : ARTICLE 5: (3 points).', 'Le CMD comporte: • une partie supérieure nominative réservée à l''officier de l''état civil. • une partie inferieure anonyme, réservée à l''usage des autorités sanitaires, oùsontindiquéesclairement', 'Source : Republique-Algerienne-Democratique-et-populaire.pptx · Diapositive 10 (ARTICLE 5:)', 'Diapositive 10', 10, 'ARTICLE 5:', 'Republique-Algerienne-Democratique-et-populaire.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_467EA182_L3_2', 'PPT_467EA182', 'PPT_467EA182_L3', 'list', 'Citez les points clés listés dans la Diapositive 11 pour : ARTICLE 6: (3 points).', 'la partie inferieure de cmd (partie I et II) doit mentionner la cause directe du décès et tout les évènement morbides ;l'' ayant précède. • Elle doit être close par le médecin immédiatement après sa rédaction pour garantir la confidentialité des informations transcrites. • Elle est transmise à la direction de wilaya chargée de la sante par les services de l''état civile de la commune.', 'Source : Republique-Algerienne-Democratique-et-populaire.pptx · Diapositive 11 (ARTICLE 6:)', 'Diapositive 11', 11, 'ARTICLE 6:', 'Republique-Algerienne-Democratique-et-populaire.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_467EA182_L4_1', 'PPT_467EA182', 'PPT_467EA182_L4', 'definition', 'Selon la Diapositive 14 (« ARTICLE 10: »), comment définir ou énoncer : ARTICLE 10: (Diapo 14) ?', 'Les dispositions du décret exécutif n16-80 du 24 février 2016 fixant le modelé du cmd, sont abrogées.', 'Source : Republique-Algerienne-Democratique-et-populaire.pptx · Diapositive 14 (ARTICLE 10:)', 'Diapositive 14', 14, 'ARTICLE 10:', 'Republique-Algerienne-Democratique-et-populaire.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_467EA182_L4_2', 'PPT_467EA182', 'PPT_467EA182_L4', 'definition', 'Selon la Diapositive 14 (« ARTICLE 10: »), comment définir ou énoncer : ARTICLE 10: (Diapo 14) ?', 'Le présent décret a été publié au journal officiel de la république Algérienne démocratique et populaire.', 'Source : Republique-Algerienne-Democratique-et-populaire.pptx · Diapositive 14 (ARTICLE 10:)', 'Diapositive 14', 14, 'ARTICLE 10:', 'Republique-Algerienne-Democratique-et-populaire.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_467EA182_L4_3', 'PPT_467EA182', 'PPT_467EA182_L4', 'list', 'Citez les points clés listés dans la Diapositive 14 pour : ARTICLE 10: (3 points).', 'Les dispositions du décret exécutif n16-80 du 24 février 2016 fixant le modelé du cmd, sont abrogées. • Le présent décret a été publié au journal officiel de la république Algérienne démocratique et populaire. • Fait a Alger, le 28 avril 2022.', 'Source : Republique-Algerienne-Democratique-et-populaire.pptx · Diapositive 14 (ARTICLE 10:)', 'Diapositive 14', 14, 'ARTICLE 10:', 'Republique-Algerienne-Democratique-et-populaire.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_467EA182_L4_4', 'PPT_467EA182', 'PPT_467EA182_L4', 'definition', 'Selon la Diapositive 15 (« VI.CONCLUSION »), comment définir ou énoncer : VI.CONCLUSION (Diapo 15) ?', 'Le décret relatif au certificat de décès en Algérie est un pilier essentiel dans la gestion administrative des décès.', 'Source : Republique-Algerienne-Democratique-et-populaire.pptx · Diapositive 15 (VI.CONCLUSION)', 'Diapositive 15', 15, 'VI.CONCLUSION', 'Republique-Algerienne-Democratique-et-populaire.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_A597601F_L1_1', 'PPT_A597601F', 'PPT_A597601F_L1', 'short_answer', 'Que précise la Diapositive 3 (« Enoncé ») à propos de : Enoncé (Diapo 3) ?', 'Aucun prélèvement pour un examen bactériologique n’a été réalisé pour les différents cas. Le tableau I contient l’information de base à propos de ces cinq cas.', 'Source : TD statistique descriptive.pptx · Diapositive 3 (Enoncé)', 'Diapositive 3', 3, 'Enoncé', 'TD statistique descriptive.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_A597601F_L1_2', 'PPT_A597601F', 'PPT_A597601F_L1', 'short_answer', 'Que précise la Diapositive 5 (« Tableau I: Information de base à propos des cinq cas d’endophtalmie ») à propos de : Tableau I: Information de base à propos des cinq cas d’endophtalmie (Diapo 5) ?', 'Le titre du tableau I vous semble-t-il complet? Si non, complétez-le.', 'Source : TD statistique descriptive.pptx · Diapositive 5 (Tableau I: Information de base à propos des cinq cas d’endophtalmie)', 'Diapositive 5', 5, 'Tableau I: Information de base à propos des cinq cas d’endophtalmie', 'TD statistique descriptive.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_A597601F_L2_1', 'PPT_A597601F', 'PPT_A597601F_L2', 'formula', 'D''après la Diapositive 6 (« 2. Déterminer le taux d’attaque spécifique d’endophtalmie en fonction de la pose d’un implant p… »), quelle formule ou valeur précise faut-il retenir sur : 2. Déterminer le taux d’attaque spécifique d’endophtalmie en fonction de la pose d’un implant p… (Diapo 6) ?', '2. Déterminer le taux d’attaque spécifique d’endophtalmie en fonction de la pose d’un implant pour les mois de janvier et février 2011 sachant que 10 cures de cataracte sans implant et 92 cataractes avec implant ont été réalisées pendant cette période.', 'Source : TD statistique descriptive.pptx · Diapositive 6 (2. Déterminer le taux d’attaque spécifique d’endophtalmie en fonction de la pose d’un implant p…)', 'Diapositive 6', 6, '2. Déterminer le taux d’attaque spécifique d’endophtalmie en fonction de la pose d’un implant p…', 'TD statistique descriptive.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_A597601F_L2_2', 'PPT_A597601F', 'PPT_A597601F_L2', 'difference', 'Que précise la Diapositive 12 (« Calculer la médiane, le mode, et la moyenne de la durée d’incubation? Commenter. ») à propos de : Calculer la médiane, le mode, et la moyenne de la durée d’incubation? Commenter. (Diapo 12) ?', 'Calculer l’écart-type de la durée d’incubation ?', 'Source : TD statistique descriptive.pptx · Diapositive 12 (Calculer la médiane, le mode, et la moyenne de la durée d’incubation? Commenter.)', 'Diapositive 12', 12, 'Calculer la médiane, le mode, et la moyenne de la durée d’incubation? Commenter.', 'TD statistique descriptive.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
