INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L2_1', 'PPT_B369321C', 'PPT_B369321C_L2', 'definition', 'Selon la Diapositive 5 (« 1. Introduction »), comment définir ou énoncer : 1. Introduction (Diapo 5) ?', 'Le test statistique est un outil qui aide à déterminer la différence entre les distributions, par comparaison ou par liaison,', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 5 (1. Introduction)', 'Diapositive 5', 5, '1. Introduction', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L2_2', 'PPT_B369321C', 'PPT_B369321C_L2', 'difference', 'Que précise la Diapositive 5 (« 1. Introduction ») à propos de : 1. Introduction (Diapo 5) ?', 'Donc le but du test statistique est de déterminer si la différence observée est due au hasard (aux fluctuations d’échantillonnage autour de la vraie valeur du paramètre de la population dont ils sont issus) ou si au contraire la différence observé est bien réelle.', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 5 (1. Introduction)', 'Diapositive 5', 5, '1. Introduction', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L2_3', 'PPT_B369321C', 'PPT_B369321C_L2', 'list', 'Citez les points clés listés dans la Diapositive 5 pour : 1. Introduction (3 points).', 'Le test statistique est un outil qui aide à déterminer la différence entre les distributions, par comparaison ou par liaison, • Les paramètres à vérifier peuvent être en moyenne, en pourcentage… • Donc le but du test statistique est de déterminer si la différence observée est due au hasard (aux fluctuations d’échantillonnage autour de la vraie valeur du paramètre de la population dont ils sont issus) ou si au contraire la différence observé est bien réelle.', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 5 (1. Introduction)', 'Diapositive 5', 5, '1. Introduction', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L2_4', 'PPT_B369321C', 'PPT_B369321C_L2', 'formula', 'D''après la Diapositive 7 (« . Formuler l’ hypothèse nulle (notée H0) »), quelle formule ou valeur précise faut-il retenir sur : L’hypothèse nulle (H0) ?', 'est une hypothèse d’absence de différence', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 7 (. Formuler l’ hypothèse nulle (notée H0))', 'Diapositive 7', 7, '. Formuler l’ hypothèse nulle (notée H0)', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L3_1', 'PPT_B369321C', 'PPT_B369321C_L3', 'formula', 'D''après la Diapositive 9 (« 2. Test d’hypothèse »), quelle formule ou valeur précise faut-il retenir sur : 2. Test d’hypothèse (Diapo 9) ?', 'au dessous duquel, on rejette l’hypothèse nulle H0 et on accepte l’hypothèse alternative H1', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 9 (2. Test d’hypothèse)', 'Diapositive 9', 9, '2. Test d’hypothèse', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L3_2', 'PPT_B369321C', 'PPT_B369321C_L3', 'formula', 'D''après la Diapositive 9 (« 2. Test d’hypothèse »), quelle formule ou valeur précise faut-il retenir sur : 2. Test d’hypothèse (Diapo 9) ?', 'risque de rejeter à tort H0 (risque de conclure à tort à une différence alors qu’elle n’existe pas dans la réalité).', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 9 (2. Test d’hypothèse)', 'Diapositive 9', 9, '2. Test d’hypothèse', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L3_3', 'PPT_B369321C', 'PPT_B369321C_L3', 'formula', 'D''après la Diapositive 9 (« 2. Test d’hypothèse »), quelle formule ou valeur précise faut-il retenir sur : 2. Test d’hypothèse (Diapo 9) ?', 'est fixé à 0.05 (5%) en santé et biologie, noté α = 0.05', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 9 (2. Test d’hypothèse)', 'Diapositive 9', 9, '2. Test d’hypothèse', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L3_4', 'PPT_B369321C', 'PPT_B369321C_L3', 'list', 'Citez les points clés listés dans la Diapositive 9 pour : 2. Test d’hypothèse (4 points).', 'au dessous duquel, on rejette l’hypothèse nulle H0 et on accepte l’hypothèse alternative H1 • risque de rejeter à tort H0 (risque de conclure à tort à une différence alors qu’elle n’existe pas dans la réalité). • est fixé a priori (avant tout calcul) • est fixé à 0.05 (5%) en santé et biologie, noté α = 0.05', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 9 (2. Test d’hypothèse)', 'Diapositive 9', 9, '2. Test d’hypothèse', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L4_1', 'PPT_B369321C', 'PPT_B369321C_L4', 'list', 'Citez les points clés listés dans la Diapositive 13 pour : 3. Test statistique de comparaison de % (4 points).', 'Test de X2 de conformité (ou d’ajustement) • Il sert à comparer une distribution observée sur un échantillon à une distribution connue dans une population ou à une distribution théorique, • Le test de X2 d’homogénéité • Il sert à comparer deux ou plusieurs distributions observées sur des échantillons.', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 13 (3. Test statistique de comparaison de %)', 'Diapositive 13', 13, '3. Test statistique de comparaison de %', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L4_2', 'PPT_B369321C', 'PPT_B369321C_L4', 'formula', 'D''après la Diapositive 14 (« Test X² de comparaison de deux % »), quelle formule ou valeur précise faut-il retenir sur : Test X² de comparaison de deux % (Diapo 14) ?', 'Sous H0, l’échantillon observé provient de la population dont on connait la distribution théorique. La distribution observée devrait lui être identique. Si on observe une différence, H0 est rejetée et on accepte H1', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 14 (Test X² de comparaison de deux %)', 'Diapositive 14', 14, 'Test X² de comparaison de deux %', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L4_3', 'PPT_B369321C', 'PPT_B369321C_L4', 'formula', 'D''après la Diapositive 14 (« Test X² de comparaison de deux % »), quelle formule ou valeur précise faut-il retenir sur : Test X² de comparaison de deux % (Diapo 14) ?', 'H1: la distribution observée est différente de la distribution théorique; l’échantillon étudié n’appartient pas à cette population .', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 14 (Test X² de comparaison de deux %)', 'Diapositive 14', 14, 'Test X² de comparaison de deux %', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L4_4', 'PPT_B369321C', 'PPT_B369321C_L4', 'formula', 'D''après la Diapositive 15 (« Test X² de comparaison de deux % »), quelle formule ou valeur précise faut-il retenir sur : Test X² de comparaison de deux % (Diapo 15) ?', 'Sous H0, les échantillons étudiés proviennent de la même population. Leurs distributions devraient être identiques entre elles et identiques à la distribution observée sur le total des échantillons .', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 15 (Test X² de comparaison de deux %)', 'Diapositive 15', 15, 'Test X² de comparaison de deux %', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L5_1', 'PPT_B369321C', 'PPT_B369321C_L5', 'formula', 'D''après la Diapositive 17 (« 3. Test statistique de comparaison de % »), quelle formule ou valeur précise faut-il retenir sur : 3. Test statistique de comparaison de % (Diapo 17) ?', 'Tableau de contingence 2X2 (à 04 cases)', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 17 (3. Test statistique de comparaison de %)', 'Diapositive 17', 17, '3. Test statistique de comparaison de %', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L5_2', 'PPT_B369321C', 'PPT_B369321C_L5', 'definition', 'Selon la Diapositive 18 (« 3. Test statistique de comparaison de % »), comment définir ou énoncer : 3. Test statistique de comparaison de % (Diapo 18) ?', 'Le principe du test consiste d’abord à calculer pour chaque case du tableau l’effectif théorique (C), qui serait observé si les distributions sont identiques .', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 18 (3. Test statistique de comparaison de %)', 'Diapositive 18', 18, '3. Test statistique de comparaison de %', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L5_3', 'PPT_B369321C', 'PPT_B369321C_L5', 'formula', 'D''après la Diapositive 18 (« 3. Test statistique de comparaison de % »), quelle formule ou valeur précise faut-il retenir sur : 3. Test statistique de comparaison de % (Diapo 18) ?', 'Dans ce cas, les effectifs de chaque distribution devraient être réparties en proportion égale. Par exemple: l’effectif C1 .1 =n1 x t1/N', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 18 (3. Test statistique de comparaison de %)', 'Diapositive 18', 18, '3. Test statistique de comparaison de %', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L5_4', 'PPT_B369321C', 'PPT_B369321C_L5', 'list', 'Citez les points clés listés dans la Diapositive 18 pour : 3. Test statistique de comparaison de % (3 points).', 'Le principe du test consiste d’abord à calculer pour chaque case du tableau l’effectif théorique (C), qui serait observé si les distributions sont identiques . • Dans ce cas, les effectifs de chaque distribution devraient être réparties en proportion égale. Par exemple: l’effectif C1 .1 =n1 x t1/N • Dans chacune des cases, l’effectif théorique est égale au produit du total de la ligne par le total de la colonne et divisé par le total général.', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 18 (3. Test statistique de comparaison de %)', 'Diapositive 18', 18, '3. Test statistique de comparaison de %', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L6_1', 'PPT_B369321C', 'PPT_B369321C_L6', 'formula', 'D''après la Diapositive 21 (« 3. Test statistique de comparaison de % »), quelle formule ou valeur précise faut-il retenir sur : 3. Test statistique de comparaison de % (Diapo 21) ?', 'X2 = ∑ ( oij – cij) 2 / cij', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 21 (3. Test statistique de comparaison de %)', 'Diapositive 21', 21, '3. Test statistique de comparaison de %', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L6_2', 'PPT_B369321C', 'PPT_B369321C_L6', 'formula', 'D''après la Diapositive 22 (« 3. Test statistique de comparaison de % »), quelle formule ou valeur précise faut-il retenir sur : 3. Test statistique de comparaison de % (Diapo 22) ?', 'X2 = (O1.1 -C1.1)2 / C1.1 + (O2.1 - C2.1)2 / C2.1 + (O1.2 - C1.2)2 / C1.2 + (O2.2 - C2.2)2 / C2.2', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 22 (3. Test statistique de comparaison de %)', 'Diapositive 22', 22, '3. Test statistique de comparaison de %', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L6_3', 'PPT_B369321C', 'PPT_B369321C_L6', 'formula', 'D''après la Diapositive 23 (« 3. Test statistique de comparaison de % »), quelle formule ou valeur précise faut-il retenir sur : 3. Test statistique de comparaison de % (Diapo 23) ?', 'Dans un tableau de contingence, on appelle degré de liberté (ddl): le nombre de cases qu’on peut remplir librement lorsque les totaux des lignes et des colonnes sont fixés', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 23 (3. Test statistique de comparaison de %)', 'Diapositive 23', 23, '3. Test statistique de comparaison de %', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L6_4', 'PPT_B369321C', 'PPT_B369321C_L6', 'formula', 'D''après la Diapositive 23 (« 3. Test statistique de comparaison de % »), quelle formule ou valeur précise faut-il retenir sur : 3. Test statistique de comparaison de % (Diapo 23) ?', 'ddl = (L-1)(C-1)', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 23 (3. Test statistique de comparaison de %)', 'Diapositive 23', 23, '3. Test statistique de comparaison de %', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L7_1', 'PPT_B369321C', 'PPT_B369321C_L7', 'formula', 'D''après la Diapositive 25 (« 3. Test statistique de comparaison de % »), quelle formule ou valeur précise faut-il retenir sur : 3. Test statistique de comparaison de % (Diapo 25) ?', 'On commence donc par repérer dans la table X2 à la ligne correspondante au nombre de ddl, la valeur X25%.', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 25 (3. Test statistique de comparaison de %)', 'Diapositive 25', 25, '3. Test statistique de comparaison de %', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L7_2', 'PPT_B369321C', 'PPT_B369321C_L7', 'formula', 'D''après la Diapositive 25 (« 3. Test statistique de comparaison de % »), quelle formule ou valeur précise faut-il retenir sur : 3. Test statistique de comparaison de % (Diapo 25) ?', 'Si le calcul du test montre une valeur observée X20 supérieur à X25%,on rejette H0.', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 25 (3. Test statistique de comparaison de %)', 'Diapositive 25', 25, '3. Test statistique de comparaison de %', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L7_3', 'PPT_B369321C', 'PPT_B369321C_L7', 'formula', 'D''après la Diapositive 25 (« 3. Test statistique de comparaison de % »), quelle formule ou valeur précise faut-il retenir sur : 3. Test statistique de comparaison de % (Diapo 25) ?', 'Le risque αcorrespondant à cette valeur donne le degré de signification p.', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 25 (3. Test statistique de comparaison de %)', 'Diapositive 25', 25, '3. Test statistique de comparaison de %', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, course_id, lesson_id, type, question, answer, hint, page_ref, slide_num, slide_title, source_file, source_type, needs_review) VALUES ('FC_PPT_B369321C_L7_4', 'PPT_B369321C', 'PPT_B369321C_L7', 'formula', 'D''après la Diapositive 25 (« 3. Test statistique de comparaison de % »), quelle formule ou valeur précise faut-il retenir sur : 3. Test statistique de comparaison de % (Diapo 25) ?', 'Il existe autant de distributions de X2 que de degrés de liberté (ddl).', 'Source : test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx · Diapositive 25 (3. Test statistique de comparaison de %)', 'Diapositive 25', 25, '3. Test statistique de comparaison de %', 'test d''hypothèse  comparaison de 2 pourcentage.ppsx.pptx', 'ai_generated_practice', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C1_1', 'C1', 'L1.1', 'Approche prospective de la santé', 'bm_original', 'Ch. 2 Q1', '2024', '', NULL, '', '', FALSE, TRUE, FALSE, 'L’approche prospective de la santé, signifie que :', '', $medjson$[{"key":"A","text":"Approche de la santé en dehors de tout critère socioéconomique et culturel"},{"key":"B","text":"Approche de la santé tenant compte des moyens de contrôle des facteurs endogènes et exogènes"},{"key":"C","text":"Approche de la santé tenant compte des dimensions sociale, physique et mentale"},{"key":"D","text":"Approche de la santé tenant compte uniquement des dimensions de l’environnement"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Selon le Pr Boumaraf (slide 9), l’approche prospective aborde la santé comme un processus dynamique qui tient compte des moyens de contrôle disponibles face aux facteurs endogènes et exogènes.', $medjson${"A":"Définit l’approche conventionnelle (absence de maladie, hors critères socio-économiques et culturels).","C":"Définit l’approche globaliste (définition OMS 1946 : physique, mental et social).","D":"Trop restrictif (« uniquement l’environnement ») : elle intègre facteurs endogènes ET exogènes."}$medjson$::jsonb, $medjson${"bmKey":"C","note":"Le corrigé BM imprime C (approche globaliste OMS) au lieu de B (approche prospective — slide 9)."}$medjson$::jsonb, FALSE, 'Intro Santé Publique — Pr Boumaraf, Ch. 2, slides 5–9') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C1_2', 'C1', 'L1.1', 'Approche conventionnelle de la santé', 'bm_original', 'Ch. 14 Q2', '2025', '', NULL, '', '', TRUE, TRUE, FALSE, 'L’approche conventionnelle de la santé est caractérisée par les éléments suivants : (Cocher la ou les réponses justes)', '', $medjson$[{"key":"A","text":"Elle tient compte de l’environnement économique et culturel"},{"key":"B","text":"Elle tient compte de l’environnement social"},{"key":"C","text":"Se définit comme : la santé c’est l’absence de la maladie"},{"key":"D","text":"Se définit comme un état complet de bien-être physique, social et psychique"}]$medjson$::jsonb, $medjson$["C"]$medjson$::jsonb, 'L’approche conventionnelle (biomédicale) réduit la santé à la simple absence de maladie ou de dysfonctionnement biologique, en dehors de tout critère socio-économique et culturel.', $medjson${"A":"Faux : l’approche conventionnelle ignore l’environnement économique et culturel.","B":"Faux : la dimension sociale appartient à l’approche globaliste (OMS).","D":"Faux : c’est la définition OMS (1946), donc l’approche globaliste."}$medjson$::jsonb, $medjson${"bmKey":"ABC","note":"Le corrigé BM imprime ABC, alors que le cours précise que l’approche conventionnelle exclut tout critère socio-économique et culturel (seul C est juste)."}$medjson$::jsonb, FALSE, 'Intro Santé Publique — Pr Boumaraf, Ch. 2, slides 5–7') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C1_3', 'C1', 'L1.1', 'Approche prospective (formulation 2025)', 'bm_original', 'Ch. 14 Q3', '2025', '', NULL, '', '', TRUE, FALSE, FALSE, 'L’approche prospective de la santé, veut dire : (Cocher les réponses justes)', '', $medjson$[{"key":"A","text":"Est perçue comme une capacité d’adaptation de l’homme à son environnement"},{"key":"B","text":"Seuls les facteurs socio-économiques influent sur la santé de l’individu"},{"key":"C","text":"La santé est le résultat de réactions de l’individu à son environnement et sa capacité à interagir"},{"key":"D","text":"Aucune des réponses n’est juste"}]$medjson$::jsonb, $medjson$["A","C"]$medjson$::jsonb, 'L’approche prospective conçoit la santé comme un processus adaptatif : capacité d’adaptation de l’homme (A) et résultat de ses réactions et interactions avec son environnement (C).', $medjson${"B":"Faux : les facteurs biologiques/endogènes et comportementaux interviennent également.","D":"Faux car A et C sont exactes."}$medjson$::jsonb, NULL, FALSE, 'Intro Santé Publique — Pr Boumaraf, Ch. 2, slide 9') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C1_4', 'C1', 'L1.1', 'Déterminants extrinsèques vs intrinsèques', 'bm_original', 'Ch. 19 Q11', '2022', '', NULL, '', '', TRUE, FALSE, FALSE, 'Les déterminants extrinsèques d’une maladie font intervenir les éléments suivants : (Cochez les réponses justes)', '', $medjson$[{"key":"A","text":"Infrastructures sanitaires"},{"key":"B","text":"Environnement microbiologique"},{"key":"C","text":"Culture et comportements"},{"key":"D","text":"Patrimoine génétique"}]$medjson$::jsonb, $medjson$["A","B","C"]$medjson$::jsonb, 'Les déterminants extrinsèques sont extérieurs à la biologie propre de l’individu : infrastructures sanitaires (A), environnement microbiologique (B), culture et comportements (C).', $medjson${"D":"Le patrimoine génétique est un déterminant INTRINSÈQUE (endogène)."}$medjson$::jsonb, NULL, TRUE, 'Intro Santé Publique — Pr Boumaraf, Ch. 2, slide 10') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C1_5', 'C1', 'L1.2', 'Prévention secondaire vs primaire/tertiaire', 'bm_original', 'Ch. 2 Q2', '2024', '', NULL, '', '', FALSE, FALSE, FALSE, 'La prévention secondaire, comprend :', '', $medjson$[{"key":"A","text":"Tous les actes destinés à diminuer les nouveaux cas d’une maladie"},{"key":"B","text":"L’ioduration du sel de cuisine contre le crétinisme et le goitre en est un exemple"},{"key":"C","text":"Le dépistage du cancer du sein en est un exemple"},{"key":"D","text":"Tous les actes destinés à réduire les récidives d’une maladie"}]$medjson$::jsonb, $medjson$["C"]$medjson$::jsonb, 'La prévention secondaire repose sur le dépistage et le traitement précoce (ex. dépistage du cancer du sein) afin de réduire la durée d’évolution et la prévalence.', $medjson${"A":"Diminuer les nouveaux cas (= incidence) correspond à la prévention primaire.","B":"L’ioduration du sel empêche l’apparition du goitre → prévention primaire.","D":"Réduire les récidives et complications relève de la prévention tertiaire."}$medjson$::jsonb, NULL, FALSE, 'Intro Santé Publique — Pr Boumaraf, Ch. 7.5.1, slides 46–49') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C1_6', 'C1', 'L1.2', 'Prévention quaternaire (2022)', 'bm_original', 'Ch. 32 Q3', '2022', '', NULL, '', '', FALSE, FALSE, FALSE, 'La prévention quaternaire : (choisir la bonne réponse)', '', $medjson$[{"key":"A","text":"Comprend des activités visant à diminuer l’incidence d’une maladie"},{"key":"B","text":"Fait appel à des activités visant à déceler la maladie précocement"},{"key":"C","text":"Axée sur la prévention des complications"},{"key":"D","text":"Est une protection du patient et du soignant d’une surmédicalisation"}]$medjson$::jsonb, $medjson$["D"]$medjson$::jsonb, 'La prévention quaternaire protège le patient (et le soignant) contre la surmédicalisation, les interventions inutiles et le risque iatrogène/IAS.', $medjson${"A":"Prévention primaire (incidence).","B":"Prévention secondaire (dépistage précoce).","C":"Prévention tertiaire (complications)."}$medjson$::jsonb, NULL, TRUE, 'Intro Santé Publique — Pr Boumaraf, slide 50') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C1_7', 'C1', 'L1.2', 'Prévention secondaire (durée & prévalence)', 'bm_original', 'Ch. 32 Q12', 'ND', '', NULL, '', '', TRUE, FALSE, FALSE, 'La prévention secondaire : (cocher les réponses justes)', '', $medjson$[{"key":"A","text":"Est l’ensemble des actes destinés à réduire la durée de vie de la maladie"},{"key":"B","text":"A pour objectif de diminuer l’incidence de la maladie"},{"key":"C","text":"Parmi ses activités : la vaccination"},{"key":"D","text":"Vise à identifier un patient et une population à risque de surmédicalisation"},{"key":"E","text":"A pour objectif de diminuer la prévalence de la maladie"}]$medjson$::jsonb, $medjson$["A","E"]$medjson$::jsonb, 'La prévention secondaire dépiste tôt pour traiter tôt, ce qui réduit la durée d’évolution de la maladie (A) et diminue sa prévalence (E).', $medjson${"B":"Diminuer l’incidence = prévention primaire.","C":"La vaccination = prévention primaire.","D":"Surmédicalisation = prévention quaternaire."}$medjson$::jsonb, NULL, FALSE, 'Intro Santé Publique — Pr Boumaraf, slides 47–48') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C1_8', 'C1', 'L1.3', 'Gratuité des soins en Algérie (1974)', 'bm_original', 'Ch. 29 Q14 (= Ch. 41 Q6)', '2023', '', NULL, '', '', FALSE, FALSE, FALSE, 'L’instauration de la gratuité des soins en Algérie était en :', '', $medjson$[{"key":"A","text":"1949"},{"key":"B","text":"1976"},{"key":"C","text":"1974"},{"key":"D","text":"Aucune réponse"}]$medjson$::jsonb, $medjson$["C"]$medjson$::jsonb, 'La gratuité des soins a été instaurée en Algérie en janvier 1974 (phase de transition), accompagnée de la réforme des études médicales et de la création du secteur sanitaire.', $medjson${"A":"1949 est antérieur à l’indépendance.","B":"1976 correspond à la Charte nationale / Constitution, pas à la gratuité des soins.","D":"Faux car 1974 figure en C."}$medjson$::jsonb, NULL, TRUE, 'Intro Santé Publique — Pr Boumaraf, Ch. 5, slide 26') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C1_9', 'C1', 'L1.3', 'Critères de priorité de santé publique', 'bm_original', 'Ch. 38 Q8', '2022', '', NULL, '', '', TRUE, FALSE, FALSE, 'Une maladie devient une priorité en santé publique aux conditions suivantes : (Cochez les réponses justes)', '', $medjson$[{"key":"A","text":"La prévalence est élevée dans la population"},{"key":"B","text":"La maladie est curable ou évitable par la prévention"},{"key":"C","text":"Il n’y a pas encore de traitement efficace"},{"key":"D","text":"Traitement curatif et prévention ont un coût élevé"}]$medjson$::jsonb, $medjson$["A","B"]$medjson$::jsonb, 'Une maladie devient prioritaire si son ampleur/fréquence est élevée (A), sa gravité/impact importants, et qu’elle est vulnérable aux actions de santé publique (curable ou évitable, B).', $medjson${"C":"L’absence de moyen d’action efficace réduit la faisabilité immédiate d’un programme de lutte.","D":"Un coût élevé du traitement/prévention est une contrainte, pas une condition pour prioriser."}$medjson$::jsonb, NULL, TRUE, 'Intro Santé Publique — Pr Boumaraf, Ch. 6, slide 30') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C1_10', 'C1', 'L1.3', 'Historique, SSP & Éducation vs Promotion', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, 'Concernant l’historique et les outils de la santé publique (Pr Boumaraf), cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"John Snow a établi en 1854–1855 le lien entre le choléra et l’eau contaminée (pompe de Broad Street)"},{"key":"B","text":"La hiérarchie des interventions suit l’ordre : Politique de SP ⊃ Plan de SP ⊃ Programme de SP ⊃ Action de SP"},{"key":"C","text":"L’éducation pour la santé est strictement synonyme de la promotion de la santé"},{"key":"D","text":"Ignace Semmelweis a démontré en 1847 le rôle du lavage des mains dans la prévention de la fièvre puerpérale"}]$medjson$::jsonb, $medjson$["A","B","D"]$medjson$::jsonb, 'John Snow (1854–1855, A), Semmelweis (1847, D) et la hiérarchie Politique ⊃ Plan ⊃ Programme ⊃ Action (B) sont des jalons clés du cours du Pr Boumaraf.', $medjson${"C":"L’éducation pour la santé cible le comportement individuel, tandis que la promotion de la santé (Charte d’Ottawa) est plus globale (environnements favorables, politiques publiques, autonomisation)."}$medjson$::jsonb, NULL, FALSE, 'Intro Santé Publique — Pr Boumaraf, slides 15–16, 32, 51–53') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C2_1', 'C2', 'L2.1', 'Pouvoir pathogène vs Virulence vs R0', 'bm_original', 'Ch. 12 Q5', '2024', '', NULL, '', '', FALSE, FALSE, FALSE, 'Le pouvoir pathogène d’un agent infectieux :', '', $medjson$[{"key":"A","text":"Est l’intensité des manifestations morbides chez l’hôte réceptif"},{"key":"B","text":"Est sa capacité de provoquer des manifestations morbides chez l’hôte réceptif"},{"key":"C","text":"Peut être, exclusivement, mesuré par le taux de létalité"},{"key":"D","text":"Le taux de reproduction R0 (contagiosité) du virus SARS-CoV-2 est supérieur à celui du virus de la rougeole"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Le pouvoir pathogène (pathogénicité) est la capacité d’un agent à provoquer des manifestations morbides chez un hôte réceptif.', $medjson${"A":"L’intensité/gravité des manifestations morbides définit la virulence.","C":"Faux (« exclusivement ») : mesuré aussi par taux d’attaque et indice de gravité.","D":"Faux : R0 de la rougeole (~12–18) est très supérieur à celui du SARS-CoV-2."}$medjson$::jsonb, NULL, FALSE, 'Épidémiologie des MT — Dr F. Beichi, § II.1, p. 3–4') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C2_2', 'C2', 'L2.1', 'Définition de la virulence', 'bm_original', 'Ch. 12 Q10 (= Ch. 19 Q10)', '2021', '', NULL, '', '', FALSE, FALSE, FALSE, 'La virulence d’un agent pathogène peut être définie comme étant :', '', $medjson$[{"key":"A","text":"Son aptitude à se propager dans une collectivité donnée"},{"key":"B","text":"Son aptitude à reproduire la maladie"},{"key":"C","text":"Son aptitude à provoquer des troubles morbides"},{"key":"D","text":"Toutes les réponses sont correctes"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Dans le cours et la BM (Ch. 12 Q10), la virulence exprime la capacité de multiplication / aptitude à reproduire la maladie et l’intensité du pouvoir pathogène.', $medjson${"A":"Aptitude à se propager dans une collectivité = contagiosité.","C":"Aptitude à provoquer des troubles morbides = pouvoir pathogène.","D":"Faux car A et C définissent d’autres propriétés."}$medjson$::jsonb, NULL, FALSE, 'Épidémiologie des MT — Dr F. Beichi, § II.1, p. 4') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C2_3', 'C2', 'L2.1', 'Situation des MT en Algérie (2024)', 'bm_original', 'Ch. 12 Q3', '2024', '', NULL, '', '', FALSE, TRUE, FALSE, 'En Algérie :', '', $medjson$[{"key":"A","text":"Les stratégies de prévention adoptées ont permis l’élimination de la poliomyélite"},{"key":"B","text":"Les actions menées sur le terrain ont abouti à l’éradication de la poliomyélite"},{"key":"C","text":"Les stratégies de prévention adoptées ont permis l’élimination de la tuberculose pulmonaire"},{"key":"D","text":"Les maladies à transmission hydrique sont prédominantes"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Le cours du Dr Beichi (p. 3) retient explicitement l’éradication de la poliomyélite en Algérie (nuance terminologique testée face à « élimination »).', $medjson${"A":"Le cours et le corrigé 2024 distinguent précisément « éradication » (B) d’« élimination ».","C":"La tuberculose pulmonaire a diminué d’incidence mais n’est PAS éliminée.","D":"Les MTH ne sont plus prédominantes (elles surviennent de façon sporadique/épidémique)."}$medjson$::jsonb, NULL, FALSE, 'Épidémiologie des MT — Dr F. Beichi, § I.4, p. 2–3') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C2_4', 'C2', 'L2.1', 'Situation des MT en Algérie (2025)', 'bm_original', 'Ch. 13 Q1', '2025', '', NULL, '', '', FALSE, TRUE, FALSE, 'En Algérie :', '', $medjson$[{"key":"A","text":"Les stratégies de prévention mises en place ont conduit à l’élimination de la poliomyélite"},{"key":"B","text":"Les actions de terrain ont permis d’éradiquer le paludisme autochtone"},{"key":"C","text":"Les maladies à transmission hydrique sont désormais rares et sporadiques"},{"key":"D","text":"Les mesures de prévention adoptées ont favorisé l’élimination de la tuberculose pulmonaire"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'En Algérie, le paludisme autochtone a été maîtrisé jusqu’à sa disparition/éradication (certification OMS 2019 — p. 3). (Note : si QCM à choix multiples, C reflète aussi la baisse des MTH vers des formes sporadiques, mais B reste l’item phare en réponse unique).', $medjson${"A":"Comme en 2024 (Ch. 12 Q3), le cours emploie « éradication » pour la poliomyélite.","C":"Les MTH restent responsables d’épisodes épidémiques saisonniers (TIAC, typhoïde), pas totalement rares.","D":"Faux : la tuberculose pulmonaire n’est pas éliminée."}$medjson$::jsonb, NULL, TRUE, 'Épidémiologie des MT — Dr F. Beichi, § I.4, p. 2–3') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C2_5', 'C2', 'L2.2', 'Surveillance des MDO (passive + réglementation)', 'bm_original', 'Ch. 38 Q1', '2022', '', NULL, '', '', TRUE, TRUE, FALSE, 'Dans un système de surveillance des maladies à déclaration obligatoire (M.D.O.) : (Cocher les réponses justes)', '', $medjson$[{"key":"A","text":"L’autorité sanitaire n’est pas censée intervenir dans le processus de collecte de l’information"},{"key":"B","text":"Le professionnel de santé est responsable de la collecte des données"},{"key":"C","text":"Une réglementation émanant de l’autorité sanitaire du pays est nécessaire"},{"key":"D","text":"Passive c.-à-d. initiée par les professionnels sans que les autorités sanitaires n’interviennent"}]$medjson$::jsonb, $medjson$["A","B","C","D"]$medjson$::jsonb, 'La surveillance des MDO est passive (les autorités attendent la remontée des données recueillies par les professionnels de santé, A, B, D) et obligatoire, donc encadrée par une réglementation nationale (C — Décret 22-250).', $medjson${}$medjson$::jsonb, $medjson${"bmKey":"ABCD (vs ABC Ch.12 Q9 / C Ch.38 Q11)","note":"Contradiction interne entre 3 occurrences BM : retenir que les 4 propositions ABCD décrivent la surveillance passive et obligatoire des MDO."}$medjson$::jsonb, FALSE, 'Épidémiologie des MT — Dr F. Beichi, § V.5–VI, p. 7–8') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C2_6', 'C2', 'L2.2', 'Spécificité d’un système de surveillance', 'bm_original', 'Ch. 38 Q4', '2022', '', NULL, '', '', TRUE, FALSE, FALSE, 'La spécificité d’un système de surveillance épidémiologique se définit comme : (Cocher les réponses justes)', '', $medjson$[{"key":"A","text":"La capacité à identifier l’absence de la maladie sous surveillance"},{"key":"B","text":"La capacité à correctement identifier les vrais négatifs"},{"key":"C","text":"La capacité à correctement identifier les cas confirmés"},{"key":"D","text":"Un rapport, au numérateur les vrais négatifs et au dénominateur les vrais négatifs et les faux positifs"}]$medjson$::jsonb, $medjson$["A","B","D"]$medjson$::jsonb, 'La spécificité mesure la capacité du système à exclure les non-malades (A, B) et se calcule par VN / (VN + FP) (D).', $medjson${"C":"Identifier les cas confirmés (vrais positifs) correspond à la SENSIBILITÉ = VP / (VP + FN)."}$medjson$::jsonb, NULL, FALSE, 'BM Ch. 38 (Surveillance épidémiologique) — complément Cours 2 § V') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C2_7', 'C2', 'L2.2', 'Souplesse d’un système de surveillance', 'bm_original', 'Ch. 38 Q3', '2022', '', NULL, '', '', TRUE, FALSE, FALSE, 'La souplesse d’un système de surveillance sous-entend que : (Cocher les réponses justes)', '', $medjson$[{"key":"A","text":"Le système est léger de par sa structure et le nombre d’acteurs"},{"key":"B","text":"Le système est capable de s’adapter à des changements dans la définition du cas de maladie"},{"key":"C","text":"Le système est capable de s’adapter à d’autres sources d’information"},{"key":"D","text":"Le délai nécessaire à la transmission de l’information est suffisant"}]$medjson$::jsonb, $medjson$["B","C"]$medjson$::jsonb, 'La souplesse (flexibilité) est la capacité d’adaptation du système à de nouvelles définitions de cas (B) ou à de nouvelles sources d’information (C).', $medjson${"A":"Structure légère et peu d’acteurs définissent la SIMPLICITÉ (Ch. 38 Q15).","D":"Le délai de transmission renvoie à la RÉACTIVITÉ / rapidité."}$medjson$::jsonb, NULL, FALSE, 'BM Ch. 38 (Surveillance épidémiologique) — complément Cours 2 § V') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C2_8', 'C2', 'L2.2', 'Définition & processus continu de surveillance', 'bm_original', 'Ch. 38 Q5', '2022', '', NULL, '', '', TRUE, FALSE, FALSE, 'La surveillance épidémiologique d’un phénomène de santé, est : (Cocher les réponses justes)', '', $medjson$[{"key":"A","text":"Processus ponctuel dans le temps qui rejoint les enquêtes"},{"key":"B","text":"Conditionnée par la rapidité du traitement de l’information"},{"key":"C","text":"La diffusion des résultats est capitale"},{"key":"D","text":"Permet une aide à la décision de santé"}]$medjson$::jsonb, $medjson$["B","C","D"]$medjson$::jsonb, 'La surveillance est conditionnée par la rapidité de traitement (B) et la diffusion (C, cf. Ch. 38 Q14), et sa finalité est l’aide à la décision / action de contrôle (D, cf. Ch. 38 Q12).', $medjson${"A":"Piège classique : la surveillance est un processus CONTINU (jamais ponctuel !)."}$medjson$::jsonb, NULL, TRUE, 'Épidémiologie des MT — Dr F. Beichi, § V, p. 6–7 & Ch. 38 Q12–Q14') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C2_9', 'C2', 'L2.2', 'Surveillance sentinelle (2024)', 'bm_original', 'Ch. 12 Q4', '2024', '', NULL, '', '', FALSE, FALSE, FALSE, 'La surveillance sentinelle des maladies transmissibles :', '', $medjson$[{"key":"A","text":"Est une surveillance active"},{"key":"B","text":"Est une surveillance passive"},{"key":"C","text":"Est une méthode non utilisée en Algérie"},{"key":"D","text":"La surveillance des cas de COVID-19 en est un exemple"}]$medjson$::jsonb, $medjson$["A"]$medjson$::jsonb, 'Dans l’examen 2024 (Ch. 12 Q4), la surveillance sentinelle est classée comme une forme de surveillance active (déclarations régulières par un réseau ciblé volontaire, ex. GROG grippe dans 6 wilayas en Algérie).', $medjson${"B":"La surveillance passive correspond surtout aux MDO routinières.","C":"Faux : l’Algérie utilise le réseau sentinelle GROG (grippe) et des labos sentinelles PFA/SIDA.","D":"La COVID-19 (SARS-CoV-2) relève d’une MDO Catégorie 2 exhaustive."}$medjson$::jsonb, NULL, FALSE, 'Épidémiologie des MT — Dr F. Beichi, § V.6, p. 7') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C2_10', 'C2', 'L2.3', 'SRAS — MDO Catégorie 2', 'bm_original', 'Ch. 12 Q7 (= Q11)', '2022', '', NULL, '', '', TRUE, FALSE, FALSE, 'Le syndrome respiratoire aigu sévère (S.R.A.S.) est une MDO : (Cocher les réponses justes)', '', $medjson$[{"key":"A","text":"Faisant partie de la catégorie 2 du nouveau listing des MDO"},{"key":"B","text":"Faisant partie de la catégorie 1 du nouveau listing des MDO"},{"key":"C","text":"Fait partie des 42 MDO de l’arrêté de Novembre 1990"},{"key":"D","text":"Est obligatoirement notifiable à l’OMS"}]$medjson$::jsonb, $medjson$["A","D"]$medjson$::jsonb, 'Dans le Décret 22-250 (30 juin 2022), le SRAS (comme Ebola, Ch. 12 Q13) figure parmi les 14 maladies de Catégorie 2 (A) soumises à surveillance internationale et obligatoirement notifiables à l’OMS (D).', $medjson${"B":"La Catégorie 1 regroupe les 44 MDO à surveillance nationale.","C":"L’arrêté de 1990 est antérieur au SRAS (2002) et a été remplacé."}$medjson$::jsonb, NULL, TRUE, 'Épidémiologie des MT — Dr F. Beichi, Annexe Décret 22-250, p. 8–10') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C2_11', 'C2', 'L2.3', 'Liste des MDO en Algérie (piège Grippe)', 'bm_original', 'Ch. 12 Q8 (= Q12)', '2022', '', NULL, '', '', TRUE, TRUE, FALSE, 'Parmi les maladies citées ci-dessous, lesquelles sont à déclaration obligatoire : (cocher les réponses justes)', '', $medjson$[{"key":"A","text":"La rubéole"},{"key":"B","text":"La grippe"},{"key":"C","text":"La peste"},{"key":"D","text":"La méningite à méningocoque"}]$medjson$::jsonb, $medjson$["A","C","D"]$medjson$::jsonb, 'La rubéole (A), la peste (C) et la méningite à méningocoque (D) sont des MDO de Catégorie 1 (Décret 22-250).', $medjson${"B":"Piège classique ! La grippe saisonnière n’est PAS une MDO (suivie par le réseau sentinelle GROG) ; seule la grippe causée par un NOUVEAU sous-type est MDO (Cat. 2)."}$medjson$::jsonb, NULL, TRUE, 'Épidémiologie des MT — Dr F. Beichi, Annexe Décret 22-250, p. 9–10') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C2_12', 'C2', 'L2.3', 'Modélisation en surveillance des MT', 'bm_original', 'Ch. 12 Q2', '2024', '', NULL, '', '', FALSE, FALSE, FALSE, 'Dans la surveillance des maladies transmissibles, la modélisation consiste en :', '', $medjson$[{"key":"A","text":"Une étude prévisionnelle et tendancielle des maladies transmissibles"},{"key":"B","text":"Une évaluation des activités sanitaires de prévention"},{"key":"C","text":"Une application des méthodes fondamentales de recherche des facteurs étiologiques"},{"key":"D","text":"Une rédaction de rapports et émission de recommandations pour lutter contre une maladie transmissible"}]$medjson$::jsonb, $medjson$["A"]$medjson$::jsonb, 'La modélisation mathématique/épidémiologique permet d’établir des prévisions et d’anticiper les tendances évolutives d’une maladie transmissible.', $medjson${"B":"Relève de l’évaluation de programme.","C":"Relève de l’épidémiologie analytique/étiologique.","D":"Correspond à l’étape de diffusion/rétro-information."}$medjson$::jsonb, NULL, TRUE, 'BM Ch. 12 Q2 (2024) — complément surveillance MT') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C2_13', 'C2', 'L2.3', 'Décret 22-250 & Prophylaxie en 3 axes', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, 'À propos du Décret 22-250 (2022) et de la prophylaxie des MT (Dr Beichi), cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"Le Décret 22-250 du 30 juin 2022 fixe 44 MDO de Catégorie 1 et 14 MDO de Catégorie 2"},{"key":"B","text":"La séroprophylaxie (SAS, SAT) et la chimioprophylaxie agissent sur le 3ème maillon (protection du sujet réceptif)"},{"key":"C","text":"Toutes les maladies transmissibles sont contagieuses d’homme à homme"},{"key":"D","text":"Les déclarants obligatoires des MDO sont les médecins et les biologistes (secteurs public et privé)"}]$medjson$::jsonb, $medjson$["A","B","D"]$medjson$::jsonb, 'Les chiffres 44/14 (A), les déclarants médecins + biologistes (D) et les 3 axes prophylactiques (B) proviennent directement du polycopié du Dr Beichi.', $medjson${"C":"Faux : toutes les contagieuses sont transmissibles, mais l’inverse est faux (tétanos, paludisme, TIAC ne sont pas contagieuses)."}$medjson$::jsonb, NULL, FALSE, 'Épidémiologie des MT — Dr F. Beichi, p. 2, 6, 8–10') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C3_1', 'C3', 'L3.1', 'Définition facteur de risque MNT', 'bm_original', 'Ch. 11 Q1', '2022', '', NULL, '', '', FALSE, FALSE, FALSE, 'Dans les maladies non transmissibles un facteur de risque est :', '', $medjson$[{"key":"A","text":"Une constante"},{"key":"B","text":"Une variable qui augmente la probabilité de la survenue de la maladie"},{"key":"C","text":"Une variable que l’on peut mesurer"},{"key":"D","text":"C’est un marqueur de risque"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Un facteur de risque est une variable liée causalement à la maladie qui augmente sa probabilité de survenue.', $medjson${"A":"Ce n’est jamais une constante (il varie d’un sujet à l’autre).","C":"Trop vague et non spécifique d’un facteur de risque.","D":"Un marqueur de risque est non modifiable / non causal, distinct d’un facteur de risque."}$medjson$::jsonb, NULL, FALSE, 'Épidémiologie des MNT, slides 6–9') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C3_2', 'C3', 'L3.1', 'Transition épidémiologique (2025)', 'bm_original', 'Ch. 19 Q2', '2025', '', NULL, '', '', FALSE, FALSE, FALSE, 'L’étape essentielle de la transition épidémiologique est marquée par :', '', $medjson$[{"key":"A","text":"La résurgence des maladies infectieuses"},{"key":"B","text":"La baisse de l’incidence des MNT"},{"key":"C","text":"La disparition des facteurs environnementaux de risque"},{"key":"D","text":"L’augmentation de l’espérance de vie"}]$medjson$::jsonb, $medjson$["D"]$medjson$::jsonb, 'La transition épidémiologique se caractérise par le recul des maladies infectieuses, l’augmentation de l’espérance de vie (77 ans en Algérie) et la prédominance des MNT.', $medjson${"A":"Inverse : recul global des infections.","B":"Inverse : forte hausse des MNT.","C":"Faux : l’urbanisation et l’industrialisation créent de nouveaux risques environnementaux."}$medjson$::jsonb, NULL, FALSE, 'Épidémiologie des MNT, slides 10–11 (+ C1 slides 23–24)') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C3_3', 'C3', 'L3.1', 'Chiffres MNT Monde & Algérie', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, FALSE, FALSE, 'Concernant le poids épidémiologique des MNT dans le monde et en Algérie, cochez les réponses exactes :', '', $medjson$[{"key":"A","text":"Les MNT causent environ 74 % des décès dans le monde (41 millions/an)"},{"key":"B","text":"En Algérie, les MNT représentent environ 80 % des décès, dominées par les MCV (35 %)"},{"key":"C","text":"L’âge, le sexe et l’hérédité sont des facteurs de risque comportementaux modifiables"},{"key":"D","text":"En Algérie, la prévalence du diabète dépasse 14 % et l’obésité féminine dépasse 27 %"}]$medjson$::jsonb, $medjson$["A","B","D"]$medjson$::jsonb, 'Tous les chiffres de A, B et D figurent textuellement dans les slides 5, 11 et 12 du cours MNT.', $medjson${"C":"Âge, sexe et hérédité sont des facteurs NON modifiables (marqueurs de risque)."}$medjson$::jsonb, NULL, FALSE, 'Épidémiologie des MNT, slides 5, 8, 11–12') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C3_4', 'C3', 'L3.2', 'Prévention secondaire MNT (nouveaux & anciens cas)', 'bm_original', 'Ch. 11 Q2', '2022', '', NULL, '', '', FALSE, TRUE, FALSE, 'La prévention secondaire des maladies non transmissibles :', '', $medjson$[{"key":"A","text":"Tend à diminuer de nouveaux cas de maladie"},{"key":"B","text":"Repose sur l’éducation et l’observance des mesures de sécurité"},{"key":"C","text":"Sont des mesures non spécifiques"},{"key":"D","text":"Vise à diminuer les nouveaux et anciens cas de maladie"}]$medjson$::jsonb, $medjson$["D"]$medjson$::jsonb, 'La prévention secondaire vise à réduire la PRÉVALENCE (Ch. 11 Q4 B), qui correspond exactement à l’ensemble des nouveaux ET anciens cas.', $medjson${"A":"Diminuer les nouveaux cas (= incidence) définit la prévention primaire.","B":"Mesures générales en amont = prévention primaire.","C":"Les actions de dépistage secondaire sont au contraire ciblées et spécifiques."}$medjson$::jsonb, NULL, FALSE, 'Épidémiologie des MNT, slide 20') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C3_5', 'C3', 'L3.2', 'Prévention primaire MNT (2025)', 'bm_original', 'Ch. 29 Q2', '2025', '', NULL, '', '', FALSE, FALSE, FALSE, 'Parmi les propositions suivantes, laquelle correspond à un exemple type de prévention Primaire ?', '', $medjson$[{"key":"A","text":"Traiter une rétinopathie diabétique"},{"key":"B","text":"Arrêter la consommation de tabac pour prévenir le cancer pulmonaire"},{"key":"C","text":"Dépister un cancer par mammographie"},{"key":"D","text":"Effectuer un scanner thoracique chez un ancien fumeur"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Le sevrage tabagique supprime l’exposition au facteur de risque avant l’apparition du cancer → prévention primaire.', $medjson${"A":"Traiter une complication avérée = prévention tertiaire.","C":"Dépistage mammographique = prévention secondaire.","D":"Scanner thoracique chez un ancien fumeur = dépistage (prévention secondaire)."}$medjson$::jsonb, NULL, FALSE, 'Épidémiologie des MNT, slides 19–21') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C3_6', 'C3', 'L3.2', 'Prévention quaternaire (2025)', 'bm_original', 'Ch. 29 Q1', '2025', '', NULL, '', '', FALSE, FALSE, FALSE, 'La prévention quaternaire a pour principal objectif de :', '', $medjson$[{"key":"A","text":"Favoriser l’augmentation des traitements disponibles"},{"key":"B","text":"Réduire la prescription d’interventions inutiles"},{"key":"C","text":"Étendre les programmes de dépistage systématique"},{"key":"D","text":"Promouvoir uniquement la recherche clinique expérimentale"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'La prévention quaternaire vise la pertinence des soins et la réduction des examens/interventions inutiles (lutte contre la surmédicalisation).', $medjson${"A":"Opposé au principe de sobriété et de pertinence des soins.","C":"Le dépistage relève de la prévention secondaire.","D":"Sans rapport avec la prévention quaternaire."}$medjson$::jsonb, NULL, FALSE, 'Épidémiologie des MNT, slide 22') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C3_7', 'C3', 'L3.3', 'Enquête STEPS OMS, DALYs & Best Buys', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, 'À propos de la surveillance et des indicateurs des MNT, cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"L’enquête STEPS de l’OMS comporte 3 étapes : questionnaire, mesures physiques et mesures biochimiques"},{"key":"B","text":"Les DALYs combinent uniquement la mortalité prématurée (YLL), sans intégrer l’incapacité"},{"key":"C","text":"Le taux standardisé sur l’âge permet de comparer équitablement la mortalité entre pays de démographies différentes"},{"key":"D","text":"Les « Best Buys » de l’OMS désignent des interventions très coût-efficaces (taxation tabac, réduction du sel…)"}]$medjson$::jsonb, $medjson$["A","C","D"]$medjson$::jsonb, 'STEPS en 3 étapes (A), standardisation sur l’âge (C) et stratégie Best Buys (D) sont les piliers des slides 23–28.', $medjson${"B":"Faux : DALY = YLL (années perdues par décès prématuré) + YLD (années vécues avec incapacité)."}$medjson$::jsonb, NULL, FALSE, 'Épidémiologie des MNT, slides 23–28') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C3_8', 'C3', 'L3.3', 'Indicateur DALY & Taux standardisé', 'course_generated', '', 'Cours', '', NULL, '', '', FALSE, FALSE, FALSE, 'Quel indicateur de charge morbide combine à la fois les années de vie perdues par mortalité prématurée et les années vécues avec incapacité ?', '', $medjson$[{"key":"A","text":"Le taux brut de mortalité"},{"key":"B","text":"Le taux d’attaque"},{"key":"C","text":"Les DALYs (AVAI)"},{"key":"D","text":"Le sex-ratio"}]$medjson$::jsonb, $medjson$["C"]$medjson$::jsonb, 'Les DALYs (Disability-Adjusted Life Years / AVAI) additionnent YLL (mortalité prématurée) et YLD (morbidité/incapacité).', $medjson${"A":"Ne mesure que les décès bruts sans ajustement ni incapacité.","B":"Indicateur d’incidence cumulée en épidémie aiguë.","D":"Ratio démographique Hommes / Femmes."}$medjson$::jsonb, NULL, FALSE, 'Épidémiologie des MNT, slides 24–25') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C3_9', 'C3', 'L3.3', 'Surveillance MNT (registres & STEPS)', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, FALSE, FALSE, 'Quels outils participent directement à la surveillance épidémiologique des MNT ?', '', $medjson$[{"key":"A","text":"Les registres du cancer, du diabète et des AVC"},{"key":"B","text":"Les enquêtes STEPS de l’OMS"},{"key":"C","text":"La déclaration obligatoire en Catégorie 2 (OMS) de l’HTA"},{"key":"D","text":"Les statistiques de mortalité par cause (taux standardisés)"}]$medjson$::jsonb, $medjson$["A","B","D"]$medjson$::jsonb, 'La surveillance des MNT s’appuie sur les registres de morbidité (A), les enquêtes de FDR STEPS (B) et les données de mortalité (D).', $medjson${"C":"Faux : la Catégorie 2 MDO concerne 14 maladies infectieuses à potentiel épidémique international, jamais l’HTA."}$medjson$::jsonb, NULL, FALSE, 'Épidémiologie des MNT, slides 23–26') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C4_1', 'C4', 'L4.1', 'Définition d’une épidémie (2025)', 'bm_original', 'Ch. 19 Q6', '2025', '', NULL, '', '', FALSE, FALSE, FALSE, 'Parmi les propositions suivantes, laquelle définit le mieux une épidémie ?', '', $medjson$[{"key":"A","text":"Survenue inattendue de cas sporadiques sans lien épidémiologique"},{"key":"B","text":"Excès de cas par rapport au niveau attendu dans une population et un temps donné"},{"key":"C","text":"Augmentation saisonnière prévue d’une maladie endémique"},{"key":"D","text":"Apparition simultanée de différentes maladies dans une population"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Une épidémie est la survenue en excès de cas par rapport au nombre habituellement attendu dans une population, un lieu et une période donnés.', $medjson${"A":"Correspond à des cas sporadiques isolés.","C":"Une variation saisonnière habituelle/prévue est une fausse épidémie.","D":"Une épidémie porte sur une même maladie / un même événement."}$medjson$::jsonb, NULL, FALSE, 'Investigation d’une épidémie — Dr F. Beichi, § I.1, p. 2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C4_2', 'C4', 'L4.1', 'Source ponctuelle vs Source persistante (2025)', 'bm_original', 'Ch. 19 Q4', '2025', '', NULL, '', '', FALSE, TRUE, FALSE, 'La différence principale entre une source ponctuelle et une source persistante est que :', '', $medjson$[{"key":"A","text":"La source ponctuelle entraîne une épidémie de longue durée"},{"key":"B","text":"La source persistante génère un seul pic épidémique"},{"key":"C","text":"La source ponctuelle libère l’agent pathogène sur une courte période uniquement"},{"key":"D","text":"La source persistante émet de manière épisodique l’agent pathogène"}]$medjson$::jsonb, $medjson$["C"]$medjson$::jsonb, 'Une source ponctuelle expose sur une courte période unique (ex. repas contaminé), générant un pic bref.', $medjson${"A":"Faux : épidémie courte (à l’inverse de la source persistante).","B":"Faux : c’est la source ponctuelle qui génère un pic unique.","D":"Piège de vocabulaire : une source persistante émet de manière CONTINUE (pas épisodique/intermittente)."}$medjson$::jsonb, NULL, FALSE, 'Investigation d’une épidémie — Dr F. Beichi, § I.3, p. 2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C4_3', 'C4', 'L4.1', 'Définition Outbreak (2025)', 'bm_original', 'Ch. 19 Q5', '2025', '', NULL, '', '', FALSE, FALSE, FALSE, 'Le terme Outbreak désigne spécifiquement :', '', $medjson$[{"key":"A","text":"L’apparition simultanée de plusieurs agents pathogènes"},{"key":"B","text":"Une épidémie limitée géographiquement ou dans le temps"},{"key":"C","text":"Une pandémie de grande ampleur"},{"key":"D","text":"Une augmentation de cas sans preuve épidémiologique claire"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Outbreak (cas groupés) désigne une épidémie de taille limitée, circonscrite dans le temps ou géographiquement.', $medjson${"A":"Faux.","C":"Exact opposé (une pandémie s’étend sur plusieurs continents).","D":"Faux."}$medjson$::jsonb, NULL, FALSE, 'Investigation d’une épidémie — Dr F. Beichi, § I.2, p. 2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C4_4', 'C4', 'L4.1', 'Objectifs généraux d’une investigation (2025)', 'bm_original', 'Ch. 19 Q1', '2025', '', NULL, '', '', FALSE, FALSE, FALSE, 'Concernant les objectifs généraux d’une investigation épidémiologique, indiquez l’affirmation correcte :', '', $medjson$[{"key":"A","text":"L’unique objectif est de produire des publications scientifiques"},{"key":"B","text":"Il s’agit de confirmer l’efficacité des actions de prévention"},{"key":"C","text":"Elle vise principalement à interrompre la transmission et prévenir de nouveaux cas"},{"key":"D","text":"Elle consiste uniquement en la surveillance de la maladie sans action corrective"}]$medjson$::jsonb, $medjson$["C"]$medjson$::jsonb, 'Les objectifs premiers d’une investigation sont d’arrêter l’épidémie (interrompre la transmission) et de prévenir de nouveaux cas ou épisodes.', $medjson${"A":"La publication n’est jamais l’unique objectif.","B":"Objectif secondaire / d’évaluation, pas l’objectif principal immédiat.","D":"Faux : l’investigation débouche impérativement sur des actions correctives."}$medjson$::jsonb, NULL, FALSE, 'Investigation d’une épidémie — Dr F. Beichi, § II.1, p. 3') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C4_5', 'C4', 'L4.2', 'Courbe épidémique (Étape 5A)', 'bm_original', 'Ch. 19 Q8 (= Ch. 14 Q49)', '2022', '', NULL, '', '', TRUE, TRUE, FALSE, 'La courbe épidémique du nombre de cas d’un événement de santé dans son évolution dans le temps : (Cocher les réponses justes)', '', $medjson$[{"key":"A","text":"Renseigne avec certitude sur la nature de l’agent causal de la maladie"},{"key":"B","text":"Permet de calculer la durée d’incubation de la maladie"},{"key":"C","text":"Fournit des informations sur le type de transmission de l’agent infectieux"},{"key":"D","text":"Fournit des informations sur la nature de la source de contamination"}]$medjson$::jsonb, $medjson$["B","C","D"]$medjson$::jsonb, 'La courbe épidémique permet d’estimer la durée d’incubation (B), le type de transmission (C) et la nature de la source — ponctuelle vs persistante (D).', $medjson${"A":"Piège majeur ! Elle oriente les hypothèses mais NE donne JAMAIS de certitude sur l’agent causal (seul le laboratoire le confirme)."}$medjson$::jsonb, $medjson${"bmKey":"B seul (Ch. 14 Q49) / manquant (Ch. 19 Q8)","note":"Le cours p. 6 confirme que B, C et D sont toutes exactes ; seul A est faux."}$medjson$::jsonb, TRUE, 'Investigation d’une épidémie — Dr F. Beichi, Étape 5A, p. 6') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C4_6', 'C4', 'L4.2', 'Taux d’attaque en épidémie', 'bm_original', 'Ch. 19 Q13 (= Ch. 17 Q32)', '2022', '', NULL, '', '', FALSE, FALSE, FALSE, 'Vous avez investigué une épidémie récente, et vous avez calculé le rapport nombre de sujets atteints / nombre de sujets de la population de la zone ; on appelle cela :', '', $medjson$[{"key":"A","text":"Le taux d’incidence"},{"key":"B","text":"Le taux d’attaque"},{"key":"C","text":"La fréquence de la maladie"},{"key":"D","text":"Le taux de morbidité"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Dans le contexte d’une épidémie aiguë sur une population exposée définie, ce rapport s’appelle spécifiquement le taux d’attaque (confirmé par Ch. 17 Q32 = C).', $medjson${"A":"Terme plus général ; le terme spécifique en investigation d’épidémie est taux d’attaque.","C":"Terme trop générique.","D":"Terme non spécifique."}$medjson$::jsonb, NULL, TRUE, 'Investigation d’une épidémie — Dr F. Beichi, Étape 5, p. 6') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C4_7', 'C4', 'L4.2', 'Collecte des cas (Étape 4 — 2025)', 'bm_original', 'Ch. 19 Q3', '2025', '', NULL, '', '', FALSE, FALSE, FALSE, 'La collecte des cas durant une investigation repose sur :', '', $medjson$[{"key":"A","text":"Les associations des quartiers et les témoignages populaires"},{"key":"B","text":"Les dossiers hospitaliers, les registres et les laboratoires de diagnostic"},{"key":"C","text":"Les prédictions basées sur les modèles climatiques"},{"key":"D","text":"Une enquête de satisfaction auprès des patients guéris"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'La recherche active et systématique des cas s’appuie sur des sources médicales fiables : dossiers hospitaliers, registres et laboratoires de diagnostic.', $medjson${"A":"Sources informelles non validées cliniquement.","C":"Modèles climatiques sans rapport avec le recensement des malades.","D":"Ne recense pas les cas de l’épidémie."}$medjson$::jsonb, NULL, FALSE, 'Investigation d’une épidémie — Dr F. Beichi, Étape 4, p. 5') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C4_8', 'C4', 'L4.3', 'Contenu de la phase descriptive', 'bm_original', 'Ch. 19 Q9', '2022', '', NULL, '', '', TRUE, FALSE, FALSE, 'La phase descriptive de l’investigation d’une épidémie comporte les étapes suivantes : (Cocher les réponses justes)', '', $medjson$[{"key":"A","text":"L’affirmation de l’épisode épidémique"},{"key":"B","text":"L’identification des personnes à risque"},{"key":"C","text":"La réalisation éventuelle d’une étude épidémiologique plus approfondie"},{"key":"D","text":"La rédaction du rapport de l’épidémie"}]$medjson$::jsonb, $medjson$["A","B"]$medjson$::jsonb, 'La phase descriptive (Étapes 1–6) comprend l’affirmation de l’épidémie (A) et la description temps/lieu/personne permettant d’identifier les personnes à risque (B).', $medjson${"C":"Correspond à la phase analytique / étiologique (Étape 7).","D":"La rédaction du rapport est l’Étape 9, en fin d’investigation."}$medjson$::jsonb, NULL, FALSE, 'Investigation d’une épidémie — Dr F. Beichi, § III, p. 3–6') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C4_9', 'C4', 'L4.3', 'Phase étiologique : approche cohorte', 'bm_original', 'Ch. 19 Q14', '2019', '', NULL, '', '', FALSE, FALSE, FALSE, 'La phase étiologique lors de l’investigation d’une épidémie, utilise :', '', $medjson$[{"key":"A","text":"L’approche expérimentale"},{"key":"B","text":"L’étude épidémiologique transversale"},{"key":"C","text":"L’approche cohorte"},{"key":"D","text":"L’étude démographique"}]$medjson$::jsonb, $medjson$["C"]$medjson$::jsonb, 'À l’Étape 7 (phase analytique/étiologique), on teste les hypothèses par une étude de cohorte rétrospective (comparaison de taux d’attaque) ou une étude cas-témoins.', $medjson${"A":"On n’expérimente pas l’exposition à un pathogène sur l’homme.","B":"L’étude transversale est descriptive, pas étiologique d’investigation.","D":"Une étude démographique ne teste pas une exposition causale."}$medjson$::jsonb, NULL, FALSE, 'Investigation d’une épidémie — Dr F. Beichi, Étape 7, p. 6') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C4_10', 'C4', 'L4.3', 'Étapes 1–10 (sensibilité, date début, mesures)', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, 'Concernant les règles opérationnelles des 10 étapes d’investigation (Dr Beichi), cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"Si la maladie est mal connue, la définition de cas privilégie la sensibilité (cas certains, probables et possibles)"},{"key":"B","text":"La date essentielle à recueillir pour tracer la courbe épidémique est la date de début des symptômes"},{"key":"C","text":"Il faut obligatoirement attendre la fin de l’étude analytique avant de mettre en place toute mesure de prévention"},{"key":"D","text":"Une étude cas-témoins en phase analytique compare les proportions d’exposition chez les cas et chez les témoins"}]$medjson$::jsonb, $medjson$["A","B","D"]$medjson$::jsonb, 'Sensibilité de la définition de cas (A), date de début des symptômes (B) et principe de l’étude cas-témoins (D) sont des points clés du cours.', $medjson${"C":"Piège majeur (Étape 10) : ne JAMAIS attendre la fin de l’investigation — instaurer des mesures générales dès le début !"}$medjson$::jsonb, NULL, FALSE, 'Investigation d’une épidémie — Dr F. Beichi, Étapes 3, 4, 7 & 10, p. 5–7') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C5_1', 'C5', 'L5.1', 'Enquête épidémiologique TIAC (2024)', 'bm_original', 'Ch. 6 Q2 (= Q1)', '2024', '', NULL, '', '', FALSE, FALSE, FALSE, 'L’investigation d’une épidémie de toxi-infection alimentaire collective TIAC nécessite :', '', $medjson$[{"key":"A","text":"Une étape strictement descriptive"},{"key":"B","text":"Une étape à visée étiologique obligatoire"},{"key":"C","text":"Une étape descriptive suivie obligatoirement d’une étape analytique"},{"key":"D","text":"Une étape descriptive selon les caractères de lieu, de personne et temps, non suivie obligatoirement d’une étape analytique"}]$medjson$::jsonb, $medjson$["C"]$medjson$::jsonb, 'L’investigation d’une TIAC associe systématiquement une enquête descriptive (T/L/P) suivie d’une enquête analytique pour identifier l’aliment incriminé.', $medjson${"A":"Insuffisant pour démontrer statistiquement l’aliment responsable.","B":"Omet l’étape descriptive indispensable.","D":"Faux : l’étape analytique suit la phase descriptive."}$medjson$::jsonb, NULL, FALSE, 'CAT TIAC — Dr Nourani, slides 4 & 10') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C5_2', 'C5', 'L5.1', 'Déclaration des cas de TIAC (2024)', 'bm_original', 'Ch. 6 Q3', '2024', '', NULL, '', '', FALSE, FALSE, FALSE, 'La déclaration des cas de TIAC se fait, par :', '', $medjson$[{"key":"A","text":"Une fiche d’enquête des toxi-infections alimentaires"},{"key":"B","text":"Un signalement rapide et une notification sur un relevé des MDO"},{"key":"C","text":"Un registre de renseignement des données des MDO"},{"key":"D","text":"Des formulaires des maladies à déclaration obligatoire"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'La TIAC étant une urgence médico-épidémiologique, elle impose un signalement rapide immédiat (SEMEP) ET une notification écrite sur le relevé des MDO.', $medjson${"A":"La fiche d’enquête sert à l’investigation par le SEMEP, pas à la déclaration initiale.","C":"Ne comporte pas l’alerte/signalement rapide immédiat.","D":"Incomplet sans le signalement rapide immédiat."}$medjson$::jsonb, NULL, FALSE, 'CAT TIAC — Dr Nourani, slide 9 ; Instr. 2026 p. 4–5') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C5_3', 'C5', 'L5.1', 'Facteurs favorisants des TIAC (2024)', 'bm_original', 'Ch. 6 Q4', '2024', '', NULL, '', '', FALSE, FALSE, FALSE, 'Les facteurs favorisant les Toxi-infections alimentaires collectives (TIAC) :', '', $medjson$[{"key":"A","text":"Le respect de la chaîne de froid"},{"key":"B","text":"Des erreurs dans le processus de préparation des aliments"},{"key":"C","text":"Un délai réduit entre la préparation et la consommation"},{"key":"D","text":"La fréquence des gastro-entérites"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Les erreurs de préparation, de conservation et d’hygiène alimentaire sont les principaux facteurs favorisants des TIAC.', $medjson${"A":"Facteur protecteur (prévention), pas favorisant.","C":"Facteur protecteur (moins de temps de multiplication bactérienne).","D":"Sans lien causal direct avec la contamination d’un repas collectif."}$medjson$::jsonb, NULL, FALSE, 'CAT TIAC — Dr Nourani, slides 5 & 16–19') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C5_4', 'C5', 'L5.1', 'Urgence médicale et épidémiologique (2024)', 'bm_original', 'Ch. 6 Q5', '2024', '', NULL, '', '', FALSE, FALSE, FALSE, 'Les toxi-infections alimentaires collectives sont :', '', $medjson$[{"key":"A","text":"Des urgences médicales et épidémiologiques"},{"key":"B","text":"Des urgences médicales nécessitant une mobilisation de moyens humains"},{"key":"C","text":"Des urgences épidémiologiques nécessitant une approche uniquement environnementale"},{"key":"D","text":"Des urgences médicales impactant les activités habituelles des structures"}]$medjson$::jsonb, $medjson$["A"]$medjson$::jsonb, 'Les TIAC constituent une double urgence : médicale (prise en charge des malades, réhydratation) et épidémiologique (alerte, retrait de l’aliment contaminé).', $medjson${"B":"Omet la dimension d’urgence épidémiologique.","C":"Faux (« uniquement environnementale »).","D":"Incomplet par rapport à la définition exacte du cours."}$medjson$::jsonb, NULL, FALSE, 'CAT TIAC — Dr Nourani, slides 2–4') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C5_5', 'C5', 'L5.2', 'Germes, incubations & botulisme', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, '25 convives présentent des vomissements et diarrhées SANS fièvre 3 h après des pâtisseries à la crème. Cochez les propositions exactes sur les TIAC :', '', $medjson$[{"key":"A","text":"Le germe le plus probable ici est Staphylococcus aureus (toxine préformée, incubation 1–6 h)"},{"key":"B","text":"Une TIAC exige toujours au moins 2 cas groupés similaires, même pour le botulisme"},{"key":"C","text":"Une TIAC fébrile (39 °C) 24 h après œufs/volaille évoque Salmonella non typhoïdique"},{"key":"D","text":"Listeria monocytogenes expose particulièrement la femme enceinte (avortement) et le nouveau-né (méningite)"}]$medjson$::jsonb, $medjson$["A","C","D"]$medjson$::jsonb, 'S. aureus (1–6 h sans fièvre, A), Salmonella (12–72 h fébrile sur œufs/volailles, C) et Listeria (femme enceinte/nouveau-né, D) sont les tableaux phares du cours.', $medjson${"B":"Faux : exception absolue pour le BOTULISME où 1 SEUL cas suffit !"}$medjson$::jsonb, NULL, FALSE, 'Cours_Epidemiologie_TIAC.pdf (Instr. 2026), p. 1–3') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C5_6', 'C5', 'L5.2', 'Prélèvements & Traitement des TIAC', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, 'Concernant les prélèvements et le traitement d’une TIAC (Instr. N°19/2026), cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"Il est formellement recommandé de congeler tous les prélèvements avant leur envoi à l’IPA"},{"key":"B","text":"Le lopéramide (Imodium®) est formellement proscrit en cas de syndrome dysentérique"},{"key":"C","text":"Un prélèvement d’eau suspecte requiert un flacon stérile de 1 litre transporté immédiatement à +4 °C"},{"key":"D","text":"Les selles doivent être prélevées (≥ 10 g) avant toute antibiothérapie"}]$medjson$::jsonb, $medjson$["B","C","D"]$medjson$::jsonb, 'Imodium® proscrit si dysenterie (B, risque de colo-stase), eau = 1 L à +4 °C (C), selles ≥ 10 g avant ATB (D).', $medjson${"A":"Piège critique ! Ne JAMAIS congeler les prélèvements (sauf force majeure), au risque de détruire les germes."}$medjson$::jsonb, NULL, FALSE, 'Cours_Epidemiologie_TIAC.pdf (Instr. 2026), p. 5–8') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C5_7', 'C5', 'L5.2', 'Complications spécifiques TIAC', 'course_generated', '', 'Cours', '', NULL, '', '', FALSE, FALSE, FALSE, 'Parmi ces couples « Germe TIAC — Aliment / Complication typique », lequel est INEXACT ?', '', $medjson$[{"key":"A","text":"Bacillus cereus — Riz / purée de légumes"},{"key":"B","text":"E. coli entéro-hémorragique (EHEC) — Syndrome hémolytique et urémique (SHU)"},{"key":"C","text":"Campylobacter — Syndrome de Guillain-Barré"},{"key":"D","text":"Clostridium perfringens — Fièvre élevée à 40 °C dès la 2ème heure"}]$medjson$::jsonb, $medjson$["D"]$medjson$::jsonb, 'Clostridium perfringens a une incubation de 8–24 h (viandes/sauces refroidies lentement) et provoque une diarrhée SANS fièvre !', $medjson${"A":"Exact (incubation 1–16 h).","B":"Exact (incubation 3–8 j, viande peu cuite/lait cru).","C":"Exact (incubation 2–10 j, volaille/lait cru)."}$medjson$::jsonb, NULL, FALSE, 'Cours_Epidemiologie_TIAC.pdf (Instr. 2026), p. 2–3') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C5_8', 'C5', 'L5.3', '5 Clés OMS & Instruction 2024', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, 'Concernant la prévention des TIAC en restauration collective (Instruction N°18/2024 & OMS), cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"Le principe de la marche en avant interdit qu’un circuit sale coupe un circuit propre"},{"key":"B","text":"Les plats chauds doivent être maintenus à \u003e 65 °C et les plats froids entre 2 et 4 °C"},{"key":"C","text":"Les restes non consommés peuvent être réchauffés et resservis le lendemain s’ils sont réfrigérés"},{"key":"D","text":"Un plat témoin (50–100 g) doit être conservé à +4 °C pendant ≥ 72 h (5 jours selon les slides)"}]$medjson$::jsonb, $medjson$["A","B","D"]$medjson$::jsonb, 'Marche en avant (A), températures > 65 °C / 2–4 °C (B) et plat témoin à +4 °C (D) sont les règles officielles de l’Instruction 2024.', $medjson${"C":"Interdit ! En restauration collective, les restes doivent être systématiquement jetés."}$medjson$::jsonb, NULL, FALSE, 'INSTRUCTION TIAC.pdf (N°18/2024), p. 2–3 ; CAT TIAC slide 10') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C5_9', 'C5', 'L5.3', 'Personnel de cuisine & désinfection', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, FALSE, FALSE, 'Selon l’Instruction N°18 (2024) relative à la restauration collective, cochez les règles exactes :', '', $medjson$[{"key":"A","text":"Le personnel de cuisine doit subir une visite médicale à l’embauche puis tous les trimestres"},{"key":"B","text":"Les ustensiles utilisés pour la viande hachée sont désinfectés à l’eau javellisée 12°"},{"key":"C","text":"Les aliments cuits peuvent rester 6 heures à température ambiante avant réfrigération"},{"key":"D","text":"Les 5 Clés OMS incluent la séparation des aliments crus et cuits et une cuisson ≥ 70 °C"}]$medjson$::jsonb, $medjson$["A","B","D"]$medjson$::jsonb, 'Visite embauche + trimestrielle (A), javel 12° (B) et 5 Clés OMS (D) sont exactes.', $medjson${"C":"Faux : ne jamais laisser un aliment cuit plus de 2 heures à température ambiante (OMS)."}$medjson$::jsonb, NULL, FALSE, 'INSTRUCTION TIAC.pdf (N°18/2024), p. 2–3 ; CAT TIAC slides 16–19') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C5_10', 'C5', 'L5.3', 'Les 5 Clés OMS', 'course_generated', '', 'Cours', '', NULL, '', '', FALSE, FALSE, FALSE, 'Laquelle des propositions suivantes NE fait PAS partie des « 5 Clés de l’OMS » pour des aliments plus sûrs ?', '', $medjson$[{"key":"A","text":"Prendre l’habitude de la propreté"},{"key":"B","text":"Séparer les aliments crus des aliments cuits"},{"key":"C","text":"Congeler systématiquement les repas témoins à −20 °C"},{"key":"D","text":"Maintenir les aliments à bonne température et bien les cuire (≥ 70 °C)"}]$medjson$::jsonb, $medjson$["C"]$medjson$::jsonb, 'Les plats témoins se conservent à +4 °C (réfrigération, jamais congélation) et ne font pas partie de l’intitulé des 5 Clés OMS.', $medjson${"A":"Clé n°1 OMS.","B":"Clé n°2 OMS.","D":"Clés n°3 et n°4 OMS."}$medjson$::jsonb, NULL, FALSE, 'CAT TIAC slides 16–19 ; Instr. 2024 p. 3') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C6_1', 'C6', 'L6.1', 'Délai ISO sur prothèse du genou (1 an)', 'bm_original', 'Ch. 10 Q14', '2021', '', NULL, '', '', FALSE, TRUE, FALSE, 'Un patient revient 2 mois après une intervention pour une prothèse du genou dans le cadre d’une infection sur le site de sa prothèse : (cocher la bonne réponse)', '', $medjson$[{"key":"A","text":"Il s’agit d’une infection du site opératoire"},{"key":"B","text":"On ne peut pas retenir le diagnostic d’une infection associée aux soins car on n’a pas d’information concernant le germe en cause"},{"key":"C","text":"On ne peut pas retenir le diagnostic d’une infection du site opératoire pour ce patient car le délai de 30 jours est dépassé"},{"key":"D","text":"C’est une infection communautaire"}]$medjson$::jsonb, $medjson$["A"]$medjson$::jsonb, 'Slide 6 du cours : le délai d’une ISO est de 30 jours en chirurgie sans matériel, mais s’étend jusqu’à 1 AN en cas de mise en place d’un implant ou d’une prothèse. À 2 mois, c’est donc bien une ISO.', $medjson${"B":"Le diagnostic d’ISO/IAS n’exige pas la connaissance préalable du germe.","C":"Erreur classique (et erreur du corrigé BM) : 30 jours ne s’applique que sans implant/prothèse.","D":"Infection directement secondaire à l’acte chirurgical prothétique."}$medjson$::jsonb, $medjson${"bmKey":"C","note":"Le corrigé BM met C (« délai 30 jours dépassé »), oubliant que le délai ISO passe à 1 AN en cas de prothèse ou d’implant (slide 6) ! La vraie réponse est A."}$medjson$::jsonb, FALSE, 'Les infections associées aux soins — Pr Tobbi / Dr Benaldjia, slide 6') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C6_2', 'C6', 'L6.1', 'Définition IAS (2025)', 'bm_original', 'Ch. 16 Q1 (= Ch. 10 Q5)', '2025', '', NULL, '', '', FALSE, FALSE, FALSE, 'L’infection associée aux soins (IAS) :', '', $medjson$[{"key":"A","text":"Survient avant 24h d’hospitalisation"},{"key":"B","text":"Survient uniquement en milieu hospitalier"},{"key":"C","text":"Survient avant 12h d’hospitalisation"},{"key":"D","text":"Aucune réponse n’est juste"}]$medjson$::jsonb, $medjson$["D"]$medjson$::jsonb, 'Une IAS survient après un délai standard > 48 h d’hospitalisation (jamais avant 12 h ou 24 h) et englobe aussi bien l’hôpital (IN) que le milieu libéral (ILS). Donc aucune des options A, B, C n’est juste.', $medjson${"A":"Faux : délai standard \u003e 48 h.","B":"Faux : inclut aussi les soins extrahospitaliers / libéraux (ILS).","C":"Faux : délai standard \u003e 48 h."}$medjson$::jsonb, NULL, FALSE, 'Les infections associées aux soins, slides 5–7') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C6_3', 'C6', 'L6.1', 'Définition complète IAS (IN + ILS)', 'bm_original', 'Ch. 10 Q21', 'ND', '', NULL, '', '', FALSE, TRUE, FALSE, 'L’Infection associée aux soins (IAS) :
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C6_4', 'C6', 'L6.1', 'Organisation CNHH/CLIN & Prévalence Algérie', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, FALSE, FALSE, 'Concernant l’épidémiologie et l’organisation de la lutte contre les IAS en Algérie, cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"L’enquête nationale algérienne de 2005 a retrouvé une prévalence des IN de 14 %"},{"key":"B","text":"Le CNHH (28 mars 1998) et les CLIN (27 novembre 1998) ont été créés en 1998"},{"key":"C","text":"Les précautions standard s’appliquent uniquement aux patients porteurs connus de BMR"},{"key":"D","text":"Une endophtalmie survenant 3 jours après chirurgie de la cataracte avec implant fait suspecter une ISO"}]$medjson$::jsonb, $medjson$["A","B","D"]$medjson$::jsonb, 'Prévalence 14 % (A), CNHH & CLIN en 1998 (B), endophtalmie à J3 sur implant cataracte = ISO suspectée (D, conforme Ch. 10 Q13 A).', $medjson${"C":"Faux : les précautions standard s’appliquent par TOUS les professionnels, pour TOUS les patients et pour TOUS les soins !"}$medjson$::jsonb, NULL, FALSE, 'Les infections associées aux soins, slides 6, 9, 22–25') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C6_5', 'C6', 'L6.2', 'Pneumonies nosocomiales — 1ère cause de décès', 'bm_original', 'Ch. 16 Q2 (= Ch. 10 Q2)', '2025', '', NULL, '', '', FALSE, FALSE, FALSE, 'Les pneumonies nosocomiales constituent :', '', $medjson$[{"key":"A","text":"1ère cause de décès par infection nosocomiale"},{"key":"B","text":"2ème cause de décès par infection nosocomiale"},{"key":"C","text":"Causent rarement de décès"},{"key":"D","text":"Aucune réponse n’est juste"}]$medjson$::jsonb, $medjson$["A"]$medjson$::jsonb, 'Si l’infection urinaire (IUN) est la plus fréquente, la pneumonie nosocomiale est la 1ère cause de mortalité par IN (tombé en 2024 ET en 2025).', $medjson${"B":"Faux : elle est au 1er rang de mortalité.","C":"Faux : mortalité très élevée, surtout en réanimation sous intubation.","D":"Faux car A est exacte."}$medjson$::jsonb, NULL, FALSE, 'Les infections associées aux soins, slide 16') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C6_6', 'C6', 'L6.2', 'Germes sur cathéters (2024 & 2025)', 'bm_original', 'Ch. 16 Q3 (= Ch. 10 Q1)', '2025', '', NULL, '', '', FALSE, FALSE, FALSE, 'Parmi les germes suivants quels sont les plus incriminés dans les infections nosocomiales sur cathéters :', '', $medjson$[{"key":"A","text":"Germes Bacilles Gram négatif"},{"key":"B","text":"Staphylocoques"},{"key":"C","text":"Champignons et levures"},{"key":"D","text":"Aucune réponse n’est juste"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Les Staphylocoques représentent 50 % des IN sur cathéters, devant les BGN (10 %) et les levures.', $medjson${"A":"Les BGN (60 %) sont le germe n°1 des PNEUMONIES nosocomiales (Ch. 16 Q4 A), pas des cathéters.","C":"Minoritaire par rapport aux Staphylocoques.","D":"Faux car B est exacte."}$medjson$::jsonb, NULL, FALSE, 'Les infections associées aux soins, slide 18') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C6_7', 'C6', 'L6.2', 'Germes des pneumonies nosocomiales (2024 & 2025)', 'bm_original', 'Ch. 16 Q4 (= Ch. 10 Q3)', '2025', '', NULL, '', '', FALSE, FALSE, FALSE, 'Parmi les germes suivants quels sont les plus incriminés dans les Pneumonies nosocomiales :', '', $medjson$[{"key":"A","text":"Germes Bacilles Gram négatif"},{"key":"B","text":"Germes Bacilles Gram positifs"},{"key":"C","text":"Candida"},{"key":"D","text":"Aspergillus"}]$medjson$::jsonb, $medjson$["A"]$medjson$::jsonb, 'Les Bacilles Gram Négatif (BGN) représentent 60 % des pneumonies nosocomiales (suivis par S. aureus 30 %, Candida 10 % et Aspergillus).', $medjson${"B":"S. aureus est un cocci Gram+ (30 %), derrière les BGN.","C":"10 % seulement.","D":"Plus rare (immunodéprimés)."}$medjson$::jsonb, NULL, FALSE, 'Les infections associées aux soins, slide 16') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C6_8', 'C6', 'L6.2', 'Colonisation du cathéter', 'bm_original', 'Ch. 10 Q22', 'ND', '', NULL, '', '', FALSE, TRUE, FALSE, 'La colonisation du cathéter se caractérise par :
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C6_9', 'C6', 'L6.2', 'IN la plus fréquente & bactéries/visiteurs', 'bm_original', 'Ch. 10 Q9', '2021', '', NULL, '', '', FALSE, FALSE, FALSE, 'Parmi les infections nosocomiales suivantes, quelle est la plus fréquente ? (Cocher la bonne réponse)', '', $medjson$[{"key":"A","text":"Infection urinaire"},{"key":"B","text":"Infection sur brûlure"},{"key":"C","text":"Bactériémie sur cathéter"},{"key":"D","text":"Infection pulmonaire"}]$medjson$::jsonb, $medjson$["A"]$medjson$::jsonb, 'L’infection urinaire nosocomiale (IUN, favorisée par le sondage vésical, germe n°1 E. coli) occupe le 1er rang en fréquence.', $medjson${"B":"Spécifique aux services de brûlés.","C":"Moins fréquente que les IUN.","D":"L’infection pulmonaire est la 1ère cause de DÉCÈS, pas la 1ère en fréquence."}$medjson$::jsonb, NULL, FALSE, 'Les infections associées aux soins, slide 15') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C6_10', 'C6', 'L6.3', 'Règles d’hygiène des mains', 'bm_original', 'Ch. 10 Q6', '2022', '', NULL, '', '', TRUE, TRUE, FALSE, 'Pour une bonne hygiène des mains : (Cochez les réponses justes)', '', $medjson$[{"key":"A","text":"Je proscris tous les bijoux"},{"key":"B","text":"J’utilise un pain de savon individuel"},{"key":"C","text":"J’utilise une serviette changée tous les jours pour m’essuyer les mains"},{"key":"D","text":"Je n’utilise absolument pas un appareil électrique pour me sécher les mains"}]$medjson$::jsonb, $medjson$["A","D"]$medjson$::jsonb, 'Proscrire tous les bijoux (A, y compris alliance lisse) et proscrire le séchoir à air chaud électrique (D, cf. Ch. 10 Q20) sont des règles strictes d’hygiène hospitalière.', $medjson${"B":"Le savon en pain est un réservoir microbien proscrit (utiliser savon liquide ou SHA — Ch. 10 Q10 \u0026 Q20).","C":"Les serviettes réutilisables sont proscrites (utiliser essuie-mains papier à usage unique)."}$medjson$::jsonb, $medjson${"bmKey":"ABC","note":"Erreur manifeste du corrigé BM (contredit Ch. 10 Q10 \u0026 Q20) : le pain de savon (B) et la serviette réutilisable (C) sont proscrits ! La vraie réponse est AD."}$medjson$::jsonb, FALSE, 'Volet Hygiène des mains — cohérence BM Ch. 10 Q7, Q10 & Q20') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C6_11', 'C6', 'L6.3', 'Contre-indications de la SHA', 'bm_original', 'Ch. 10 Q11', '2021', '', NULL, '', '', TRUE, FALSE, FALSE, 'Parmi les propositions suivantes choisissez celles qui correspondent à des contre-indications de la friction hydro-alcoolique :', '', $medjson$[{"key":"A","text":"Les mains mouillées"},{"key":"B","text":"Les mains poudrées ou talquées"},{"key":"C","text":"Les mains sèches"},{"key":"D","text":"Les mains visiblement souillées"}]$medjson$::jsonb, $medjson$["A","B","D"]$medjson$::jsonb, 'La SHA est contre-indiquée sur mains mouillées (A), poudrées/talquées (B) et visiblement souillées (D). Elle nécessite des mains propres et sèches.', $medjson${"C":"Des mains sèches constituent au contraire la condition requise pour utiliser la SHA."}$medjson$::jsonb, NULL, FALSE, 'Volet Hygiène des mains / Précautions standard (BM Ch. 10 Q11 & Q18)') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C6_12', 'C6', 'L6.3', 'Flore résidente vs Flore transitoire', 'bm_original', 'Ch. 10 Q8', '2021', '', NULL, '', '', FALSE, FALSE, FALSE, 'Parmi les caractéristiques de la flore microbienne résidente, on retient : (cocher la bonne réponse)', '', $medjson$[{"key":"A","text":"Elle est d’acquisition récente à partir de l’environnement hospitalier lors des activités de soins"},{"key":"B","text":"Elle est difficile à enlever par les gestes d’hygiène courants"},{"key":"C","text":"Elle est facile à enlever par les gestes d’hygiène courants"},{"key":"D","text":"Elle est toujours pathogène"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'La flore résidente est profonde, propre à l’individu, rarement pathogène et difficile à éliminer par les gestes d’hygiène courants.', $medjson${"A":"Caractéristique de la flore TRANSITOIRE.","C":"Caractéristique de la flore TRANSITOIRE.","D":"Faux : elle constitue au contraire un risque faible d’infections manuportées."}$medjson$::jsonb, NULL, FALSE, 'Volet Hygiène des mains (BM Ch. 10 Q8, Q16 & Q19)') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C6_13', 'C6', 'L6.3', 'Pré-requis hygiène des mains (alliance)', 'bm_original', 'Ch. 10 Q7', '2021', '', NULL, '', '', TRUE, FALSE, FALSE, 'Les règles qu’on doit respecter avant l’hygiène des mains sont appelées : pré-requis. Parmi les propositions suivantes choisir les règles correctes :', '', $medjson$[{"key":"A","text":"Les ongles doivent être courts"},{"key":"B","text":"Pas de vernis à ongles"},{"key":"C","text":"L’alliance lisse est autorisée"},{"key":"D","text":"Pas de bijoux"}]$medjson$::jsonb, $medjson$["A","B","D"]$medjson$::jsonb, 'Les pré-requis exigent ongles courts (A), sans vernis (B) et absence totale de bijoux (D).', $medjson${"C":"Piège classique ! Même l’alliance lisse est INTERDITE en milieu de soins."}$medjson$::jsonb, NULL, FALSE, 'Volet Hygiène des mains (BM Ch. 10 Q7)') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C7_1', 'C7', 'L7.1', 'Rattachement EPSP de l’équipe (2025)', 'bm_original', 'Ch. 26 Q1', '2025', '', NULL, '', '', FALSE, TRUE, FALSE, 'L’équipe de santé assurant la prise en charge des enfants scolarisés, exerce au sein :', '', $medjson$[{"key":"A","text":"Des structures de santé de proximité de terrain"},{"key":"B","text":"Des structures de santé privées"},{"key":"C","text":"Un centre hospitalo-universitaire"},{"key":"D","text":"Service de pédiatrie d’un hôpital"}]$medjson$::jsonb, $medjson$["A"]$medjson$::jsonb, 'Slide 15 : les équipes de santé scolaire (médecin, infirmier, chirurgien-dentiste, assistant médical, psychologue) sont rattachées aux EPSP, c’est-à-dire aux structures de santé de proximité de terrain.', $medjson${"B":"Programme national public, pas le secteur privé.","C":"Le CHU relève du 3ème recours, pas de la santé scolaire de terrain.","D":"Les services hospitaliers reçoivent uniquement les cas référés."}$medjson$::jsonb, NULL, TRUE, 'Santé scolaire — Dr Nourani Imane, slide 15') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C7_2', 'C7', 'L7.1', 'Prise en charge en milieu scolaire : UDS (2025)', 'bm_original', 'Ch. 26 Q3', '2025', '', NULL, '', '', FALSE, FALSE, FALSE, 'La prise en charge sanitaire des enfants scolarisés en milieu scolaire se fait au niveau :', '', $medjson$[{"key":"A","text":"Des structures de santé privées"},{"key":"B","text":"De pédiatrie"},{"key":"C","text":"Structures de santé de proximité"},{"key":"D","text":"Des unités de dépistage et de suivi UDS"}]$medjson$::jsonb, $medjson$["D"]$medjson$::jsonb, 'En milieu scolaire (collèges et lycées), la prise en charge se fait au niveau des Unités de Dépistage et de Suivi (UDS) couvrant une circonscription (slide 15).', $medjson${"A":"Faux.","B":"Faux.","C":"Les structures de proximité (EPSP) sont le rattachement de l’équipe (Q1) ; en milieu scolaire le local dédié est l’UDS (D)."}$medjson$::jsonb, NULL, TRUE, 'Santé scolaire — Dr Nourani Imane, slide 15') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C7_3', 'C7', 'L7.1', 'Objectif principal de la santé scolaire (2025)', 'bm_original', 'Ch. 26 Q5', '2025', '', NULL, '', '', FALSE, FALSE, FALSE, 'Quel est l’objectif principal du programme de santé scolaire ?', '', $medjson$[{"key":"A","text":"Assurer une couverture vaccinale nationale"},{"key":"B","text":"Fournir aux enfants et adolescents des prestations préventives, curatives et éducatives pour un développement harmonieux"},{"key":"C","text":"Réduire les dépenses en matière de santé publique"},{"key":"D","text":"Promouvoir uniquement la vaccination en milieu scolaire"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Formulation exacte de la slide 13 : prestations préventives, curatives et éducatives visant un développement harmonieux physique, mental, intellectuel et social.', $medjson${"A":"La couverture vaccinale nationale est l’objectif global du PEV, pas l’objectif unique de la santé scolaire.","C":"Faux.","D":"Trop restrictif (« uniquement la vaccination »)."}$medjson$::jsonb, NULL, FALSE, 'Santé scolaire — Dr Nourani Imane, slide 13') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C7_4', 'C7', 'L7.1', 'Population cible & mission des UDS (2025)', 'bm_original', 'Ch. 26 Q7', '2025', '', NULL, '', '', FALSE, FALSE, FALSE, 'Quelle est la population cible principale du programme de santé scolaire ?', '', $medjson$[{"key":"A","text":"Les enfants scolarisés et les enseignants"},{"key":"B","text":"Les enfants et les personnes âgées"},{"key":"C","text":"Les enseignants uniquement"},{"key":"D","text":"L’ensemble des citoyens"}]$medjson$::jsonb, $medjson$["A"]$medjson$::jsonb, 'Slide 12 : la population cible regroupe les enfants scolarisés, le personnel enseignant et le personnel administratif/de service.', $medjson${"B":"Les personnes âgées ne sont pas visées par la santé scolaire.","C":"Omet la cible première : les élèves.","D":"Programme en milieu spécifique scolaire, pas toute la population."}$medjson$::jsonb, NULL, FALSE, 'Santé scolaire — Dr Nourani Imane, slide 12') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C7_5', 'C7', 'L7.2', 'Classes cibles vaccination scolaire (2025)', 'bm_original', 'Ch. 26 Q4', '2025', '', NULL, '', '', FALSE, TRUE, FALSE, 'La vaccination des élèves concernés, conformément au calendrier national de vaccination en vigueur, cible les classes de :', '', $medjson$[{"key":"A","text":"1ère année primaire, 2ème année moyenne, 1ère année secondaire"},{"key":"B","text":"1ère année primaire, 2ème année moyenne, 3ème année secondaire"},{"key":"C","text":"3ème année primaire, 2ème année moyenne, 1ère année secondaire"},{"key":"D","text":"1ère année primaire, 1ère année moyenne, 1ère année secondaire"}]$medjson$::jsonb, $medjson$["D"]$medjson$::jsonb, 'Slides 13 et 18 : la vaccination scolaire cible la 1ère année de chaque cycle : 1ère AP, 1ère AM et 1ère AS (+ rattrapage).', $medjson${"A":"Piège ! La 2ème AM est ciblée par la santé BUCCO-DENTAIRE, pas par la vaccination.","B":"2ème AM et 3ème AS sont fausses.","C":"3ème AP et 2ème AM sont fausses."}$medjson$::jsonb, NULL, TRUE, 'Santé scolaire — Dr Nourani Imane, slides 13 & 18') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C7_6', 'C7', 'L7.2', 'Évaluation de la vaccination scolaire (2025)', 'bm_original', 'Ch. 26 Q2', '2025', '', NULL, '', '', FALSE, FALSE, FALSE, 'L’évaluation de l’activité de vaccination dans le cadre du programme national de santé scolaire, se fait :', '', $medjson$[{"key":"A","text":"Par combien d’élèves ont été examinés"},{"key":"B","text":"Par le nombre d’élèves traités pour une ou plusieurs pathologies"},{"key":"C","text":"Par le taux de couverture vaccinale par antigène"},{"key":"D","text":"Par la population des classes-cibles / population scolaire totale"}]$medjson$::jsonb, $medjson$["C"]$medjson$::jsonb, 'Slides 26–27 et 33 : l’indicateur d’activité spécifique de la vaccination scolaire est le taux de couverture vaccinale par antigène (Vaccinés / Population cible).', $medjson${"A":"Mesure l’activité de visite médicale / dépistage général.","B":"Mesure l’activité curative.","D":"Proportion démographique qui ne mesure pas la vaccination réalisée."}$medjson$::jsonb, NULL, TRUE, 'Santé scolaire — Dr Nourani Imane, slides 26–27 & 33') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C7_7', 'C7', 'L7.2', 'Élimination du trachome au Sud (2025)', 'bm_original', 'Ch. 13 Q3', '2025', '', NULL, '', '', FALSE, TRUE, FALSE, 'Quelle maladie est ciblée par la campagne d’élimination dans les wilayas du Sud ?', '', $medjson$[{"key":"A","text":"La tuberculose miliaire de l’enfant"},{"key":"B","text":"Marasme et kwashiorkor"},{"key":"C","text":"Tuberculose pulmonaire, extra-pulmonaire"},{"key":"D","text":"Aucune des réponses"}]$medjson$::jsonb, $medjson$["D"]$medjson$::jsonb, 'Slide 19 du cours Santé scolaire : la campagne accélérée d’élimination dans les wilayas du Sud cible le TRACHOME ! Comme il ne figure dans aucune des propositions A–C, la bonne réponse est D.', $medjson${"A":"Faux (piège de classement BM dans Ch. 13).","B":"Faux.","C":"Faux."}$medjson$::jsonb, NULL, FALSE, 'Santé scolaire — Dr Nourani Imane, slide 19') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C7_8', 'C7', 'L7.3', 'Santé bucco-dentaire (« Stop à la carie »)', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, 'Concernant le programme de santé bucco-dentaire (« Stop à la carie ») et le contrôle d’hygiène scolaire, cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"Les classes cibles bucco-dentaires sont : Préscolaire, 1ère AP, 4ème AP, 2ème AM et 1ère AS"},{"key":"B","text":"La polyclinique de l’EPSP réserve au moins 2 après-midi par semaine aux élèves"},{"key":"C","text":"Les travailleurs des cantines scolaires subissent des examens médicaux au moins 2 fois par an"},{"key":"D","text":"Les rapports d’évaluation des SEMEP/EPSP sont transmis uniquement une fois par an en fin d’année"}]$medjson$::jsonb, $medjson$["A","B","C"]$medjson$::jsonb, 'Classes bucco-dentaires (A), créneaux EPSP ≥ 2 après-midi/semaine (B) et cantines ≥ 2 visites/an (C) sont conformes aux slides 20–22.', $medjson${"D":"Faux : les rapports sont TRIMESTRIELS (transmis aux directeurs d’établissements et à la DSP)."}$medjson$::jsonb, NULL, FALSE, 'Santé scolaire — Dr Nourani Imane, slides 20–27') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C7_9', 'C7', 'L7.3', 'Indices carieux cao vs CAO', 'course_generated', '', 'Cours', '', NULL, '', '', FALSE, FALSE, FALSE, 'Dans les supports d’évaluation bucco-dentaire scolaire, que mesure l’indice « CAO » (en majuscules) ?', '', $medjson$[{"key":"A","text":"Les dents temporaires (de lait) cariées, absentes ou obturées"},{"key":"B","text":"Les dents permanentes de 6 ans cariées, absentes ou obturées"},{"key":"C","text":"Le taux de couverture vaccinale antitétanique"},{"key":"D","text":"Le pourcentage de cantines conformes"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Par convention dentaire du cours (slides 34–36), « cao » (minuscules) concerne les dents temporaires et « CAO » (majuscules) les dents permanentes de 6 ans.', $medjson${"A":"Correspond à « cao » en minuscules.","C":"Sans rapport.","D":"Sans rapport."}$medjson$::jsonb, NULL, FALSE, 'Santé scolaire — Dr Nourani Imane, slides 34–36') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C7_10', 'C7', 'L7.3', 'Équipe UDS & Comité de wilaya', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, FALSE, FALSE, 'Parmi les affirmations suivantes sur l’organisation de la santé scolaire, lesquelles sont exactes ?', '', $medjson$[{"key":"A","text":"L’équipe complète d’une UDS comprend médecin, infirmier, chirurgien-dentiste, assistant médical et psychologue"},{"key":"B","text":"Les UDS sont implantées au niveau des collèges et lycées"},{"key":"C","text":"Le Comité de wilaya se réunit au début de l’année scolaire et chaque trimestre"},{"key":"D","text":"Les écoles privées agréées sont exclues du programme de dépistage systématique"}]$medjson$::jsonb, $medjson$["A","B","C"]$medjson$::jsonb, 'Équipe de 5 profils (A), implantation collèges/lycées (B) et réunions du Comité de wilaya (C) sont exactes.', $medjson${"D":"Faux : le dépistage concerne les établissements publics ET privés agréés."}$medjson$::jsonb, NULL, FALSE, 'Santé scolaire — Dr Nourani Imane, slides 15–27') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C8_1', 'C8', 'L8.1', 'Décret 22-178, exemplaire unique & volets', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, 'Selon le Décret exécutif n° 22-178 du 28 avril 2022 relatif au Certificat Médical de Décès (CMD), cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"Le CMD peut être établi par tout médecin autorisé à exercer (public, privé/libéral, militaire ou sûreté nationale)"},{"key":"B","text":"Il est délivré en deux exemplaires originaux : un pour l’APC et un pour l’INSP"},{"key":"C","text":"Sa partie supérieure est nominative (volet administratif) et sa partie inférieure est anonyme (volet médical immédiatement scellé par le médecin)"},{"key":"D","text":"Le délai de déclaration à l’APC est de 24 heures, porté à 20 jours dans les wilayas du Sud"}]$medjson$::jsonb, $medjson$["A","C","D"]$medjson$::jsonb, 'Articles 2 et 5 du Décret 22-178 + délais réglementaires (24 h / 20 j Sud).', $medjson${"B":"Piège Art. 4 ! Le CMD est délivré en UN SEUL EXEMPLAIRE."}$medjson$::jsonb, NULL, FALSE, 'CMD — Décret 22-178 (Art. 2, 4, 5) & modele de cmd et circuit.pptx') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C8_2', 'C8', 'L8.1', 'Circuit du volet médical & signalements', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, FALSE, FALSE, 'Concernant le circuit administratif et le formulaire du CMD en Algérie, cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"Le circuit du volet médical suit l’ordre : Médecin → Famille → APC → DSP (SEMEP) → INSP"},{"key":"B","text":"La transmission du volet inférieur par l’APC vers la DSP s’effectue mensuellement avec bordereau"},{"key":"C","text":"Le médecin doit signaler la présence d’une prothèse fonctionnant avec pile ou le besoin de mise en cercueil hermétique"},{"key":"D","text":"Le Décret 22-178 a remplacé la loi sanitaire de 1985 uniquement"}]$medjson$::jsonb, $medjson$["A","B","C"]$medjson$::jsonb, 'Circuit mensuel APC → DSP (SEMEP) → INSP (A, B) et les 3 signalements particuliers dont prothèse à pile et cercueil hermétique (C) sont exacts.', $medjson${"D":"Le Décret 22-178 (28/04/2022) abroge précisément le décret exécutif n° 16-80 du 24/02/2016."}$medjson$::jsonb, NULL, FALSE, 'modele de cmd et circuit.pptx, slides 4–14 ; Formulaire CMD') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C8_3', 'C8', 'L8.1', 'Rôle du SEMEP et de l’INSP', 'course_generated', '', 'Cours', '', NULL, '', '', FALSE, FALSE, FALSE, 'Dans le circuit national des causes médicales de décès, quel organisme assure la codification CIM-10 finale, l’exploitation statistique et l’archivage national ?', '', $medjson$[{"key":"A","text":"L’officier d’état civil de l’APC"},{"key":"B","text":"Le service des causes de décès de l’INSP"},{"key":"C","text":"La CNAS"},{"key":"D","text":"Le Bureau d’Hygiène Communale (BHC)"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'L’APC conserve le volet nominatif ; le SEMEP/DSP récupère mensuellement les volets médicaux et contrôle leur qualité ; l’INSP assure l’exploitation, la codification CIM-10 et l’archivage.', $medjson${"A":"Volet administratif uniquement.","C":"Caisse de sécurité sociale, hors circuit CMD.","D":"Intervient sur l’hygiène/TIAC, pas la codification CMD."}$medjson$::jsonb, NULL, FALSE, 'modele de cmd et circuit.pptx, slides 10–15') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C8_4', 'C8', 'L8.2', 'Cas clinique Partie I vs II & piège ACR', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, 'Un patient alcoolique suivi pour hépatite B chronique → cirrhose → hypertension portale décède d’un arrêt cardio-respiratoire (ACR) sur rupture de varices œsophagiennes. Comment remplir le CMD ?', '', $medjson$[{"key":"A","text":"Inscrire « Arrêt cardio-respiratoire » sur la dernière ligne de la Partie I comme cause initiale"},{"key":"B","text":"Inscrire « Hémorragie par rupture de varices œsophagiennes » sur la ligne a) (cause directe) de la Partie I"},{"key":"C","text":"Inscrire « Hépatite virale B chronique » sur la ligne la plus basse remplie (d) comme cause initiale"},{"key":"D","text":"Inscrire « Alcoolisme chronique » en Partie II (comorbidité contributive)"}]$medjson$::jsonb, $medjson$["B","C","D"]$medjson$::jsonb, 'La Partie I se lit de haut en bas : a) cause directe (hémorragie VO, B) ← b) HTP ← c) cirrhose ← d) cause initiale (hépatite B, C — retenue pour stats OMS). Les comorbidités sans lien causal direct vont en Partie II (D).', $medjson${"A":"Interdiction absolue ! L’ACR est un mode de décès, JAMAIS une cause initiale."}$medjson$::jsonb, NULL, FALSE, 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx, slides 10–20') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C8_5', 'C8', 'L8.2', 'Mort violente (Art. 6.2) & Partie III', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, 'Devant un décès par mort violente, suspecte ou de cause indéterminée (Art. 6.2 du Décret 22-178), cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"Le médecin constatant remplit uniquement la partie supérieure (volet administratif) et avise les autorités"},{"key":"B","text":"La Partie III du volet médical est réservée exclusivement au médecin légiste"},{"key":"C","text":"Le médecin constatant doit quand même remplir les Parties I et II et sceller le certificat"},{"key":"D","text":"Le certificat doit être rédigé lisiblement en majuscules et sans aucune abréviation"}]$medjson$::jsonb, $medjson$["A","B","D"]$medjson$::jsonb, 'En cas de mort violente/suspecte (Art. 6.2), le médecin constatant remplit uniquement la partie supérieure (A) et le médecin légiste remplit la Partie III (B). Rédaction toujours en majuscules sans abréviation (D).', $medjson${"C":"Faux : remplir Parties I et II concerne exclusivement la mort naturelle (Art. 6.1)."}$medjson$::jsonb, NULL, FALSE, 'Republique-Algerienne…pptx (Art. 6) ; modele de cmd et circuit.pptx') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C8_6', 'C8', 'L8.2', 'Cause retenue pour les statistiques OMS', 'course_generated', '', 'Cours', '', NULL, '', '', FALSE, FALSE, FALSE, 'Pour l’établissement des statistiques mondiales de mortalité (OMS), quelle cause du CMD est retenue ?', '', $medjson$[{"key":"A","text":"La cause directe (ligne a de la Partie I)"},{"key":"B","text":"La cause initiale (dernière ligne remplie de la Partie I)"},{"key":"C","text":"La comorbidité inscrite en Partie II"},{"key":"D","text":"Le mode de décès (arrêt cardio-respiratoire)"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'L’OMS sélectionne la cause initiale (maladie ou traumatisme ayant déclenché la séquence morbide), afin d’orienter la prévention à la racine.', $medjson${"A":"La cause directe est la complication finale, pas la cause statistique OMS.","C":"La Partie II regroupe les états contributifs secondaires.","D":"L’ACR est proscrit comme cause de décès."}$medjson$::jsonb, NULL, FALSE, 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx, slides 10–14') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C8_7', 'C8', 'L8.3', 'Les 4 groupes CIM-10 EXCLUS comme cause initiale', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, 'Parmi les catégories CIM-10 suivantes, lesquelles sont FORMELLEMENT EXCLUES comme cause initiale de décès ?', '', $medjson$[{"key":"A","text":"B95–B97 (agents bactériens et viraux isolés)"},{"key":"B","text":"O80–O84 (accouchement normal/simple)"},{"key":"C","text":"S00–T98 (lésions traumatiques seules sans cause externe)"},{"key":"D","text":"G97, H95, N99 (affections post-actes médicaux ou chirurgicaux)"},{"key":"E","text":"C97 (tumeurs malignes de sièges primitifs multiples indépendants en Partie I)"}]$medjson$::jsonb, $medjson$["A","B","C","D"]$medjson$::jsonb, 'A, B, C et D constituent exactement les 4 groupes CIM-10 exclus comme cause initiale (pour un traumatisme, il faut coder la cause externe ex. AVP !).', $medjson${"E":"C97 est au contraire un code valide utilisé lorsque 2 tumeurs primitives indépendantes figurent en Partie I."}$medjson$::jsonb, NULL, FALSE, 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx, slides 24–33') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C8_8', 'C8', 'L8.3', 'Règles tumeurs (C97, C34) & Décès maternel', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, 'À propos des règles particulières de certification (tumeurs et décès maternel), cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"Deux tumeurs primitives indépendantes toutes deux en Partie I se codent en C97"},{"key":"B","text":"Si une tumeur primitive est en Partie I et une seconde en Partie II, on code aussi en C97"},{"key":"C","text":"Une lésion pulmonaire (C34) associée à une autre tumeur est présumée métastatique, mais un « cancer bronchique » est considéré comme tumeur primitive"},{"key":"D","text":"Un décès maternel couvre la grossesse, l’accouchement/avortement et les 42 jours suivant la fin de la gestation"}]$medjson$::jsonb, $medjson$["A","C","D"]$medjson$::jsonb, 'Règles exactes du cours : C97 si 2 primitives en Partie I (A), distinction C34 métastase vs cancer bronchique primitif (C), délai 42 jours pour décès maternel (D).', $medjson${"B":"Piège du cours ! Si la 2ème tumeur est en Partie II, on IGNORE la Partie II pour le codage C97."}$medjson$::jsonb, NULL, FALSE, 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx, slides 28–36') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C8_9', 'C8', 'L8.3', 'Cause externe d’un traumatisme (AVP)', 'course_generated', '', 'Cours', '', NULL, '', '', FALSE, FALSE, FALSE, 'Un piéton décède d’une hémorragie intracrânienne suite à un traumatisme crânien lors d’un accident de la voie publique (AVP). Quelle est la cause initiale à coder en CIM-10 ?', '', $medjson$[{"key":"A","text":"L’hémorragie intracrânienne"},{"key":"B","text":"Le traumatisme crânien (code S00–T98)"},{"key":"C","text":"La cause externe : l’accident de la voie publique (AVP)"},{"key":"D","text":"L’arrêt cardio-respiratoire"}]$medjson$::jsonb, $medjson$["C"]$medjson$::jsonb, 'Les lésions traumatiques (S00–T98) étant exclues comme cause initiale, la codification retient toujours la CAUSE EXTERNE (ici l’AVP).', $medjson${"A":"Cause directe/intermédiaire.","B":"Groupe S00–T98 formellement exclu comme cause initiale.","D":"Mode de décès proscrit."}$medjson$::jsonb, NULL, FALSE, 'Certification-de-la-Cause-Medicale-de-Deces2(3).pptx, slides 24–27') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C9_1', 'C9', 'L9.1', 'Financement de la sécurité sociale en Algérie', 'bm_original', 'Ch. 15 Q1', '2023', '', NULL, '', '', TRUE, TRUE, FALSE, 'Le financement du système de la sécurité sociale en Algérie est assuré par : (cocher la ou les réponses justes)', '', $medjson$[{"key":"A","text":"Les cotisations à la charge des employeurs et des travailleurs"},{"key":"B","text":"Les taxes et des prélèvements effectués sur des produits à partir de la fiscalité"},{"key":"C","text":"Dépenses totales de santé des ménages"},{"key":"D","text":"Par les biens achetés et consommés par les ménages"}]$medjson$::jsonb, $medjson$["A"]$medjson$::jsonb, 'Slide 10 : le financement propre de la sécurité sociale (CNAS/CASNOS) provient des cotisations obligatoires à la charge des employeurs et des travailleurs. (Attention : Ch. 40 Q1 qui demande le financement du « système de santé » global inclut aussi fiscalité et ménages).', $medjson${"B":"La fiscalité alimente le budget général de l’État (financement public).","C":"Correspond au financement privé direct par les ménages.","D":"Définit la consommation médicale, pas les recettes de la sécurité sociale."}$medjson$::jsonb, NULL, TRUE, 'Financement du système de santé, slides 7–11') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C9_2', 'C9', 'L9.1', 'Coût d’investissement d’un projet sanitaire', 'bm_original', 'Ch. 15 Q3', '2022', '', NULL, '', '', FALSE, FALSE, FALSE, 'Le coût d’investissement est le coût en capital d’un projet sanitaire, il regroupe généralement : (choisir la bonne réponse)', '', $medjson$[{"key":"A","text":"Les coûts de terrains, des bâtiments, des équipements lourds et semi-lourds"},{"key":"B","text":"Les coûts nécessaires à l’exploitation de l’investissement"},{"key":"C","text":"Les coûts des petites réparations"},{"key":"D","text":"Ce sont des coûts répétitifs"}]$medjson$::jsonb, $medjson$["A"]$medjson$::jsonb, 'Le coût d’investissement (en capital) comprend les terrains, constructions/bâtiments et équipements lourds ou semi-lourds.', $medjson${"B":"Définit le coût de fonctionnement.","C":"Relève du coût de fonctionnement.","D":"Les coûts répétitifs sont des coûts de fonctionnement (l’investissement est non répétitif)."}$medjson$::jsonb, NULL, FALSE, 'BM Ch. 15 Q3 (2022) — Financement / gestion de projet') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C9_3', 'C9', 'L9.1', 'CNAS / CASNOS & Ticket modérateur', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, FALSE, FALSE, 'Concernant la sécurité sociale et le financement en Algérie, cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"La CNAS couvre les travailleurs salariés et la CASNOS couvre les travailleurs non-salariés"},{"key":"B","text":"Le taux standard de remboursement des médicaments est de 80 % (ticket modérateur = 20 %), porté à 100 % pour les maladies chroniques"},{"key":"C","text":"La contribution symbolique des ménages représente 45 % du budget de fonctionnement des hôpitaux publics"},{"key":"D","text":"L’assurance-maladie algérienne couvre 5 risques : maladie, maternité, invalidité, AT et MP"}]$medjson$::jsonb, $medjson$["A","B","D"]$medjson$::jsonb, 'CNAS/CASNOS (A), règle 80 % / 20 % / 100 % (B) et 5 risques couverts (D) sont exacts.', $medjson${"C":"Faux : la contribution des ménages aux établissements publics est symbolique : 1,20 % seulement (depuis 1974 / arrêté 1995)."}$medjson$::jsonb, NULL, FALSE, 'Financement du système de santé, slides 8–11') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C9_4', 'C9', 'L9.2', 'Critère d’équité (2× en BM)', 'bm_original', 'Ch. 15 Q2 (= Q4)', '2022', '', NULL, '', '', FALSE, FALSE, FALSE, 'L’équité est un critère d’évaluation d’un système de financement de la santé qui permet d’apprécier : (choisir la bonne réponse)', '', $medjson$[{"key":"A","text":"L’accès aux soins"},{"key":"B","text":"La continuité des services prodigués par un système de santé"},{"key":"C","text":"L’efficacité d’un système de financement de la santé"},{"key":"D","text":"Les objectifs d’un système de financement de la santé"}]$medjson$::jsonb, $medjson$["A"]$medjson$::jsonb, 'Slide 18 : l’équité évalue l’accès financier aux soins pour l’ensemble de la population (tombé à l’identique en 2021 et 2022).', $medjson${"B":"La continuité des services définit le critère de PÉRENNITÉ.","C":"L’efficacité est un critère distinct de l’équité.","D":"Formulation vague non spécifique."}$medjson$::jsonb, NULL, FALSE, 'Financement du système de santé, slide 18') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C9_5', 'C9', 'L9.2', 'Financement privé : avantages & limites', 'bm_original', 'Ch. 15 Q5', 'ND', '', NULL, '', '', FALSE, TRUE, FALSE, 'Le financement privé des dépenses de santé permet de :', '', $medjson$[{"key":"A","text":"Assurer l’équité dans l’accès aux soins"},{"key":"B","text":"Fournir d’autres ressources à la santé"},{"key":"C","text":"Ne permet pas d’éviter le gaspillage"},{"key":"D","text":"Permet la pérennité des services de santé"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Le financement privé allège l’État, fournit des ressources additionnelles à la santé (B) et évite le gaspillage.', $medjson${"A":"Faux : son défaut majeur est au contraire l’inéquité et l’exclusion des pauvres.","C":"Piège de négation : selon le cours, le privé PERMET d’éviter le gaspillage !","D":"La pérennité repose surtout sur les financements collectifs/publics."}$medjson$::jsonb, NULL, FALSE, 'Financement du système de santé, slides 9 & 18–19') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C9_6', 'C9', 'L9.2', 'Matrice Public / Sécu / Privé', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, FALSE, FALSE, 'Selon la matrice d’évaluation du cours (slides 18–19), cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"Le financement public assure l’équité mais n’est pas entièrement efficace (lourdeurs bureaucratiques)"},{"key":"B","text":"La sécurité sociale assure l’équité et est efficace si un contrôle rigoureux existe"},{"key":"C","text":"La pérennité apprécie la continuité des services dans le temps"},{"key":"D","text":"Le financement privé assure à la fois l’équité et l’efficacité"}]$medjson$::jsonb, $medjson$["A","B","C"]$medjson$::jsonb, 'Public = équitable mais bureaucratique (A) ; Sécu = équitable et efficace si contrôlée (B) ; Pérennité = continuité (C).', $medjson${"D":"Faux : le privé n’assure PAS l’équité (exclusion financière des pauvres)."}$medjson$::jsonb, NULL, FALSE, 'Financement du système de santé, slides 18–19') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C9_7', 'C9', 'L9.3', 'Niveaux Macro, Méso et Micro-économique', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, 'Concernant les 3 niveaux d’analyse économique du financement (slides 13–17), cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"L’analyse du ratio Dépenses Nationales de Santé / PIB (DNS/PIB) relève du niveau macro-économique"},{"key":"B","text":"Au niveau méso-économique, les dépenses de personnel représentent environ 80 % du budget d’un établissement"},{"key":"C","text":"L’analyse de la gestion d’un CHU ou du coût d’un GHM relève du niveau micro-économique"},{"key":"D","text":"En Algérie, le ratio DNS/PIB atteignait 7,23 % en 2018 (contre 4,57 % en 1993)"}]$medjson$::jsonb, $medjson$["A","B","C","D"]$medjson$::jsonb, 'Les 4 items correspondent exactement aux définitions et chiffres des slides 13–17 et 21 du cours.', $medjson${}$medjson$::jsonb, NULL, FALSE, 'Financement du système de santé, slides 13–17 & 21') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C9_8', 'C9', 'L9.3', 'Distinction Méso vs Micro', 'course_generated', '', 'Cours', '', NULL, '', '', FALSE, FALSE, FALSE, 'L’étude de la consommation pharmaceutique ou du coût précis d’une intervention chirurgicale dans un CHU relève du niveau :', '', $medjson$[{"key":"A","text":"Macro-économique"},{"key":"B","text":"Méso-économique"},{"key":"C","text":"Micro-économique"},{"key":"D","text":"Externe / international"}]$medjson$::jsonb, $medjson$["C"]$medjson$::jsonb, 'Le niveau micro-économique étudie une unité de soins précise (un CHU, un service, un acte/GHM, la consommation de médicaments).', $medjson${"A":"Macro = échelle nationale/régionale (DNS/PIB).","B":"Méso = échelle globale du secteur de la santé (structure budgétaire sectorielle).","D":"Faux."}$medjson$::jsonb, NULL, FALSE, 'Financement du système de santé, slides 16–17') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C9_9', 'C9', 'L9.3', 'Problématique de financement & DNS/PIB', 'course_generated', '', 'Cours', '', NULL, '', '', FALSE, FALSE, FALSE, 'Quelle est la problématique économique fondamentale à l’origine de l’étude du financement des systèmes de santé ?', '', $medjson$[{"key":"A","text":"Des ressources illimitées face à une demande décroissante"},{"key":"B","text":"La rareté des ressources face à la croissance continue des dépenses de santé"},{"key":"C","text":"L’absence de dépenses de personnel dans les hôpitaux publics"},{"key":"D","text":"La gratuité absolue du secteur privé"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Toute l’économie de la santé repose sur la rareté des ressources limitées face à une demande et des dépenses en croissance constante, imposant une meilleure allocation.', $medjson${"A":"Exact inverse (ressources limitées, dépenses croissantes).","C":"Les dépenses de personnel représentent au contraire ~80 % du budget !","D":"Faux."}$medjson$::jsonb, NULL, FALSE, 'Financement du système de santé, slides 2–3') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C10_1', 'C10', 'L10.1', 'Place du questionnaire (2025)', 'bm_original', 'Ch. 34 Q1', '2025', '', NULL, '', '', FALSE, FALSE, FALSE, 'Dans une étude épidémiologique le questionnaire est :', '', $medjson$[{"key":"A","text":"Fait à la fin du protocole"},{"key":"B","text":"Élaboré dans la phase de planification"},{"key":"C","text":"Est détaillé dans la partie « Discussion »"},{"key":"D","text":"Ne répond pas à l’objectif de l’étude"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Page 1 du cours de Dr Chiboub : le questionnaire est élaboré durant la phase de planification de l’étude (tombé en 2024 ET 2025).', $medjson${"A":"Jamais à la fin : il doit être prêt et pré-testé avant la collecte.","C":"Il est décrit dans Matériel et Méthodes, pas dans Discussion.","D":"L’objectif de l’étude guide directement la rédaction du questionnaire."}$medjson$::jsonb, NULL, FALSE, 'Élaboration du questionnaire d’une étude — Dr Chiboub B., p. 1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C10_2', 'C10', 'L10.1', 'Place du questionnaire (2024)', 'bm_original', 'Ch. 9 Q1', '2024', '', NULL, '', '', FALSE, FALSE, FALSE, 'Dans une étude épidémiologique le questionnaire est :', '', $medjson$[{"key":"A","text":"Fait à la fin du travail"},{"key":"B","text":"Élaboré dans la phase de planification"},{"key":"C","text":"Ne répond pas à l’objectif de l’étude"},{"key":"D","text":"Explique la problématique du sujet"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Doublon quasi-identique de Ch. 34 Q1 (2025) : élaboré dans la phase de planification.', $medjson${"A":"Faux.","C":"Faux : l’étape 1 consiste justement à définir l’objectif.","D":"La problématique relève de l’introduction du protocole, pas du questionnaire."}$medjson$::jsonb, NULL, FALSE, 'Élaboration du questionnaire d’une étude — Dr Chiboub B., p. 1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C10_3', 'C10', 'L10.1', 'Titre, structure & 7 étapes', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, 'Concernant la présentation et la structuration d’un questionnaire (Dr Chiboub), cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"Il est conseillé d’éviter le mot « Questionnaire » dans le titre car il est jugé péjoratif"},{"key":"B","text":"Les questions sont classées par thème en allant du général au spécifique"},{"key":"C","text":"On commence par des questions simples pour mettre le répondant en confiance"},{"key":"D","text":"Le questionnaire est une technique de collecte de données non quantifiables"}]$medjson$::jsonb, $medjson$["A","B","C"]$medjson$::jsonb, 'Titre sans « Questionnaire » (A), structure thématique général → spécifique (B) et début par questions simples (C) sont des règles exactes de la p. 1.', $medjson${"D":"Faux : le questionnaire collecte des données QUANTIFIABLES."}$medjson$::jsonb, NULL, FALSE, 'Élaboration du questionnaire d’une étude — Dr Chiboub B., p. 1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C10_4', 'C10', 'L10.2', 'Types de questions & seuils', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, 'Concernant les types de questions dans un questionnaire (Dr Chiboub), cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"Pour une question fermée ordonnée (classement hiérarchique), on ne doit pas dépasser 3 propositions"},{"key":"B","text":"Les questions ouvertes sont à éviter autant que possible car leur dépouillement est plus long"},{"key":"C","text":"Lors du dépouillement (Étape 7), les questions ouvertes doivent être codifiées"},{"key":"D","text":"Les questions fermées à choix multiples n’influencent jamais les réponses"}]$medjson$::jsonb, $medjson$["A","B","C"]$medjson$::jsonb, 'Classement ≤ 3 propositions (A), éviter les ouvertes (B) et codifier les ouvertes au dépouillement (C) figurent p. 1–2.', $medjson${"D":"Faux : le cours mentionne précisément que les QCM peuvent influencer les réponses (et présenter une liste trop longue)."}$medjson$::jsonb, NULL, FALSE, 'Élaboration du questionnaire d’une étude — Dr Chiboub B., p. 1–2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C10_5', 'C10', 'L10.2', 'Pré-test (4 buts) & E-mailing', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, 'Concernant le pré-test (Étape 5) et les modes d’administration (Étape 6), cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"Le pré-test vérifie la conception des questions, l’adaptation des modalités, les oublis éventuels et le temps réel de passation"},{"key":"B","text":"L’administration par courriel (e-mailing) est rapide mais peu efficace (environ 5 % de retour)"},{"key":"C","text":"L’administration en face à face permet un contact direct et l’observation des réactions"},{"key":"D","text":"Le pré-test est facultatif lorsque le questionnaire comporte moins de 20 questions"}]$medjson$::jsonb, $medjson$["A","B","C"]$medjson$::jsonb, 'Les 4 vérifications du pré-test (A), le faible taux de retour de l’e-mailing ~5 % (B) et les avantages du face à face (C) sont exacts.', $medjson${"D":"Faux : le pré-test est une étape systématique et obligatoire (Étape 5)."}$medjson$::jsonb, NULL, FALSE, 'Élaboration du questionnaire d’une étude — Dr Chiboub B., p. 2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C10_6', 'C10', 'L10.2', 'Ordre des étapes : Pré-test', 'course_generated', '', 'Cours', '', NULL, '', '', FALSE, FALSE, FALSE, 'À quel moment intervient le pré-test dans les 7 étapes d’élaboration d’un questionnaire ?', '', $medjson$[{"key":"A","text":"Après le dépouillement statistique final"},{"key":"B","text":"Juste avant l’administration finale (Étape 5 sur 7)"},{"key":"C","text":"Avant même de définir les objectifs de l’étude"},{"key":"D","text":"Uniquement pour les questionnaires par courriel"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Le pré-test est l’Étape 5 : après choix des modalités (Étape 4) et avant l’administration sur le terrain (Étape 6).', $medjson${"A":"Trop tard, les données seraient déjà collectées.","C":"L’Étape 1 est toujours la définition des objectifs.","D":"Il s’applique à tous les modes d’administration."}$medjson$::jsonb, NULL, FALSE, 'Élaboration du questionnaire d’une étude — Dr Chiboub B., p. 2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C11_1', 'C11', 'L11.1', 'Graphique stades d’une affection chronique (2025)', 'bm_original', 'Ch. 37 Q1', '2025', '', NULL, '', '', TRUE, FALSE, FALSE, 'Quel est le ou (les) graphique(s), le ou (les) plus adapté(s) pour représenter la fréquence des stades d’une affection chronique :', '', $medjson$[{"key":"A","text":"Diagramme à barres"},{"key":"B","text":"Polygone de fréquence"},{"key":"C","text":"Histogramme"},{"key":"D","text":"Diagramme circulaire"}]$medjson$::jsonb, $medjson$["A","D"]$medjson$::jsonb, 'Les stades d’une affection chronique forment une variable qualitative ordinale → diagramme en barres (A) et diagramme circulaire (D).', $medjson${"B":"Polygone de fréquence = variable quantitative continue.","C":"Histogramme = variable quantitative continue."}$medjson$::jsonb, NULL, FALSE, 'Statistique descriptive 2026 — Pr Benaldjia, slides 4 & 24–35') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C11_2', 'C11', 'L11.1', 'Graphique poids (2024 ×2)', 'bm_original', 'Ch. 37 Q7 (= Q6)', '2024', '', NULL, '', '', FALSE, FALSE, FALSE, 'Quel est le graphique le plus adapté pour représenter le poids d’une série de 1000 individus :', '', $medjson$[{"key":"A","text":"Histogramme"},{"key":"B","text":"Diagramme circulaire"},{"key":"C","text":"Diagramme à barres"},{"key":"D","text":"Diagramme à bâtonnets"}]$medjson$::jsonb, $medjson$["A"]$medjson$::jsonb, 'Le poids est une variable quantitative continue → représentée par un histogramme (barres juxtaposées).', $medjson${"B":"Réservé aux variables qualitatives.","C":"Réservé aux variables qualitatives.","D":"Réservé aux variables quantitatives discrètes (ex. nombre de rappels)."}$medjson$::jsonb, NULL, FALSE, 'Statistique descriptive 2026 — Pr Benaldjia, slide 32') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C11_3', 'C11', 'L11.1', 'Caractéristiques de l’histogramme', 'bm_original', 'Ch. 37 Q8', '2022', '', NULL, '', '', TRUE, FALSE, FALSE, 'Dans la représentation graphique des données, l’histogramme : (cocher les réponses justes)', '', $medjson$[{"key":"A","text":"Est une représentation graphique des distributions d’un caractère qualitatif"},{"key":"B","text":"Est une représentation graphique des distributions d’un caractère quantitatif continu"},{"key":"C","text":"Les barres du graphe adéquat sont juxtaposées"},{"key":"D","text":"Les surfaces constituent les effectifs cumulés"}]$medjson$::jsonb, $medjson$["B","C"]$medjson$::jsonb, 'L’histogramme représente une variable quantitative continue (B) avec des rectangles/barres juxtaposées sans espace (C).', $medjson${"A":"Un caractère qualitatif se représente par un diagramme en barres (espacées) ou circulaire.","D":"Les surfaces représentent les effectifs simples (ou fréquences relatives), PAS les effectifs cumulés !"}$medjson$::jsonb, NULL, TRUE, 'Statistique descriptive 2026 — Pr Benaldjia, slides 32–33') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C11_4', 'C11', 'L11.1', 'Définition d’un Ratio (2× en BM)', 'bm_original', 'Ch. 17 Q14 (cf. Ch. 37 Q12)', '2022', '', NULL, '', '', FALSE, TRUE, FALSE, 'Un ratio est : (cochez la réponse juste)', '', $medjson$[{"key":"A","text":"Un rapport de fréquences de 02 modalités de 02 variables différentes"},{"key":"B","text":"Rapport de 02 fréquences relatives"},{"key":"C","text":"Un rapport de fréquences de 02 modalités d’une même variable"},{"key":"D","text":"Un rapport de risque de survenue d’un événement"}]$medjson$::jsonb, $medjson$["C"]$medjson$::jsonb, 'Slide 9 : un ratio compare deux modalités exclusives d’une MÊME variable (ex. Sex-ratio = Masculin / Féminin). Note : dans Ch. 37 Q12 où C n’apparaît pas, la bonne réponse est D « Aucune réponse n’est juste » !', $medjson${"A":"Piège classique : jamais 2 variables différentes !","B":"Formulation incomplète.","D":"Un rapport de risques est un Risque Relatif (RR)."}$medjson$::jsonb, NULL, TRUE, 'Statistique descriptive 2026 — Pr Benaldjia, slide 9') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C11_5', 'C11', 'L11.1', 'Diagramme circulaire & piège 3,6° vs 4,6°', 'bm_original', 'Ch. 37 Q22', '2019', '', NULL, '', '', FALSE, TRUE, FALSE, 'Un diagramme circulaire est :', '', $medjson$[{"key":"A","text":"Un graphe adapté pour représenter les variables quantitatives continues"},{"key":"B","text":"Un graphe adapté pour représenter les variables qualitatives nominales"},{"key":"C","text":"Peut être remplacé par un histogramme"},{"key":"D","text":"Les angles des secteurs sont proportionnels aux fréquences relatives : 1 % est représenté par 4,6°"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Le diagramme circulaire (secteurs) représente les variables qualitatives (nominales ou ordinales à peu de modalités).', $medjson${"A":"Quantitatif continu → histogramme/polygone.","C":"Jamais remplacé par un histogramme (mais peut l’être par un diagramme en barres).","D":"Piège numérique ! 360° / 100 % = 3,6° pour 1 % (PAS 4,6° !)."}$medjson$::jsonb, NULL, FALSE, 'Statistique descriptive 2026 — Pr Benaldjia, slides 29–30') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C11_6', 'C11', 'L11.2', 'La moyenne arithmétique', 'bm_original', 'Ch. 37 Q23', 'ND', '', NULL, '', '', TRUE, FALSE, FALSE, 'La moyenne arithmétique : (cocher les réponses justes)', '', $medjson$[{"key":"A","text":"Est une mesure qui localise le centre d’une distribution"},{"key":"B","text":"Une statistique de la tendance centrale, sans unité de mesure"},{"key":"C","text":"A pour unité, l’unité de la variable"},{"key":"D","text":"Vaut la médiane quand l’échantillon est homogène"},{"key":"E","text":"Est différente de la médiane si la distribution est dissymétrique"}]$medjson$::jsonb, $medjson$["A","C","E"]$medjson$::jsonb, 'La moyenne localise le centre (A), possède l’unité de la variable (C) et s’écarte de la médiane dans une distribution dissymétrique (E).', $medjson${"B":"Faux : c’est le CV qui est sans unité ; la moyenne a l’unité de la variable.","D":"Elle vaut la médiane quand la distribution est SYMÉTRIQUE (pas simplement « homogène »)."}$medjson$::jsonb, NULL, FALSE, 'Statistique descriptive 2026 — Pr Benaldjia, slides 41–45') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C11_7', 'C11', 'L11.2', 'La médiane', 'bm_original', 'Ch. 37 Q17', '2019', '', NULL, '', '', TRUE, FALSE, FALSE, 'La médiane : (cocher la ou les réponses justes)', '', $medjson$[{"key":"A","text":"Est un paramètre de dispersion"},{"key":"B","text":"Nécessite, pour être calculée, de ranger les valeurs observées par ordre croissant"},{"key":"C","text":"S’exprime dans la même unité que la variable dont elle caractérise la distribution"},{"key":"D","text":"Est la racine carrée de l’écart-type"}]$medjson$::jsonb, $medjson$["B","C"]$medjson$::jsonb, 'Pour calculer la médiane, il faut impérativement ranger les données par ordre croissant (B) ; elle s’exprime dans l’unité de la variable (C). (Note : le corrigé BM Q17 en choix unique retient B).', $medjson${"A":"Paramètre de tendance centrale / position (Q2), pas de dispersion.","D":"Absurde (l’écart-type est la racine carrée de la variance)."}$medjson$::jsonb, NULL, FALSE, 'Statistique descriptive 2026 — Pr Benaldjia, slides 49–53') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C11_8', 'C11', 'L11.2', 'Les quartiles', 'bm_original', 'Ch. 37 Q27', 'ND', '', NULL, '', '', TRUE, FALSE, FALSE, 'Les quartiles : (cocher les réponses justes)', '', $medjson$[{"key":"A","text":"Sont au nombre de trois, le deuxième est aussi la médiane"},{"key":"B","text":"Sont des paramètres de dispersion"},{"key":"C","text":"Divisent en quatre parties égales une distribution"},{"key":"D","text":"Occupent un certain rang dans la série de valeurs d’une série statistique"}]$medjson$::jsonb, $medjson$["A","C"]$medjson$::jsonb, 'Il existe 3 quartiles (Q1, Q2 = Médiane, Q3 — item A) qui partagent une distribution ordonnée en 4 parts égales de 25 % (C). (Note : D n’est pas retenu dans la clé BM AC car il faut que la série soit ordonnée).', $medjson${"B":"Ce sont des paramètres de POSITION (quantiles), pas de dispersion.","D":"Imprécis sans mentionner le tri préalable de la série."}$medjson$::jsonb, NULL, FALSE, 'Statistique descriptive 2026 — Pr Benaldjia, slides 55–57') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C11_9', 'C11', 'L11.3', 'Définition de l’étendue (⚠️ Erreur BM)', 'bm_original', 'Ch. 37 Q14', '2019', '', NULL, '', '', FALSE, TRUE, FALSE, 'L’étendue est :', '', $medjson$[{"key":"A","text":"La différence entre la limite supérieure et la limite inférieure d’une classe"},{"key":"B","text":"La différence entre le 3ème et le premier quartile"},{"key":"C","text":"La différence entre la valeur maximale et la valeur minimale d’une série de données"},{"key":"D","text":"La différence entre le 9ème et le 1er quartile"}]$medjson$::jsonb, $medjson$["C"]$medjson$::jsonb, 'Slide 64 : l’étendue (paramètre de dispersion) vaut Xmax − Xmin sur l’ensemble de la série.', $medjson${"A":"Définit l’amplitude d’une classe (h), pas l’étendue.","B":"Q3 − Q1 = intervalle interquartile (IIQ).","D":"Absurde : il n’existe que 3 quartiles (confusion avec les déciles)."}$medjson$::jsonb, $medjson${"bmKey":"A","note":"Erreur du corrigé BM : A définit l’AMPLITUDE d’une classe ! Selon le cours (slide 64), l’étendue = max − min (réponse C)."}$medjson$::jsonb, FALSE, 'Statistique descriptive 2026 — Pr Benaldjia, slide 64') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C11_10', 'C11', 'L11.3', 'La variance (4× en BM)', 'bm_original', 'Ch. 37 Q2 (= Q3, Q10)', '2024', '', NULL, '', '', FALSE, FALSE, FALSE, 'La variance est considérée comme :', '', $medjson$[{"key":"A","text":"Un rapport de risque de survenue d’un événement"},{"key":"B","text":"Un paramètre de position d’une série des valeurs observées"},{"key":"C","text":"Une mesure de l’étalement de valeurs observées par rapport à une valeur moyenne"},{"key":"D","text":"Une mesure qui localise le centre d’une distribution de valeurs observées"}]$medjson$::jsonb, $medjson$["C"]$medjson$::jsonb, 'La variance mesure l’étalement (dispersion) des observations autour de la moyenne ; plus elle est élevée, plus les valeurs s’éloignent de la moyenne.', $medjson${"A":"Définit le Risque Relatif (RR).","B":"Paramètre de dispersion, pas de position.","D":"Définit un paramètre de tendance centrale (moyenne/médiane)."}$medjson$::jsonb, NULL, FALSE, 'Statistique descriptive 2026 — Pr Benaldjia, slides 65–67') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C11_11', 'C11', 'L11.3', 'Coefficient de variation — CV (⚠️ Erreur BM)', 'bm_original', 'Ch. 37 Q11 (cf. Q4, Q5, Q24)', '2022', '', NULL, '', '', TRUE, TRUE, FALSE, 'Le coefficient de variation est : (cocher les réponses justes)', '', $medjson$[{"key":"A","text":"Un paramètre de la tendance centrale"},{"key":"B","text":"Est exprimé par un pourcentage"},{"key":"C","text":"Est donné par la formule CV = écart-type / moyenne"},{"key":"D","text":"Est donné par la formule CV = moyenne / écart-type"}]$medjson$::jsonb, $medjson$["B","C"]$medjson$::jsonb, 'Slide 68 : CV = (s / m) × 100 (C), sans unité de la variable, exprimé en pourcentage (B).', $medjson${"A":"C’est un paramètre de DISPERSION.","D":"Formule inversée (piège récurrent en Q4, Q5, Q11)."}$medjson$::jsonb, $medjson${"bmKey":"C seul","note":"Le corrigé BM oublie l’item B : le CV est bien exprimé en pourcentage (%) ET donné par s / m (×100). Même omission en Q24 (vraie réponse BDE)."}$medjson$::jsonb, FALSE, 'Statistique descriptive 2026 — Pr Benaldjia, slide 68') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C11_12', 'C11', 'L11.3', 'Calcul complet (Série cours + CV + Angle)', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, 'Soit la série d’âges du cours : 15 ; 20 ; 25 ; 30 ; 35 ans, et une autre variable de moyenne m = 25 et d’écart-type s = 5. Cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"La moyenne et la médiane de la série 15 ; 20 ; 25 ; 30 ; 35 valent toutes deux 25 ans"},{"key":"B","text":"L’étendue de cette série vaut 20 ans"},{"key":"C","text":"Pour m = 25 et s = 5, le coefficient de variation vaut CV = 20 %"},{"key":"D","text":"La variance est la racine carrée de l’écart-type"}]$medjson$::jsonb, $medjson$["A","B","C"]$medjson$::jsonb, 'Moyenne = 125/5 = 25, médiane = 3ème valeur = 25 (A) ; Étendue = 35 − 15 = 20 (B) ; CV = (5 / 25) × 100 = 20 % (C).', $medjson${"D":"Piège classique inversé ! C’est l’ÉCART-TYPE qui est la racine carrée de la variance (S = √S²)."}$medjson$::jsonb, NULL, FALSE, 'Statistique descriptive 2026 — Pr Benaldjia, slides 41, 50, 64–68') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C12_1', 'C12', 'L12.1', 'Risque α vs p-value & H₀/H₁', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, 'Concernant la démarche d’un test d’hypothèse (Pr Aouidane), cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"Le risque de 1ère espèce α est le risque de rejeter à tort l’hypothèse nulle H₀"},{"key":"B","text":"Le risque α est fixé a priori avant le calcul, tandis que la p-value est déterminée a posteriori après le calcul"},{"key":"C","text":"L’hypothèse alternative bilatérale H₁ s’écrit PA ≠ PB sans préciser le sens de la différence"},{"key":"D","text":"Le test du χ² s’applique directement sur les pourcentages sans passer par les effectifs"}]$medjson$::jsonb, $medjson$["A","B","C"]$medjson$::jsonb, 'Définition de α (A), opposition α a priori vs p a posteriori (B) et H₁ bilatérale (C) sont conformes aux slides 8–13.', $medjson${"D":"Piège majeur ! Le test du χ² se calcule TOUJOURS sur des EFFECTIFS (jamais directement sur des pourcentages)."}$medjson$::jsonb, NULL, FALSE, 'Test d’hypothèse (χ²) — Pr Aouidane, slides 8–16') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C12_2', 'C12', 'L12.1', 'χ² de conformité vs d’homogénéité', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, FALSE, FALSE, 'Concernant les types de test du χ² de Pearson, cochez les propositions exactes :', '', $medjson$[{"key":"A","text":"Le χ² de conformité (ou d’ajustement) compare un échantillon observé à une distribution théorique connue"},{"key":"B","text":"Le χ² d’homogénéité compare deux ou plusieurs échantillons entre eux"},{"key":"C","text":"Le but du test est de déterminer si la différence observée est due au hasard (fluctuations d’échantillonnage) ou si elle est réelle"},{"key":"D","text":"Le test du χ² est réservé exclusivement aux variables quantitatives continues non groupées"}]$medjson$::jsonb, $medjson$["A","B","C"]$medjson$::jsonb, 'Conformité (A), homogénéité (B) et objectif du test (C) sont exacts (slides 5 & 15).', $medjson${"D":"Faux : il s’applique aux variables qualitatives (ou quantitatives discrétisées en classes) présentées en effectifs."}$medjson$::jsonb, NULL, FALSE, 'Test d’hypothèse (χ²) — Pr Aouidane, slides 5 & 15') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C12_3', 'C12', 'L12.1', 'Formulation de la conclusion (Non-rejet H₀)', 'course_generated', '', 'Cours', '', NULL, '', '', FALSE, TRUE, FALSE, 'Dans l’exemple du cours (slide 27), on obtient χ²o = 3,125 pour ddl = 1 (avec χ²10% = 2,706 et χ²5% = 3,841). Quelle est la conclusion statistique rigoureuse au risque α = 5 % ?', '', $medjson$[{"key":"A","text":"p \u003c 0,05 ; rejet de H₀ ; différence statistiquement significative"},{"key":"B","text":"0,05 \u003c p \u003c 0,10 ; non-rejet de H₀ ; différence statistiquement non significative"},{"key":"C","text":"0,05 \u003c p \u003c 0,10 ; on accepte formellement que H₀ est prouvée vraie"},{"key":"D","text":"p \u003c 0,01 ; différence hautement significative"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Puisque 2,706 < 3,125 < 3,841, on encadre 0,05 < p < 0,10. Comme χ²o < 3,841, on conclut au NON-REJET de H₀ (différence non significative).', $medjson${"A":"Faux : 3,125 \u003c 3,841 donc p \u003e 0,05.","C":"Piège du cours : on dit « non-rejet de H₀ », JAMAIS « on accepte H₀ » !","D":"Il faudrait χ²o \u003e 6,635."}$medjson$::jsonb, NULL, FALSE, 'Test d’hypothèse (χ²) — Pr Aouidane, slides 25–27') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C12_4', 'C12', 'L12.2', 'Décision χ² sur tableau 2×2 (2025)', 'bm_original', 'Ch. 43 Q1 (reclassé vers C12)', '2025', '', NULL, '', '', TRUE, FALSE, FALSE, 'On a enquêté dans une commune (827 ménages, 5 670 personnes) pour mesurer la prévalence des handicaps selon le sexe (tableau 2×2 — note : photo BM corrompue). Existe-t-il une relation entre la présence d’un handicap et le sexe ? (cocher les réponses justes)', '', $medjson$[{"key":"A","text":"χ² = 0,04"},{"key":"B","text":"χ² = 0,40"},{"key":"C","text":"Test statistiquement significatif"},{"key":"D","text":"Test statistiquement non significatif"}]$medjson$::jsonb, $medjson$["B","D"]$medjson$::jsonb, 'Pour un tableau 2×2 (ddl = 1) au risque α = 5 %, la valeur critique est 3,841. Avec χ² = 0,40 < 3,841, le test est statistiquement non significatif (non-rejet de H₀).', $medjson${"A":"Erreur de virgule sur le calcul original de l’épreuve.","C":"Faux : il faudrait χ² \u003e 3,841 pour conclure à la significativité."}$medjson$::jsonb, NULL, FALSE, 'Test d’hypothèse (χ²) — Pr Aouidane, slides 24–27') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C12_5', 'C12', 'L12.2', 'Calcul complet χ² sur tableau 2×2 (inspiré Ch. 42 Q4)', 'course_generated', '', 'Cours', '', NULL, '', '', TRUE, TRUE, FALSE, 'On compare l’évolution d’une maladie (Guérison vs Rechute) selon la voie d’administration chez N = 100 patients (risque α = 5 %, χ²5%, ddl=1 = 3,841). Cochez les propositions exactes :', '<table class="mini-table"><thead><tr><th></th><th>Guérison</th><th>Rechute</th><th>Total</th></tr></thead><tbody><tr><td><strong>Voie orale</strong></td><td>18</td><td>32</td><td><strong>50</strong></td></tr><tr><td><strong>Voie parentérale</strong></td><td>32</td><td>18</td><td><strong>50</strong></td></tr><tr><td><strong>Total</strong></td><td><strong>50</strong></td><td><strong>50</strong></td><td><strong>100</strong></td></tr></tbody></table>', $medjson$[{"key":"A","text":"Chaque effectif théorique Cij vaut (50 × 50) / 100 = 25 ≥ 5 : condition d’application vérifiée"},{"key":"B","text":"Le nombre de degrés de liberté est ddl = 4"},{"key":"C","text":"La valeur calculée du χ² observé est χ²o = 7,84"},{"key":"D","text":"Comme χ²o \u003e 3,841, on rejette H₀ : la différence est statistiquement significative"}]$medjson$::jsonb, $medjson$["A","C","D"]$medjson$::jsonb, '1) Cij = (50×50)/100 = 25 ≥ 5 dans les 4 cases (A). 2) χ²o = 4 × (7² / 25) = 196 / 25 = 7,84 (C). 3) ddl = (2−1)(2−1) = 1 → 7,84 > 3,841 (et même > 6,635 ⇒ p < 0,01) ⇒ rejet de H₀, différence significative (D).', $medjson${"B":"Faux : ddl = (L − 1)(C − 1) = (2 − 1)(2 − 1) = 1 (pas 4 !)."}$medjson$::jsonb, NULL, FALSE, 'Test d’hypothèse (χ²) — Pr Aouidane, slides 16–27') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.qcms (id, course_id, lesson_id, topic, source_type, bm_ref, year, page_ref, slide_num, slide_title, source_file, multi_select, is_hard, needs_review, stem, table_html, options, correct, explanation, wrong_reasons, bm_error, bm_unanswered, course_ref) VALUES ('Q_C12_6', 'C12', 'L12.2', 'Condition d’application Cij ≥ 5 (Théoriques vs Observés)', 'course_generated', '', 'Cours', '', NULL, '', '', FALSE, TRUE, FALSE, 'Quelle est la condition d’application indispensable du test du χ² de Pearson sur un tableau de contingence ?', '', $medjson$[{"key":"A","text":"Tous les effectifs OBSERVÉS (Oij) doivent être ≥ 5"},{"key":"B","text":"Tous les effectifs THÉORIQUES calculés (Cij) doivent être ≥ 5"},{"key":"C","text":"L’effectif total N doit être supérieur à 1 000"},{"key":"D","text":"Le nombre de degrés de liberté doit être supérieur à 3"}]$medjson$::jsonb, $medjson$["B"]$medjson$::jsonb, 'Slide 20 : la validité du χ² exige que tous les effectifs THÉORIQUES calculés Cij = (Total ligne × Total colonne) / N soient supérieurs ou égaux à 5.', $medjson${"A":"Piège très fréquent ! Ce sont les effectifs THÉORIQUES (Cij), pas les effectifs observés (Oij).","C":"Faux.","D":"Faux : un tableau 2×2 a ddl = 1."}$medjson$::jsonb, NULL, FALSE, 'Test d’hypothèse (χ²) — Pr Aouidane, slide 20') ON CONFLICT (id) DO NOTHING;
